	if d.Plays != nil {
		out.Plays = make([]LiveEventPlay, len(d.Plays))
		for i, p := range d.Plays {
			out.Plays[i] = p
			if p.Score != nil {
				out.Plays[i].Score = make(map[string]string, len(p.Score))
				for k, v := range p.Score {
