func (m Manifest) LiveFeedByID(id string) (LiveFeedMeta, bool) {
	if e := m.EffectiveEther(); e != nil {
		for _, lf := range e.Contributes.LiveFeeds {
			if lf.ID == id {
				return lf, true
			}
		}
