	// Identify: the plugin answers /identify, which file imports need.
	Identify bool `json:"identify,omitempty"`
}

// KindRelatedDecl names which relation purposes a kind's plugin answers.
type KindRelatedDecl struct {
	Similar      bool `json:"similar,omitempty"`
	Continuation bool `json:"continuation,omitempty"`
}

// Answers reports whether purpose is declared.
func (d *KindRelatedDecl) Answers(purpose string) bool {
	if d == nil {
		return false
	}
	switch purpose {
	case "similar":
		return d.Similar
	case "continuation":
		return d.Continuation
	}
	return false
}

// KindBrowseDecl is how a kind library is browsed.
type KindBrowseDecl struct {
	Sorts        []string          `json:"sorts,omitempty"`        // subset of title|added|released|year|rating|index
	Facets       []string          `json:"facets,omitempty"`       // field keys; each must be indexed
	Search       bool              `json:"search"`                 // full-text over the title plus SearchFields
	SearchFields []string          `json:"searchFields,omitempty"` // declared text fields included in search
	Expand       *KindBrowseExpand `json:"expand,omitempty"`       // on-demand background facet/person expansion
	// LiveSearch: client searches also call the plugin's /search route
	// with a short budget; results are upserted and merged (§15.4).
	LiveSearch bool `json:"liveSearch,omitempty"`
}

// Kind sync modes (spec §3.5 as narrowed by §15.4: no ondemand mode).
const (
	KindSyncPull = "pull"
	KindSyncPush = "push"
)

// Kind sync undo modes for push-synced kinds (#766).
//   - "snapshots" (default when omitted): journal previous copies of modified
//     items so undo restores them; unchanged items are never snapshotted.
//   - "ids": journal only created and touched item IDs without reading item
//     snapshots; undo deletes only items the batch created.
const (
	KindSyncUndoSnapshots = "snapshots"
	KindSyncUndoIDs       = "ids"
)

// KindSyncDecl is how a kind's items reach Ether's store. Mode is empty
// only for a resolver-only kind, which owns no item sync; a catalog
// provider must pick pull or push.
type KindSyncDecl struct {
	Mode    string `json:"mode"`              // pull|push
	Refresh string `json:"refresh,omitempty"` // at least 15m, pull only
	Undo    string `json:"undo,omitempty"`    // snapshots|ids, push only
}

// KindCacheDecl is the per-library blob cache budget (§5.4).
type KindCacheDecl struct {
	MaxBytes int64  `json:"maxBytes,omitempty"` // 0 inherits the media pool budget.
	TTL      string `json:"ttl,omitempty"`
}

// KindMatchDecl holds matcher defaults for a kind (spec §7).
type KindMatchDecl struct {
	// ThresholdDefault is the score (0..1) at or above which an
	// automatic match is accepted; 0 leaves the server default.
	ThresholdDefault float64 `json:"thresholdDefault,omitempty"`
}

// FrontendAdapterMeta declares one plugin-provided protocol surface
// (spec §6.5).
type FrontendAdapterMeta struct {
	Key          string   `json:"key"`
	Label        string   `json:"label"`
	ProtocolHint string   `json:"protocolHint"` // opds|subsonic|custom
	PathPrefix   string   `json:"pathPrefix"`
	DefaultPort  int      `json:"defaultPort,omitempty"`
	Clients      []string `json:"clients,omitempty"`
	Auth         string   `json:"auth,omitempty"` // ether_token (default)|basic|none_lan|query_credentials
	// Libraries lists the plugin's media-kind keys this adapter publishes.
	// Ether resolves each key to the library the kind created and admits a
	// viewer only to the libraries they may see; a viewer who sees none of
	// them is answered 404. Empty means the adapter is not library-scoped.
	Libraries []string `json:"libraries,omitempty"`
	// SearchPaths optionally lists adapter subpaths (such as "/search",
	// "/rest/search3", or "/graphql") that handle interactive viewer searches
	// and may call ai.complete when permissions.ai is "complete+search" (#702).
	// When omitted, conventional search subpaths (ending in /search, /search2,
	// or /search3, with optional .json/.xml/.view suffix) are recognized.
	SearchPaths []string `json:"searchPaths,omitempty"`
	// UploadPaths opt in to disk staging for selected adapter subpaths.
	UploadPaths []FrontendUploadPath `json:"uploadPaths,omitempty"`
	// Icon is the adapter's own mark on the Apps page: a path to an SVG or
	// PNG inside the package. Without one the plugin's icon stands in.
	Icon string `json:"icon,omitempty"`
}

// FrontendUploadPath declares a glob and the maximum wire body size in bytes.
type FrontendUploadPath struct {
	Path     string `json:"path"`
	MaxBytes int64  `json:"maxBytes"`
}

// SetupMeta declares guided setup for any plugin kind (spec §8).
type SetupMeta struct {
	Steps []SetupStep `json:"steps"`
}

// SetupStep is one setup wizard step. An empty Test means saving the
// fields is the whole step; otherwise Ether posts the step's saved
// field values to Test, conventionally /ether/v1/setup/<key>/test.
type SetupStep struct {
	Key      string   `json:"key"`
	Label    string   `json:"label"`
	Hint     string   `json:"hint,omitempty"`
	Fields   []string `json:"fields"` // settings field keys this step collects
	Test     string   `json:"test"`   // plugin route, or "" for no test
	Required bool     `json:"required"`
}

// Request is one HTTP-shaped call from Ether to a plugin (SPEC §5.1.2).
// Hosted plugins receive the same object in-process.
type Request struct {
	Op       string            `json:"op,omitempty"`
	ID       string            `json:"id,omitempty"`
	PluginID string            `json:"pluginId"`
	Method   string            `json:"method"`
	Path     string            `json:"path"`
	Query    map[string]string `json:"query,omitempty"`
	// RepeatedQuery holds every value of query keys that appeared more than
	// once on a frontend adapter request (Subsonic sends id=1&id=2). Hosted
	// runtimes deliver those keys as arrays; the remote wire keeps Query's
	// first value. Host-side only.
	RepeatedQuery map[string][]string `json:"-"`
	Headers       map[string]string   `json:"headers,omitempty"`
	Body          json.RawMessage     `json:"body,omitempty"`
	// BodyBase64 carries the exact request bytes, base64-encoded, when the
	// caller needs them byte-for-byte (frontend adapter routes). Body holds
	// the parsed JSON value when the bytes are valid JSON; a non-JSON body
	// arrives only here, never as an invalid RawMessage.
	BodyBase64  string          `json:"bodyBase64,omitempty"`
	ContentType string          `json:"contentType,omitempty"`
	Upload      *FrontendUpload `json:"upload,omitempty"`
	// Locale is the console locale for calls that return copy.
	Locale string `json:"locale,omitempty"`
	// Foreground marks an /ether/job/ call that a viewer is waiting on
	// (playback resolution). It never yields to background throttling.
	// Host-side only; never sent to the plugin.
	Foreground bool `json:"-"`
	// Deadline carries the effective per-call deadline computed by the manager
	// (including live overrides) for hosted runtimes. Host-side only.
	Deadline time.Duration `json:"-"`
	// AISearch marks a search route whose plugin has active permissions.ai:
	// "complete+search" so hosted runtimes allow Deadline up to the AI search
	// route bound. Host-side only.
	AISearch bool `json:"-"`
	// CheckResponse validates a successful body before recording the call. Host-side only.
	CheckResponse func(json.RawMessage) error `json:"-"`
}

// FrontendBlob asks the host to serve bytes directly. A blob:<sha256> ref
// requires LibraryKey for an owned, viewer-visible kind library and can select
// an archive member. A durable:<sha256> ref serves the plugin's entire saved
// blob with durable storage permission.
type FrontendBlob struct {
	LibraryKey  string `json:"libraryKey,omitempty"`
	Ref         string `json:"ref"`
	MemberIndex *int   `json:"memberIndex,omitempty"`
}

// FrontendMedia asks Ether to serve one of the plugin's own playable kind
// items to the authenticated adapter viewer, at the adapter URL itself, with
// Range support. Ether re-checks ownership and library visibility exactly as
// frontend.streamURL does; the bytes never pass through the plugin. It suits
// protocols whose clients do not follow redirects or re-request ranges long
// after a stream ticket would have expired.
type FrontendMedia struct {
	ItemRef   string `json:"itemRef"`
	PartIndex *int   `json:"partIndex,omitempty"`
	Source    string `json:"source,omitempty"`
}

// FrontendArt asks Ether to serve the stored artwork of one of the plugin's
// own kind items (role poster, thumb, backdrop or logo; empty picks the
// first). Ether fetches and caches the image itself, so a plugin cannot use it
// to proxy arbitrary URLs.
type FrontendArt struct {
	ItemRef string `json:"itemRef"`
	Role    string `json:"role,omitempty"`
}

// Response is a plugin's answer to a Request.
type Response struct {
	Blob    *FrontendBlob     `json:"blob,omitempty"`
	Media   *FrontendMedia    `json:"media,omitempty"`
	Art     *FrontendArt      `json:"art,omitempty"`
	Status  int               `json:"status"`
	Headers map[string]string `json:"headers,omitempty"`
	Body    json.RawMessage   `json:"body,omitempty"`

	// Failure holds an owner-facing diagnostic and is never sent to the plugin.
	Failure *RouteFailure `json:"-"`

	pendingFallback func() error
}

// Runtime is how the host reaches one installed plugin. WS8a (hosted) and
// WS8b (remote) implement it; tests use a fake. Call must honour ctx
// deadlines. Close releases the instance; the host may open a fresh one
// after a failure (restart with backoff).
type Runtime interface {
	Call(ctx context.Context, req Request) (Response, error)
	Close() error
}

// Installed is the host's record of one installed plugin, handed to a
// RuntimeFactory when an instance is opened.
type Installed struct {
	RuntimeLimits *RuntimeLimits
	Busy          func() bool
	ID            string
	Manifest      Manifest
	// SourceURL is where the manifest came from (remote endpoint base).
	SourceURL string
	// Files returns an artifact file (entry, module, strings, schema) for
	// the installed version, or false. Hosted runtimes load code through it.
	Files func(path string) ([]byte, bool)
	// Host is the per-plugin host-services handle (SPEC §5.1.5).
	Host Host
}

// RuntimeFactory opens a Runtime for one installed plugin. The factory is
// chosen by manifest ether.runtime.kind ("hosted" or "remote").
type RuntimeFactory func(inst Installed) (Runtime, error)

// KVUsage reports a plugin's current KV bytes (including the 256-byte charge
// per key), key count, and configured quotas (#591).
type KVUsage struct {
	Bytes      int64 `json:"bytes"`
	Keys       int64 `json:"keys"`
	QuotaBytes int64 `json:"quotaBytes"`
	QuotaKeys  int64 `json:"quotaKeys"`
}

// Poster badge bounds (#594).
const (
	MaxPosterBadgeSets     = 4
	MaxBadgeEntriesPerCall = 500
	MaxBadgeLabelsPerTitle = 3
	MaxBadgeLabelLen       = 16
	PosterBadgeQuotaTitles = 200_000
)

// BadgeTitleRef identifies a canonical movie or show by TMDB and/or IMDb id.
type BadgeTitleRef struct {
	Type string `json:"type"`
	TMDB int64  `json:"tmdb,omitempty"`
	IMDB string `json:"imdb,omitempty"`
}

// BadgeEntry pushes or clears (empty Labels) poster badges for one title.
type BadgeEntry struct {
	Title  BadgeTitleRef `json:"title"`
	Labels []string      `json:"labels"`
}

// BadgeUsage reports a plugin's badged title count and per-plugin title quota.
type BadgeUsage struct {
	Titles      int64 `json:"titles"`
	QuotaTitles int64 `json:"quotaTitles"`
}

// Host is the set of Ether services a plugin may call (SPEC §5.1.5).
// Every method re-checks the plugin's live grants, so a revoke takes
// effect mid-call. Writes are journalled; in shadow mode they are
// recorded without applying. The hosted runtime exposes Host as imports;
// remote plugins reach it over /ether/plugin-host/* (WS8b).
type Host interface {
	KVGet(ctx context.Context, key string) ([]byte, bool, error)
	KVPut(ctx context.Context, key string, value []byte) error
	KVDelete(ctx context.Context, key string) error
	KVList(ctx context.Context, prefix string) ([]string, error)
	KVUsage(ctx context.Context) (KVUsage, error)

	// BadgesSet, BadgesClear and BadgesUsage need poster_badges (#594).
	BadgesSet(ctx context.Context, setKey string, entries []BadgeEntry) error
	BadgesClear(ctx context.Context, setKey string) error
	BadgesUsage(ctx context.Context) (BadgeUsage, error)

	// SecretGet returns a sealed setting the manifest declared in
	// permissions.secrets (owner-configured first, then plugin-written derived
	// secrets). Hosted plugins only.
	SecretGet(ctx context.Context, name string) (string, error)
	// SecretSet stores a sealed derived secret under a name declared in
	// permissions.secrets that is not an owner-configured settings secret.
	// Passing an empty value deletes the derived secret. ttlSec <= 0 means no
	// expiry; positive values expire after ttlSec seconds.
	SecretSet(ctx context.Context, name, value string, ttlSec int64) error
	// SecretDelete removes a plugin-written derived secret declared in
	// permissions.secrets. Owner-configured settings secrets cannot be deleted.
	SecretDelete(ctx context.Context, name string) error

	// HTTPFetch fetches through egress and safefetch; only manifest
	// network hosts are allowed. Observed hosts feed the privacy label.
	HTTPFetch(ctx context.Context, req FetchRequest) (FetchResponse, error)

	// CatalogSearch and CatalogGet need catalog: read. Results are JSON
	// title summaries produced by the injected catalog backend.
	CatalogSearch(ctx context.Context, query string, limit, offset int) (json.RawMessage, error)
	CatalogGet(ctx context.Context, id string) (json.RawMessage, error)

	// ViewerHistory needs viewers.watch_history for that viewer.
	ViewerGranted(ctx context.Context) (json.RawMessage, error)
	ViewerHistory(ctx context.Context, viewerID int64, limit, offset int) (json.RawMessage, error)
	// SetWatchState needs viewers.write_watch_state for the requested viewer.
	// titleID is an owned playable item ref or a catalogue movie/episode ID.
	SetWatchState(ctx context.Context, viewerID int64, titleID string, watched bool) error
	// CollectionsUpsert needs collections: write; journalled.
	CollectionsUpsert(ctx context.Context, collection json.RawMessage) error

	// KindUpsert and KindDelete need catalog_provider and a push-mode
	// kind (spec §3.6): the sync engine is the only writer for pull
	// kinds. Writes are journalled in shadow mode without applying.
	KindUpsert(ctx context.Context, kindKey string, items []core.KindItem) (accepted int, err error)
	KindDelete(ctx context.Context, kindKey string, externalIDs []string) error
	// KindItems reads the plugin's own library back, keyset-paged.
	KindItems(ctx context.Context, kindKey, cursor string, limit int) (core.KindPage, error)
	// KindVisible returns the subset of external IDs (at most MaxKindVisibleIDs)
	// in kindKey that the library's Rules and viewer access policy allow for the
	// requesting frontend-adapter viewer (#615). Only viewer-authenticated
	// frontend adapter requests may call it; the viewer comes from the adapter
	// request context, never from guest input.
	KindVisible(ctx context.Context, kindKey string, ids []string) ([]string, error)
	// KindBrowse browses or searches kindKey using the same LibraryPolicy path
	// as Ether's console and protocol projectors for the requesting
	// frontend-adapter viewer (#615). Only viewer-authenticated frontend adapter
	// requests may call it; the viewer comes from the adapter request context,
	// never from guest input.
	KindBrowse(ctx context.Context, kindKey string, q core.KindBrowseRequest) (core.KindPage, error)
	// ResolveSources needs kind_resolver and permissions.sources
	// (search to look, acquire to open debrid content, §4.5).
	ResolveSources(ctx context.Context, q core.SourceQuery) ([]core.SourceCandidate, error)
	// CachePut stores one blob in a kind library's cache namespace and
	// returns its "blob:<sha256>" reference; CacheOpen reads one back;
	// CacheDelete removes one from this plugin's own namespaces.
	CachePut(ctx context.Context, libraryKey, name string, r io.Reader) (blobRef string, err error)
	CacheOpen(ctx context.Context, blobRef string) (io.ReadSeekCloser, error)
	CacheDelete(ctx context.Context, blobRef string) error

	// StreamURL mints a short-lived, scoped ticket for one of this
	// plugin's own kind items and returns the Ether stream URL a frontend
	// adapter embeds instead of a plugin URL (spec §6.5). The viewer is
	// the one the proxied request authenticated (X-Ether-Viewer); items
	// from another plugin, or a library the viewer cannot see, are
	// refused. Bytes are then served by Ether, never by the plugin.
	StreamURL(ctx context.Context, itemRef string) (string, error)
	StreamPartURL(ctx context.Context, itemRef string, partIndex *int) (string, error)
	StreamURLWithOptions(ctx context.Context, itemRef string, opts StreamURLOptions) (string, error)

	// FoldersRoots lists the live owner-picked absolute paths on non-client routes.
	FoldersRoots(ctx context.Context) ([]string, error)

	// FoldersList and FoldersStat need folders: read and an owner-picked
	// root. They never return file contents.
	FoldersList(ctx context.Context, root, path string, options ...FolderListOptions) (FolderPage, error)
	FoldersStat(ctx context.Context, root, path string) (FolderEntry, error)
	FoldersHash(ctx context.Context, root, path string, options ...FolderHashOptions) (FolderHash, error)
	FoldersHashStart(ctx context.Context, root, path string, options ...FolderHashOptions) (FolderHashJob, error)
	FoldersFrame(ctx context.Context, root, path string, options FolderFrameOptions) (FolderFrame, error)
	FoldersHashPoll(ctx context.Context, id string) (FolderHashJob, error)
	FoldersHashCancel(ctx context.Context, id string) (FolderHashJob, error)

	// Settings returns the plugin's current non-secret settings. Plugins
	// read them per request instead of keeping them in instance memory,
	// because hosted plugins run in a pool of instances that restart.
	// Secrets stay behind SecretGet.
	Settings(ctx context.Context) (map[string]any, error)

	// PublishEvent emits one manifest-declared plugin event onto Ether's event
	// bus as "plugin:<pluginId>/<key>". Requires the events capability and a
	// matching entry in contributes.events.publish; payload is schema-validated
	// and rate-limited.
	PublishEvent(ctx context.Context, key string, payload json.RawMessage, corr events.Correlation) error

	// ScreensInvalidate makes every open screen and surface of this plugin
	// read its sources again now (screens capability). It returns how many
	// open streams heard it; nobody watching means nothing happens.
	ScreensInvalidate(ctx context.Context) (int, error)
	// ScreensPutRecords pushes new values for the plugin's own records
	// ([{type, id, value}], at most 100) to open screens already showing
	// them (screens capability).
	ScreensPutRecords(ctx context.Context, records json.RawMessage) (int, error)

	// AIComplete runs a bounded text or JSON-Schema-validated completion against
	// the owner's configured language model (Settings -> Integrations -> Language
	// model). Requires permissions.ai: "complete" (or "complete+search" to also
	// allow bounded, cached calls on Stremio catalog search, kinds search, and
	// declared frontend-adapter search routes; #702). Every other viewer/client
	// request path stays refused. Returns ErrNotConfigured when no model is
	// configured.
	AIComplete(ctx context.Context, req AICompleteRequest) (AICompleteResponse, error)

	// MediaProbe reads container metadata ({durationSec, container, width,
	// height, sizeBytes}) for a PlayableSource in the same shape /resolve
	// returns, reusing Ether's durable release_probes cache. Requires
	// permissions.media: "probe", is restricted to jobs, actions, and
	// background routes (never viewer or client request paths), is rate-limited
	// per plugin, and is bounded at 10 s per probe.
	MediaProbe(ctx context.Context, src core.PlayableSource) (core.MediaProbeResult, error)

	// NotifyOwner posts a console notice (rate-limited).
	NotifyOwner(ctx context.Context, text string) error
	// Log appends to the plugin's log ring (redacted, rate-limited).
	Log(ctx context.Context, level, msg string, attrs map[string]any) error
}

// AIMessage is one chat turn sent to Host.AIComplete.
type AIMessage struct {
	Role    string `json:"role"`
	Content string `json:"content"`
}

// AICompleteRequest configures one completion on the owner's configured
// language model (#669).
type AICompleteRequest struct {
	Messages []AIMessage `json:"messages"`
	// Schema is an optional JSON Schema object. When set, the host extracts
	// JSON from the reply, validates it against Schema, and populates JSON
	// (returning ErrInvalidOutput if validation fails). External $ref URLs
	// are rejected.
	Schema json.RawMessage `json:"schema,omitempty"`
	// MaxTokens bounds output tokens (default DefaultAIMaxTokens, max MaxAIMaxTokens).
	MaxTokens int `json:"maxTokens,omitempty"`
	// Temperature optionally adjusts sampling in [0, 2]. Providers or models
	// that disallow explicit temperature ignore it safely.
	Temperature *float64 `json:"temperature,omitempty"`
	// TimeoutMS optionally tightens the call timeout (clamped to MaxAITimeout
	// on background/action paths, MaxAISearchTimeout on interactive search
	// routes, and the enclosing call deadline).
	TimeoutMS int64 `json:"timeoutMs,omitempty"`
	// SearchQuery identifies the viewer's search query when calling ai.complete
	// on an interactive search route under permissions.ai: "complete+search"
	// (#702). Required on frontend-adapter search routes that do not carry a
	// query parameter in the URL (such as GraphQL POST endpoints) and used for
	// normalized per-query caching so repeated searches do not re-ask the model.
	SearchQuery string `json:"searchQuery,omitempty"`
}

// AICompleteResponse is the completion returned by Host.AIComplete.
type AICompleteResponse struct {
	// Text is the assistant reply (with reasoning blocks stripped). When
	// Schema was provided, Text holds the compact canonical JSON of JSON.
	Text string `json:"text"`
	// JSON holds the validated JSON value when Schema was provided.
	JSON json.RawMessage `json:"json,omitempty"`
}

// AICompleteBackendRequest is passed from the plugin host to Backends.AIComplete
// after permissions, route policy, input bounds, and rate limits have been checked.
type AICompleteBackendRequest struct {
	Messages    []AIMessage
	JSONMode    bool
	MaxTokens   int
	Temperature *float64
}

// StreamURLOptions scopes a frontend adapter stream ticket to a specific
// zero-based item part and/or resolver PlayableSource.ID (#576, #661) and
// optionally asks Ether to return an absolute URL using the client-visible
// request origin or the adapter's first published address (#772).
type StreamURLOptions struct {
	Fallback  bool              `json:"fallback,omitempty"` // Try remaining sources when the named source cannot open.
	PartIndex *int              `json:"partIndex,omitempty"`
	Source    string            `json:"source,omitempty"`
	Absolute  bool              `json:"absolute,omitempty"`
	Wait      *StreamWaitPolicy `json:"wait,omitempty"`
}

// StreamWaitPolicy opts a download ticket into holding the media response
// during preparation. MaxSeconds must be positive. Ether caps it at 1800.
type StreamWaitPolicy struct {
	MaxSeconds int `json:"maxSeconds"`
}

// FetchRequest is one plugin outbound HTTP call.
type FetchRequest struct {
	TimeoutMS int64             `json:"timeoutMs,omitempty"`
	Method    string            `json:"method"`
	URL       string            `json:"url"`
	Headers   map[string]string `json:"headers,omitempty"`
	Body      []byte            `json:"body,omitempty"`
	// KeepHeadersOnRedirect lists optional host or wildcard (*.example.org)
	// patterns (within permissions.network / granted hosts) that may keep
	// credentials and caller headers across redirects when the target is not
	// already the same origin or a strict same-site subdomain. Never applies
	// across HTTPS -> HTTP downgrades.
	KeepHeadersOnRedirect []string `json:"keepHeadersOnRedirect,omitempty"`
}

// FetchResponse is the answer to a FetchRequest (body capped at 10 MiB).
type FetchResponse struct {
	Status  int               `json:"status"`
	Headers map[string]string `json:"headers,omitempty"`
	Body    []byte            `json:"body,omitempty"`
}

// FetchManyOptions configures a bounded concurrent http.fetchMany batch call.
// Concurrency defaults to DefaultFetchManyConcurrency (8) and clamps to
// MaxFetchManyConcurrency (8); there is no owner setting.
type FetchManyOptions struct {
	Concurrency int `json:"concurrency,omitempty"`
}

// FetchManyError describes one failed request inside http.fetchMany. Code
// matches the hosted fault code vocabulary ("timeout", "forbidden",
// "invalid_input", "host_error", "bad_arguments").
type FetchManyError struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

// FetchManyResult is one ordered answer from http.fetchMany. Either Error is
// non-nil or Response carries the received HTTP response (including non-2xx
// statuses, matching http.fetch).
type FetchManyResult struct {
	Response FetchResponse   `json:"-"`
	Error    *FetchManyError `json:"error,omitempty"`
}

// FolderHashJob is a pollable background hash. Bytes is the progress so far.
// Terminal states are done, canceled and error. Only done carries Result.
type FolderHashJob struct {
	ID     string      `json:"id"`
	State  string      `json:"state"`
	Bytes  int64       `json:"bytes"`
	Result *FolderHash `json:"result,omitempty"`
	Error  string      `json:"error,omitempty"`
}

// FolderHash contains digests, never file contents. ModTime is Unix seconds.
type FolderHash struct {
	Size    int64  `json:"size"`
	ModTime int64  `json:"modTime"`
	CRC32   string `json:"crc32,omitempty"`
	MD5     string `json:"md5,omitempty"`
	SHA1    string `json:"sha1,omitempty"`
	OSHash  string `json:"oshash,omitempty"`
	PHash   string `json:"phash,omitempty"`
}

// FolderHashOptions limits which digests are computed. Phash requires a background hash job.
type FolderHashOptions struct {
	Algorithms []string `json:"algorithms,omitempty"`
}

// FolderFrameOptions selects a timestamp, image width and optional owned cache library.
type FolderFrameOptions struct {
	AtSec      float64 `json:"atSec"`
	Width      int     `json:"width"`
	LibraryKey string  `json:"libraryKey,omitempty"`
}

// FolderFrame identifies a cached PNG image.
type FolderFrame struct {
	Ref        string `json:"ref"`
	LibraryKey string `json:"libraryKey"`
}

// FolderListOptions selects names strictly after Cursor in ascending name order.
type FolderListOptions struct {
	Cursor string `json:"cursor,omitempty"`
	Limit  int    `json:"limit,omitempty"`
}

// FolderPage is a name-sorted page. NextCursor is empty at the end.
type FolderPage struct {
	Entries    []FolderEntry `json:"entries"`
	NextCursor string        `json:"nextCursor"`
	Truncated  bool          `json:"truncated"`
}

// FolderEntry is one entry from FoldersList or FoldersStat.
type FolderEntry struct {
	Name  string `json:"name"`
	Path  string `json:"path"`
	Dir   bool   `json:"dir"`
	Size  int64  `json:"size,omitempty"`
	Mtime int64  `json:"mtime,omitempty"` // unix seconds
}

// Event is one normalized Ether event (SPEC §5.7). Payload is JSON with no
// secrets; viewer identity appears only for plugins granted it (the host
// strips it per plugin at delivery).
type Event struct {
	ID       string          `json:"id"`
	Name     string          `json:"name"`
	At       time.Time       `json:"at"`
	ViewerID int64           `json:"viewerId,omitempty"`
	Payload  json.RawMessage `json:"payload,omitempty"`
}

type FolderRootsChangedPayload struct {
	Roots []string `json:"roots"`
}

// KnownEvents is the closed v1 event set.
var KnownEvents = map[string]bool{
	EventPlaybackStarted: true, EventPlaybackPaused: true, EventPlaybackResumed: true,
	EventPlaybackStopped: true, EventPlaybackCompleted: true, EventPlaybackError: true,
	EventPlaybackFailover: true, EventTitleAvailable: true, EventViewerAdded: true,
	EventViewerAccess: true, EventCollectionRebuilt: true, EventServerHealth: true,
}

// ClientCaps is what the playing client can show.
type ClientCaps struct {
	MaxHeight int      `json:"maxHeight,omitempty"`
	HDR       []string `json:"hdr,omitempty"`
	Codecs    []string `json:"codecs,omitempty"`
}

// Catalogue is the signed catalogue hook used by the owner API, install
// and update flows (WS12).
type Catalogue interface {
	http.Handler
	// Resolve looks up a plugin in the verified catalogue by plugin ID (or
	// artifact URL) and optional version (empty means latest). It fails when
	// the plugin is not in the catalogue or is revoked.
	Resolve(ctx context.Context, idOrURL, version string) (CatalogueArtifact, error)
}

// RateLimitError reports a rate-limited host call together with when the
// plugin may retry (for example, UTC midnight for a daily allowance). It wraps
// ErrRateLimited so callers checking errors.Is(err, ErrRateLimited) match.
type RateLimitError struct {
	Message    string
	RetryAt    time.Time
	RetryAfter time.Duration
}

func (e *RateLimitError) Error() string {
	if e == nil {
		return ErrRateLimited.Error()
	}
	msg := strings.TrimSpace(e.Message)
	if msg == "" {
		msg = ErrRateLimited.Error()
	}
	if !e.RetryAt.IsZero() {
		return fmt.Sprintf("%s (retry after %s)", msg, e.RetryAt.UTC().Format(time.RFC3339))
	}
	if sec := e.RetryAfterSeconds(time.Now()); sec > 0 {
		return fmt.Sprintf("%s (retry in %ds)", msg, sec)
	}
	return msg
}

// RetryAfterSeconds returns the positive whole-second delay until the limit
// resets (at least 1 second when a retry window is set).
func (e *RateLimitError) RetryAfterSeconds(now time.Time) int64 {
	if e == nil {
		return 0
	}
	d := e.RetryAfter
	if d <= 0 && !e.RetryAt.IsZero() {
		d = e.RetryAt.Sub(now)
	}
	if d <= 0 {
		if !e.RetryAt.IsZero() {
			return 1
		}
		return 0
	}
	sec := int64((d + time.Second - 1) / time.Second)
	if sec < 1 {
		return 1
	}
	return sec
}

// FieldError is one validation problem, keyed by a dotted field path.
type FieldError struct {
	Field   string `json:"field"`
	Message string `json:"message"`
}

func (e *ValidationError) Error() string {
	if len(e.Fields) == 0 {
		return "plugins: invalid"
	}
	return fmt.Sprintf("plugins: invalid: %s: %s", e.Fields[0].Field, e.Fields[0].Message)
}

// MetadataMeta declares a provider of canonical catalogue records. Resolution
// happens during explicit materialization, never as part of ordinary browsing.
// Ether-native providers implement POST /ether/metadata/resolve using
// core.MetadataRequest and a {"title": core.Title} response.
type MetadataMeta struct {
	Types []string `json:"types"`
}

// DirectoryMeta declares a protocol-neutral plugin discovery source.
// Entries are suggestions, never installation authorization or verification.
type DirectoryMeta struct {
	Key   string `json:"key"`
	Label string `json:"label"`
}

// OnAirFeed declares a bounded household feed. MaxAge is a Go duration.
type OnAirFeed struct {
	ID     string            `json:"id"`
	Fields map[string]string `json:"fields"`
	Sample map[string]any    `json:"sample,omitempty"`
	MaxAge string            `json:"maxAge"`
}

// OnAirSegment is a fixed-duration declarative scene, never arbitrary video.
type OnAirSegment struct {
	ID       string   `json:"id"`
	Name     string   `json:"name"`
	Duration int      `json:"duration"`
	File     string   `json:"file"`
	Feeds    []string `json:"feeds"`
	Rating   string   `json:"rating,omitempty"`
}

// textOf converts a manifest label ("$t:key" or plain text) to registry
// Text. Plain plugin text is carried as Resolved so the console shows it
// without a catalogue entry; $t: keys resolve through plugin strings.
func textOf(plugin, s string) extend.Text {
	if strings.HasPrefix(s, "$t:") {
		return extend.PluginText(plugin, strings.TrimPrefix(s, "$t:"))
	}
	return extend.Text{Resolved: s}
}

// DescriptorsFor builds the registry descriptors a manifest contributes.
// Exported for the kit and Studio previews.
func DescriptorsFor(man Manifest) []extend.Descriptor {
	isStremio := man.SpeaksStremio()
	man.Ether = man.EffectiveEther()
	id := man.ID
	c := man.Ether.Contributes
	var out []extend.Descriptor
	add := func(kind extend.Kind, key string, label extend.Text, meta any) {
		d := extend.Descriptor{Kind: kind, ID: extend.PluginID(id, key), Owner: id, Label: label, Group: man.Name}
		if meta != nil {
			d = d.WithMeta(meta)
		}
		out = append(out, d)
	}
	if man.HasCapability(CapOnAirContent) {
		for _, seg := range c.OnAirSegments {
			add(extend.KindOnAirSegment, seg.ID, textOf(id, seg.Name), map[string]any{"duration": seg.Duration, "rating": seg.Rating, "feeds": seg.Feeds})
		}
	}
	for _, p := range c.Pages {
		meta := map[string]any{"route": p.Route, "pluginRoute": "/api/plugins/" + id + "/views/" + p.Key, "icon": p.Icon}
		if p.Group != "" {
			meta["group"] = p.Group
		}
		add(extend.KindPage, p.Key, textOf(id, p.Label), meta)
		add(extend.KindNavItem, "page-"+p.Key, textOf(id, p.Label), map[string]any{
			"route": "/plugins/" + id + "/" + p.Key, "pageKey": p.Key})
	}
	for _, s := range c.Slots {
		add(extend.KindSlot, s.Key, textOf(id, s.Label), map[string]any{"slot": s.Slot, "route": s.Route, "action": s.Action, "key": s.Key})
	}
	for _, cm := range c.Commands {
		add(extend.KindCommand, cm.Key, textOf(id, cm.Label), map[string]any{"action": cm.Action})
	}
	for _, rs := range c.RankingSteps {
		add(extend.KindRankingStep, rs.Key, textOf(id, rs.Label), map[string]any{
			"editor": rs.Editor, "budget": rs.Budget, "hint": rs.Hint})
	}
	for _, rc := range c.RuleConditions {
		add(extend.KindRuleField, rc.Key, textOf(id, rc.Label), map[string]any{
			"operators": rc.Operators, "editor": rc.Editor})
	}
	if man.HasCapability(CapPosterBadges) {
		for _, pb := range c.PosterBadges {
			d := extend.Descriptor{
				Kind:  extend.KindPosterBadge,
				ID:    extend.PluginID(id, pb.Key),
				Owner: id,
				Label: textOf(id, pb.Label),
				Group: man.Name,
			}
			if pb.Description != "" {
				d.Hint = textOf(id, pb.Description)
			}
			out = append(out, d.WithMeta(map[string]any{
				"key":        pb.Key,
				"layerKey":   "plugin:" + id + ":" + pb.Key,
				"pluginName": man.Name,
			}))
		}
	}
	for _, ls := range c.ListSources {
		if !man.HasCapability(CapListSource) {
			continue
		}
		pid := extend.PluginID(id, ls.Key)
		fields, defaults := ParamFieldsFromList(id, ParseListParamFields(ls.Params))
		var values map[string]any
		_ = json.Unmarshal([]byte(defaults), &values)
		sourceDefaults := map[string]any{}
		if len(values) > 0 {
			sourceDefaults["params"] = values
		}
		meta := map[string]any{
			"catalog":          ls.Catalog,
			"params":           fields,
			"editor":           "plugin",
			"defaults":         sourceDefaults,
			"maxItems":         ls.MaxItems,
			"refresh":          ls.Refresh,
			"hint":             ls.Hint,
			"hubId":            pid,
			"rowKind":          pid,
			"collectionSource": pid,
			"sections":         []string{"home", "movies", "shows"},
		}
		dCol := extend.Descriptor{Kind: extend.KindCollectionSource, ID: pid, Owner: id, Label: textOf(id, ls.Label), Group: man.Name}
		dRow := extend.Descriptor{Kind: extend.KindRowSource, ID: pid, Owner: id, Label: textOf(id, ls.Label), Group: man.Name}
		if ls.Hint != "" {
			h := textOf(id, ls.Hint)
			dCol.Hint, dRow.Hint = h, h
		}
		out = append(out, dCol.WithMeta(meta), dRow.WithMeta(meta))
	}
	if man.HasCapability(CapLiveTV) && c.Channels != nil {
		add(extend.KindLiveTVSource, "channels", textOf(id, man.Name), map[string]any{
			"refresh": c.Channels.Refresh, "yieldsChannels": true, "yieldsGuide": true})
	}
	if man.HasCapability(CapNotify) && c.Notification != nil {
		add(extend.KindChannelKind, "notify", textOf(id, man.Name), map[string]any{
			"fields": notificationFields(id, c.Notification.Fields), "sendTest": c.Notification.SendTest, "selectable": true, "formats": c.Notification.Formats, "maxLength": c.Notification.MaxLength})
	}
	if man.HasCapability(CapPluginDirectory) {
		for _, d := range c.Directories {
			add(extend.KindPluginDirectory, d.Key, textOf(id, d.Label), map[string]any{"key": d.Key})
		}
	}
	if man.HasCapability(CapMetadata) && c.Metadata != nil {
		add(extend.KindMetadataProvider, "metadata", textOf(id, man.Name), c.Metadata)
	}
	if man.HasCapability(CapSubtitles) && c.Subtitles != nil {
		meta := map[string]any{
			"languages": c.Subtitles.Languages,
			"formats":   c.Subtitles.Formats,
		}
		if isStremio {
			meta["stremio"] = true
		}
		add(extend.KindSubtitleProvider, "subtitles", textOf(id, man.Name), meta)
	}
	if man.HasCapability(CapMarkers) && c.Markers != nil {
		add(extend.KindMarkerSource, "markers", textOf(id, man.Name), map[string]any{"kinds": c.Markers.Kinds})
	}
	if man.HasCapability(CapStreamSource) && c.Source != nil {
		cfg := map[string]any{"class": c.Source.Class, "abilities": c.Source.Abilities, "limits": c.Source.Limits}
		if c.Source.Search != nil {
			cfg["search"] = c.Source.Search
		}
		add(extend.KindSourceKind, "stream", textOf(id, man.Name), cfg)
	}
	if man.HasCapability(CapDebridProvider) && c.Source != nil {
		add(extend.KindSourceKind, "debrid", textOf(id, man.Name), map[string]any{"class": "debrid", "abilities": c.Source.Abilities})
	}
	if man.Ether.Kind == KindIntegration && c.Integration != nil {
		add(extend.KindIntegration, "integration", textOf(id, man.Name), map[string]any{
			"category": c.Integration.Category, "adds": c.Integration.Adds, "connect": c.Integration.Connect, "logo": c.Integration.Logo})
	}
	for _, tl := range c.Tools {
		add(extend.KindTool, tl.Name, textOf(id, tl.Title), map[string]any{
			"name": ToolName(id, tl.Name), "readOnly": tl.ReadOnly && man.RuntimeKind() == "hosted", "destructive": tl.Destructive, "openWorld": tl.OpenWorld})
	}
	return out
}

// ToolName namespaces a plugin tool for the catalogue: dots and dashes
// become underscores ("<plugin>__<name>").
func ToolName(plugin, name string) string {
	p := strings.NewReplacer(".", "_", "-", "_").Replace(plugin)
	return p + "__" + name
}

// syncDescriptors replaces a plugin's registry descriptors and tools to
// match its record: none while disabled.
func (m *Manager) syncDescriptors(ctx context.Context, r Record) {
	if !r.Enabled {
		m.deps.OnAirContent.RemovePlugin(r.ID)
	} else {
		m.deps.OnAirContent.EnablePlugin(r.ID)
	}
	m.indexEventSubscriptions(r)
	m.syncNotificationKind(r)
	m.mu.Lock()
	m.shadow[r.ID] = r.Shadow
	m.mu.Unlock()
	m.syncPosterBadgeSets(ctx, r)
	m.syncLiveFeeds(ctx, r)
	m.syncFlowsPlugin(ctx, r)
	if m.deps.Registry != nil {
		var ds []extend.Descriptor
		if r.Enabled {
			ds = DescriptorsFor(r.Manifest)
		}
		if err := m.deps.Registry.ReplaceOwner(r.ID, ds); err != nil {
			m.log.Warn("plugins: registry sync", "plugin", r.ID, "err", err)
		}
	}
	if m.deps.Tools != nil {
		var ts []tools.Tool
		if r.Enabled && r.Manifest.Ether != nil {
			for _, tl := range r.Manifest.Ether.Contributes.Tools {
				ts = append(ts, m.pluginTool(r, tl))
			}
		}
		if err := m.deps.Tools.ReplaceOwner(r.ID, ts); err != nil {
			m.log.Warn("plugins: tool sync", "plugin", r.ID, "err", err)
		}
	}
	m.mu.Lock()
	hooks := append([]func(context.Context, Record){}, m.syncHooks...)
	m.mu.Unlock()
	for _, fn := range hooks {
		fn(ctx, r)
	}
	m.prewarmHot(r)
}

// pluginTool adapts one contributed tool to the catalogue. Read-only tools
// execute through /ether/tool/{name}; writes return a Proposal whose
// Apply runs the call after owner approval (SPEC §5.10). Hosted read-only
// calls carry a host-enforced write restriction; remote tools always require
// approval because a sidecar can write independently of the current call.
func (m *Manager) pluginTool(r Record, tl ToolMeta) tools.Tool {
	pluginID, name := r.ID, tl.Name
	readOnly := tl.ReadOnly && r.Manifest.RuntimeKind() == "hosted"
	title := tl.Title
	if strings.HasPrefix(title, "$t:") {
		title = name
	}
	run := func(ctx context.Context, input map[string]any) (tools.Result, error) {
		body, err := json.Marshal(input)
		if err != nil {
			return tools.Result{}, err
		}
		resp, err := m.Call(ctx, pluginID, Request{Method: "POST", Path: "/ether/tool/" + name, Body: body})
		if err != nil {
			return tools.Result{}, tools.Userf("Plugin %s tool %s failed.", pluginID, name)
		}
		if resp.Status >= 300 {
			return tools.Result{}, tools.Userf("Plugin %s tool %s failed with status %d.", pluginID, name, resp.Status)
		}
		if len(resp.Body) > 64*1024 {
			return tools.Result{}, tools.Userf("Plugin tool output is too large.")
		}
		var data map[string]any
		if len(resp.Body) > 0 {
			if err := json.Unmarshal(resp.Body, &data); err != nil {
				return tools.Result{}, tools.Userf("Plugin tool returned invalid output.")
			}
		}
		encoded, err := json.Marshal(data)
		if err != nil {
			return tools.Result{}, tools.Userf("Plugin tool returned invalid output.")
		}
		clean := m.store.redactKnown(ctx, pluginID, string(encoded))
		if err := json.Unmarshal([]byte(clean), &data); err != nil {
			return tools.Result{}, tools.Userf("Plugin tool output could not be safely displayed.")
		}
		redactValue(data)
		return tools.Result{Data: data}, nil
	}
	return tools.Tool{
		Name: ToolName(pluginID, name), Title: title, Description: tl.Description,
		InputSchema: tl.InputSchema, ReadOnly: readOnly, Destructive: tl.Destructive,
		OpenWorld: tl.OpenWorld, Audience: tools.AudienceOwner, Owner: pluginID,
		Execute: func(ctx context.Context, _ tools.Principal, input map[string]any) (tools.Result, error) {
			encoded, err := json.Marshal(input)
			if err != nil || len(encoded) > 64*1024 {
				return tools.Result{}, tools.Userf("Tool input is invalid or too large.")
			}
			var snapshot map[string]any
			if err := json.Unmarshal(encoded, &snapshot); err != nil {
				return tools.Result{}, tools.Userf("Tool input is invalid.")
			}
			if err := agent.ValidateToolInput(tl.InputSchema, snapshot); err != nil {
				return tools.Result{}, tools.Userf("Invalid tool input: %s", err)
			}
			if readOnly {
				return run(context.WithValue(ctx, readOnlyToolContextKey{}, true), snapshot)
			}
			return tools.Result{Proposal: &tools.Proposal{
				Category:    fmt.Sprintf("Run %s from %s", title, r.Name),
				Description: tl.Description,
				Input:       snapshot,
				Apply: func(ctx context.Context) (tools.Result, error) {
					var approved map[string]any
					if err := json.Unmarshal(encoded, &approved); err != nil {
						return tools.Result{}, err
					}
					return run(ctx, approved)
				},
			}}, nil
		},
	}
}

// PermissionSheet returns the plain-language lines the owner sees at
// install (SPEC §5.4). needsViewers and needsFolders say the sheet needs
// viewer or folder picks.
func PermissionSheet(man Manifest) (lines []string, needsViewers, needsFolders bool) {
	if man.Ether != nil && man.Ether.Runtime.Kind == "data" {
		return []string{"Adds channel styles and licensed artwork. Runs no code."}, false, false
	}
	if man.Ether == nil {
		lines = []string{"Connects to the add-on address you gave"}
		if n := man.ListItemsRequested(); n > 0 {
			lines = append(lines, listItemsLine(n))
		}
		return lines, false, false
	}
	if man.Ether.Stremio {
		lines = append(lines, "Connects to the add-on it was made from")
	}
	p := man.Ether.Permissions
	var localHosts []string
	for _, h := range p.Network {
		switch {
		case strings.EqualFold(strings.TrimSpace(h), OperatorNetworkEntry):
			lines = append(lines, "Connects to addresses you approve")
		case IsLocalNetworkHost(h):
			localHosts = append(localHosts, h)
		default:
			lines = append(lines, "Connects to "+h)
		}
	}
	if len(localHosts) > 0 {
		lines = append(lines, "May reach on your network: "+strings.Join(localHosts, ", "))
	}
	if normLevel(p.Catalog) == "read" {
		lines = append(lines, "Reads your catalogue")
	}
	if normLevel(p.Viewers.Identity) != "none" {
		lines = append(lines, "Sees who is watching (viewers you choose)")
		needsViewers = needsViewers || normLevel(p.Viewers.Identity) == "granted_viewers"
	}
	if normLevel(p.Viewers.WatchHistory) != "none" {
		lines = append(lines, "Reads watch history")
		needsViewers = needsViewers || normLevel(p.Viewers.WatchHistory) == "granted_viewers"
	}
	if normLevel(p.Viewers.WriteWatchState) != "none" {
		lines = append(lines, "Marks titles watched")
		needsViewers = true
	}
	if normLevel(p.Collections) == "write" {
		lines = append(lines, "Creates and updates collections")
	}
	if normLevel(p.Folders) == "read" {
		lines = append(lines, "Reads folders you choose")
		needsFolders = true
	}
	if SourcesPermissionAllowsAcquire(p.Sources) {
		lines = append(lines, "Searches your indexers and opens sources through your debrid accounts")
	} else if SourcesPermissionAllowsSearch(p.Sources) {
		lines = append(lines, "Searches your indexers for sources")
	}
	if SourcesPermissionAllowsBackgroundCheck(p.Sources) {
		lines = append(lines, "Checks Usenet releases in the background within a daily allowance")
	}
	switch normLevel(p.AI) {
	case "complete":
		lines = append(lines, "Uses your configured language model")
	case "complete+search":
		lines = append(lines, "Uses your configured language model")
		lines = append(lines, "Uses your language model while a viewer searches")
	}
	if allowsDurableStorage(storagePermission(man)) {
		lines = append(lines, DurableStoragePermissionLine)
	}
	if normLevel(p.Media) == "probe" {
		lines = append(lines, "Probes media container metadata")
	}
	for _, k := range man.Ether.Contributes.MediaKinds {
		if !k.HasLibrary() {
			continue
		}
		name := k.Library.Name
		if strings.HasPrefix(name, "$t:") {
			name = k.Key
		}
		lines = append(lines, "Adds a library: "+name)
	}
	for _, sc := range man.Ether.Contributes.Screens {
		title := sc.Title
		if strings.HasPrefix(title, "$t:") {
			title = sc.ID
		}
		lines = append(lines, "Adds a screen: "+title)
	}
	for range p.Secrets {
		lines = append(lines, "Stores an access token")
	}
	if man.HasCapability(CapEvents) {
		ev := man.Ether.Contributes.Events
		if ev == nil || len(ev.Subscribe) > 0 || len(ev.Publish) == 0 {
			lines = append(lines, "Gets play and new-release events")
		}
		if ev != nil && len(ev.Publish) > 0 {
			lines = append(lines, "Publishes custom events to Flows")
		}
	}
	if man.HasCapability(CapFlowActions) {
		lines = append(lines, "Adds actions to Flows")
	}
	if man.HasCapability(CapPosterBadges) {
		lines = append(lines, "Adds badges to library posters")
	}
	if man.HasCapability(CapLiveEvents) {
		lines = append(lines, "Provides live event feeds")
	}
	if man.HasCapability(CapScreens) {
		lines = append(lines, screensPermissionLine(man))
	}
	if man.HasCapability(CapDebridCacheHints) {
		lines = append(lines, "Gets the torrents you are about to play and says which are cached")
	}
	if len(lines) == 0 {
		lines = []string{"Needs no access to your server or the network"}
	}
	if n := man.ListItemsRequested(); n > 0 {
		lines = append(lines, listItemsLine(n))
	}
	return lines, needsViewers, needsFolders
}

// PermissionDiff lists the permissions `next` asks for that `cur` does
// not have. A non-empty result pauses auto-update and asks the owner.
func PermissionDiff(cur, next Manifest) []string {
	if cur.Ether == nil || next.Ether == nil {
		if next.Ether != nil {
			lines, _, _ := PermissionSheet(next)
			return lines
		}
		return nil
	}
	a, b := cur.Ether.Permissions, next.Ether.Permissions
	var added []string
	have := map[string]bool{}
	for _, h := range a.Network {
		have[h] = true
	}
	var addedLocal []string
	for _, h := range b.Network {
		if !have[h] {
			switch {
			case strings.EqualFold(strings.TrimSpace(h), OperatorNetworkEntry):
				added = append(added, "Connects to addresses you approve")
			case IsLocalNetworkHost(h):
				addedLocal = append(addedLocal, h)
			default:
				added = append(added, "Connects to "+h)
			}
		}
	}
	if len(addedLocal) > 0 {
		added = append(added, "May reach on your network: "+strings.Join(addedLocal, ", "))
	}
	level := map[string]int{"none": 0, "granted_viewers": 1, "read": 1, "write": 1, "complete": 1, "probe": 1, "all": 2}
	raised := func(x, y string) bool { return level[normLevel(y)] > level[normLevel(x)] }
	if raised(a.Catalog, b.Catalog) {
		added = append(added, "Reads your catalogue")
	}
	if raised(a.Viewers.Identity, b.Viewers.Identity) {
		added = append(added, "Sees who is watching (viewers you choose)")
	}
	if raised(a.Viewers.WatchHistory, b.Viewers.WatchHistory) {
		added = append(added, "Reads watch history")
	}
	if raised(a.Viewers.WriteWatchState, b.Viewers.WriteWatchState) {
		added = append(added, "Marks titles watched")
	}
	if raised(a.Collections, b.Collections) {
		added = append(added, "Creates and updates collections")
	}
	if raised(a.Folders, b.Folders) {
		added = append(added, "Reads folders you choose")
	}
	if !allowsDurableStorage(normLevel(string(a.Storage))) && allowsDurableStorage(normLevel(string(b.Storage))) {
		added = append(added, DurableStoragePermissionLine)
	}
	if raised(a.Media, b.Media) {
		added = append(added, "Probes media container metadata")
	}
	aiLevel := map[string]int{"none": 0, "complete": 1, "complete+search": 2}
	if aiLevel[normLevel(b.AI)] > aiLevel[normLevel(a.AI)] {
		if aiLevel[normLevel(a.AI)] == 0 {
			added = append(added, "Uses your configured language model")
		}
		if normLevel(b.AI) == "complete+search" {
			added = append(added, "Uses your language model while a viewer searches")
		}
	}
	sourcesBase := func(l string) int {
		switch {
		case SourcesPermissionAllowsAcquire(l):
			return 2
		case SourcesPermissionAllowsSearch(l):
			return 1
		default:
			return 0
		}
	}
	if sourcesBase(b.Sources) > sourcesBase(a.Sources) {
		if SourcesPermissionAllowsAcquire(b.Sources) {
			added = append(added, "Searches your indexers and opens sources through your debrid accounts")
		} else {
			added = append(added, "Searches your indexers for sources")
		}
	}
	if !SourcesPermissionAllowsBackgroundCheck(a.Sources) && SourcesPermissionAllowsBackgroundCheck(b.Sources) {
		added = append(added, "Checks Usenet releases in the background within a daily allowance")
	}
	haveKindLib := map[string]bool{}
	for _, k := range cur.Ether.Contributes.MediaKinds {
		if k.HasLibrary() {
			haveKindLib[k.Key] = true
		}
	}
	for _, k := range next.Ether.Contributes.MediaKinds {
		if k.HasLibrary() && !haveKindLib[k.Key] {
			name := k.Library.Name
			if strings.HasPrefix(name, "$t:") {
				name = k.Key
			}
			added = append(added, "Adds a library: "+name)
		}
	}
	haveSecret := map[string]bool{}
	for _, s := range a.Secrets {
		haveSecret[s] = true
	}
	for _, s := range b.Secrets {
		if !haveSecret[s] {
			added = append(added, "Stores an access token")
		}
	}
	if !cur.HasCapability(CapEvents) && next.HasCapability(CapEvents) {
		ev := next.Ether.Contributes.Events
		if ev == nil || len(ev.Subscribe) > 0 || len(ev.Publish) == 0 {
			added = append(added, "Gets play and new-release events")
		}
		if ev != nil && len(ev.Publish) > 0 {
			added = append(added, "Publishes custom events to Flows")
		}
	} else if cur.HasCapability(CapEvents) && next.HasCapability(CapEvents) {
		curPub := cur.Ether.Contributes.Events != nil && len(cur.Ether.Contributes.Events.Publish) > 0
		nextPub := next.Ether.Contributes.Events != nil && len(next.Ether.Contributes.Events.Publish) > 0
		if !curPub && nextPub {
			added = append(added, "Publishes custom events to Flows")
		}
	}
	if !cur.HasCapability(CapFlowActions) && next.HasCapability(CapFlowActions) {
		added = append(added, "Adds actions to Flows")
	}
	if !cur.HasCapability(CapPosterBadges) && next.HasCapability(CapPosterBadges) {
		added = append(added, "Adds badges to library posters")
	}
	if !cur.HasCapability(CapLiveEvents) && next.HasCapability(CapLiveEvents) {
		added = append(added, "Provides live event feeds")
	}
	if !cur.HasCapability(CapScreens) && next.HasCapability(CapScreens) {
		added = append(added, screensPermissionLine(next))
	}
	if !cur.HasCapability(CapDebridCacheHints) && next.HasCapability(CapDebridCacheHints) {
		added = append(added, "Gets the torrents you are about to play and says which are cached")
	}
	// Cover every remaining capability so a silent update or catalogue entry
	// mismatch cannot add new capabilities without owner approval.
	handledCaps := map[Capability]bool{
		CapEvents: true, CapFlowActions: true, CapPosterBadges: true,
		CapLiveEvents: true, CapScreens: true, CapDebridCacheHints: true,
	}
	for _, cap := range next.EffectiveEther().Capabilities {
		if handledCaps[cap] || cur.HasCapability(cap) {
			continue
		}
		added = append(added, capabilityPermissionLine(cap))
	}
	haveTools := map[string]bool{}
	for _, tl := range cur.Ether.Contributes.Tools {
		haveTools[tl.Name] = true
	}
	for _, tl := range next.Ether.Contributes.Tools {
		if !haveTools[tl.Name] {
			added = append(added, "Adds tool: "+tl.Name)
		}
	}
	added = append(added, runtimeLimitDiff(cur.Ether.Runtime.Limits, next.Ether.Runtime.Limits)...)
	if n := next.ListItemsRequested(); n > cur.ListItemsRequested() {
		added = append(added, listItemsLine(n))
	}
	return added
}

func runtimeLimitDiff(cur, next *RuntimeLimits) []string {
	if next == nil {
		return nil
	}
	var a RuntimeLimits
	if cur != nil {
		a = *cur
	}
	b := *next
	var added []string
	if b.MemoryBytes > a.MemoryBytes {
		added = append(added, fmt.Sprintf("Raises memory limit to %d bytes", b.MemoryBytes))
	}
	if b.FetchBytes > a.FetchBytes {
		added = append(added, fmt.Sprintf("Raises fetch size limit to %d bytes", b.FetchBytes))
	}
	if b.ReadBytes > a.ReadBytes {
		added = append(added, fmt.Sprintf("Raises read size limit to %d bytes", b.ReadBytes))
	}
	if b.ArchiveMemberBytes > a.ArchiveMemberBytes {
		added = append(added, fmt.Sprintf("Raises archive member limit to %d bytes", b.ArchiveMemberBytes))
	}
	if b.ArchiveExpandedBytes > a.ArchiveExpandedBytes {
		added = append(added, fmt.Sprintf("Raises archive expanded limit to %d bytes", b.ArchiveExpandedBytes))
	}
	if b.ArchiveMembers > a.ArchiveMembers {
		added = append(added, fmt.Sprintf("Raises archive member count limit to %d", b.ArchiveMembers))
	}
	if b.MaxItems > a.MaxItems {
		added = append(added, fmt.Sprintf("Raises stored items limit to %d", b.MaxItems))
	}
	if b.UnitBudget > a.UnitBudget {
		added = append(added, fmt.Sprintf("Raises compute budget limit to %d", b.UnitBudget))
	}
	if b.PoolSize > a.PoolSize {
		added = append(added, fmt.Sprintf("Raises instance pool size to %d", b.PoolSize))
	}
	if b.Deadline != "" && b.Deadline != a.Deadline {
		bd, bErr := time.ParseDuration(b.Deadline)
		ad, aErr := time.ParseDuration(a.Deadline)
		if bErr == nil && (a.Deadline == "" || aErr != nil || bd > ad) {
			added = append(added, "Raises call deadline to "+b.Deadline)
		}
	}
	return added
}

// IsSubscribableEvent reports whether name is either one of the 12 legacy
// EPP/1 event names or a valid canonical event type ("domain.noun.verb" or
// "plugin:<pluginId>/<key>").
func IsSubscribableEvent(name string) bool {
	return KnownEvents[name] || events.ValidateType(name) == nil
}

func newEventID() string {
	var b [8]byte
	_, _ = rand.Read(b[:])
	return hex.EncodeToString(b[:])
}

// Publish normalizes and fans out one Ether event: it is written to the
// 7-day event log and queued for every enabled plugin that subscribed to
// it (and was not revoked). Viewer identity is stripped per plugin unless
// the plugin's grants allow it. Both legacy EPP/1 names and canonical
// domain.noun.verb names are accepted and bridged to matching subscribers.
func (m *Manager) Publish(ctx context.Context, ev Event) {
	if ev.Name == EventPluginFoldersChanged || !IsSubscribableEvent(ev.Name) {
		return
	}
	names := []string{ev.Name}
	if canonical, ok := LegacyToCanonicalEvent[ev.Name]; ok {
		names = append(names, canonical)
	} else if legacy, ok := CanonicalToLegacyEvent[ev.Name]; ok {
		names = append(names, legacy)
	}
	if ev.ID == "" {
		ev.ID = newEventID()
	}
	if ev.At.IsZero() {
		ev.At = m.now()
	}
	canonicalType := ev.Name
	if c, ok := LegacyToCanonicalEvent[ev.Name]; ok {
		canonicalType = c
	}
	m.fanOutEvent(ctx, canonicalType, names, ev, "")
}

// StartEventBridge subscribes the plugin host to Ether's events.Bus so plugins
// receive both canonical event types and translated legacy 12 event names
// without blocking publishers. Safe to call multiple times; returns a function
// that detaches the bridge subscription.
func (m *Manager) StartEventBridge(ctx context.Context) func() {
	bus := m.flowsEventBus()
	if bus == nil {
		return func() {}
	}
	m.eventBridgeMu.Lock()
	if m.eventBridgeSub != nil {
		m.eventBridgeMu.Unlock()
		return func() {}
	}
	sub := bus.SubscribeFunc(ctx, events.SubscriptionOptions{
		Name:   "plugins.bridge",
		Buffer: events.DefaultSubscriberBuffer,
	}, m.HandleBusEvent)
	m.eventBridgeSub = sub
	m.eventBridgeMu.Unlock()
	return func() {
		m.eventBridgeMu.Lock()
		if m.eventBridgeSub == sub {
			m.eventBridgeSub = nil
		}
		m.eventBridgeMu.Unlock()
		sub.Unsubscribe()
	}
}

// HandleBusEvent delivers one events.Bus envelope to any enabled plugin
// subscribed to its canonical type or mapped legacy EPP/1 event name.
// When no plugin subscribes to either name it does zero database work.
func (m *Manager) HandleBusEvent(ctx context.Context, env events.Envelope) {
	if env.Meta.DryRun || env.Type == "" || env.Type == EventPluginFoldersChanged {
		return
	}
	names := []string{env.Type}
	if legacy, ok := CanonicalToLegacyEvent[env.Type]; ok {
		names = append(names, legacy)
	}
	viewerID := env.Correlation.ViewerID
	if viewerID == 0 {
		viewerID = viewerIDFromPayload(env.Payload)
	}
	at := env.OccurredAt
	if at.IsZero() {
		at = m.now()
	}
	id := env.ID
	if id == "" {
		id = newEventID()
	}
	payload := env.Payload
	if len(payload) == 0 {
		payload = json.RawMessage(`{}`)
	}
	m.fanOutEvent(ctx, env.Type, names, Event{
		ID:       id,
		Name:     env.Type,
		At:       at,
		ViewerID: viewerID,
		Payload:  payload,
	}, env.Source)
}

type eventDeliveryTarget struct {
	rec  Record
	name string
}

func (m *Manager) fanOutEvent(ctx context.Context, canonicalType string, names []string, base Event, source string) {
	m.mu.Lock()
	var targets []eventDeliveryTarget
	for _, name := range names {
		for _, r := range m.eventSubs[name] {
			targets = append(targets, eventDeliveryTarget{rec: r, name: name})
		}
	}
	m.mu.Unlock()
	if len(targets) == 0 {
		return
	}

	reg, _ := m.flowsRegistries()
	var schema events.EventSchema
	hasSchema := false
	if reg != nil && canonicalType != "" {
		schema, hasSchema = reg.Get(canonicalType)
	}

	var producer, itemOwner string
	switch canonicalType {
	case events.EventViewerWatchScrobbled, events.EventViewerWatchWatched, events.EventViewerWatchUnwatched, events.EventViewerWatchProgress:
		if id, ok := strings.CutPrefix(source, events.PluginPrefix); ok {
			producer = id
		}
		var item struct {
			Ref core.ItemRef `json:"itemRef"`
		}
		if json.Unmarshal(base.Payload, &item) == nil {
			itemOwner = item.Ref.Plugin()
		}
	}

	logged := false
	for _, target := range targets {
		r := target.rec
		if r.ID == producer || !r.Enabled || r.Manifest.Ether == nil || !r.Manifest.HasCapability(CapEvents) {
			continue
		}
		sub := false
		if evMeta := r.Manifest.Ether.Contributes.Events; evMeta != nil {
			for _, n := range evMeta.Subscribe {
				if n == target.name {
					sub = true
					break
				}
			}
		}
		if !sub {
			continue
		}
		g, err := m.store.grants(ctx, r.ID)
		if err != nil || g.revoked("events") {
			continue
		}
		out := base
		out.Name = target.name
		if !logged {
			m.store.logEvent(ctx, out)
			logged = true
		}
		allowViewer := viewerOK(g, normLevel(r.Manifest.Ether.Permissions.Viewers.Identity), base.ViewerID)
		if !allowViewer {
			out.ViewerID = 0
		}
		out.Payload = sanitizePluginEventPayload(out.Payload, schema, hasSchema, allowViewer)
		if itemOwner != "" && itemOwner != r.ID {
			if fields, err := (events.Envelope{Payload: out.Payload}).PayloadMap(); err == nil {
				delete(fields, "itemRef")
				out.Payload, _ = json.Marshal(fields)
			}
		}
		dropped, err := m.store.enqueue(ctx, r.ID, out)
		if err == nil {
			m.noteOutboxDrops(ctx, r, dropped)
		}
	}
}

func (m *Manager) noteOutboxDrops(ctx context.Context, r Record, dropped int) {
	if dropped <= 0 {
		return
	}
	m.healthMu.Lock()
	if h, err := m.store.health(ctx, r.ID); err == nil {
		h.Drops += int64(dropped)
		_ = m.store.putHealth(ctx, r.ID, h)
	}
	m.healthMu.Unlock()
	m.emitBusEvent(events.EventPluginQuotaExceeded, r.ID, events.PluginQuotaExceededPayload{
		PluginID:  r.ID,
		Name:      r.Name,
		QuotaKind: "events_outbox",
		Used:      int64(OutboxCap),
		Limit:     int64(OutboxCap),
		Drops:     int64(dropped),
	}, false)
}

func sanitizePluginEventPayload(raw json.RawMessage, schema events.EventSchema, hasSchema, allowViewer bool) json.RawMessage {
	payload := raw
	if hasSchema && len(payload) > 0 {
		if m, err := (events.Envelope{Payload: payload}).PayloadMap(); err == nil {
			redacted := schema.Redact(m, events.RedactOptions{StripPII: !allowViewer})
			if b, err := json.Marshal(redacted); err == nil {
				payload = b
			}
		}
	}
	if !allowViewer {
		payload = stripViewer(payload)
	}
	return payload
}

func viewerIDFromPayload(raw json.RawMessage) int64 {
	if len(raw) == 0 {
		return 0
	}
	var doc struct {
		ViewerID int64 `json:"viewerId"`
		Viewer   *struct {
			ID int64 `json:"id"`
		} `json:"viewer"`
	}
	if json.Unmarshal(raw, &doc) != nil {
		return 0
	}
	if doc.ViewerID > 0 {
		return doc.ViewerID
	}
	if doc.Viewer != nil && doc.Viewer.ID > 0 {
		return doc.Viewer.ID
	}
	return 0
}

// indexEventSubscriptions is updated together with the plugin's descriptors.
func (m *Manager) indexEventSubscriptions(r Record) {
	m.mu.Lock()
	defer m.mu.Unlock()
	for _, subscribers := range m.eventSubs {
		delete(subscribers, r.ID)
	}
	if !r.Enabled || r.Manifest.Ether == nil || !r.Manifest.HasCapability(CapEvents) || r.Manifest.Ether.Contributes.Events == nil {
		return
	}
	for _, name := range r.Manifest.Ether.Contributes.Events.Subscribe {
		if !IsSubscribableEvent(name) {
			continue
		}
		if m.eventSubs[name] == nil {
			m.eventSubs[name] = make(map[string]Record)
		}
		m.eventSubs[name][r.ID] = r
	}
}

func stripViewer(payload json.RawMessage) json.RawMessage {
	var doc any
	if json.Unmarshal(payload, &doc) != nil {
		return json.RawMessage(`{}`)
	}
	changed := false
	var strip func(any)
	strip = func(v any) {
		switch value := v.(type) {
		case map[string]any:
			for k, child := range value {
				lk := strings.ToLower(k)
				if strings.Contains(lk, "viewer") || strings.Contains(lk, "user") {
					delete(value, k)
					changed = true
				} else {
					strip(child)
				}
			}
		case []any:
			for _, child := range value {
				strip(child)
			}
		}
	}
	strip(doc)
	if !changed {
		return payload
	}
	out, err := json.Marshal(doc)
	if err != nil {
		return payload
	}
	return out
}

// NormalizePlayback maps a playback.Manager event kind to §5.7 names.
// state is the raw timeline state for updates (playing, paused, stopped).
// It returns "" for kinds with no normalized event.
func NormalizePlayback(kind, state string) string {
	switch kind {
	case "start", "started":
		return EventPlaybackStarted
	case "stop", "stopped":
		return EventPlaybackStopped
	case "completed", "complete":
		return EventPlaybackCompleted
	case "error":
		return EventPlaybackError
	case "failover", "downfailover":
		return EventPlaybackFailover
	case "update", "progress":
		switch state {
		case "paused":
			return EventPlaybackPaused
		case "playing":
			return EventPlaybackResumed
		}
	}
	return ""
}

// DeliverOutbox sends queued events to one plugin in batches of 50 and
// deletes the ones it acks. A missing ack keeps events for redelivery
// (at least once).
func (m *Manager) DeliverOutbox(ctx context.Context, pluginID string) error {
	for {
		evs, ids, err := m.store.outboxBatch(ctx, pluginID, 50)
		if err != nil || len(evs) == 0 {
			return err
		}
		body, _ := json.Marshal(map[string]any{"events": evs})
		resp, err := m.Call(ctx, pluginID, Request{Method: "POST", Path: "/ether/event", Body: body})
		if err != nil {
			return err
		}
		if resp.Status < 200 || resp.Status >= 300 {
			return fmt.Errorf("event delivery failed with status %d", resp.Status)
		}
		var out struct {
			Ack []string `json:"ack"`
		}
		_ = json.Unmarshal(resp.Body, &out)
		acked := map[string]bool{}
		for _, id := range out.Ack {
			acked[id] = true
		}
		var done []int64
		for i, ev := range evs {
			if acked[ev.ID] {
				done = append(done, ids[i])
			}
		}
		if len(done) == 0 {
			return nil // nothing acked; try again later
		}
		if err := m.store.ackOutbox(ctx, done); err != nil {
			return err
		}
		if len(done) < len(evs) {
			return nil
		}
	}
}

// Run drives health checks, scheduled jobs and outbox delivery until ctx
// ends. Leader plugins run jobs and event delivery only on the leader;
// every_node plugins run everywhere. Health checks run on every node.
type scheduleFlight struct {
	cancel context.CancelFunc
}

func (m *Manager) waitSchedule() {
	m.scheduleWG.Wait()
}

func (m *Manager) scheduleBusyLocked(pluginID, callPath string) bool {
	key := pluginID + "|" + callPath
	if m.scheduleInFlight[key] != nil {
		return true
	}
	if j := m.scheduleJobs[key]; j != nil {
		if j.snapshot().State == "running" {
			return true
		}
		delete(m.scheduleJobs, key)
	}
	if strings.HasPrefix(callPath, "/ether/job/") {
		if old, ok := m.jobs.Load(key); ok && old.(*actionJob).snapshot().State == "running" {
			return true
		}
	}
	return false
}

func (m *Manager) runScheduledCall(ctx context.Context, flight *scheduleFlight, pluginID, callPath, key string) {
	defer m.scheduleWG.Done()
	defer flight.cancel()
	startedAt := m.now()
	resp, err := m.Call(WithBackgroundCall(ctx), pluginID, Request{Method: "POST", Path: callPath})
	var started *actionJob
	var startErr error
	if err == nil && ctx.Err() == nil && resp.Status >= 200 && resp.Status < 300 && len(resp.Body) > 0 {
		started, startErr = m.startResolverJob(pluginID, resp.Body, nil, "")
		if started != nil && ctx.Err() != nil {
			started.cancel()
			started = nil
		}
	}
	var cancelStarted *actionJob
	m.mu.Lock()
	if m.scheduleInFlight[key] == flight {
		delete(m.scheduleInFlight, key)
		if started != nil {
			if m.scheduleJobs == nil {
				m.scheduleJobs = map[string]*actionJob{}
			}
			m.scheduleJobs[key] = started
		}
	} else if started != nil {
		cancelStarted = started
	}
	m.mu.Unlock()
	if cancelStarted != nil {
		cancelStarted.cancel()
	}
	if startErr != nil {
		m.log.Warn("plugin schedule: start job", "plugin", pluginID, "call", callPath, "err", startErr)
	}
	var jobErr string
	switch {
	case err != nil && ctx.Err() == nil:
		jobErr = m.store.redactKnown(context.Background(), pluginID, err.Error())
	case startErr != nil:
		jobErr = m.store.redactKnown(context.Background(), pluginID, startErr.Error())
	case err == nil && resp.Status >= 400:
		redact := func(s string) string {
			return m.store.redactKnown(context.Background(), pluginID, s)
		}
		jobErr = formatJobHTTPError(resp.Status, resp.Body, redact).Error()
		m.log.Warn("plugin schedule: job failed", "plugin", pluginID, "call", callPath, "err", jobErr)
	}
	if jobErr != "" {
		durMS := max(m.now().Sub(startedAt).Milliseconds(), int64(0))
		m.emitBusEvent(events.EventPluginJobFailed, pluginID, events.PluginJobFailedPayload{
			PluginID:   pluginID,
			Name:       m.pluginDisplayName(context.Background(), pluginID),
			Job:        callPath,
			Kind:       "scheduled",
			Error:      jobErr,
			DurationMS: durMS,
		}, false)
	}
}

func (m *Manager) Run(ctx context.Context) {
	stopBridge := m.StartEventBridge(ctx)
	defer stopBridge()
	defer m.scheduleWG.Wait()
	inspectorTick := time.NewTicker(250 * time.Millisecond)
	defer inspectorTick.Stop()
	defer func() {
		flushCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		m.flushAdapterCalls(flushCtx)
	}()
	defer m.cancelActionJobs("")
	defer m.cancelRemoteHashes("")
	defer func() {
		m.hashMu.Lock()
		defer m.hashMu.Unlock()
		for _, job := range m.hashJobs {
			job.cancel()
		}
	}()

	tick := time.NewTicker(5 * time.Second)
	defer tick.Stop()
	lastHealth := map[string]time.Time{}
	for {
		select {
		case <-ctx.Done():
			return
		case <-inspectorTick.C:
			m.flushAdapterCalls(ctx)
		case <-tick.C:
			m.runOnce(ctx, lastHealth)
		}
	}
}

// runOnce is one scheduler pass; tests drive it directly.
// stremioManifestRefresh is how often an installed Stremio add-on's
// manifest is re-read.
const stremioManifestRefresh = time.Hour

func (m *Manager) runOnce(ctx context.Context, lastHealth map[string]time.Time) {
	recs, err := m.store.list(ctx)
	if err != nil {
		return
	}
	now := m.now()
	m.refreshOnAir(ctx, recs, now)
	for _, r := range recs {
		if r.Enabled && r.Manifest.IsStremioOnly() && r.SourceKind == "url" && m.isLeader() {
			// Stremio add-ons change catalogs and resources without a
			// version bump; re-read the manifest hourly (cluster leader).
			key := "stremio-manifest|" + r.ID
			if last, seen := lastHealth[key]; !seen || now.Sub(last) >= stremioManifestRefresh {
				lastHealth[key] = now
				if seen {
					go func(id string) {
						rctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), time.Minute)
						defer cancel()
						_, _, _ = m.CheckUpdate(rctx, id)
					}(r.ID)
				}
			}
		}
		if !r.Enabled || r.Manifest.Ether == nil || m.sidecarWaiting(r) {
			continue
		}
		interval := time.Minute
		if d, err := time.ParseDuration(r.Manifest.Ether.Health.Interval); err == nil && d >= 15*time.Second {
			interval = d
		}
		if _, hasRuntime := m.factoryFor(r); hasRuntime && now.Sub(lastHealth[r.ID]) >= interval {
			lastHealth[r.ID] = now
			h, _ := m.store.health(ctx, r.ID)
			if h.NextRetry.IsZero() || !now.Before(h.NextRetry) || h.Status != "error" {
				_, _ = m.CheckHealth(ctx, r.ID)
			}
		}
		if !m.mayRunJobs(r) {
			continue
		}
		for _, job := range r.Manifest.Ether.Schedule {
			if job.Call == "/ether/feeds" {
				continue
			}
			every, err := time.ParseDuration(job.Every)
			if err != nil {
				continue
			}
			key := r.ID + "|" + job.Call
			m.mu.Lock()
			next, seen := m.nextRun[key]
			if !seen {
				last, err := m.store.scheduleLastRun(ctx, r.ID, job.Call)
				if err != nil {
					m.mu.Unlock()
					m.log.Warn("plugin schedule: read last run", "plugin", r.ID, "call", job.Call, "err", err)
					continue
				}
				if !last.IsZero() {
					next = last.Add(every)
					m.nextRun[key] = next
				}
			}
			if now.Before(next) {
				m.mu.Unlock()
				continue
			}
			if ctx.Err() != nil {
				m.mu.Unlock()
				return
			}
			if m.scheduleBusyLocked(r.ID, job.Call) {
				m.mu.Unlock()
				continue
			}
			// Record dispatch before calling: failures (or a restart during a
			// long job) must not produce a first-run storm on the next boot.
			dispatched := m.now()
			if err := m.store.markScheduleRun(ctx, r.ID, job.Call, dispatched); err != nil {
				m.mu.Unlock()
				m.log.Warn("plugin schedule: save last run", "plugin", r.ID, "call", job.Call, "err", err)
				continue
			}
			m.nextRun[key] = dispatched.Add(every)
			callCtx, cancel := context.WithCancel(ctx)
			flight := &scheduleFlight{cancel: cancel}
			if m.scheduleInFlight == nil {
				m.scheduleInFlight = map[string]*scheduleFlight{}
			}
			m.scheduleInFlight[key] = flight
			m.scheduleWG.Add(1)
			m.mu.Unlock()
			go m.runScheduledCall(callCtx, flight, r.ID, job.Call, key)
		}
		_ = m.DeliverOutbox(ctx, r.ID)
		// Capability refreshes ride the schedule: list sources and
		// channels declare their own refresh in contributes.
		m.maybeRefresh(ctx, r, now)
	}
}

func (m *Manager) factoryFor(r Record) (RuntimeFactory, bool) {
	m.mu.Lock()
	defer m.mu.Unlock()
	f, ok := m.fatories[r.Manifest.RuntimeKind()]
	return f, ok
}

// mayRunJobs applies cluster placement: leader plugins only on the
// leader, every_node everywhere.
func (m *Manager) mayRunJobs(r Record) bool {
	if r.Manifest.Ether.Cluster == "every_node" {
		return true
	}
	return m.isLeader()
}

func (m *Manager) maybeRefresh(ctx context.Context, r Record, now time.Time) {
	type refresh struct {
		key   string
		every time.Duration
		path  string
	}
	var jobs []refresh
	c := r.Manifest.Ether.Contributes
	if c.Channels != nil && c.Channels.Refresh != "" {
		if d, err := time.ParseDuration(c.Channels.Refresh); err == nil {
			jobs = append(jobs, refresh{"channels", d, "/ether/channels.json"})
		}
	}
	for _, ls := range c.ListSources {
		refreshStr := ls.Refresh
		if refreshStr == "" {
			refreshStr = "1h"
		}
		if d, err := time.ParseDuration(refreshStr); err == nil {
			jobs = append(jobs, refresh{"list:" + ls.Key, d, "/catalog/movie/" + ls.Catalog + ".json"})
		}
	}
	for _, j := range jobs {
		key := r.ID + "|refresh:" + j.key
		m.mu.Lock()
		next, seen := m.nextRun[key]
		if !seen {
			m.nextRun[key] = now.Add(j.every)
			m.mu.Unlock()
			continue
		}
		if now.Before(next) {
			m.mu.Unlock()
			continue
		}
		m.nextRun[key] = now.Add(j.every)
		m.mu.Unlock()
		_, _ = m.Call(ctx, r.ID, Request{Method: "GET", Path: j.path})
	}
}

func parseFolderAlgorithms(options []FolderHashOptions) (folderAlgorithms, error) {
	if len(options) == 0 || len(options[0].Algorithms) == 0 {
		return folderWhole | folderOSHash | folderDefaultHash, nil
	}
	var mask folderAlgorithms
	for _, algo := range options[0].Algorithms {
		switch algo {
		case "crc32":
			mask |= folderCRC32
		case "md5":
			mask |= folderMD5
		case "sha1":
			mask |= folderSHA1
		case "oshash":
			mask |= folderOSHash
		case "phash":
			mask |= folderPHash
		default:
			return 0, fmt.Errorf("folders.hash: unsupported algorithm")
		}
	}
	return mask, nil
}

type openedFolderFile struct {
	*os.File
	root *os.Root
	info os.FileInfo
	path string
}

func (h *host) openFolderFile(ctx context.Context, root, path string) (*openedFolderFile, error) {
	if filepath.IsAbs(path) {
		return nil, ErrPermissionDenied
	}
	for _, segment := range strings.FieldsFunc(path, func(r rune) bool { return r == '/' || r == '\\' }) {
		if segment == ".." {
			return nil, ErrPermissionDenied
		}
	}
	if _, err := h.folderCheck(ctx, root, path); err != nil {
		return nil, err
	}
	fs, err := os.OpenRoot(root)
	if err != nil {
		return nil, fmt.Errorf("folders: cannot open picked folder")
	}
	before, err := fs.Stat(path)
	if err != nil || !before.Mode().IsRegular() {
		fs.Close()
		return nil, fmt.Errorf("folders: a regular file is required")
	}
	f, err := fs.OpenFile(path, folderReadFlags, 0)
	if err != nil {
		fs.Close()
		return nil, fmt.Errorf("folders: cannot open picked file")
	}
	info, err := f.Stat()
	if err != nil || !os.SameFile(before, info) || !info.Mode().IsRegular() {
		f.Close()
		fs.Close()
		return nil, fmt.Errorf("folders: a regular file is required")
	}
	return &openedFolderFile{File: f, root: fs, info: info, path: path}, nil
}

func (f *openedFolderFile) Close() {
	f.File.Close()
	f.root.Close()
}

func (f *openedFolderFile) unchanged() bool {
	current, err := f.root.Stat(f.path)
	return err == nil && os.SameFile(f.info, current) &&
		current.Size() == f.info.Size() && current.ModTime().Equal(f.info.ModTime())
}

func (f *openedFolderFile) cacheKey(operation string) string {
	dev, inode, ok := core.OpenFileID(f.File, f.info)
	if !ok {
		return ""
	}
	identity := fmt.Sprintf("%s:%d:%d:%d:%d", operation, dev, inode, f.info.Size(), f.info.ModTime().UnixNano())
	return fmt.Sprintf("folder.v1.%x", sha256.Sum256([]byte(identity)))
}

func openSubtitlesHash(f io.ReaderAt, size int64) (string, error) {
	if size < osHashBlock {
		return "", fmt.Errorf("folders.hash: oshash requires at least 64 KiB")
	}
	var block [osHashBlock]byte
	sum := uint64(size)
	for _, off := range []int64{0, size - osHashBlock} {
		if _, err := f.ReadAt(block[:], off); err != nil {
			return "", fmt.Errorf("folders.hash: could not read oshash blocks")
		}
		for i := 0; i < len(block); i += 8 {
			sum += binary.LittleEndian.Uint64(block[i : i+8])
		}
	}
	return fmt.Sprintf("%016x", sum), nil
}

// FoldersHash keeps small whole-file hashes synchronous. Oshash alone is a
// bounded read regardless of file size.
func (h *host) FoldersHash(ctx context.Context, root, path string, options ...FolderHashOptions) (FolderHash, error) {
	algos, err := parseFolderAlgorithms(options)
	if err != nil {
		return FolderHash{}, err
	}
	if algos&folderPHash != 0 {
		return FolderHash{}, fmt.Errorf("folders.hash: use hashStart for phash")
	}
	return h.hashFile(ctx, root, path, algos, false, nil)
}

func (h *host) hashFile(ctx context.Context, root, path string, algos folderAlgorithms, background bool, progress func(int64)) (FolderHash, error) {
	f, err := h.openFolderFile(ctx, root, path)
	if err != nil {
		return FolderHash{}, err
	}
	defer f.Close()
	const syncLimit = 256 << 20
	size := f.info.Size()
	if !background && algos&folderWhole != 0 && size > syncLimit {
		return FolderHash{}, fmt.Errorf("folders.hash: use hashStart for whole-file digests above 256 MiB")
	}
	if algos&folderDefaultHash != 0 {
		algos &^= folderDefaultHash
		if size < osHashBlock {
			algos &^= folderOSHash
		}
	}

	key := f.cacheKey(fmt.Sprintf("hash:%d", algos))
	if key != "" {
		raw, ok, err := h.m.store.hashCacheGet(ctx, h.plugin, key)
		if err != nil {
			return FolderHash{}, err
		}
		var cached FolderHash
		if ok && json.Unmarshal(raw, &cached) == nil && f.unchanged() {
			return cached, nil
		}
	}

	result := FolderHash{Size: size, ModTime: f.info.ModTime().Unix()}
	if algos&folderOSHash != 0 {
		result.OSHash, err = openSubtitlesHash(f, size)
		if err != nil {
			return FolderHash{}, err
		}
	}
	if algos&folderWhole != 0 {
		if err := h.hashWholeFile(ctx, root, f, algos, background, progress, &result); err != nil {
			return FolderHash{}, err
		}
	}
	if algos&folderPHash != 0 {
		result.PHash, err = h.videoPHash(ctx, root, f)
		if err != nil {
			return FolderHash{}, err
		}
	}
	if _, err := h.folderCheck(ctx, root, path); err != nil {
		return FolderHash{}, err
	}
	if !f.unchanged() {
		return FolderHash{}, fmt.Errorf("folders.hash: file changed while hashing")
	}
	if key != "" {
		raw, _ := json.Marshal(result)
		if err := h.m.store.hashCachePut(ctx, h.plugin, key, raw); err != nil {
			return FolderHash{}, err
		}
	}
	return result, nil
}

func (h *host) hashWholeFile(ctx context.Context, root string, f *openedFolderFile, algos folderAlgorithms, background bool, progress func(int64), result *FolderHash) error {
	var hashes []hash.Hash
	var writers []io.Writer
	var targets []*string
	digests := []struct {
		flag folderAlgorithms
		make func() hash.Hash
		dest *string
	}{
		{folderCRC32, func() hash.Hash { return crc32.NewIEEE() }, &result.CRC32},
		{folderMD5, md5.New, &result.MD5},
		{folderSHA1, sha1.New, &result.SHA1},
	}
	for _, d := range digests {
		if algos&d.flag != 0 {
			digest := d.make()
			hashes = append(hashes, digest)
			writers = append(writers, digest)
			targets = append(targets, d.dest)
		}
	}
	w := io.MultiWriter(writers...)
	buf := make([]byte, 1<<20)
	var total int64
	r := io.NewSectionReader(f, 0, f.info.Size())
	for {
		if err := ctx.Err(); err != nil {
			return err
		}
		if _, err := h.folderCheck(ctx, root, f.path); err != nil {
			return err
		}
		n, err := r.Read(buf)
		total += int64(n)
		if n > 0 {
			_, _ = w.Write(buf[:n])
			if progress != nil {
				progress(total)
			}
			if background {
				select {
				case <-ctx.Done():
					return ctx.Err()
				case <-time.After(2 * time.Millisecond):
				}
			}
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			return fmt.Errorf("folders.hash: could not read picked file")
		}
	}
	if total != f.info.Size() {
		return fmt.Errorf("folders.hash: file changed while hashing")
	}
	for i, digest := range hashes {
		*targets[i] = fmt.Sprintf("%x", digest.Sum(nil))
	}
	return nil
}

func (h *folderNames) Pop() any {
	last := len(*h) - 1
	v := (*h)[last]
	*h = (*h)[:last]
	return v
}

func declaresFolderRead(man Manifest) bool {
	return man.Ether != nil && man.RuntimeKind() == "hosted" && normLevel(man.Ether.Permissions.Folders) == "read"
}

// folderRoots returns the stored root strings verbatim, as required by folderCheck.
func folderRoots(man Manifest, g Grants) []string {
	roots := []string{}
	if !declaresFolderRead(man) || g.revoked("folders") {
		return roots
	}
	for _, root := range g.Folders {
		if filepath.IsAbs(root) {
			roots = append(roots, root)
		}
	}
	return roots
}

func (h *host) FoldersRoots(ctx context.Context) ([]string, error) {
	if isClientRequestPath(callPathFromContext(ctx)) {
		return nil, fmt.Errorf("%w: folders.roots requires a non-client route", ErrPermissionDenied)
	}
	r, g, err := h.record(ctx)
	if err != nil {
		return nil, err
	}
	return folderRoots(r.Manifest, g), nil
}

func (h *host) FoldersList(ctx context.Context, root, path string, options ...FolderListOptions) (FolderPage, error) {
	if isClientRequestPath(callPathFromContext(ctx)) {
		return FolderPage{}, fmt.Errorf("%w: folders.list requires a non-client route", ErrPermissionDenied)
	}
	if _, err := h.folderCheck(ctx, root, path); err != nil {
		return FolderPage{}, err
	}
	opts := FolderListOptions{}
	if len(options) != 0 {
		opts = options[0]
	}
	if opts.Limit <= 0 {
		opts.Limit = maxFolderPage
	}
	limit := min(opts.Limit, maxFolderPage)
	fs, err := os.OpenRoot(root)
	if err != nil {
		return FolderPage{}, err
	}
	defer fs.Close()
	dir, err := fs.OpenFile(filepath.Clean(path), folderReadFlags, 0)
	if err != nil {
		return FolderPage{}, err
	}
	defer dir.Close()
	info, err := dir.Stat()
	if err != nil || !info.IsDir() {
		return FolderPage{}, fmt.Errorf("folders.list requires a directory")
	}

	names := make(folderNames, 0, limit)
	truncated := false
	for {
		if err := ctx.Err(); err != nil {
			return FolderPage{}, err
		}
		batch, err := dir.ReadDir(256)
		if err != nil && !errors.Is(err, io.EOF) {
			return FolderPage{}, err
		}
		for _, entry := range batch {
			name := entry.Name()
			if name <= opts.Cursor || !utf8.ValidString(name) {
				continue
			}
			// Rooted Stat follows only links whose targets stay in the grant.
			if entry.Type()&os.ModeSymlink != 0 {
				if _, err := fs.Stat(filepath.Join(path, name)); err != nil {
					continue
				}
			}
			if len(names) < limit {
				heap.Push(&names, name)
			} else {
				truncated = true
				if name < names[0] {
					names[0] = name
					heap.Fix(&names, 0)
				}
			}
		}
		if errors.Is(err, io.EOF) {
			break
		}
	}

	slices.Sort(names)
	page := FolderPage{Entries: make([]FolderEntry, 0, len(names)), Truncated: truncated}
	if truncated {
		page.NextCursor = names[len(names)-1]
	}
	for _, name := range names {
		rel := filepath.Join(path, name)
		info, err := fs.Stat(rel)
		if err != nil {
			continue // An entry may disappear or become an escaping link during the scan.
		}
		page.Entries = append(page.Entries, FolderEntry{
			Name: name, Path: rel, Dir: info.IsDir(), Size: info.Size(), Mtime: info.ModTime().Unix(),
		})
	}
	if _, err := h.folderCheck(ctx, root, path); err != nil {
		return FolderPage{}, err
	}
	return page, nil
}

const (
	folderVideoFormats = "mov,matroska,webm,avi,mpeg,mpegts,flv,asf,ogg,mxf,rm"
	folderMaxPixels    = "37748736" // 8192 x 4608
)

func (h *host) checkFolderVideoCall(ctx context.Context) error {
	rec, _, err := h.record(ctx)
	if err != nil {
		return err
	}
	path := callPathFromContext(ctx)
	if (path == "" && !isBackgroundCall(ctx)) || (path != "" && !MediaProbeAllowedPath(rec.Manifest, path, isBackgroundCall(ctx))) {
		return fmt.Errorf("%w: folder video operations require a job or background route", ErrPermissionDenied)
	}
	if h.m.deps.FFmpeg == "" {
		return ErrUnavailable
	}
	return nil
}

// Use the already opened rooted file across all platforms, with HTTP Range
// for seeks. The child never receives a filesystem path to reopen.
func serveFolderVideo(f *openedFolderFile) (string, func(), error) {
	listener, err := net.Listen("tcp4", "127.0.0.1:0")
	if err != nil {
		return "", nil, ErrUnavailable
	}
	path := "/" + rand.Text()
	server := &http.Server{
		ReadHeaderTimeout: 2 * time.Second,
		Handler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if r.URL.Path != path || (r.Method != http.MethodGet && r.Method != http.MethodHead) {
				http.NotFound(w, r)
				return
			}
			w.Header().Set("Content-Type", "application/octet-stream")
			http.ServeContent(w, r, "", time.Time{}, io.NewSectionReader(f, 0, f.info.Size()))
		}),
	}
	go func() { _ = server.Serve(listener) }()
	return "http://" + listener.Addr().String() + path, func() { _ = server.Close() }, nil
}

// Only self-contained demuxers and the loopback HTTP transport are enabled.
// Clear proxy variables so the file capability cannot leave the machine.
func runFolderMedia(ctx context.Context, binary string, args ...string) ([]byte, error) {
	cmd := mediaproc.CommandContext(ctx, 10*time.Second, binary, args...)
	for _, env := range os.Environ() {
		key, _, _ := strings.Cut(env, "=")
		if !strings.HasSuffix(strings.ToLower(key), "_proxy") {
			cmd.Env = append(cmd.Env, env)
		}
	}
	cmd.Env = append(cmd.Env, "NO_PROXY=127.0.0.1", "no_proxy=127.0.0.1")
	out, err := cmd.Output()
	if err != nil {
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}
		if errors.Is(err, context.DeadlineExceeded) {
			return nil, context.DeadlineExceeded
		}
		return nil, fmt.Errorf("folders: media tool could not read the video")
	}
	return out, nil
}

func folderScreenshot(ctx context.Context, ffmpeg, input string, at float64, width int, perception bool) ([]byte, error) {
	args := []string{"-v", "error", "-nostdin", "-filter_threads", "1", "-ss", strconv.FormatFloat(at, 'f', -1, 64),
		"-protocol_whitelist", "http,tcp", "-format_whitelist", folderVideoFormats,
		"-threads", "1", "-max_pixels", folderMaxPixels, "-i", input}
	if !perception {
		args = append(args, "-map", "0:V:0")
	}
	args = append(args, "-an", "-sn", "-dn", "-frames:v", "1", "-threads", "1")
	if perception {
		// Stash scales to 160:-2. Bound extreme aspect ratios before allocating;
		// the caller rejects a frame that reaches this safety ceiling.
		args = append(args, "-vf", `scale=160:if(gte(ih\,iw*6.4)\,1024\,-2)`, "-c:v", "bmp", "-f", "rawvideo")
	} else {
		args = append(args, "-vf", fmt.Sprintf("scale=%d:1024:force_original_aspect_ratio=decrease:force_divisible_by=2", width), "-c:v", "png", "-f", "image2pipe")
	}
	out, err := runFolderMedia(ctx, ffmpeg, append(args, "pipe:1")...)
	if err == nil && len(out) == 0 {
		err = fmt.Errorf("folders: no video frame at requested timestamp")
	}
	return out, err
}

func (h *host) videoPHash(ctx context.Context, root string, f *openedFolderFile) (string, error) {
	if h.m.deps.FFprobe == "" {
		return "", ErrUnavailable
	}
	ctx, cancel := context.WithTimeout(ctx, time.Minute)
	defer cancel()
	input, closeInput, err := serveFolderVideo(f)
	if err != nil {
		return "", err
	}
	defer closeInput()
	out, err := runFolderMedia(ctx, h.m.deps.FFprobe, "-v", "error",
		"-protocol_whitelist", "http,tcp", "-format_whitelist", folderVideoFormats,
		"-threads", "1", "-max_pixels", folderMaxPixels, "-select_streams", "V", "-show_entries", "stream=index:format=duration", "-of", "json", input)
	if err != nil {
		return "", err
	}
	var probe struct {
		Streams []struct{ Index int }
		Format  struct{ Duration string }
	}
	if json.Unmarshal(out, &probe) != nil || len(probe.Streams) == 0 {
		return "", fmt.Errorf("folders.hash: phash requires a video stream")
	}
	duration, err := strconv.ParseFloat(probe.Format.Duration, 64)
	duration = math.Round(duration*100) / 100
	if err != nil || duration <= 0 || math.IsNaN(duration) || math.IsInf(duration, 0) {
		return "", fmt.Errorf("folders.hash: phash requires a known video duration")
	}
	return folderPerceptionHash(duration, func(at float64) (image.Image, error) {
		if _, err := h.folderCheck(ctx, root, f.path); err != nil {
			return nil, err
		}
		frame, err := folderScreenshot(ctx, h.m.deps.FFmpeg, input, at, 160, true)
		if err != nil {
			return nil, err
		}
		img, err := bmp.Decode(bytes.NewReader(frame))
		if err != nil {
			return nil, fmt.Errorf("folders.hash: invalid video frame")
		}
		return img, nil
	})
}

// Match Stash v0.31.1's sample positions and row-major montage, then call the
// same PerceptionHash implementation used by Stash.
func folderPerceptionHash(duration float64, frameAt func(float64) (image.Image, error)) (string, error) {
	const columns, rows, width = 5, 5, 160
	var tile *image.NRGBA
	var height int
	for i := range columns * rows {
		at := 0.05*duration + float64(i)*(0.9*duration/float64(columns*rows))
		frame, err := frameAt(at)
		if err != nil {
			return "", err
		}
		b := frame.Bounds()
		if b.Dx() != width || b.Dy() < 1 || b.Dy() >= 1024 {
			return "", fmt.Errorf("folders.hash: unsupported frame dimensions")
		}
		if tile == nil {
			height = b.Dy()
			tile = image.NewNRGBA(image.Rect(0, 0, width*columns, height*rows))
		}
		point := image.Pt(i%columns*width, i/columns*height)
		draw.Draw(tile, b.Sub(b.Min).Add(point), frame, b.Min, draw.Src)
	}
	hash, err := goimagehash.PerceptionHash(tile)
	if err != nil {
		return "", err
	}
	return fmt.Sprintf("%016x", hash.GetHash()), nil
}

func (h *host) FoldersFrame(ctx context.Context, root, path string, opts FolderFrameOptions) (FolderFrame, error) {
	if err := h.checkFolderVideoCall(ctx); err != nil {
		return FolderFrame{}, err
	}
	if opts.AtSec < 0 || math.IsNaN(opts.AtSec) || math.IsInf(opts.AtSec, 0) || opts.Width < 16 || opts.Width > 1024 {
		return FolderFrame{}, fmt.Errorf("folders.frame: atSec must be finite and nonnegative and width must be 16–1024")
	}
	lib, err := h.archiveExtractCheck(ctx, opts.LibraryKey)
	if err != nil {
		return FolderFrame{}, err
	}
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	f, err := h.openFolderFile(ctx, root, path)
	if err != nil {
		return FolderFrame{}, err
	}
	defer f.Close()

	key := f.cacheKey("frame:" + strconv.FormatFloat(opts.AtSec, 'g', -1, 64) + ":" + strconv.Itoa(opts.Width))
	if key == "" {
		key = "frame-" + rand.Text()
	}
	key += ".png"
	if lookup := h.m.kindBackends().CacheLookup; lookup != nil {
		if ref, ok := lookup(h.plugin, lib, key); ok && f.unchanged() {
			return FolderFrame{Ref: ref, LibraryKey: lib}, nil
		}
	}
	if !h.m.rateOK(h.m.folderFrameTimes, h.plugin, 20, time.Minute) {
		return FolderFrame{}, fmt.Errorf("%w: folders.frame exceeds 20 uncached calls per minute", ErrRateLimited)
	}
	select {
	case folderHashSlots <- struct{}{}:
		defer func() { <-folderHashSlots }()
	default:
		return FolderFrame{}, fmt.Errorf("%w: folder media workers are busy", ErrRateLimited)
	}
	input, closeInput, err := serveFolderVideo(f)
	if err != nil {
		return FolderFrame{}, err
	}
	defer closeInput()
	frame, err := folderScreenshot(ctx, h.m.deps.FFmpeg, input, opts.AtSec, opts.Width, false)
	if err != nil {
		return FolderFrame{}, err
	}
	if _, err := h.folderCheck(ctx, root, path); err != nil {
		return FolderFrame{}, err
	}
	if !f.unchanged() {
		return FolderFrame{}, fmt.Errorf("folders.frame: file changed while extracting a frame")
	}

	ref, err := h.CachePut(ctx, lib, key, bytes.NewReader(frame))
	if err != nil {
		return FolderFrame{}, err
	}
	return FolderFrame{Ref: ref, LibraryKey: lib}, nil
}

func (h *host) FoldersHashStart(ctx context.Context, root, path string, options ...FolderHashOptions) (FolderHashJob, error) {
	algos, err := parseFolderAlgorithms(options)
	if err != nil {
		return FolderHashJob{}, err
	}
	if algos&folderPHash != 0 {
		if err := h.checkFolderVideoCall(ctx); err != nil {
			return FolderHashJob{}, err
		}
	}
	if _, err := h.FoldersStat(ctx, root, path); err != nil {
		return FolderHashJob{}, err
	}
	m := h.m
	m.hashMu.Lock()
	defer m.hashMu.Unlock()
	if m.hashJobs == nil {
		m.hashJobs = make(map[string]*folderHashWork)
	}
	for id, w := range m.hashJobs {
		if w.plugin != h.plugin {
			continue
		}
		w.mu.Lock()
		running := w.status.State == "running"
		status := w.status
		w.mu.Unlock()
		if running {
			if w.root == root && w.path == path && w.algorithms == algos {
				return status, nil
			}
			return FolderHashJob{}, fmt.Errorf("folders.hash: plugin already has a running job")
		}
		delete(m.hashJobs, id)
	}
	select {
	case folderHashSlots <- struct{}{}:
	default:
		return FolderHashJob{}, fmt.Errorf("folders.hash: global job limit reached; retry later")
	}
	// The job intentionally survives the initiating host call, but has a finite lifetime.
	jobCtx, cancel := context.WithTimeout(context.Background(), 24*time.Hour)
	m.hashSequence++
	w := &folderHashWork{plugin: h.plugin, root: root, path: path, algorithms: algos, cancel: cancel, status: FolderHashJob{ID: fmt.Sprintf("hash-%d", m.hashSequence), State: "running"}}
	m.hashJobs[w.status.ID] = w
	go func() {
		defer func() { cancel(); <-folderHashSlots }()
		result, err := h.hashFile(jobCtx, root, path, algos, true, func(n int64) { w.mu.Lock(); w.status.Bytes = n; w.mu.Unlock() })
		w.mu.Lock()
		defer w.mu.Unlock()
		if err != nil {
			w.status.State = "error"
			w.status.Error = err.Error()
			if jobCtx.Err() != nil {
				w.status.State = "canceled"
			}
		} else {
			w.status.State = "done"
			w.status.Bytes = result.Size
			w.status.Result = &result
		}
	}()
	return FolderHashJob{ID: w.status.ID, State: "running"}, nil
}

func (h *host) hashJob(ctx context.Context, id string, cancel bool) (FolderHashJob, error) {
	h.m.hashMu.Lock()
	w := h.m.hashJobs[id]
	h.m.hashMu.Unlock()
	if w == nil || w.plugin != h.plugin {
		return FolderHashJob{}, fmt.Errorf("folders.hash: unknown job")
	}
	if _, err := h.folderCheck(ctx, w.root, w.path); err != nil {
		w.cancel()
		return FolderHashJob{}, err
	}
	if cancel {
		w.cancel()
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	status := w.status
	if status.Result != nil {
		result := *status.Result
		status.Result = &result
	}
	return status, nil
}

func (h *host) FoldersHashPoll(ctx context.Context, id string) (FolderHashJob, error) {
	return h.hashJob(ctx, id, false)
}

func (h *host) FoldersHashCancel(ctx context.Context, id string) (FolderHashJob, error) {
	return h.hashJob(ctx, id, true)
}

func (s *storage) hashCacheGet(ctx context.Context, plugin, key string) ([]byte, bool, error) {
	var raw []byte
	err := s.db.QueryRowContext(ctx, `SELECT value FROM plugins_hash_cache WHERE plugin=? AND kkey=?`, plugin, key).Scan(&raw)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, false, nil
	}
	return raw, err == nil, err
}

func (s *storage) hashCachePut(ctx context.Context, plugin, key string, raw []byte) error {
	_, err := s.db.ExecContext(ctx, `INSERT INTO plugins_hash_cache(plugin,kkey,value) VALUES(?,?,?) ON CONFLICT(plugin,kkey) DO UPDATE SET value=excluded.value`, plugin, key, raw)
	return err
}

// host implements Host for one plugin. Grants are re-read on every call,
// so a revoke takes effect mid-call. Writes are journalled with their
// inverse; in shadow mode they are recorded without applying.
type host struct {
	m      *Manager
	plugin string
}

func (h *host) requireWritableToolContext(ctx context.Context) error {
	if readOnly, _ := ctx.Value(readOnlyToolContextKey{}).(bool); readOnly {
		h.noteDenied("read-only tool")
		return fmt.Errorf("%w: read-only tool cannot write", ErrPermissionDenied)
	}
	return nil
}

func (h *host) record(ctx context.Context) (Record, Grants, error) {
	return h.m.store.hostAccess(ctx, h.plugin)
}

func (h *host) deny(r Record, g Grants, key, level string, allowed func(string) bool) error {
	if g.revoked(key) || !allowed(level) {
		h.noteDenied(key)
		return fmt.Errorf("%w: %s", ErrPermissionDenied, key)
	}
	return nil
}

func (h *host) noteDenied(key string) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	h.m.healthMu.Lock()
	defer h.m.healthMu.Unlock()
	if hh, err := h.m.store.health(ctx, h.plugin); err == nil && hh.Status == "ok" {
		hh.Status = "attention"
		hh.Reason = "A permission it needs was taken back: " + key
		_ = h.m.store.putHealth(ctx, h.plugin, hh)
	}
}

func viewerOK(g Grants, level string, viewerID int64) bool {
	switch level {
	case "all":
		return true
	case "granted_viewers":
		return g.viewerGranted(viewerID)
	}
	return false
}

func (h *host) KVGet(ctx context.Context, key string) ([]byte, bool, error) {
	if _, _, err := h.record(ctx); err != nil {
		return nil, false, err
	}
	value, ok, err := h.m.store.kvGet(ctx, h.plugin, key)
	if !ok || err != nil {
		return value, ok, err
	}
	if normalize := h.m.kindBackends().NormalizeStoredReleaseLinks; normalize != nil {
		value, err = normalize(ctx, value)
	}
	return value, ok && err == nil, err
}

func (h *host) KVPut(ctx context.Context, key string, value []byte) error {
	r, _, err := h.record(ctx)
	if err != nil {
		return err
	}
	err = h.m.store.kvPut(ctx, h.plugin, key, value)
	if errors.Is(err, ErrQuotaExceeded) {
		usage, _ := h.m.store.kvUsage(ctx, h.plugin)
		h.m.emitBusEvent(events.EventPluginQuotaExceeded, h.plugin, events.PluginQuotaExceededPayload{
			PluginID:  h.plugin,
			Name:      r.Name,
			QuotaKind: "kv",
			Used:      usage.Bytes,
			Limit:     KVQuotaBytes,
		}, false)
	}
	return err
}

func (h *host) KVDelete(ctx context.Context, key string) error {
	if _, _, err := h.record(ctx); err != nil {
		return err
	}
	return h.m.store.kvDelete(ctx, h.plugin, key)
}

func (h *host) KVList(ctx context.Context, prefix string) ([]string, error) {
	if _, _, err := h.record(ctx); err != nil {
		return nil, err
	}
	return h.m.store.kvList(ctx, h.plugin, prefix)
}

func (h *host) KVUsage(ctx context.Context) (KVUsage, error) {
	if _, _, err := h.record(ctx); err != nil {
		return KVUsage{}, err
	}
	return h.m.store.kvUsage(ctx, h.plugin)
}

// Settings returns the plugin's stored non-secret settings.
func (h *host) Settings(ctx context.Context) (map[string]any, error) {
	r, _, err := h.record(ctx)
	if err != nil {
		return nil, err
	}
	row, err := h.m.store.requestSettings(ctx, h.plugin)
	if err != nil {
		return nil, err
	}
	return NonSecretSettings(row.Settings, row.Schema, settingsSecrets(r)), nil
}

const (
	// MaxDerivedSecretBytes caps a single plugin-written derived secret value.
	MaxDerivedSecretBytes = 16 << 10
	// MaxDerivedSecrets caps the number of derived secrets a plugin may store.
	MaxDerivedSecrets = 32
	// MaxDerivedSecretTTLSec caps an explicit derived-secret TTL (1 year).
	MaxDerivedSecretTTLSec int64 = 365 * 24 * 3600
)

func (h *host) checkSecretAccess(ctx context.Context, name string) (Record, error) {
	r, g, err := h.record(ctx)
	if err != nil {
		return Record{}, err
	}
	declared := false
	for _, s := range r.Manifest.Ether.Permissions.Secrets {
		if s == name {
			declared = true
			break
		}
	}
	if err := h.deny(r, g, "secrets", "", func(string) bool { return declared }); err != nil {
		return Record{}, err
	}
	return r, nil
}

func (h *host) SecretGet(ctx context.Context, name string) (string, error) {
	if _, err := h.checkSecretAccess(ctx, name); err != nil {
		return "", err
	}
	row, err := h.m.store.requestSettings(ctx, h.plugin)
	if err != nil {
		return "", err
	}
	if stored, ok := row.Secrets[name]; ok && stored != "" {
		return h.m.store.openSecret(h.plugin, name, stored)
	}
	if plain, ok, err := h.m.store.derivedSecret(ctx, h.plugin, name); err != nil {
		return "", err
	} else if ok {
		return plain, nil
	}
	return "", fmt.Errorf("%w: secret %s is not saved", ErrUnavailable, name)
}

func (h *host) SecretSet(ctx context.Context, name, value string, ttlSec int64) error {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return err
	}
	if _, err := h.checkSecretAccess(ctx, name); err != nil {
		return err
	}
	if ttlSec < 0 || ttlSec > MaxDerivedSecretTTLSec {
		return &ValidationError{Fields: []FieldError{{
			Field:   "ttlSec",
			Message: fmt.Sprintf("must be between 0 and %d seconds", MaxDerivedSecretTTLSec),
		}}}
	}
	row, err := h.m.store.settings(ctx, h.plugin)
	if err != nil {
		return err
	}
	if secretFieldNames(row.Schema)[name] || row.Secrets[name] != "" {
		return fmt.Errorf("%w: secret %s is owner-configured and cannot be modified by the plugin", ErrPermissionDenied, name)
	}
	if value == "" {
		return h.m.store.deleteDerivedSecret(ctx, h.plugin, name)
	}
	if len(value) > MaxDerivedSecretBytes {
		return fmt.Errorf("%w: secret %s exceeds %d bytes", ErrQuotaExceeded, name, MaxDerivedSecretBytes)
	}
	if strings.ContainsRune(value, 0) {
		return &ValidationError{Fields: []FieldError{{Field: "value", Message: "must not contain NUL bytes"}}}
	}
	exists, err := h.m.store.hasDerivedSecret(ctx, h.plugin, name)
	if err != nil {
		return err
	}
	if !exists {
		count, err := h.m.store.derivedSecretCount(ctx, h.plugin)
		if err != nil {
			return err
		}
		if count >= MaxDerivedSecrets {
			return fmt.Errorf("%w: derived secret limit (%d) reached", ErrQuotaExceeded, MaxDerivedSecrets)
		}
	}
	var expiresAt int64
	if ttlSec > 0 {
		expiresAt = h.m.now().Unix() + ttlSec
	}
	return h.m.store.putDerivedSecret(ctx, h.plugin, name, value, expiresAt)
}

func (h *host) SecretDelete(ctx context.Context, name string) error {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return err
	}
	if _, err := h.checkSecretAccess(ctx, name); err != nil {
		return err
	}
	row, err := h.m.store.settings(ctx, h.plugin)
	if err != nil {
		return err
	}
	if secretFieldNames(row.Schema)[name] || row.Secrets[name] != "" {
		return fmt.Errorf("%w: secret %s is owner-configured and cannot be modified by the plugin", ErrPermissionDenied, name)
	}
	return h.m.store.deleteDerivedSecret(ctx, h.plugin, name)
}

// CheckIndexerNetwork rejects a plugin network request to a configured indexer.
func (m *Manager) CheckIndexerNetwork(hostName string) error {
	if m.deps.IsIndexerHost != nil && m.deps.IsIndexerHost(hostName) {
		return errIndexerNetwork
	}
	return nil
}

// AllowNetworkHost reports whether pluginID is enabled, still holds its
// network grant, and declared hostName in permissions.network.
func (m *Manager) AllowNetworkHost(ctx context.Context, pluginID, hostName string) bool {
	if m.CheckIndexerNetwork(hostName) != nil {
		return false
	}
	h := &host{m: m, plugin: pluginID}
	r, g, err := h.record(ctx)
	if err != nil || r.Manifest.Ether == nil {
		return false
	}
	if g.revoked("network") {
		h.noteDenied("network")
		return false
	}
	if hostAllowed(r.Manifest.Ether.Permissions.Network, hostName) ||
		g.allowsLocalHostName(hostName) ||
		(DeclaresOperatorHosts(r.Manifest) && g.allowsOperatorHostName(hostName)) {
		return true
	}
	if DeclaresOperatorHosts(r.Manifest) {
		m.noteBlockedOperatorHost(ctx, pluginID, hostName)
		return false
	}
	if IsLocalNetworkHost(hostName) {
		m.noteBlockedLocalHost(ctx, pluginID, hostName)
		return false
	}
	h.noteDenied("network")
	return false
}

// hostAllowed matches a host against the manifest network list.
func hostAllowed(patterns []string, host string) bool {
	host = strings.ToLower(host)
	for _, p := range patterns {
		p = strings.ToLower(strings.TrimSpace(p))
		if p == OperatorNetworkEntry {
			continue
		}
		if strings.HasPrefix(p, "*.") {
			if strings.HasSuffix(host, p[1:]) && host != p[2:] {
				return true
			}
			continue
		}
		if p == host {
			return true
		}
	}
	return false
}

// ErrFetchFailed is returned when a plugin's outbound request fails. Its
// message names only the host and a category: request URLs can carry
// plugin secrets (API keys in the query), and net/http errors include the
// full URL, so neither the URL nor the underlying error text is exposed.
var ErrFetchFailed = errors.New("plugins: request failed")

func fetchError(host string, err error) error {
	var blocked *BlockedLocalHostError
	if errors.As(err, &blocked) {
		return blocked
	}
	var blockedOp *BlockedOperatorHostError
	if errors.As(err, &blockedOp) {
		return blockedOp
	}
	if errors.Is(err, errIndexerNetwork) {
		return errIndexerNetwork
	}
	reason := "network error"
	var netErr net.Error
	switch {
	case errors.Is(err, context.DeadlineExceeded) || (errors.As(err, &netErr) && netErr.Timeout()):
		reason = "timed out"
	case errors.Is(err, context.Canceled):
		reason = "canceled"
	case errors.Is(err, ErrPermissionDenied):
		// A redirect left the plugin's network grant.
		return fmt.Errorf("%w: a redirect from %s left the granted hosts", ErrPermissionDenied, host)
	case errors.Is(err, safefetch.ErrBlocked):
		if isNonPublicBlockError(err) {
			return &BlockedLocalHostError{Host: host}
		}
		return fmt.Errorf("%w: %s is not allowed (%w)", ErrFetchFailed, host, safefetch.ErrBlocked)
	}
	if reason == "timed out" {
		return fmt.Errorf("%w: %s: %w", ErrFetchFailed, host, context.DeadlineExceeded)
	}
	return fmt.Errorf("%w: %s: %s", ErrFetchFailed, host, reason)
}

type fetchOptions struct {
	stripCrossOriginHeaders []string
	stripAllCallerHeaders   bool
	applyHostLimit          bool
	dedicatedConnection     bool
}

func validateKeepHeadersOnRedirect(man Manifest, g Grants, raw []string) ([]safefetch.RedirectHeaderPattern, error) {
	patterns, err := safefetch.ParseRedirectHeaderPatterns(raw)
	if err != nil {
		return nil, &ValidationError{Fields: []FieldError{{
			Field:   "keepHeadersOnRedirect",
			Message: err.Error(),
		}}}
	}
	var network []string
	if man.Ether != nil {
		network = man.Ether.Permissions.Network
	}
	for _, p := range patterns {
		if !networkCoversRedirectPattern(network, g, man, p) {
			return nil, fmt.Errorf("%w: keepHeadersOnRedirect %q is not in granted network hosts", ErrPermissionDenied, p.Raw)
		}
	}
	return patterns, nil
}

func networkCoversRedirectPattern(network []string, g Grants, man Manifest, p safefetch.RedirectHeaderPattern) bool {
	if p.Wildcard {
		return hostPatternCoveredByNetwork(network, p.Host)
	}
	u := p.SyntheticURL()
	if u == nil {
		return false
	}
	return networkAllowedURL(network, u) ||
		g.allowsLocalURL(u) ||
		(DeclaresOperatorHosts(man) && g.allowsOperatorURL(u))
}

func hostPatternCoveredByNetwork(network []string, wildcardSuffix string) bool {
	for _, raw := range network {
		p := strings.ToLower(strings.TrimSpace(raw))
		if !strings.HasPrefix(p, "*.") {
			continue
		}
		netSuffix := strings.TrimSuffix(p[2:], ".")
		if netSuffix == "" {
			continue
		}
		if wildcardSuffix == netSuffix || strings.HasSuffix(wildcardSuffix, "."+netSuffix) {
			return true
		}
	}
	return false
}

func (h *host) openFetch(ctx context.Context, req FetchRequest) (*http.Response, error) {
	return h.openFetchWithOptions(ctx, req, fetchOptions{})
}

func (h *host) openFetchWithOptions(ctx context.Context, req FetchRequest, opts fetchOptions) (*http.Response, error) {
	r, g, err := h.record(ctx)
	if err != nil {
		return nil, err
	}
	u, err := url.Parse(req.URL)
	if err != nil || u.Hostname() == "" || (u.Scheme != "https" && u.Scheme != "http") {
		return nil, fmt.Errorf("%w: bad url", ErrPermissionDenied)
	}
	if err := h.m.CheckIndexerNetwork(u.Hostname()); err != nil {
		return nil, err
	}
	if g.revoked("network") {
		h.noteDenied("network")
		return nil, fmt.Errorf("%w: network", ErrPermissionDenied)
	}
	if !networkAllowedURL(r.Manifest.Ether.Permissions.Network, u) &&
		!g.allowsLocalURL(u) &&
		!(DeclaresOperatorHosts(r.Manifest) && g.allowsOperatorURL(u)) {
		if DeclaresOperatorHosts(r.Manifest) {
			blocked := urlHostPortDisplay(u)
			h.m.noteBlockedOperatorHost(ctx, h.plugin, blocked)
			return nil, &BlockedOperatorHostError{Host: blocked}
		}
		if IsLocalNetworkHost(u.Hostname()) {
			blocked := urlHostPortDisplay(u)
			h.m.noteBlockedLocalHost(ctx, h.plugin, blocked)
			return nil, &BlockedLocalHostError{Host: blocked}
		}
		h.noteDenied("network")
		return nil, fmt.Errorf("%w: network", ErrPermissionDenied)
	}
	redirectPatterns, err := validateKeepHeadersOnRedirect(r.Manifest, g, req.KeepHeadersOnRedirect)
	if err != nil {
		if errors.Is(err, ErrPermissionDenied) {
			h.noteDenied("network")
		}
		return nil, err
	}
	if trusted := trustedFetchHosts(r.Manifest, g); len(trusted) > 0 {
		ctx = safefetch.WithTrustedHosts(ctx, trusted)
	}
	method := req.Method
	if method == "" {
		method = http.MethodGet
	}
	hr, err := http.NewRequestWithContext(ctx, method, req.URL, bytes.NewReader(req.Body))
	if err != nil {
		return nil, err
	}
	hr.Close = opts.dedicatedConnection
	for k, v := range req.Headers {
		hr.Header.Set(k, v)
	}
	// Recheck the current grant before every redirect, as well as the SSRF
	// guard's own redirect policy. A redirect is another network request.
	// Credentials and caller-supplied headers follow redirects only within the
	// same origin, to a strict same-site subdomain (no scheme downgrade or port
	// change, verified via the Public Suffix List), or to a host explicitly
	// listed in KeepHeadersOnRedirect (still within live network grants and
	// never across HTTPS -> HTTP downgrades). Confinement is sticky across hops.
	// When ctx already has a deadline, let Request.Context govern both headers
	// and body reads so timeouts always surface context.DeadlineExceeded rather
	// than net/http's non-unwrapping Client.Timeout error.
	client := *h.m.client
	if _, ok := ctx.Deadline(); ok {
		client.Timeout = 0
	}
	lastURL := u
	redirectHeaders := safefetch.NewRedirectHeaderState(u, safefetch.RedirectHeaderOptions{
		Patterns:              redirectPatterns,
		InitialHeaders:        hr.Header,
		StripAllCallerHeaders: opts.stripAllCallerHeaders,
		StripHeaders:          opts.stripCrossOriginHeaders,
	})
	previousRedirect := client.CheckRedirect
	release := func() {}
	acquire := func(ctx context.Context, target *url.URL) error {
		if !opts.applyHostLimit || h.m.fetchHosts == nil {
			return nil
		}
		var err error
		release, err = h.m.fetchHosts.Acquire(ctx, target.String())
		if err != nil {
			release = func() {}
			return fetchError(target.Hostname(), err)
		}
		return nil
	}
	client.CheckRedirect = func(next *http.Request, via []*http.Request) error {
		lastURL = next.URL
		if err := h.m.CheckIndexerNetwork(next.URL.Hostname()); err != nil {
			return err
		}
		redirectHeaders.Apply(next)
		next.Close = opts.dedicatedConnection
		current, grants, err := h.record(next.Context())
		if err != nil {
			return err
		}
		if grants.revoked("network") {
			h.noteDenied("network")
			return fmt.Errorf("%w: network", ErrPermissionDenied)
		}
		if !networkAllowedURL(current.Manifest.Ether.Permissions.Network, next.URL) &&
			!grants.allowsLocalURL(next.URL) &&
			!(DeclaresOperatorHosts(current.Manifest) && grants.allowsOperatorURL(next.URL)) {
			if DeclaresOperatorHosts(current.Manifest) {
				blocked := urlHostPortDisplay(next.URL)
				h.m.noteBlockedOperatorHost(next.Context(), h.plugin, blocked)
				return &BlockedOperatorHostError{Host: blocked}
			}
			if IsLocalNetworkHost(next.URL.Hostname()) {
				blocked := urlHostPortDisplay(next.URL)
				h.m.noteBlockedLocalHost(next.Context(), h.plugin, blocked)
				return &BlockedLocalHostError{Host: blocked}
			}
			h.noteDenied("network")
			return fmt.Errorf("%w: network", ErrPermissionDenied)
		}
		*next = *next.WithContext(safefetch.WithTrustedHosts(next.Context(), trustedFetchHosts(current.Manifest, grants)))
		if previousRedirect != nil {
			if err := previousRedirect(next, via); err != nil {
				return err
			}
		} else if len(via) >= 10 {
			return errors.New("plugins: stopped after 10 redirects")
		}
		// Release before acquiring another origin so reciprocal redirects
		// cannot deadlock at the shared concurrency cap.
		if opts.applyHostLimit && fetchHostKey(via[len(via)-1].URL.String()) != fetchHostKey(next.URL.String()) {
			release()
			return acquire(next.Context(), next.URL)
		}
		return nil
	}
	if err := acquire(ctx, u); err != nil {
		return nil, err
	}
	resp, err := client.Do(hr)
	if err != nil {
		release()
		if isNonPublicBlockError(err) {
			blocked := urlHostPortDisplay(lastURL)
			h.m.noteBlockedLocalHost(ctx, h.plugin, blocked)
			return nil, fetchError(blocked, err)
		}
		return nil, fetchError(u.Hostname(), err)
	}
	if opts.applyHostLimit {
		resp.Body = &releaseOnCloseReadCloser{ReadCloser: resp.Body, release: release}
	}
	return resp, nil
}

