// journalWrite records a write (and, unless shadow, has already applied
// it; callers pass the inverse they obtained).
func (h *host) journal(ctx context.Context, r Record, op, detail string, inverse any) error {
	raw, err := json.Marshal(inverse)
	if err != nil {
		return err
	}
	_, err = h.m.store.journal(ctx, JournalEntry{Plugin: h.plugin, Op: op, Detail: detail, Inverse: raw, Shadow: r.Shadow})
	return err
}

type watchInverse struct {
	Op       string `json:"op"`
	ViewerID int64  `json:"viewerId"`
	TitleID  string `json:"titleId"`
	Watched  bool   `json:"watched"`
}

type collectionInverse struct {
	Op       string          `json:"op"`
	Previous json.RawMessage `json:"previous,omitempty"` // empty means delete
	Doc      json.RawMessage `json:"doc,omitempty"`
}

func (h *host) SetWatchState(ctx context.Context, viewerID int64, titleID string, watched bool) error {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return err
	}
	r, g, err := h.record(ctx)
	if err != nil {
		return err
	}
	if err := h.deny(r, g, "viewers.write_watch_state", normLevel(r.Manifest.Ether.Permissions.Viewers.WriteWatchState),
		func(l string) bool { return viewerOK(g, l, viewerID) }); err != nil {
		return err
	}
	if r.Shadow {
		return h.journal(ctx, r, "viewers.setWatchState", titleID, watchInverse{Op: "viewers.setWatchState", ViewerID: viewerID, TitleID: titleID, Watched: !watched})
	}
	if h.m.deps.Backends.SetWatchState == nil {
		return ErrUnavailable
	}
	prev, err := h.m.deps.Backends.SetWatchState(ctx, h.plugin, viewerID, titleID, watched)
	if err != nil {
		return err
	}
	return h.journal(ctx, r, "viewers.setWatchState", titleID, watchInverse{Op: "viewers.setWatchState", ViewerID: viewerID, TitleID: titleID, Watched: prev})
}

func (h *host) CollectionsUpsert(ctx context.Context, doc json.RawMessage) error {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return err
	}
	r, g, err := h.record(ctx)
	if err != nil {
		return err
	}
	if err := h.deny(r, g, "collections", normLevel(r.Manifest.Ether.Permissions.Collections),
		func(l string) bool { return l == "write" }); err != nil {
		return err
	}
	if r.Shadow {
		return h.journal(ctx, r, "collections.upsert", "", collectionInverse{Op: "collections.upsert", Doc: doc})
	}
	if h.m.deps.Backends.CollectionsUpsert == nil {
		return ErrUnavailable
	}
	prev, err := h.m.deps.Backends.CollectionsUpsert(collectionContext(ctx, h.plugin), doc)
	if err != nil {
		return err
	}
	return h.journal(ctx, r, "collections.upsert", "", collectionInverse{Op: "collections.upsert", Previous: prev, Doc: doc})
}

// UndoAll replays a plugin's live journal inverses, newest first, and
// returns how many entries were undone.
func (m *Manager) UndoAll(ctx context.Context, pluginID string) (int, error) {
	return m.UndoSince(ctx, pluginID, 0)
}

// UndoSince reverses the plugin's changes back to and including entry
// since (0 means all of them within the retained live journal window),
// newest first, so an older change is never reversed underneath a later one.
func (m *Manager) UndoSince(ctx context.Context, pluginID string, since int64) (int, error) {
	entries, err := m.store.journalList(ctx, pluginID, JournalLiveMaxEntries, true)
	if err != nil {
		return 0, err
	}
	undone := 0
	for _, e := range entries { // journalList is newest first
		if e.ID < since {
			break
		}
		if err := m.applyInverse(ctx, e); err != nil {
			return undone, err
		}
		if err := m.store.markUndone(ctx, e.ID); err != nil {
			return undone, err
		}
		undone++
	}
	return undone, nil
}

func (m *Manager) applyInverse(ctx context.Context, e JournalEntry) error {
	switch e.Op {
	case "viewers.setWatchState":
		var inv watchInverse
		if err := json.Unmarshal(e.Inverse, &inv); err != nil {
			return err
		}
		if m.deps.Backends.SetWatchState == nil {
			return ErrUnavailable
		}
		_, err := m.deps.Backends.SetWatchState(ctx, e.Plugin, inv.ViewerID, inv.TitleID, inv.Watched)
		return err
	case "collections.upsert":
		var inv collectionInverse
		if err := json.Unmarshal(e.Inverse, &inv); err != nil {
			return err
		}
		if len(inv.Previous) > 0 {
			if m.deps.Backends.CollectionsUpsert == nil {
				return ErrUnavailable
			}
			_, err := m.deps.Backends.CollectionsUpsert(collectionContext(ctx, e.Plugin), inv.Previous)
			return err
		}
		if m.deps.Backends.CollectionsDelete == nil {
			return ErrUnavailable
		}
		return m.deps.Backends.CollectionsDelete(collectionContext(ctx, e.Plugin), inv.Doc)
	case "kinds.upsert":
		var inv kindInverse
		if err := json.Unmarshal(e.Inverse, &inv); err != nil {
			return err
		}
		b := m.kindBackends()
		if len(inv.Previous) > 0 {
			if b.KindUpsert == nil {
				return ErrUnavailable
			}
			if _, err := b.KindUpsert(ctx, e.Plugin, inv.Kind, inv.Previous); err != nil {
				return err
			}
		}
		if len(inv.Items) > 0 {
			if b.KindDelete == nil {
				return ErrUnavailable
			}
			if err := b.KindDelete(ctx, e.Plugin, inv.Kind, inv.Items); err != nil {
				return err
			}
		}
		return nil
	case "kinds.delete":
		var inv kindInverse
		if err := json.Unmarshal(e.Inverse, &inv); err != nil {
			return err
		}
		if len(inv.Previous) > 0 {
			b := m.kindBackends()
			if b.KindUpsert == nil {
				return ErrUnavailable
			}
			_, err := b.KindUpsert(ctx, e.Plugin, inv.Kind, inv.Previous)
			return err
		}
		return nil
	case "badges.set", "badges.clear":
		return nil
	default:
		return fmt.Errorf("plugins: no inverse for journal op %q", e.Op)
	}
}

func (h *host) folderCheck(ctx context.Context, root, path string) (string, error) {
	r, g, err := h.record(ctx)
	if err != nil {
		return "", err
	}
	if err := h.deny(r, g, "folders", normLevel(r.Manifest.Ether.Permissions.Folders),
		func(l string) bool { return l == "read" }); err != nil {
		return "", err
	}
	granted := false
	for _, f := range g.Folders {
		if f == root {
			granted = true
		}
	}
	if !granted {
		h.noteDenied("folders")
		return "", fmt.Errorf("%w: folder was not picked for this plugin", ErrPermissionDenied)
	}
	cleanRoot := filepath.Clean(root)
	joined := filepath.Clean(filepath.Join(cleanRoot, path))
	if joined != cleanRoot && !strings.HasPrefix(joined, cleanRoot+string(filepath.Separator)) {
		return "", fmt.Errorf("%w: path leaves the picked folder", ErrPermissionDenied)
	}
	return joined, nil
}

func (h *host) FoldersStat(ctx context.Context, root, path string) (FolderEntry, error) {
	_, err := h.folderCheck(ctx, root, path)
	if err != nil {
		return FolderEntry{}, err
	}
	fs, err := os.OpenRoot(root)
	if err != nil {
		return FolderEntry{}, err
	}
	defer fs.Close()
	name := path
	if name == "" {
		name = "."
	}
	info, err := fs.Stat(name)
	if err != nil {
		return FolderEntry{}, err
	}
	return FolderEntry{Name: info.Name(), Path: path, Dir: info.IsDir(), Size: info.Size(), Mtime: info.ModTime().Unix()}, nil
}

func (m *Manager) rateOK(bucket map[string][]time.Time, key string, limit int, window time.Duration) bool {
	ok, _ := m.rateOKRetryAt(bucket, key, limit, window)
	return ok
}

func (m *Manager) rateOKRetryAt(bucket map[string][]time.Time, key string, limit int, window time.Duration) (bool, time.Time) {
	m.mu.Lock()
	defer m.mu.Unlock()
	now := m.now()
	kept := bucket[key][:0:0]
	for _, t := range bucket[key] {
		if now.Sub(t) < window {
			kept = append(kept, t)
		}
	}
	if len(kept) >= limit {
		bucket[key] = kept
		retryAt := now.Add(window)
		if len(kept) > 0 {
			retryAt = kept[0].Add(window)
		}
		return false, retryAt.UTC()
	}
	bucket[key] = append(kept, now)
	return true, time.Time{}
}

func (m *Manager) rateLimitError(message string, retryAt time.Time) error {
	now := m.now()
	var after time.Duration
	if !retryAt.IsZero() {
		retryAt = retryAt.UTC()
		after = retryAt.Sub(now)
		if after < time.Second {
			after = time.Second
		}
	}
	return &RateLimitError{
		Message:    message,
		RetryAt:    retryAt,
		RetryAfter: after,
	}
}

func (h *host) NotifyOwner(ctx context.Context, text string) error {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return err
	}
	if _, _, err := h.record(ctx); err != nil {
		return err
	}
	if !h.m.rateOK(h.m.notifyTimes, h.plugin, 5, time.Hour) {
		return fmt.Errorf("plugins: owner notices are limited to five an hour")
	}
	text = h.m.store.redactKnown(ctx, h.plugin, text)
	if h.m.deps.Backends.Notice != nil {
		h.m.deps.Backends.Notice(truncate(text, 500))
	}
	h.m.store.addLog(ctx, h.plugin, "notice: "+text)
	return nil
}

func (h *host) Log(ctx context.Context, level, msg string, attrs map[string]any) error {
	if _, _, err := h.record(ctx); err != nil {
		return err
	}
	if !h.m.rateOK(h.m.logTimes, h.plugin, 600, time.Minute) {
		return nil // drop, never fail the caller for logging
	}
	line := level + ": " + msg
	if len(attrs) > 0 {
		if raw, err := json.Marshal(attrs); err == nil {
			line += " " + redactJSON(raw)
		}
	}
	h.m.store.addLog(ctx, h.plugin, line)
	return nil
}

func (h *host) noteFetchTraffic(ctx context.Context, req FetchRequest, size int64) {
	u, err := url.Parse(req.URL)
	if err != nil {
		return
	}
	h.m.healthMu.Lock()
	defer h.m.healthMu.Unlock()
	if hh, err := h.m.store.health(ctx, h.plugin); err == nil {
		hh.Observed[u.Hostname()]++
		hh.EgressBytes += size + int64(len(req.Body))
		_ = h.m.store.putHealth(ctx, h.plugin, hh)
	}
}

// Safe per-plugin bounds for Host.AIComplete (#669, #702). No owner settings are
// exposed for these bounds; they protect the owner's configured language model
// and memory budget with predictable defaults.
const (
	// DefaultAICompletePerMin caps completions per plugin in a sliding minute.
	DefaultAICompletePerMin = 20
	// DefaultAISearchCompletePerMin caps uncached interactive search completions
	// per (plugin, viewer) in a sliding minute, separate from the plugin's
	// background completion budget (#702).
	DefaultAISearchCompletePerMin = 10
	// MaxAIMessages caps the chat message count in a single completion request.
	MaxAIMessages = 20
	// MaxAIInputBytes caps total UTF-8 message content bytes per request.
	MaxAIInputBytes = 32 * 1024
	// MaxAISchemaBytes caps the optional JSON Schema document size.
	MaxAISchemaBytes = 32 * 1024
	// DefaultAIMaxTokens is the reply token budget when maxTokens is omitted.
	DefaultAIMaxTokens = 1024
	// MaxAIMaxTokens is the hard ceiling on maxTokens per completion.
	MaxAIMaxTokens = 4096
	// DefaultAITimeout bounds one background/action completion when timeoutMs is omitted.
	DefaultAITimeout = 30 * time.Second
	// MaxAITimeout is the hard ceiling on timeoutMs for background/action completions.
	MaxAITimeout = 30 * time.Second
	// DefaultAISearchTimeout bounds one completion on an interactive search route
	// when timeoutMs is omitted (#702). Matches Ether's own descriptive search
	// wait bound (experience.DescriptiveSearchWaitBound).
	DefaultAISearchTimeout = 20 * time.Second
	// MaxAISearchTimeout is the hard per-request ceiling on timeoutMs for
	// interactive search completions (#702), never exceeding Ether's 20 s
	// descriptive search wait bound.
	MaxAISearchTimeout = 20 * time.Second
	// AISearchRouteDeadline gives an opted-in catalog/kind search route room
	// for MaxAISearchTimeout plus fallback serialization after a timeout.
	AISearchRouteDeadline = MaxAISearchTimeout + 2*time.Second
	// MaxAISearchQueryBytes bounds the search query string used for interactive
	// search completions and per-query caching (matches Ether's descriptive search).
	MaxAISearchQueryBytes = 1000
	// DefaultAISearchCacheTTL bounds how long a search completion stays cached
	// per normalized query before re-asking the model (matches Ether's search cache).
	DefaultAISearchCacheTTL = 10 * time.Minute
	// MaxAISearchCacheEntries caps cached search completions per plugin.
	MaxAISearchCacheEntries = 256
	// MaxAdapterSearchPaths caps declared searchPaths entries per frontend adapter.
	MaxAdapterSearchPaths = 16
	// MaxAIResponseBytes caps the model reply text / validated JSON returned
	// to the plugin.
	MaxAIResponseBytes = 64 * 1024
)

// withCallPath records the active plugin route path on ctx so host calls can
// enforce route-class policies (for example blocking ai.complete on client
// request paths).
func withCallPath(ctx context.Context, path string) context.Context {
	if path == "" {
		return ctx
	}
	return context.WithValue(ctx, callPathKey{}, path)
}

func withCallSearchQuery(ctx context.Context, query string) context.Context {
	q := strings.TrimSpace(query)
	if q == "" {
		return ctx
	}
	return context.WithValue(ctx, callSearchQueryKey{}, q)
}

// WithCallContext attaches the active plugin route path and any host-extracted
// search query to ctx (used by remote host callbacks authenticated with a
// host-minted X-Ether-Viewer-Token).
func WithCallContext(ctx context.Context, path, searchQuery string) context.Context {
	ctx = withCallPath(ctx, path)
	return withCallSearchQuery(ctx, searchQuery)
}

func callPathFromContext(ctx context.Context) string {
	if ctx == nil {
		return ""
	}
	if p, _ := ctx.Value(callPathKey{}).(string); p != "" {
		return p
	}
	return wasm.CallPath(ctx)
}

func callSearchQueryFromContext(ctx context.Context) string {
	if ctx == nil {
		return ""
	}
	q, _ := ctx.Value(callSearchQueryKey{}).(string)
	return strings.TrimSpace(q)
}

// AIPermissionAllowsComplete reports whether an ether.permissions.ai level
// grants base ai.complete access ("complete" or "complete+search").
func AIPermissionAllowsComplete(level string) bool {
	l := normLevel(strings.TrimSpace(level))
	return l == "complete" || l == "complete+search"
}

// AIPermissionAllowsSearch reports whether an ether.permissions.ai level
// opts in to bounded, cached ai.complete on interactive search routes (#702).
func AIPermissionAllowsSearch(level string) bool {
	return normLevel(strings.TrimSpace(level)) == "complete+search"
}

// NormalizeAISearchQuery normalizes a viewer search query for per-query
// caching (lowercased, runs of whitespace collapsed to a single space).
func NormalizeAISearchQuery(q string) string {
	return strings.ToLower(strings.Join(strings.Fields(q), " "))
}

func normalizeAdapterSearchPath(raw string) (string, bool) {
	s := strings.TrimSpace(raw)
	if s == "" || !strings.HasPrefix(s, "/") {
		return "", false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c <= 0x20 || c == 0x7f || c == '?' || c == '#' || c == '\\' {
			return "", false
		}
	}
	if strings.Contains(s, "..") || strings.Contains(s, "//") {
		return "", false
	}
	if len(s) > 1 {
		s = strings.TrimRight(s, "/")
		if s == "" {
			s = "/"
		}
	}
	return s, true
}

// isClientRequestPath reports whether p is an interactive viewer, client
// protocol adapter, or console UI/lifecycle path that must never wait on a
// language model call (except opted-in interactive search routes under
// permissions.ai: "complete+search").
func isClientRequestPath(p string) bool {
	p, _, _ = strings.Cut(strings.TrimSpace(p), "?")
	return wasm.ViewerRequestPath(p) ||
		strings.HasPrefix(p, "/ether/stream/") ||
		strings.HasPrefix(p, "/ether/v1/frontend/") ||
		strings.HasPrefix(p, "/ether/view/") || p == "/ether/view" ||
		strings.HasPrefix(p, "/ether/options/") || p == "/ether/options" ||
		p == "/ether/health" ||
		p == "/ether/configure" ||
		strings.HasPrefix(p, "/ether/file/") ||
		strings.HasPrefix(p, "/ether/directory/")
}

func isStremioCatalogRoute(path string) bool {
	p, _, _ := strings.Cut(strings.TrimSpace(path), "?")
	if !strings.HasPrefix(p, "/catalog/") || !strings.HasSuffix(p, ".json") {
		return false
	}
	trimmed := strings.TrimSuffix(strings.TrimPrefix(p, "/catalog/"), ".json")
	parts := strings.Split(trimmed, "/")
	if len(parts) != 2 && len(parts) != 3 {
		return false
	}
	for _, seg := range parts {
		if seg == "" {
			return false
		}
	}
	return true
}

// stremioCatalogSearchQuery extracts a non-empty Stremio catalog search query
// from /catalog/{type}/{id}/{extra}.json (extra containing search=<q>) or
// /catalog/{type}/{id}.json?search=<q>.
func stremioCatalogSearchQuery(path string) (string, bool) {
	p, rawQuery, _ := strings.Cut(strings.TrimSpace(path), "?")
	if !strings.HasPrefix(p, "/catalog/") || !strings.HasSuffix(p, ".json") {
		return "", false
	}
	trimmed := strings.TrimSuffix(strings.TrimPrefix(p, "/catalog/"), ".json")
	parts := strings.Split(trimmed, "/")
	if len(parts) == 3 && parts[0] != "" && parts[1] != "" && parts[2] != "" {
		if vals, err := url.ParseQuery(parts[2]); err == nil {
			if q := strings.TrimSpace(vals.Get("search")); q != "" {
				return q, true
			}
		}
	}
	if (len(parts) == 2 || len(parts) == 3) && parts[0] != "" && parts[1] != "" && rawQuery != "" {
		if vals, err := url.ParseQuery(rawQuery); err == nil {
			if q := strings.TrimSpace(vals.Get("search")); q != "" {
				return q, true
			}
		}
	}
	return "", false
}

func isKindSearchPath(path string) bool {
	p, _, _ := strings.Cut(strings.TrimSpace(path), "?")
	if !strings.HasPrefix(p, "/ether/v1/kinds/") {
		return false
	}
	rest := strings.TrimPrefix(p, "/ether/v1/kinds/")
	kindKey, action, ok := strings.Cut(rest, "/")
	return ok && kindKey != "" && action == "search"
}

func isConventionalAdapterSearchSubpath(subpath string) bool {
	if subpath == "" || subpath == "/" {
		return false
	}
	trimmed := strings.Trim(subpath, "/")
	if trimmed == "" {
		return false
	}
	last := trimmed
	if idx := strings.LastIndexByte(trimmed, '/'); idx >= 0 {
		last = trimmed[idx+1:]
	}
	last = strings.ToLower(last)
	for _, ext := range []string{".json", ".xml", ".view"} {
		last = strings.TrimSuffix(last, ext)
	}
	return last == "search" || last == "search2" || last == "search3"
}

func isFrontendAdapterSearchPath(man Manifest, path string) bool {
	p, _, _ := strings.Cut(strings.TrimSpace(path), "?")
	if !strings.HasPrefix(p, "/ether/v1/frontend/") {
		return false
	}
	if !man.HasCapability(CapFrontendAdapter) {
		return false
	}
	e := man.EffectiveEther()
	if e == nil {
		return false
	}
	rest := strings.TrimPrefix(p, "/ether/v1/frontend/")
	if rest == "" {
		return false
	}
	adapterKey, tail, hasSlash := strings.Cut(rest, "/")
	if adapterKey == "" {
		return false
	}
	subpath := "/"
	if hasSlash {
		subpath = "/" + tail
	}
	normSub, ok := normalizeAdapterSearchPath(subpath)
	if !ok {
		return false
	}
	for _, a := range e.Contributes.FrontendAdapters {
		if a.Key != adapterKey {
			continue
		}
		if len(a.SearchPaths) > 0 {
			for _, declared := range a.SearchPaths {
				if normDecl, ok := normalizeAdapterSearchPath(declared); ok && normDecl == normSub {
					return true
				}
			}
			return false
		}
		return isConventionalAdapterSearchSubpath(normSub)
	}
	return false
}

// AICompleteSearchPath reports whether path is an interactive viewer search
// route eligible for ai.complete when permissions.ai is "complete+search":
//   - a Stremio-style catalog search with a non-empty query (/catalog/{type}/{id}/search=….json),
//   - a media-kind live search (/ether/v1/kinds/{kind}/search), or
//   - a declared frontend adapter's search route (/ether/v1/frontend/{key}/…).
func AICompleteSearchPath(man Manifest, path string) bool {
	if _, ok := stremioCatalogSearchQuery(path); ok {
		return true
	}
	if isKindSearchPath(path) {
		return true
	}
	return isFrontendAdapterSearchPath(man, path)
}

func isActiveSearchRoute(man Manifest, path, callQuery string) bool {
	if AICompleteSearchPath(man, path) {
		return true
	}
	return isStremioCatalogRoute(path) && strings.TrimSpace(callQuery) != ""
}

// extractCallSearchQuery pulls a viewer search query from an inbound plugin
// request when present (Stremio search extra, kinds search JSON body, or
// frontend-adapter query string) for host enforcement and per-query caching.
func extractCallSearchQuery(req Request) string {
	if q, ok := stremioCatalogSearchQuery(req.Path); ok {
		return q
	}
	if isStremioCatalogRoute(req.Path) && req.Query != nil {
		if q := strings.TrimSpace(req.Query["search"]); q != "" {
			return q
		}
	}
	if isKindSearchPath(req.Path) {
		if len(req.Body) > 0 {
			var body struct {
				Query string `json:"query"`
			}
			if json.Unmarshal(req.Body, &body) == nil {
				if q := strings.TrimSpace(body.Query); q != "" {
					return q
				}
			}
		}
		if q := queryParamFromRequest(req, "query", "q", "search"); q != "" {
			return q
		}
		return ""
	}
	if isFrontendAdapterRoute(req.Path) {
		return queryParamFromRequest(req, "q", "query", "search")
	}
	return ""
}

func queryParamFromRequest(req Request, keys ...string) string {
	if _, rawQuery, ok := strings.Cut(req.Path, "?"); ok && rawQuery != "" {
		if vals, err := url.ParseQuery(rawQuery); err == nil {
			for _, k := range keys {
				if q := strings.TrimSpace(vals.Get(k)); q != "" {
					return q
				}
			}
		}
	}
	for _, k := range keys {
		if q := strings.TrimSpace(req.Query[k]); q != "" {
			return q
		}
	}
	return ""
}

// AICompleteAllowedPath reports whether a plugin route may call ai.complete.
// Interactive viewer/client request paths are refused except opted-in search
// routes (Stremio catalog search with a query, kinds search, and frontend
// adapter search routes) when the manifest declares permissions.ai:
// "complete+search" (#702). Actions, jobs, Flow actions, tools, event
// deliveries, setup/test, background sync, and declared scheduled routes are
// allowed under both "complete" and "complete+search".
func AICompleteAllowedPath(man Manifest, path string, background bool) bool {
	p, _, _ := strings.Cut(strings.TrimSpace(path), "?")
	if p == "" {
		return false
	}
	if isClientRequestPath(p) {
		e := man.EffectiveEther()
		return e != nil && AIPermissionAllowsSearch(e.Permissions.AI) && AICompleteSearchPath(man, path)
	}
	if background {
		return true
	}
	switch {
	case strings.HasPrefix(p, "/ether/action/"),
		strings.HasPrefix(p, "/ether/job/"),
		strings.HasPrefix(p, "/ether/v1/flow-actions/"),
		p == "/ether/event",
		strings.HasPrefix(p, "/ether/tool/"),
		strings.HasPrefix(p, "/ether/v1/setup/"),
		p == "/ether/test",
		strings.HasPrefix(p, "/ether/feed/"),
		wasm.KindSyncPath(p),
		wasm.LiveTVSyncPath(p):
		return true
	}
	man.Ether = man.EffectiveEther()
	if man.Ether != nil {
		for _, s := range man.Ether.Schedule {
			callPath, _, _ := strings.Cut(strings.TrimSpace(s.Call), "?")
			if callPath == p {
				return true
			}
		}
		for _, fa := range man.Ether.Contributes.FlowActions {
			route, _, _ := strings.Cut(strings.TrimSpace(fa.Route), "?")
			if route == p {
				return true
			}
		}
	}
	return false
}

// denyExternalSchemaLoader refuses every external $ref load so plugin-supplied
// JSON Schemas can never trigger outbound network calls or local file reads.
type denyExternalSchemaLoader struct{}

func (denyExternalSchemaLoader) Load(url string) (any, error) {
	return nil, fmt.Errorf("external schema $ref is not allowed (%s)", url)
}

// ValidateAICompleteRequest validates messages, size/token/temperature/timeout
// bounds, and compiles any optional JSON Schema. Exported for Studio and the
// conformance kit so offline checks enforce the same contract as the host.
func ValidateAICompleteRequest(req AICompleteRequest) (*compiledAIRequest, error) {
	var errs []FieldError
	if len(req.Messages) == 0 {
		errs = append(errs, FieldError{Field: "messages", Message: "at least one message is required"})
	} else if len(req.Messages) > MaxAIMessages {
		errs = append(errs, FieldError{Field: "messages", Message: fmt.Sprintf("at most %d messages are allowed", MaxAIMessages)})
	}

	var totalBytes int
	hasUser := false
	msgs := make([]AIMessage, 0, len(req.Messages))
	for i, m := range req.Messages {
		role := strings.TrimSpace(m.Role)
		switch role {
		case "system", "user", "assistant":
			if role == "user" {
				hasUser = true
			}
		default:
			errs = append(errs, FieldError{
				Field:   fmt.Sprintf("messages[%d].role", i),
				Message: "must be one of system, user, assistant",
			})
		}
		if strings.TrimSpace(m.Content) == "" {
			errs = append(errs, FieldError{
				Field:   fmt.Sprintf("messages[%d].content", i),
				Message: "must not be empty",
			})
		}
		totalBytes += len(m.Content)
		msgs = append(msgs, AIMessage{Role: role, Content: m.Content})
	}
	if len(req.Messages) > 0 && !hasUser {
		errs = append(errs, FieldError{Field: "messages", Message: "at least one user message is required"})
	}
	if totalBytes > MaxAIInputBytes {
		errs = append(errs, FieldError{Field: "messages", Message: fmt.Sprintf("total message content exceeds %d bytes", MaxAIInputBytes)})
	}

	maxTokens := req.MaxTokens
	if maxTokens == 0 {
		maxTokens = DefaultAIMaxTokens
	} else if maxTokens < 0 || maxTokens > MaxAIMaxTokens {
		errs = append(errs, FieldError{Field: "maxTokens", Message: fmt.Sprintf("must be between 1 and %d", MaxAIMaxTokens)})
	}

	var temp *float64
	if req.Temperature != nil {
		t := *req.Temperature
		if math.IsNaN(t) || math.IsInf(t, 0) || t < 0 || t > 2 {
			errs = append(errs, FieldError{Field: "temperature", Message: "must be between 0 and 2"})
		} else {
			temp = &t
		}
	}

	timeout := DefaultAITimeout
	if req.TimeoutMS < 0 {
		errs = append(errs, FieldError{Field: "timeoutMs", Message: "must not be negative"})
	} else if req.TimeoutMS > 0 {
		timeout = min(time.Duration(req.TimeoutMS)*time.Millisecond, MaxAITimeout)
	}

	searchQuery := strings.TrimSpace(req.SearchQuery)
	if len(searchQuery) > MaxAISearchQueryBytes {
		errs = append(errs, FieldError{Field: "searchQuery", Message: fmt.Sprintf("exceeds %d bytes", MaxAISearchQueryBytes)})
	}

	var compiled *jsonschema.Schema
	var canonicalSchema []byte
	var jsonObjectMode bool
	trimmedSchema := bytes.TrimSpace(req.Schema)
	if len(trimmedSchema) > 0 && !bytes.Equal(trimmedSchema, []byte("null")) {
		if len(trimmedSchema) > MaxAISchemaBytes {
			errs = append(errs, FieldError{Field: "schema", Message: fmt.Sprintf("exceeds %d bytes", MaxAISchemaBytes)})
		} else {
			doc, err := jsonschema.UnmarshalJSON(bytes.NewReader(trimmedSchema))
			if err != nil {
				errs = append(errs, FieldError{Field: "schema", Message: "must be valid JSON"})
			} else if obj, ok := doc.(map[string]any); !ok {
				errs = append(errs, FieldError{Field: "schema", Message: "must be a JSON Schema object"})
			} else {
				compiler := jsonschema.NewCompiler()
				compiler.UseLoader(denyExternalSchemaLoader{})
				const schemaURI = "urn:ether:plugin:ai:schema.json"
				if err := compiler.AddResource(schemaURI, doc); err != nil {
					errs = append(errs, FieldError{Field: "schema", Message: "invalid JSON Schema: " + err.Error()})
				} else if s, err := compiler.Compile(schemaURI); err != nil {
					errs = append(errs, FieldError{Field: "schema", Message: "invalid JSON Schema: " + err.Error()})
				} else {
					compiled = s
					canonicalSchema, _ = json.Marshal(doc)
					jsonObjectMode = schemaExpectsJSONObject(obj)
				}
			}
		}
	}

	if len(errs) > 0 {
		return nil, &ValidationError{Fields: errs}
	}
	return &compiledAIRequest{
		messages:        msgs,
		maxTokens:       maxTokens,
		temperature:     temp,
		timeout:         timeout,
		schema:          compiled,
		canonicalSchema: canonicalSchema,
		jsonObjectMode:  jsonObjectMode,
		searchQuery:     searchQuery,
	}, nil
}

func schemaExpectsJSONObject(doc map[string]any) bool {
	if rawType, ok := doc["type"]; ok {
		s, _ := rawType.(string)
		return s == "object"
	}
	_, hasProps := doc["properties"]
	return hasProps
}

func (m *Manager) aiCompletePerMin() int {
	m.mu.Lock()
	limit := m.aiCompleteLimit
	m.mu.Unlock()
	if limit <= 0 {
		return DefaultAICompletePerMin
	}
	return limit
}

func (m *Manager) aiSearchPerMin() int {
	m.mu.Lock()
	limit := m.aiSearchLimit
	m.mu.Unlock()
	if limit <= 0 {
		return DefaultAISearchCompletePerMin
	}
	return limit
}

func (m *Manager) aiSearchCacheTTL() time.Duration {
	m.aiSearchCacheMu.Lock()
	ttl := m.aiSearchTTL
	m.aiSearchCacheMu.Unlock()
	if ttl <= 0 {
		return DefaultAISearchCacheTTL
	}
	return ttl
}

// AISearchGranted reports whether pluginID is enabled, declares
// permissions.ai: "complete+search", and has neither "ai" nor "ai.search"
// revoked in its live grants.
func (m *Manager) AISearchGranted(ctx context.Context, pluginID string) bool {
	if m == nil || m.store == nil || pluginID == "" {
		return false
	}
	r, err := m.store.record(ctx, pluginID)
	if err != nil || !r.Enabled {
		return false
	}
	return m.aiSearchGrantedRecord(ctx, r)
}

func (m *Manager) aiSearchGrantedRecord(ctx context.Context, r Record) bool {
	e := r.Manifest.EffectiveEther()
	if e == nil || !AIPermissionAllowsSearch(e.Permissions.AI) {
		return false
	}
	g, err := m.store.grants(ctx, r.ID)
	if err != nil {
		return false
	}
	return !g.revoked("ai") && !g.revoked("ai.search")
}

type aiSearchCacheEntry struct {
	resp AICompleteResponse
	at   time.Time
}

type aiSearchFlight struct {
	done    chan struct{}
	cancel  context.CancelFunc
	waiters int
	resp    AICompleteResponse
	err     error
}

func cloneAICompleteResponse(resp AICompleteResponse) AICompleteResponse {
	if len(resp.JSON) == 0 {
		return resp
	}
	cp := make([]byte, len(resp.JSON))
	copy(cp, resp.JSON)
	resp.JSON = cp
	return resp
}

func aiSearchCacheKey(rawQuery string, compiled *compiledAIRequest) string {
	normQ := NormalizeAISearchQuery(rawQuery)
	trimmedRaw := strings.TrimSpace(rawQuery)
	h := sha256.New()
	h.Write([]byte("q:"))
	h.Write([]byte(normQ))
	h.Write([]byte{0})
	for _, msg := range compiled.messages {
		content := msg.Content
		if trimmedRaw != "" && trimmedRaw != normQ {
			content = strings.ReplaceAll(content, trimmedRaw, normQ)
		}
		h.Write([]byte(msg.Role))
		h.Write([]byte{0})
		h.Write([]byte(content))
		h.Write([]byte{0})
	}
	h.Write([]byte("s:"))
	h.Write(compiled.canonicalSchema)
	h.Write([]byte{0})
	h.Write([]byte(strconv.Itoa(compiled.maxTokens)))
	h.Write([]byte{0})
	if compiled.temperature != nil {
		h.Write([]byte(strconv.FormatFloat(*compiled.temperature, 'f', 6, 64)))
	}
	return hex.EncodeToString(h.Sum(nil))
}

func (m *Manager) lookupAISearchCacheLocked(pluginID, key string, now time.Time, ttl time.Duration) (AICompleteResponse, bool) {
	byPlugin := m.aiSearchCache[pluginID]
	if byPlugin == nil {
		return AICompleteResponse{}, false
	}
	entry, ok := byPlugin[key]
	if !ok {
		return AICompleteResponse{}, false
	}
	if now.Sub(entry.at) >= ttl {
		delete(byPlugin, key)
		return AICompleteResponse{}, false
	}
	return cloneAICompleteResponse(entry.resp), true
}

func (m *Manager) storeAISearchCache(pluginID, key string, resp AICompleteResponse) {
	now := m.now()
	ttl := m.aiSearchCacheTTL()
	m.aiSearchCacheMu.Lock()
	defer m.aiSearchCacheMu.Unlock()
	if m.aiSearchCache == nil {
		m.aiSearchCache = map[string]map[string]aiSearchCacheEntry{}
	}
	byPlugin := m.aiSearchCache[pluginID]
	if byPlugin == nil {
		byPlugin = map[string]aiSearchCacheEntry{}
		m.aiSearchCache[pluginID] = byPlugin
	}
	if len(byPlugin) >= MaxAISearchCacheEntries {
		for k, v := range byPlugin {
			if now.Sub(v.at) >= ttl {
				delete(byPlugin, k)
			}
		}
		if len(byPlugin) >= MaxAISearchCacheEntries {
			var oldestKey string
			var oldestAt time.Time
			for k, v := range byPlugin {
				if oldestKey == "" || v.at.Before(oldestAt) {
					oldestKey = k
					oldestAt = v.at
				}
			}
			if oldestKey != "" {
				delete(byPlugin, oldestKey)
			}
		}
	}
	byPlugin[key] = aiSearchCacheEntry{
		resp: cloneAICompleteResponse(resp),
		at:   now,
	}
}

func (m *Manager) clearAISearchCache(pluginID string) {
	m.aiSearchCacheMu.Lock()
	delete(m.aiSearchCache, pluginID)
	m.aiSearchCacheMu.Unlock()
}

func (m *Manager) executeAISearchCached(
	ctx context.Context,
	pluginID string,
	viewerID int64,
	rawQuery string,
	compiled *compiledAIRequest,
	backend func(context.Context, AICompleteBackendRequest) (string, error),
) (AICompleteResponse, error) {
	cacheKey := aiSearchCacheKey(rawQuery, compiled)
	flightKey := pluginID + "\x00" + cacheKey
	ttl := m.aiSearchCacheTTL()
	now := m.now()

	waitForFlight := func(f *aiSearchFlight) (AICompleteResponse, error) {
		timer := time.NewTimer(compiled.timeout)
		defer timer.Stop()
		select {
		case <-f.done:
			m.aiSearchCacheMu.Lock()
			f.waiters--
			resp, err := cloneAICompleteResponse(f.resp), f.err
			m.aiSearchCacheMu.Unlock()
			return resp, err
		case <-timer.C:
			m.aiSearchCacheMu.Lock()
			f.waiters--
			if f.waiters <= 0 && f.cancel != nil {
				f.cancel()
			}
			m.aiSearchCacheMu.Unlock()
			return AICompleteResponse{}, context.DeadlineExceeded
		case <-ctx.Done():
			m.aiSearchCacheMu.Lock()
			f.waiters--
			if f.waiters <= 0 && f.cancel != nil {
				f.cancel()
			}
			m.aiSearchCacheMu.Unlock()
			return AICompleteResponse{}, ctx.Err()
		}
	}

	m.aiSearchCacheMu.Lock()
	if resp, ok := m.lookupAISearchCacheLocked(pluginID, cacheKey, now, ttl); ok {
		m.aiSearchCacheMu.Unlock()
		return resp, nil
	}
	if existing := m.aiSearchInflight[flightKey]; existing != nil {
		existing.waiters++
		m.aiSearchCacheMu.Unlock()
		return waitForFlight(existing)
	}
	m.aiSearchCacheMu.Unlock()

	rateKey := fmt.Sprintf("%s\x00%d", pluginID, viewerID)
	limit := m.aiSearchPerMin()
	if !m.rateOK(m.aiSearchTimes, rateKey, limit, time.Minute) {
		return AICompleteResponse{}, fmt.Errorf("%w: ai.complete search is limited to %d calls per minute per viewer", ErrRateLimited, limit)
	}

	m.aiSearchCacheMu.Lock()
	if resp, ok := m.lookupAISearchCacheLocked(pluginID, cacheKey, m.now(), ttl); ok {
		m.aiSearchCacheMu.Unlock()
		m.rateRefund(m.aiSearchTimes, rateKey)
		return resp, nil
	}
	if existing := m.aiSearchInflight[flightKey]; existing != nil {
		existing.waiters++
		m.aiSearchCacheMu.Unlock()
		m.rateRefund(m.aiSearchTimes, rateKey)
		return waitForFlight(existing)
	}
	if m.aiSearchInflight == nil {
		m.aiSearchInflight = map[string]*aiSearchFlight{}
	}
	flightCtx, flightCancel := context.WithTimeout(context.Background(), compiled.timeout)
	f := &aiSearchFlight{
		done:    make(chan struct{}),
		cancel:  flightCancel,
		waiters: 1,
	}
	m.aiSearchInflight[flightKey] = f
	m.aiSearchCacheMu.Unlock()

	go func() {
		defer flightCancel()
		flightCompiled := *compiled
		resp, err := executeAIComplete(flightCtx, m.log, pluginID, backend, &flightCompiled)
		if err == nil {
			m.storeAISearchCache(pluginID, cacheKey, resp)
		} else if errors.Is(err, ErrNotConfigured) {
			m.rateRefund(m.aiSearchTimes, rateKey)
		}
		m.aiSearchCacheMu.Lock()
		f.resp = resp
		f.err = err
		delete(m.aiSearchInflight, flightKey)
		close(f.done)
		m.aiSearchCacheMu.Unlock()
	}()

	return waitForFlight(f)
}

// executeAIComplete runs a validated completion against backend, keeping
// provider credentials, endpoints, and raw upstream errors out of plugin-visible
// results, and validating structured output against the compiled JSON Schema.
func executeAIComplete(
	ctx context.Context,
	log *slog.Logger,
	pluginID string,
	backend func(context.Context, AICompleteBackendRequest) (string, error),
	compiled *compiledAIRequest,
) (AICompleteResponse, error) {
	if backend == nil {
		return AICompleteResponse{}, ErrNotConfigured
	}

	msgs := make([]AIMessage, 0, len(compiled.messages)+1)
	if compiled.schema != nil {
		msgs = append(msgs, AIMessage{
			Role: "system",
			Content: "Respond with valid JSON only, with no markdown fences or extra text. " +
				"The JSON value must conform to this JSON Schema:\n" + string(compiled.canonicalSchema),
		})
	}
	msgs = append(msgs, compiled.messages...)

	callCtx, cancel := context.WithTimeout(ctx, compiled.timeout)
	defer cancel()

	rawText, err := backend(callCtx, AICompleteBackendRequest{
		Messages:    msgs,
		JSONMode:    compiled.jsonObjectMode,
		MaxTokens:   compiled.maxTokens,
		Temperature: compiled.temperature,
	})
	if err != nil {
		switch {
		case errors.Is(err, ErrNotConfigured) || errors.Is(err, llm.ErrNotConfigured):
			return AICompleteResponse{}, ErrNotConfigured
		case errors.Is(err, context.DeadlineExceeded) || errors.Is(callCtx.Err(), context.DeadlineExceeded):
			return AICompleteResponse{}, context.DeadlineExceeded
		case errors.Is(err, context.Canceled) || errors.Is(ctx.Err(), context.Canceled):
			return AICompleteResponse{}, context.Canceled
		default:
			if log != nil {
				log.Warn("plugin ai.complete failed", "plugin", pluginID, "err", err)
			}
			// Never return raw provider errors, URLs, or upstream response bodies
			// to the plugin: they may contain owner endpoint info or key hints.
			return AICompleteResponse{}, fmt.Errorf("%w: language model request failed", ErrUnavailable)
		}
	}

	text := llm.StripReasoning(rawText)
	if len(text) > MaxAIResponseBytes {
		return AICompleteResponse{}, fmt.Errorf("%w: language model response exceeded %d bytes", ErrInvalidOutput, MaxAIResponseBytes)
	}

	if compiled.schema == nil {
		return AICompleteResponse{Text: text}, nil
	}

	candidate := strings.TrimSpace(text)
	if candidate == "" || !json.Valid([]byte(candidate)) {
		candidate = strings.TrimSpace(stripCodeFence(candidate))
	}
	if candidate == "" || !json.Valid([]byte(candidate)) {
		candidate = strings.TrimSpace(llm.ExtractJSON(text))
	}
	if candidate == "" || !json.Valid([]byte(candidate)) {
		return AICompleteResponse{}, fmt.Errorf("%w: language model did not return valid JSON", ErrInvalidOutput)
	}

	val, err := jsonschema.UnmarshalJSON(strings.NewReader(candidate))
	if err != nil {
		return AICompleteResponse{}, fmt.Errorf("%w: language model did not return valid JSON", ErrInvalidOutput)
	}
	if err := compiled.schema.Validate(val); err != nil {
		return AICompleteResponse{}, fmt.Errorf("%w: language model output did not match schema", ErrInvalidOutput)
	}
	canonical, err := json.Marshal(val)
	if err != nil || len(canonical) > MaxAIResponseBytes {
		return AICompleteResponse{}, fmt.Errorf("%w: language model response exceeded %d bytes", ErrInvalidOutput, MaxAIResponseBytes)
	}
	return AICompleteResponse{
		Text: string(canonical),
		JSON: json.RawMessage(canonical),
	}, nil
}

func stripCodeFence(s string) string {
	if !strings.HasPrefix(s, "```") {
		return s
	}
	rest := s[3:]
	if nl := strings.IndexByte(rest, '\n'); nl >= 0 {
		rest = rest[nl+1:]
	}
	if end := strings.LastIndex(rest, "```"); end >= 0 {
		return rest[:end]
	}
	return s
}

func (m *Manager) rateRefund(bucket map[string][]time.Time, key string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if times := bucket[key]; len(times) > 0 {
		bucket[key] = times[:len(times)-1]
	}
}

// AIComplete runs one bounded completion on the owner's configured language
// model. Requires permissions.ai: "complete" (or "complete+search" for opted-in
// interactive search routes; #702), checked live against grants. Every
// non-search viewer/client request path is refused. Interactive search calls are
// hard-bounded at MaxAISearchTimeout (20 s), cached per normalized query, and
// rate-limited per viewer separately from the plugin's background budget.
func (h *host) AIComplete(ctx context.Context, req AICompleteRequest) (AICompleteResponse, error) {
	r, g, err := h.record(ctx)
	if err != nil {
		return AICompleteResponse{}, err
	}
	level := normLevel(r.Manifest.Ether.Permissions.AI)
	if err := h.deny(r, g, "ai", level, AIPermissionAllowsComplete); err != nil {
		return AICompleteResponse{}, err
	}

	path := callPathFromContext(ctx)
	callQuery := callSearchQueryFromContext(ctx)
	isSearchPath := false
	if path != "" {
		if isClientRequestPath(path) {
			if !isActiveSearchRoute(r.Manifest, path, callQuery) {
				h.noteDenied("ai_client_path")
				return AICompleteResponse{}, fmt.Errorf("%w: ai.complete cannot run on viewer or client request path %s", ErrPermissionDenied, path)
			}
			if err := h.deny(r, g, "ai.search", level, AIPermissionAllowsSearch); err != nil {
				return AICompleteResponse{}, err
			}
			isSearchPath = true
		} else if !AICompleteAllowedPath(r.Manifest, path, isBackgroundCall(ctx) || wasm.IsBackgroundCall(ctx)) {
			h.noteDenied("ai_client_path")
			return AICompleteResponse{}, fmt.Errorf("%w: ai.complete cannot run on viewer or client request path %s", ErrPermissionDenied, path)
		}
	}

	compiled, err := ValidateAICompleteRequest(req)
	if err != nil {
		return AICompleteResponse{}, err
	}

	var searchQuery string
	if isSearchPath {
		searchQuery = compiled.searchQuery
		if searchQuery == "" {
			searchQuery = callQuery
		}
		if searchQuery == "" {
			if q, ok := stremioCatalogSearchQuery(path); ok {
				searchQuery = q
			} else if isFrontendAdapterRoute(path) {
				searchQuery = queryParamFromRequest(Request{Path: path}, "q", "query", "search")
			}
		}
		if searchQuery == "" {
			return AICompleteResponse{}, fmt.Errorf("%w: ai.complete on a search route requires a non-empty searchQuery", ErrPermissionDenied)
		}
		if len(searchQuery) > MaxAISearchQueryBytes {
			return AICompleteResponse{}, &ValidationError{Fields: []FieldError{{
				Field:   "searchQuery",
				Message: fmt.Sprintf("exceeds %d bytes", MaxAISearchQueryBytes),
			}}}
		}
		if req.TimeoutMS == 0 || compiled.timeout > MaxAISearchTimeout {
			compiled.timeout = MaxAISearchTimeout
		}
	} else if path == "" && compiled.searchQuery != "" && AIPermissionAllowsSearch(level) && !g.revoked("ai.search") {
		// Remote plugin calling /ether/plugin-host/ai/complete for a search
		// without a frontend-adapter viewer token (e.g. Stremio catalog search
		// or kinds search) still gets the hard search bound and per-query cache.
		isSearchPath = true
		searchQuery = compiled.searchQuery
		if req.TimeoutMS == 0 || compiled.timeout > MaxAISearchTimeout {
			compiled.timeout = MaxAISearchTimeout
		}
	}

	backend := h.m.deps.Backends.AIComplete
	if backend == nil {
		return AICompleteResponse{}, ErrNotConfigured
	}

	if isSearchPath {
		viewerID, _ := ViewerFromContext(ctx)
		return h.m.executeAISearchCached(ctx, h.plugin, viewerID, searchQuery, compiled, backend)
	}

	limit := h.m.aiCompletePerMin()
	if !h.m.rateOK(h.m.aiCompleteTimes, h.plugin, limit, time.Minute) {
		return AICompleteResponse{}, fmt.Errorf("%w: ai.complete is limited to %d calls per minute", ErrRateLimited, limit)
	}

	resp, err := executeAIComplete(ctx, h.m.log, h.plugin, backend, compiled)
	if errors.Is(err, ErrNotConfigured) {
		h.m.rateRefund(h.m.aiCompleteTimes, h.plugin)
	}
	return resp, err
}

// archiveIOBudget caps all metadata and compressed input reads cumulatively,
// including decoder read-ahead; seekReaderAt propagates the call deadline.
type archiveIOBudget struct {
	r    io.ReaderAt
	left int64
}

func (r *archiveIOBudget) ReadAt(p []byte, off int64) (int, error) {
	if int64(len(p)) > r.left {
		return 0, fmt.Errorf("plugins: archive input exceeds byte grant")
	}
	n, err := r.r.ReadAt(p, off)
	r.left -= int64(n)
	return n, err
}

type dataArchive struct {
	members []ArchiveMember
	open    func(int) (io.ReadCloser, error)
}

// archiveFormatEntryBytes bounds the format's own per-member index entry
// (offsets, sizes, checksums, flags) kept beside ArchiveMember.
const archiveFormatEntryBytes = 128

// archiveDirectoryCap scales with the grant like the other archive limits
// and matches the data parser's directory cap (host_data.go).
func archiveDirectoryCap(l RuntimeLimits) int64 {
	return min(int64(maxArchiveDirectory), int64(l.ArchiveMembers)*65536, archiveMemory(l)/8)
}

func archiveMemory(l RuntimeLimits) int64 {
	if l.MemoryBytes == 0 {
		return 32 << 20
	}
	return int64(min(l.MemoryBytes, 2<<30))
}

// UnsafeArchiveMemberError describes an archive member whose stored name is
// unsafe to use as a filesystem path. By-index archive reads no longer refuse
// members for their name; Name is an identifier only.
type UnsafeArchiveMemberError struct {
	Index  int
	Name   string
	Reason string
}

func (e *UnsafeArchiveMemberError) Error() string {
	return fmt.Sprintf("plugins: unsafe archive member %d %q: %s", e.Index, e.Name, e.Reason)
}

// dataArchiveDirectory retains metadata only, never a reader, budget or context.
type dataArchiveDirectory struct {
	members []ArchiveMember
	bind    func(context.Context, *archiveIOBudget, RuntimeLimits) func(int) (io.ReadCloser, error)
	bytes   int64
}

func openDataArchive(ctx context.Context, rc io.ReadSeeker, l RuntimeLimits) (*dataArchive, error) {
	ra := &archiveIOBudget{r: seekReaderAt{ctx, rc}, left: l.FetchBytes}
	d, err := parseDataArchive(ctx, rc, ra, l)
	if err != nil {
		return nil, err
	}
	return &dataArchive{members: d.members, open: d.bind(ctx, ra, l)}, nil
}

func parseDataArchive(ctx context.Context, rc io.ReadSeeker, ra *archiveIOBudget, l RuntimeLimits) (*dataArchiveDirectory, error) {
	size, err := rc.Seek(0, io.SeekEnd)
	if err != nil {
		return nil, err
	}
	if size < 8 || size > l.FetchBytes {
		return nil, fmt.Errorf("plugins: archive size outside grant")
	}
	memory := archiveMemory(l)
	if memory < 1<<20 {
		return nil, fmt.Errorf("plugins: archive memory grant too small")
	}
	var sig [8]byte
	if _, err = ra.ReadAt(sig[:], 0); err != nil {
		return nil, err
	}
	format := container.Detect(sig[:])
	a := &dataArchiveDirectory{members: make([]ArchiveMember, 0)}
	switch format {
	case container.Format7z:
		files, e := container.List7zData(ctx, ra, size, container.Data7zLimits{MemoryBytes: memory, ExpandedBytes: l.ArchiveExpandedBytes, Members: l.ArchiveMembers})
		if e != nil {
			return nil, e
		}
		for i, f := range files {
			a.members = append(a.members, ArchiveMember{Index: i, Name: f.Name, Size: uint64(f.Size)})
		}
		a.bind = func(ctx context.Context, ra *archiveIOBudget, l RuntimeLimits) func(int) (io.ReadCloser, error) {
			return func(i int) (io.ReadCloser, error) {
				r, e := container.Open7zData(ctx, ra, files[i])
				if e != nil {
					return nil, e
				}
				return io.NopCloser(r), nil
			}
		}
	case container.FormatRAR4, container.FormatRAR5:
		// Header-only walk: listing a solid RAR never inflates earlier members.
		metadata := &archiveIOBudget{r: ra, left: min(int64(maxArchiveDirectory), memory/4)}
		v, e := container.ReadRARVolume(metadata, size, &container.RAROptions{Context: ctx, MaxHeaderBytes: memory / 16, MaxFiles: min(l.ArchiveMembers+1, int(memory/4096))})
		if e != nil {
			return nil, e
		}
		if v.MultiVolume || v.MoreVolumes || len(v.Files) > l.ArchiveMembers || len(v.Files) >= int(memory/4096) {
			return nil, fmt.Errorf("plugins: split RAR or directory exceeds grant")
		}
		var solidPacked, solidExpanded int64
		for i, f := range v.Files {
			if f.SplitBefore || f.SplitAfter || f.Encrypted || f.NonRegular || f.UnpackedSize < 0 {
				return nil, fmt.Errorf("plugins: split, encrypted or unsupported RAR member")
			}
			if !f.Solid {
				solidPacked, solidExpanded = 0, 0
			}
			solidPacked += f.PackedSize
			if f.UnpackedSize > l.ArchiveExpandedBytes-solidExpanded {
				return nil, fmt.Errorf("plugins: RAR solid block exceeds byte grant")
			}
			solidExpanded += f.UnpackedSize
			if solidExpanded > 0 && (solidPacked == 0 || (solidPacked <= 1<<53 && solidExpanded > solidPacked*maxArchiveRatio)) {
				return nil, fmt.Errorf("plugins: RAR member exceeds compression-ratio limit")
			}
			a.members = append(a.members, ArchiveMember{Index: i, Name: f.StoredName, Size: uint64(f.UnpackedSize)})
		}
		a.bind = func(ctx context.Context, ra *archiveIOBudget, l RuntimeLimits) func(int) (io.ReadCloser, error) {
			return func(i int) (io.ReadCloser, error) {
				if v.Files[i].Dir {
					return nil, fmt.Errorf("plugins: cannot open an archive directory")
				}
				r, e := rardecode.NewReader(io.NewSectionReader(ra, 0, size), rardecode.MaxDictionarySize(memory/8), rardecode.BufferSize(4096))
				if e != nil {
					return nil, e
				}
				// Explicitly consume dependencies under the expanded-byte grant. This also
				// keeps implicit solid skipping inside the decoder from doing uncounted work.
				left := l.ArchiveExpandedBytes
				start := i
				for start > 0 && v.Files[start].Solid {
					start--
				}
				for j := 0; j <= i; j++ {
					h, e := r.Next()
					if e != nil {
						return nil, e
					}
					normName := strings.ReplaceAll(h.Name, `\`, "/")
					if (normName != v.Files[j].Name && normName != strings.ReplaceAll(v.Files[j].StoredName, `\`, "/")) || h.UnPackedSize != v.Files[j].UnpackedSize || h.Encrypted || h.HeaderEncrypted {
						return nil, fmt.Errorf("plugins: inconsistent RAR member")
					}
					if j == i {
						return io.NopCloser(io.LimitReader(r, h.UnPackedSize)), nil
					}
					if j >= start || v.Solid {
						if h.UnPackedSize > left {
							return nil, fmt.Errorf("plugins: RAR decode exceeds byte grant")
						}
						if _, e = io.CopyN(io.Discard, &boundedDataReader{ctx: ctx, r: r, left: left}, h.UnPackedSize); e != nil {
							return nil, e
						}
						left -= h.UnPackedSize
					}
				}
				return nil, io.EOF
			}
		}
	default:
		z, e := parseDataZIP(rc, ra, l)
		if e != nil {
			return nil, e
		}
		files := make([]dataZIPMember, len(z.File))
		for i, f := range z.File {
			offset, e := f.DataOffset()
			if e != nil {
				return nil, e
			}
			if offset < 0 || offset > size || f.CompressedSize64 > uint64(size-offset) {
				return nil, zip.ErrFormat
			}
			// Descriptor metadata is immutable too; validate it once while
			// building the index, rather than retaining a zip.File's reader.
			if f.Flags&8 != 0 {
				at := offset + int64(f.CompressedSize64)
				var descriptor [12]byte
				if _, e := ra.ReadAt(descriptor[:], at); e != nil {
					return nil, e
				}
				crc := binary.LittleEndian.Uint32(descriptor[:])
				if crc == 0x08074b50 {
					var rest [4]byte
					if _, e := ra.ReadAt(rest[:], at+12); e != nil {
						return nil, e
					}
					crc = binary.LittleEndian.Uint32(descriptor[4:])
				}
				if crc != f.CRC32 {
					return nil, zip.ErrChecksum
				}
			}
			files[i] = dataZIPMember{offset: offset, packed: int64(f.CompressedSize64), size: f.UncompressedSize64, crc: f.CRC32, method: f.Method, dir: f.FileInfo().IsDir(), verifyCRC: f.Flags&8 != 0 || f.CRC32 != 0}
			a.members = append(a.members, ArchiveMember{Index: i, Name: f.Name, Size: f.UncompressedSize64})
		}
		a.bind = func(_ context.Context, ra *archiveIOBudget, _ RuntimeLimits) func(int) (io.ReadCloser, error) {
			return func(i int) (io.ReadCloser, error) { return files[i].open(ra) }
		}
	}
	var total uint64
	var names int64
	for i := range a.members {
		m := &a.members[i]
		m.UnsafeReason = archiveNameReason(m.Name)
		m.Unsafe = m.UnsafeReason != ""
		names += int64(len(m.Name) + len(m.UnsafeReason))
		if names > memory/4 || m.Size > uint64(l.ArchiveMemberBytes) || m.Size > uint64(l.ArchiveExpandedBytes)-total {
			return nil, fmt.Errorf("plugins: archive directory or member size exceeds grant")
		}
		total += m.Size
	}
	// Measure what the directory retains: each member's entry (including the
	// slice's spare capacity), a bounded per-member format table, and the name
	// bytes. ZIP comments/extras and raw directory buffers are not retained.
	a.bytes = 1024 + int64(cap(a.members))*(int64(unsafe.Sizeof(ArchiveMember{}))+archiveFormatEntryBytes) + names
	if a.bytes > archiveDirectoryCap(l) {
		return nil, fmt.Errorf("plugins: archive directory exceeds limit")
	}
	return a, nil
}

var (
	emptyFlateSource = bytes.NewReader(nil)
	flateReaderPool  sync.Pool
)

type pooledFlateReader struct {
	zr   io.ReadCloser
	br   *bufio.Reader
	done bool
}

func newPooledFlateReader(src io.Reader) io.ReadCloser {
	if p, ok := flateReaderPool.Get().(*pooledFlateReader); ok {
		p.br.Reset(src)
		if resetter, ok := p.zr.(flate.Resetter); ok && resetter.Reset(p.br, nil) == nil {
			p.done = false
			return p
		}
	}
	br := bufio.NewReaderSize(src, 4096)
	return &pooledFlateReader{zr: flate.NewReader(br), br: br}
}

func (p *pooledFlateReader) Read(b []byte) (int, error) {
	return p.zr.Read(b)
}

func (p *pooledFlateReader) Close() error {
	if p.done {
		return nil
	}
	p.done = true
	err := p.zr.Close()
	p.br.Reset(emptyFlateSource)
	if resetter, ok := p.zr.(flate.Resetter); ok {
		_ = resetter.Reset(emptyFlateSource, nil)
	}
	flateReaderPool.Put(p)
	return err
}

// ZIP member offsets come from the validated immutable central directory. Each
// open creates a decoder and checksum state over this call's reader only.
type dataZIPMember struct {
	offset, packed int64
	size           uint64
	crc            uint32
	method         uint16
	dir            bool
	verifyCRC      bool
}

func (f dataZIPMember) open(ra io.ReaderAt) (io.ReadCloser, error) {
	if f.dir {
		return nil, fmt.Errorf("plugins: cannot open an archive directory")
	}
	section := io.NewSectionReader(ra, f.offset, f.packed)
	var r io.ReadCloser
	if f.method == zip.Deflate {
		r = newPooledFlateReader(section)
	} else {
		r = io.NopCloser(section)
	}
	return &dataZIPChecksum{ReadCloser: r, hash: crc32.NewIEEE(), size: f.size, crc: f.crc, verifyCRC: f.verifyCRC}, nil
}

func (r *dataZIPChecksum) Read(p []byte) (int, error) {
	n, err := r.ReadCloser.Read(p)
	r.read += uint64(n)
	r.hash.Write(p[:n])
	if r.read > r.size {
		return n, zip.ErrFormat
	}
	if err == io.EOF {
		if r.read != r.size {
			return n, io.ErrUnexpectedEOF
		}
		if r.verifyCRC && r.hash.Sum32() != r.crc {
			return n, zip.ErrChecksum
		}
	}
	return n, err
}

// ActivePosterBadgeSet describes one enabled, non-shadow plugin's declared
// poster badge set for overlay rendering and console settings (#594).
type ActivePosterBadgeSet struct {
	PluginID    string `json:"pluginId"`
	PluginName  string `json:"pluginName"`
	Key         string `json:"key"`
	LayerKey    string `json:"layerKey"`
	Label       string `json:"label"`
	Description string `json:"description,omitempty"`
}

// NormalizeBadgeLabel uppercases ASCII lowercase characters and validates that
// raw is 1..16 characters from [A-Z0-9 +&'./-] and not blank (#594).
func NormalizeBadgeLabel(raw string) (string, error) {
	if len(raw) < 1 || len(raw) > MaxBadgeLabelLen {
		return "", fmt.Errorf("must be 1 to %d characters", MaxBadgeLabelLen)
	}
	buf := make([]byte, len(raw))
	nonSpace := false
	for i := 0; i < len(raw); i++ {
		c := raw[i]
		if c >= 'a' && c <= 'z' {
			c = c - 'a' + 'A'
		}
		switch {
		case c >= 'A' && c <= 'Z',
			c >= '0' && c <= '9',
			c == '+', c == '&', c == '\'', c == '.', c == '/', c == '-':
			nonSpace = true
		case c == ' ':
		default:
			return "", fmt.Errorf("must contain only [A-Z0-9 +&'./-]")
		}
		buf[i] = c
	}
	if !nonSpace {
		return "", fmt.Errorf("must not be blank")
	}
	return string(buf), nil
}

// ExternalBadgeKeys returns the deterministic external-id fallback keys
// ("tmdb:<type>:<id>", "imdb:<type>:<id>") for a normalized BadgeTitleRef.
func ExternalBadgeKeys(ref BadgeTitleRef) (tmdbKey, imdbKey string) {
	if ref.TMDB > 0 && (ref.Type == "movie" || ref.Type == "show") {
		tmdbKey = fmt.Sprintf("tmdb:%s:%d", ref.Type, ref.TMDB)
	}
	if ref.IMDB != "" && (ref.Type == "movie" || ref.Type == "show") {
		imdbKey = fmt.Sprintf("imdb:%s:%s", ref.Type, strings.ToLower(strings.TrimSpace(ref.IMDB)))
	}
	return tmdbKey, imdbKey
}

func (m *Manager) badgeTitleQuota() int64 {
	m.mu.Lock()
	q := m.badgeQuotaTitles
	m.mu.Unlock()
	if q > 0 {
		return q
	}
	return PosterBadgeQuotaTitles
}

// SetBadgeQuotaForTest overrides the per-plugin badged-title quota (<=0 restores
// PosterBadgeQuotaTitles). Intended for unit tests.
func (m *Manager) SetBadgeQuotaForTest(quota int64) {
	m.mu.Lock()
	m.badgeQuotaTitles = quota
	m.mu.Unlock()
}

// SetResolveBadgeTitles wires the batched local catalogue lookup used by
// BadgesSet to map (type, tmdb, imdb) refs to canonical rating keys.
func (m *Manager) SetResolveBadgeTitles(fn func(ctx context.Context, refs []BadgeTitleRef) ([]string, error)) {
	m.mu.Lock()
	m.deps.Backends.ResolveBadgeTitles = fn
	m.mu.Unlock()
}

func (m *Manager) resolveBadgeTitlesFn() func(ctx context.Context, refs []BadgeTitleRef) ([]string, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	return m.deps.Backends.ResolveBadgeTitles
}

func (m *Manager) buildPosterBadgeSets(ctx context.Context, r Record) []ActivePosterBadgeSet {
	if !r.Enabled || r.Shadow {
		return nil
	}
	man := r.Manifest
	man.Ether = man.EffectiveEther()
	if man.Ether == nil || !man.HasCapability(CapPosterBadges) {
		return nil
	}
	if g, err := m.store.grants(ctx, r.ID); err == nil && g.revoked(string(CapPosterBadges)) {
		return nil
	}
	decls := man.Ether.Contributes.PosterBadges
	if len(decls) == 0 {
		return nil
	}
	out := make([]ActivePosterBadgeSet, 0, len(decls))
	for _, pb := range decls {
		lbl := pb.Label
		if strings.HasPrefix(lbl, "$t:") {
			if resolved, ok := m.ResolveText(ctx, r.ID, strings.TrimPrefix(lbl, "$t:"), "en"); ok && resolved != "" {
				lbl = resolved
			} else {
				lbl = pb.Key
			}
		}
		desc := pb.Description
		if strings.HasPrefix(desc, "$t:") {
			if resolved, ok := m.ResolveText(ctx, r.ID, strings.TrimPrefix(desc, "$t:"), "en"); ok {
				desc = resolved
			} else {
				desc = ""
			}
		}
		out = append(out, ActivePosterBadgeSet{
			PluginID:    r.ID,
			PluginName:  r.Name,
			Key:         pb.Key,
			LayerKey:    "plugin:" + r.ID + ":" + pb.Key,
			Label:       lbl,
			Description: desc,
		})
	}
	return out
}

// syncPosterBadgeSets updates the in-memory active badge-set index when a
// plugin is installed, updated, enabled, disabled, shadowed or removed.
//
// Disabled and shadow plugins retain their stored rows in plugin_poster_badges
// and are filtered out at read time via ActivePosterBadgeSets, so re-enabling a
// plugin restores its badges immediately without drawing them while disabled.
func (m *Manager) syncPosterBadgeSets(ctx context.Context, r Record) {
	sets := m.buildPosterBadgeSets(ctx, r)
	m.mu.Lock()
	if m.posterBadgeSets == nil {
		m.posterBadgeSets = map[string][]ActivePosterBadgeSet{}
	}
	if len(sets) == 0 {
		delete(m.posterBadgeSets, r.ID)
	} else {
		m.posterBadgeSets[r.ID] = sets
	}
	m.mu.Unlock()
}

// ActivePosterBadgeSets returns declared poster badge sets for all currently
// enabled, non-shadow plugins in deterministic order without hitting SQLite
// once loaded.
func (m *Manager) ActivePosterBadgeSets(ctx context.Context) []ActivePosterBadgeSet {
	if m == nil {
		return nil
	}
	m.mu.Lock()
	loaded := m.posterBadgesLoaded
	m.mu.Unlock()
	if !loaded {
		if recs, err := m.store.list(ctx); err == nil {
			built := make(map[string][]ActivePosterBadgeSet, len(recs))
			for _, r := range recs {
				if sets := m.buildPosterBadgeSets(ctx, r); len(sets) > 0 {
					built[r.ID] = sets
				}
			}
			m.mu.Lock()
			m.posterBadgeSets = built
			m.posterBadgesLoaded = true
			m.mu.Unlock()
		}
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	if len(m.posterBadgeSets) == 0 {
		return nil
	}
	ids := make([]string, 0, len(m.posterBadgeSets))
	for id := range m.posterBadgeSets {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	var out []ActivePosterBadgeSet
	for _, id := range ids {
		out = append(out, m.posterBadgeSets[id]...)
	}
	return out
}

func (h *host) badgeCheck(ctx context.Context, setKey string, needSet bool) (Record, PosterBadgeSetMeta, error) {
	r, g, err := h.record(ctx)
	if err != nil {
		return Record{}, PosterBadgeSetMeta{}, err
	}
	man := r.Manifest
	man.Ether = man.EffectiveEther()
	if g.revoked(string(CapPosterBadges)) || man.Ether == nil || !man.HasCapability(CapPosterBadges) {
		h.noteDenied(string(CapPosterBadges))
		return Record{}, PosterBadgeSetMeta{}, fmt.Errorf("%w: %s", ErrPermissionDenied, CapPosterBadges)
	}
	if !needSet {
		return r, PosterBadgeSetMeta{}, nil
	}
	if !posterBadgeKeyRe.MatchString(setKey) {
		return Record{}, PosterBadgeSetMeta{}, &ValidationError{Fields: []FieldError{{
			Field:   "setKey",
			Message: "must match ^[a-z][a-z0-9_]{0,31}$",
		}}}
	}
	for _, pb := range man.Ether.Contributes.PosterBadges {
		if pb.Key == setKey {
			return r, pb, nil
		}
	}
	return Record{}, PosterBadgeSetMeta{}, &ValidationError{Fields: []FieldError{{
		Field:   "setKey",
		Message: fmt.Sprintf("badge set %q is not declared in ether.contributes.posterBadges", setKey),
	}}}
}

type normalizedBadgeWrite struct {
	ref      BadgeTitleRef
	labels   []string
	titleKey string
	aliases  []string
}

// BadgesSet pushes or deletes (empty Labels) poster badges for up to 500
// canonical titles in one declared badge set (#594).
//
// Title resolution runs once per batch against the local catalogue
// (TMDB first, then IMDb). Known titles store title_key = ratingKey.String();
// titles not yet in catalog_titles store title_key = "tmdb:<type>:<id>" (or
// "imdb:<type>:<id>"), and overlays queries both canonical and external keys
// in its per-page batch so pre-pushed badges light up as soon as a title
// enters the catalogue without any ingest hook.
func (h *host) BadgesSet(ctx context.Context, setKey string, entries []BadgeEntry) error {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return err
	}
	r, _, err := h.badgeCheck(ctx, setKey, true)
	if err != nil {
		return err
	}
	if len(entries) > MaxBadgeEntriesPerCall {
		return &ValidationError{Fields: []FieldError{{
			Field:   "entries",
			Message: fmt.Sprintf("must contain at most %d entries per call", MaxBadgeEntriesPerCall),
		}}}
	}
	if len(entries) == 0 {
		return nil
	}

	writes := make([]normalizedBadgeWrite, len(entries))
	refs := make([]BadgeTitleRef, len(entries))
	hasUpsert := false
	for i, e := range entries {
		base := fmt.Sprintf("entries[%d]", i)
		typ := strings.TrimSpace(e.Title.Type)
		if typ != "movie" && typ != "show" {
			return &ValidationError{Fields: []FieldError{{
				Field:   base + ".title.type",
				Message: "must be movie or show",
			}}}
		}
		if e.Title.TMDB < 0 {
			return &ValidationError{Fields: []FieldError{{
				Field:   base + ".title.tmdb",
				Message: "must be a positive TMDB id",
			}}}
		}
		imdb := strings.ToLower(strings.TrimSpace(e.Title.IMDB))
		if imdb != "" && !imdbBadgeRe.MatchString(imdb) {
			return &ValidationError{Fields: []FieldError{{
				Field:   base + ".title.imdb",
				Message: "must match tt<digits>",
			}}}
		}
		if e.Title.TMDB == 0 && imdb == "" {
			return &ValidationError{Fields: []FieldError{{
				Field:   base + ".title",
				Message: "tmdb or imdb is required",
			}}}
		}
		if len(e.Labels) > MaxBadgeLabelsPerTitle {
			return &ValidationError{Fields: []FieldError{{
				Field:   base + ".labels",
				Message: fmt.Sprintf("at most %d labels per title per set", MaxBadgeLabelsPerTitle),
			}}}
		}
		var cleanLabels []string
		if len(e.Labels) > 0 {
			seenLabel := make(map[string]bool, len(e.Labels))
			cleanLabels = make([]string, 0, len(e.Labels))
			for j, raw := range e.Labels {
				norm, lerr := NormalizeBadgeLabel(raw)
				if lerr != nil {
					return &ValidationError{Fields: []FieldError{{
						Field:   fmt.Sprintf("%s.labels[%d]", base, j),
						Message: lerr.Error(),
					}}}
				}
				if !seenLabel[norm] {
					seenLabel[norm] = true
					cleanLabels = append(cleanLabels, norm)
				}
			}
			hasUpsert = true
		}
		ref := BadgeTitleRef{Type: typ, TMDB: e.Title.TMDB, IMDB: imdb}
		refs[i] = ref
		writes[i] = normalizedBadgeWrite{ref: ref, labels: cleanLabels}
	}

	if r.Shadow {
		return h.journal(ctx, r, "badges.set", setKey, map[string]any{
			"op":      "badges.set",
			"setKey":  setKey,
			"entries": len(entries),
		})
	}

	var resolved []string
	if resolveFn := h.m.resolveBadgeTitlesFn(); resolveFn != nil {
		resolved, err = resolveFn(ctx, refs)
		if err != nil {
			return err
		}
	}
	for i := range writes {
		tmdbKey, imdbKey := ExternalBadgeKeys(writes[i].ref)
		var primary string
		if i < len(resolved) && resolved[i] != "" {
			primary = resolved[i]
		} else if tmdbKey != "" {
			primary = tmdbKey
		} else {
			primary = imdbKey
		}
		writes[i].titleKey = primary
		for _, candidate := range []string{primary, tmdbKey, imdbKey} {
			if candidate == "" {
				continue
			}
			dup := false
			for _, existing := range writes[i].aliases {
				if existing == candidate {
					dup = true
					break
				}
			}
			if !dup {
				writes[i].aliases = append(writes[i].aliases, candidate)
			}
		}
	}

	quota := h.m.badgeTitleQuota()
	err = h.m.store.badgesSet(ctx, h.plugin, setKey, writes, hasUpsert, quota)
	if errors.Is(err, ErrQuotaExceeded) {
		used, _ := h.m.store.badgesTitleCount(ctx, h.plugin)
		h.m.emitBusEvent(events.EventPluginQuotaExceeded, h.plugin, events.PluginQuotaExceededPayload{
			PluginID:  h.plugin,
			Name:      r.Name,
			QuotaKind: "badges",
			Used:      used,
			Limit:     quota,
		}, false)
	}
	return err
}

// BadgesClear removes every badge in one declared set for the calling plugin.
func (h *host) BadgesClear(ctx context.Context, setKey string) error {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return err
	}
	r, _, err := h.badgeCheck(ctx, setKey, true)
	if err != nil {
		return err
	}
	if r.Shadow {
		return h.journal(ctx, r, "badges.clear", setKey, map[string]any{
			"op":     "badges.clear",
			"setKey": setKey,
		})
	}
	return h.m.store.badgesClear(ctx, h.plugin, setKey)
}

// BadgesUsage returns the calling plugin's distinct badged title count and quota.
func (h *host) BadgesUsage(ctx context.Context) (BadgeUsage, error) {
	if _, _, err := h.badgeCheck(ctx, "", false); err != nil {
		return BadgeUsage{}, err
	}
	titles, err := h.m.store.badgesTitleCount(ctx, h.plugin)
	if err != nil {
		return BadgeUsage{}, err
	}
	return BadgeUsage{
		Titles:      titles,
		QuotaTitles: h.m.badgeTitleQuota(),
	}, nil
}

func (s *storage) badgesSet(ctx context.Context, pluginID, setKey string, writes []normalizedBadgeWrite, hasUpsert bool, quota int64) error {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback() //nolint:errcheck

	// Serialize concurrent badge writes for this plugin across connections so
	// the per-plugin distinct-title quota cannot be raced past.
	if _, err := tx.ExecContext(ctx, `UPDATE plugins_grants SET grants=grants WHERE plugin=?`, pluginID); err != nil {
		return err
	}

	var exists int
	if err := tx.QueryRowContext(ctx, `SELECT 1 FROM plugins_installed WHERE id=?`, pluginID).Scan(&exists); errors.Is(err, sql.ErrNoRows) {
		return ErrPermissionDenied
	} else if err != nil {
		return err
	}

	now := s.now().Unix()
	for _, w := range writes {
		if len(w.labels) == 0 {
			for _, k := range w.aliases {
				if _, err := tx.ExecContext(ctx, `DELETE FROM plugin_poster_badges WHERE plugin_id=? AND set_key=? AND title_key=?`, pluginID, setKey, k); err != nil {
					return err
				}
			}
			continue
		}
		for _, k := range w.aliases {
			if k != w.titleKey {
				if _, err := tx.ExecContext(ctx, `DELETE FROM plugin_poster_badges WHERE plugin_id=? AND set_key=? AND title_key=?`, pluginID, setKey, k); err != nil {
					return err
				}
			}
		}
		raw, err := json.Marshal(w.labels)
		if err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `INSERT INTO plugin_poster_badges(plugin_id,set_key,title_key,labels_json,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(plugin_id,set_key,title_key) DO UPDATE SET labels_json=excluded.labels_json,updated_at=excluded.updated_at`,
			pluginID, setKey, w.titleKey, string(raw), now); err != nil {
			return err
		}
	}

	if hasUpsert {
		var titles int64
		if err := tx.QueryRowContext(ctx, `SELECT COUNT(DISTINCT title_key) FROM plugin_poster_badges WHERE plugin_id=?`, pluginID).Scan(&titles); err != nil {
			return err
		}
		if titles > quota {
			return fmt.Errorf("%w: poster badges are limited to %d titles per plugin", ErrQuotaExceeded, quota)
		}
	}

	return tx.Commit()
}

func (s *storage) badgesClear(ctx context.Context, pluginID, setKey string) error {
	_, err := s.db.ExecContext(ctx, `DELETE FROM plugin_poster_badges WHERE plugin_id=? AND set_key=?`, pluginID, setKey)
	return err
}

func (s *storage) badgesTitleCount(ctx context.Context, pluginID string) (int64, error) {
	var n int64
	err := s.db.QueryRowContext(ctx, `SELECT COUNT(DISTINCT title_key) FROM plugin_poster_badges WHERE plugin_id=?`, pluginID).Scan(&n)
	return n, err
}

// ValidateBadgeClearCall checks poster_badges capability and setKey against a
// manifest, for use by conformance and Studio sandboxes (#594).
func ValidateBadgeClearCall(man Manifest, setKey string) error {
	man.Ether = man.EffectiveEther()
	if man.Ether == nil || !man.HasCapability(CapPosterBadges) {
		return fmt.Errorf("%w: %s", ErrPermissionDenied, CapPosterBadges)
	}
	if !posterBadgeKeyRe.MatchString(setKey) {
		return &ValidationError{Fields: []FieldError{{Field: "setKey", Message: "must match ^[a-z][a-z0-9_]{0,31}$"}}}
	}
	for _, pb := range man.Ether.Contributes.PosterBadges {
		if pb.Key == setKey {
			return nil
		}
	}
	return &ValidationError{Fields: []FieldError{{
		Field:   "setKey",
		Message: fmt.Sprintf("badge set %q is not declared in ether.contributes.posterBadges", setKey),
	}}}
}

// ValidateBadgeSetCall validates setKey and entries against manifest and label
// bounds, returning normalized entries for sandbox hosts (#594).
func ValidateBadgeSetCall(man Manifest, setKey string, entries []BadgeEntry) ([]BadgeEntry, error) {
	if err := ValidateBadgeClearCall(man, setKey); err != nil {
		return nil, err
	}
	if len(entries) > MaxBadgeEntriesPerCall {
		return nil, &ValidationError{Fields: []FieldError{{
			Field:   "entries",
			Message: fmt.Sprintf("must contain at most %d entries per call", MaxBadgeEntriesPerCall),
		}}}
	}
	out := make([]BadgeEntry, len(entries))
	for i, e := range entries {
		base := fmt.Sprintf("entries[%d]", i)
		typ := strings.TrimSpace(e.Title.Type)
		if typ != "movie" && typ != "show" {
			return nil, &ValidationError{Fields: []FieldError{{Field: base + ".title.type", Message: "must be movie or show"}}}
		}
		if e.Title.TMDB < 0 {
			return nil, &ValidationError{Fields: []FieldError{{Field: base + ".title.tmdb", Message: "must be a positive TMDB id"}}}
		}
		imdb := strings.ToLower(strings.TrimSpace(e.Title.IMDB))
		if imdb != "" && !imdbBadgeRe.MatchString(imdb) {
			return nil, &ValidationError{Fields: []FieldError{{Field: base + ".title.imdb", Message: "must match tt<digits>"}}}
		}
		if e.Title.TMDB == 0 && imdb == "" {
			return nil, &ValidationError{Fields: []FieldError{{Field: base + ".title", Message: "tmdb or imdb is required"}}}
		}
		if len(e.Labels) > MaxBadgeLabelsPerTitle {
			return nil, &ValidationError{Fields: []FieldError{{Field: base + ".labels", Message: fmt.Sprintf("at most %d labels per title per set", MaxBadgeLabelsPerTitle)}}}
		}
		var clean []string
		if len(e.Labels) > 0 {
			seen := make(map[string]bool, len(e.Labels))
			for j, raw := range e.Labels {
				norm, lerr := NormalizeBadgeLabel(raw)
				if lerr != nil {
					return nil, &ValidationError{Fields: []FieldError{{Field: fmt.Sprintf("%s.labels[%d]", base, j), Message: lerr.Error()}}}
				}
				if !seen[norm] {
					seen[norm] = true
					clean = append(clean, norm)
				}
			}
		}
		out[i] = BadgeEntry{Title: BadgeTitleRef{Type: typ, TMDB: e.Title.TMDB, IMDB: imdb}, Labels: clean}
	}
	return out, nil
}

// Data-service limits are host enforced. Per-call read ceilings scale with the
// plugin's memory grant; all operations use the plugin-owned cache namespace.
const (
	MaxDataFetchBytes       = 8 << 30
	MinDataReadBytes        = wasm.MinDataReadBytes
	MaxDataReadBytes        = wasm.MaxDataReadBytes
	MaxArchiveReadItems     = 4096
	maxArchiveMembers       = 65535
	maxArchiveDirectory     = 64 << 20
	maxArchiveMemberBytes   = 8 << 30
	maxArchiveExpandedBytes = 32 << 30
	maxArchiveRatio         = 1000
)

// DataReadBytes returns the per-call byte ceiling for cache.read, archive.open,
// and archive.read derived from the plugin's memory grant:
// clamp(memoryBytes/4, 8 MiB, 512 MiB).
func DataReadBytes(memoryBytes uint64) int64 {
	return wasm.DataReadBytes(memoryBytes)
}

func dataReadLimit(limits RuntimeLimits) int64 {
	if limits.ReadBytes > 0 {
		return min(max(limits.ReadBytes, MinDataReadBytes), MaxDataReadBytes)
	}
	return DataReadBytes(limits.MemoryBytes)
}

type DataRange struct {
	Offset int64 `json:"offset"`
	Length int64 `json:"length"`
}

// ArchiveReadItem selects one byte range inside one archive member for archive.read.
type ArchiveReadItem struct {
	Member int   `json:"member"`
	Offset int64 `json:"offset"`
	Length int64 `json:"length"`
}

// ArchiveReadResult is one item returned by archive.read in request order.
type ArchiveReadResult struct {
	Index      int    `json:"index"`
	Member     int    `json:"member"`
	Size       int    `json:"size"`
	BodyBase64 string `json:"bodyBase64"`
}

type FetchCacheRequest struct {
	FetchRequest
	LibraryKey string `json:"libraryKey"`
	Name       string `json:"name"`
	// Resume continues a partial cached download with Range: bytes=<cached>-
	// when the server supports ranges and ETag / Last-Modified validators match.
	Resume bool `json:"resume,omitempty"`
	// Connections requests 1 to 6 parallel ranges in jobs and background calls.
	// Defaults to 1 and shares the host's per-origin limit of 6.
	Connections int `json:"connections,omitempty"`
}

// ArchiveExtractOptions optionally targets one of the plugin's declared media
// kind libraries or overrides the stored entry name when extracting a member.
// When omitted, archive.extract writes into the source archive's own library
// cache namespace (or the plugin's first declared media kind) using the
// member's base name.
type ArchiveExtractOptions struct {
	LibraryKey string `json:"libraryKey,omitempty"`
