	Height int    `json:"height,omitempty"`
	Format string `json:"format,omitempty"`
}

// RasterizeResult is returned by cache.rasterize after rasterising a cached
// SVG blob into a new cached bitmap blob in the plugin's own library cache.
type RasterizeResult struct {
	Blob        string `json:"blob"`
	ContentType string `json:"contentType"`
	Width       int    `json:"width"`
	Height      int    `json:"height"`
	Size        int64  `json:"size"`
}

// boundedDataReader propagates cancellation and rejects overflow instead of
// turning a truncated file into a successful content-addressed cache entry.
type boundedDataReader struct {
	ctx  context.Context
	r    io.Reader
	left int64
	size int64
}

func (r *boundedDataReader) Read(p []byte) (int, error) {
	if err := r.ctx.Err(); err != nil {
		return 0, err
	}
	if r.left < 0 {
		return 0, errDataExceedsSizeLimit
	}
	if int64(len(p))-1 > r.left {
		p = p[:r.left+1]
	}
	n, err := r.r.Read(p)
	r.left -= int64(n)
	r.size += int64(n)
	if r.left < 0 {
		return n, errDataExceedsSizeLimit
	}
	return n, err
}

// archiveExtractReader bounds extracted bytes by both the archive member grant
// and the target library cache quota, charges per-MiB governance units, and
// refuses truncated streams before CachePut commits a partial blob.
type archiveExtractReader struct {
	ctx         context.Context
	r           io.Reader
	memberLimit int64
	cacheLimit  int64
	expected    int64
	size        int64
	chargedMiB  int64
}

func (r *archiveExtractReader) Read(p []byte) (int, error) {
	if err := r.ctx.Err(); err != nil {
		return 0, err
	}
	maxAllowed := min(r.memberLimit, r.cacheLimit)
	if r.size > maxAllowed {
		if r.size > r.cacheLimit {
			return 0, fmt.Errorf("%w: archive member exceeds library cache quota", ErrQuotaExceeded)
		}
		return 0, fmt.Errorf("plugins: archive member exceeds size grant")
	}
	if rem := maxAllowed - r.size; rem < int64(len(p))-1 {
		p = p[:rem+1]
	}
	n, err := r.r.Read(p)
	if n > 0 {
		r.size += int64(n)
		if r.size > r.memberLimit {
			return n, fmt.Errorf("plugins: archive member exceeds size grant")
		}
		if r.size > r.cacheLimit {
			return n, fmt.Errorf("%w: archive member exceeds library cache quota", ErrQuotaExceeded)
		}
		if wantMiB := (r.size + (1 << 20) - 1) >> 20; wantMiB > r.chargedMiB {
			if cerr := wasm.ChargeUnits(r.ctx, (wantMiB-r.chargedMiB)*wasm.ArchiveExtractUnitsPerMiB); cerr != nil {
				return n, cerr
			}
			r.chargedMiB = wantMiB
		}
	}
	if err == io.EOF && r.size != r.expected {
		return n, io.ErrUnexpectedEOF
	}
	return n, err
}

// FetchToCacheLongTimeoutAllowedPath reports whether a call on path (or marked
// background) may raise http.fetchToCache's timeoutMs past the 10-minute
// default up to the calling job's remaining deadline. Viewer and interactive
// request paths stay capped at 10 minutes.
func FetchToCacheLongTimeoutAllowedPath(man Manifest, path string, background bool) bool {
	p, _, _ := strings.Cut(strings.TrimSpace(path), "?")
	if p != "" && isClientRequestPath(p) {
		return false
	}
	if background {
		return true
	}
	if p == "" {
		return false
	}
	if strings.HasPrefix(p, "/ether/job/") || wasm.BackgroundPoolPath(p) {
		return true
	}
	man.Ether = man.EffectiveEther()
	if man.Ether != nil {
		for _, s := range man.Ether.Schedule {
			callPath, _, _ := strings.Cut(strings.TrimSpace(s.Call), "?")
			if callPath == p {
				return true
			}
		}
	}
	return false
}

func (h *host) allowsLongFetchToCache(ctx context.Context) bool {
	path := callPathFromContext(ctx)
	bg := isBackgroundCall(ctx) || wasm.IsBackgroundCall(ctx)
	var man Manifest
	if r, err := h.callRecord(ctx); err == nil {
		man = r.Manifest
	}
	return FetchToCacheLongTimeoutAllowedPath(man, path, bg)
}

func (h *host) fetchToCacheTimeout(ctx context.Context, timeoutMS int64) time.Duration {
	if timeoutMS <= 0 {
		return defaultHostDataFetchTimeout
	}
	const maxMS = int64(math.MaxInt64 / int64(time.Millisecond))
	var requested time.Duration
	if timeoutMS > maxMS {
		requested = time.Duration(math.MaxInt64)
	} else {
		requested = time.Duration(timeoutMS) * time.Millisecond
	}
	if requested <= defaultHostDataFetchTimeout {
		return requested
	}
	if !h.allowsLongFetchToCache(ctx) {
		return defaultHostDataFetchTimeout
	}
	if dl, ok := ctx.Deadline(); ok {
		if rem := time.Until(dl); rem > 0 {
			return min(requested, rem)
		}
		return time.Nanosecond
	}
	if maxDL, err := time.ParseDuration(h.DataLimits(ctx).Deadline); err == nil && maxDL > 0 {
		return min(requested, maxDL)
	}
	return min(requested, 12*time.Hour)
}

func wrapFetchCacheError(fetchCtx context.Context, rawURL string, err error) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, blobcache.ErrTooLarge) {
		return fmt.Errorf("%w: %v", ErrQuotaExceeded, err)
	}
	var netErr net.Error
	if errors.Is(err, context.DeadlineExceeded) ||
		(errors.As(err, &netErr) && netErr.Timeout()) ||
		(errors.Is(fetchCtx.Err(), context.DeadlineExceeded) && !errors.Is(err, ErrPermissionDenied) && !errors.Is(err, ErrQuotaExceeded)) {
		u, _ := url.Parse(rawURL)
		return fetchError(u.Hostname(), context.DeadlineExceeded)
	}
	return err
}

func (h *host) HTTPFetchToCache(ctx context.Context, req FetchCacheRequest) (FetchCacheResult, error) {
	if req.Method != "" && req.Method != "GET" {
		return FetchCacheResult{}, fmt.Errorf("plugins: fetchToCache supports GET only")
	}
	if err := h.requireWritableToolContext(ctx); err != nil {
		return FetchCacheResult{}, err
	}
	decl, err := h.cacheWriteCheck(ctx, req.LibraryKey, req.Name)
	if err != nil {
		return FetchCacheResult{}, err
	}
	timeout := h.fetchToCacheTimeout(ctx, req.TimeoutMS)
	fetchCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	fetchLimit := h.DataLimits(ctx).FetchBytes
	cacheQuota := h.m.kindBackends().libraryLimit(h.plugin, req.LibraryKey, decl.Cache)
	maxBytes := min(fetchLimit, cacheQuota)

	connections := h.fetchCacheConnections(ctx, req)
	if req.Resume || connections > 1 {
		if openPartial := h.m.kindBackends().CachePartial; openPartial != nil {
			return h.httpFetchToCacheResumable(ctx, fetchCtx, req, connections, fetchLimit, cacheQuota, openPartial)
		}
	}

	resp, err := h.openFetch(fetchCtx, req.FetchRequest)
	if err != nil {
		return FetchCacheResult{}, err
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return FetchCacheResult{}, fmt.Errorf("plugins: fetchToCache HTTP %d", resp.StatusCode)
	}
	if resp.ContentLength > maxBytes {
		return FetchCacheResult{}, fetchSizeLimitError(resp.ContentLength, fetchLimit, cacheQuota)
	}
	crc, m, s := crc32.NewIEEE(), md5.New(), sha1.New()
	reader := &boundedDataReader{ctx: fetchCtx, r: resp.Body, left: maxBytes}
	input := sizedCacheInput{io.TeeReader(reader, io.MultiWriter(crc, m, s)), resp.ContentLength}
	ref, err := h.CachePut(fetchCtx, req.LibraryKey, req.Name, input)
	h.noteFetchTraffic(ctx, req.FetchRequest, reader.size)
	if err != nil {
		if errors.Is(err, errDataExceedsSizeLimit) && reader.size > cacheQuota {
			err = fetchSizeLimitError(reader.size, fetchLimit, cacheQuota)
		}
		return FetchCacheResult{}, wrapFetchCacheError(fetchCtx, req.URL, err)
	}
	return FetchCacheResult{Blob: ref, Size: reader.size, CRC32: fmt.Sprintf("%08x", crc.Sum32()), MD5: fmt.Sprintf("%x", m.Sum(nil)), SHA1: fmt.Sprintf("%x", s.Sum(nil)), Status: resp.StatusCode}, nil
}

type parsedContentRange struct {
	start int64
	end   int64
	total int64 // -1 when "*"
}

func parseContentRange(raw string) (parsedContentRange, bool) {
	s := strings.TrimSpace(raw)
	if len(s) < 6 || !strings.EqualFold(s[:6], "bytes ") {
		return parsedContentRange{}, false
	}
	s = strings.TrimSpace(s[6:])
	rangePart, totalPart, ok := strings.Cut(s, "/")
	if !ok || strings.TrimSpace(rangePart) == "*" {
		return parsedContentRange{}, false
	}
	startStr, endStr, ok := strings.Cut(rangePart, "-")
	if !ok {
		return parsedContentRange{}, false
	}
	start, err1 := strconv.ParseInt(strings.TrimSpace(startStr), 10, 64)
	end, err2 := strconv.ParseInt(strings.TrimSpace(endStr), 10, 64)
	if err1 != nil || err2 != nil || start < 0 || end < start {
		return parsedContentRange{}, false
	}
	totalPart = strings.TrimSpace(totalPart)
	total := int64(-1)
	if totalPart != "*" {
		t, err := strconv.ParseInt(totalPart, 10, 64)
		if err != nil || t <= end {
			return parsedContentRange{}, false
		}
		total = t
	}
	return parsedContentRange{start: start, end: end, total: total}, true
}

func isWeakETag(etag string) bool {
	etag = strings.TrimSpace(etag)
	return strings.HasPrefix(etag, "W/") || strings.HasPrefix(etag, "w/")
}

func isStrongETag(etag string) bool {
	etag = strings.TrimSpace(etag)
	return etag != "" && !isWeakETag(etag)
}

func hasResumeValidator(meta blobcache.PartialMeta) bool {
	return isStrongETag(meta.ETag) || strings.TrimSpace(meta.LastModified) != ""
}

func httpTimesEqual(a, b string) bool {
	a, b = strings.TrimSpace(a), strings.TrimSpace(b)
	if a == "" || b == "" {
		return false
	}
	if a == b {
		return true
	}
	ta, errA := http.ParseTime(a)
	tb, errB := http.ParseTime(b)
	return errA == nil && errB == nil && ta.Equal(tb)
}

func validatorsMatch(saved blobcache.PartialMeta, hdr http.Header) bool {
	savedETag := strings.TrimSpace(saved.ETag)
	savedLM := strings.TrimSpace(saved.LastModified)
	respETag := strings.TrimSpace(hdr.Get("ETag"))
	respLM := strings.TrimSpace(hdr.Get("Last-Modified"))

	if isStrongETag(savedETag) {
		if !isStrongETag(respETag) || respETag != savedETag {
			return false
		}
		if savedLM != "" && respLM != "" && !httpTimesEqual(savedLM, respLM) {
			return false
		}
		return true
	}
	if savedLM != "" {
		if !httpTimesEqual(savedLM, respLM) {
			return false
		}
		if savedETag != "" && respETag != "" && respETag != savedETag {
			return false
		}
		return true
	}
	return false
}

func ifRangeHeaderValue(saved blobcache.PartialMeta) string {
	etag := strings.TrimSpace(saved.ETag)
	if isStrongETag(etag) && strings.HasPrefix(etag, `"`) && strings.HasSuffix(etag, `"`) && len(etag) >= 2 {
		return etag
	}
	lm := strings.TrimSpace(saved.LastModified)
	if lm != "" {
		if _, err := http.ParseTime(lm); err == nil {
			return lm
		}
	}
	return ""
}

func isCompressedResponse(resp *http.Response) bool {
	if resp.Uncompressed {
		return true
	}
	ce := strings.TrimSpace(resp.Header.Get("Content-Encoding"))
	return ce != "" && !strings.EqualFold(ce, "identity")
}

func partialMetaFromResponse(hdr http.Header, expectedTotal int64, compressed bool) blobcache.PartialMeta {
	if compressed {
		return blobcache.PartialMeta{ContentLength: expectedTotal}
	}
	return blobcache.PartialMeta{
		ETag:          strings.TrimSpace(hdr.Get("ETag")),
		LastModified:  strings.TrimSpace(hdr.Get("Last-Modified")),
		ContentLength: expectedTotal,
	}
}

func mergePartialMeta(saved blobcache.PartialMeta, hdr http.Header, expectedTotal int64) blobcache.PartialMeta {
	out := saved
	if out.ETag == "" {
		out.ETag = strings.TrimSpace(hdr.Get("ETag"))
	}
	if out.LastModified == "" {
		out.LastModified = strings.TrimSpace(hdr.Get("Last-Modified"))
	}
	if expectedTotal >= 0 {
		out.ContentLength = expectedTotal
	}
	return out
}

func fetchSizeLimitError(total, fetchLimit, cacheQuota int64) error {
	if total > cacheQuota {
		return fmt.Errorf("%w: fetch size %d exceeds library cache quota %d", ErrQuotaExceeded, total, cacheQuota)
	}
	return errDataExceedsSizeLimit
}

func (h *host) httpFetchToCacheResumable(
	ctx context.Context,
	fetchCtx context.Context,
	req FetchCacheRequest,
	connections int,
	fetchLimit, cacheQuota int64,
	openPartial func(ctx context.Context, pluginID, libraryKey, key string) (*blobcache.Partial, error),
) (FetchCacheResult, error) {
	for k := range req.Headers {
		if strings.EqualFold(k, "Range") {
			return FetchCacheResult{}, fmt.Errorf("plugins: fetchToCache resume cannot be combined with an explicit Range header")
		}
	}

	maxBytes := min(fetchLimit, cacheQuota)
	partialKey := req.URL + "\x00" + req.Name
	if !req.Resume {
		partialKey += "\x00transient"
	}
	partial, err := openPartial(fetchCtx, h.plugin, req.LibraryKey, partialKey)
	if err != nil {
		return FetchCacheResult{}, wrapFetchCacheError(fetchCtx, req.URL, err)
	}
	defer partial.Close()
	if !req.Resume {
		if err := partial.Discard(); err != nil {
			return FetchCacheResult{}, err
		}
		defer partial.Discard()
	}

	baseHeaders := cloneHeaders(req.Headers)
	if baseHeaders == nil {
		baseHeaders = make(map[string]string, 2)
	}
	hasAcceptEncoding := false
	for k := range baseHeaders {
		if strings.EqualFold(k, "Accept-Encoding") {
			hasAcceptEncoding = true
			break
		}
	}
	if !hasAcceptEncoding {
		// Prevent net/http transparent gzip decoding so byte offsets stay
		// aligned between initial GET and resumed Range requests.
		baseHeaders["Accept-Encoding"] = "identity"
	}

	openFetch := func(req FetchRequest) (*http.Response, error) {
		return h.openFetchWithOptions(fetchCtx, req, fetchOptions{applyHostLimit: connections > 1})
	}
	useParallel := connections > 1
	if cached := partial.Size(); cached > 0 {
		meta := partial.Meta()
		if !hasResumeValidator(meta) || cached > maxBytes || (meta.ContentLength >= 0 && meta.ContentLength > maxBytes) {
			_ = partial.Discard()
		}
	}

	var totalTransferred int64
	defer func() {
		if totalTransferred > 0 {
			h.noteFetchTraffic(ctx, req.FetchRequest, totalTransferred)
		}
	}()

	buf := make([]byte, 64<<10)
	restarted := false

	for {
		if err := fetchCtx.Err(); err != nil {
			return FetchCacheResult{}, wrapFetchCacheError(fetchCtx, req.URL, err)
		}

		attemptReq := req.FetchRequest
		attemptReq.Headers = cloneHeaders(baseHeaders)
		cached := partial.Size()
		meta := partial.Meta()
		sentRange := false
		if cached > 0 && len(meta.RangeProgress) == 0 && hasResumeValidator(meta) {
			attemptReq.Headers["Range"] = fmt.Sprintf("bytes=%d-", cached)
			if ifRange := ifRangeHeaderValue(meta); ifRange != "" {
				attemptReq.Headers["If-Range"] = ifRange
			}
			sentRange = true
		}

		resp, err := openFetch(attemptReq)
		if err != nil {
			return FetchCacheResult{}, wrapFetchCacheError(fetchCtx, req.URL, err)
		}

		if sentRange && (resp.StatusCode == http.StatusRequestedRangeNotSatisfiable || resp.StatusCode == http.StatusPreconditionFailed) {
			_ = resp.Body.Close()
			_ = partial.Discard()
			if !restarted {
				restarted = true
				useParallel = false
				continue
			}
			return FetchCacheResult{}, fmt.Errorf("plugins: fetchToCache HTTP %d", resp.StatusCode)
		}

		if resp.StatusCode == http.StatusPartialContent {
			if !sentRange {
				_ = resp.Body.Close()
				return FetchCacheResult{}, fmt.Errorf("plugins: fetchToCache HTTP %d", resp.StatusCode)
			}
			cr, ok := parseContentRange(resp.Header.Get("Content-Range"))
			chunkExpected := cr.end - cr.start + 1
			valid := ok &&
				cr.start == cached &&
				!isCompressedResponse(resp) &&
				validatorsMatch(meta, resp.Header) &&
				(resp.ContentLength < 0 || resp.ContentLength == chunkExpected) &&
				(meta.ContentLength < 0 || cr.total < 0 || cr.total == meta.ContentLength)
			if !valid {
				_ = resp.Body.Close()
				_ = partial.Discard()
				if !restarted {
					restarted = true
					useParallel = false
					continue
				}
				return FetchCacheResult{}, fmt.Errorf("plugins: fetchToCache resume validator or Content-Range mismatch")
			}

			expectedTotal := cr.total
			if expectedTotal < 0 && meta.ContentLength >= 0 {
				expectedTotal = meta.ContentLength
			}
			if (expectedTotal >= 0 && expectedTotal > maxBytes) || cached+chunkExpected > maxBytes {
				_ = resp.Body.Close()
				_ = partial.Discard()
				over := max(expectedTotal, cached+chunkExpected)
				return FetchCacheResult{}, fetchSizeLimitError(over, fetchLimit, cacheQuota)
			}

			if err := partial.SetMeta(mergePartialMeta(meta, resp.Header, expectedTotal)); err != nil {
				_ = resp.Body.Close()
				return FetchCacheResult{}, err
			}
			reserveTotal := expectedTotal
			if reserveTotal < 0 {
				reserveTotal = cached + chunkExpected
			}
			if reserveTotal > cached {
				if err := partial.Reserve(reserveTotal); err != nil {
					_ = resp.Body.Close()
					if errors.Is(err, blobcache.ErrTooLarge) && !errors.Is(err, blobcache.ErrQuotaFull) {
						_ = partial.Discard()
					} else {
						_ = partial.Sync()
					}
					return FetchCacheResult{}, wrapFetchCacheError(fetchCtx, req.URL, err)
				}
			}

			reader := &boundedDataReader{ctx: fetchCtx, r: resp.Body, left: maxBytes - cached}
			_, copyErr := io.CopyBuffer(partial, reader, buf)
			totalTransferred += reader.size
			_ = resp.Body.Close()
			if copyErr != nil {
				if errors.Is(copyErr, errDataExceedsSizeLimit) || (errors.Is(copyErr, blobcache.ErrTooLarge) && !errors.Is(copyErr, blobcache.ErrQuotaFull)) {
					_ = partial.Discard()
					if errors.Is(copyErr, errDataExceedsSizeLimit) && cached+reader.size > cacheQuota {
						return FetchCacheResult{}, fetchSizeLimitError(cached+reader.size, fetchLimit, cacheQuota)
					}
					return FetchCacheResult{}, wrapFetchCacheError(fetchCtx, req.URL, copyErr)
				}
				_ = partial.Sync()
				return FetchCacheResult{}, wrapFetchCacheError(fetchCtx, req.URL, copyErr)
			}

			if reader.size < chunkExpected {
				_ = partial.Sync()
				return FetchCacheResult{}, io.ErrUnexpectedEOF
			}
			if reader.size > chunkExpected {
				_ = partial.Discard()
				return FetchCacheResult{}, fmt.Errorf("plugins: fetchToCache range response exceeded Content-Range length")
			}
			if expectedTotal >= 0 && partial.Size() < expectedTotal {
				_ = partial.Sync()
				if reader.size > 0 {
					// Server capped this 206 response below EOF; continue with next range.
					continue
				}
				return FetchCacheResult{}, io.ErrUnexpectedEOF
			}
			if expectedTotal >= 0 && partial.Size() > expectedTotal {
				_ = partial.Discard()
				return FetchCacheResult{}, fmt.Errorf("plugins: fetchToCache exceeded expected content length")
			}

			committed, cerr := partial.Commit(fetchCtx, req.Name)
			if cerr != nil {
				if errors.Is(cerr, blobcache.ErrTooLarge) && !errors.Is(cerr, blobcache.ErrQuotaFull) {
					_ = partial.Discard()
				} else {
					_ = partial.Sync()
				}
				return FetchCacheResult{}, wrapFetchCacheError(fetchCtx, req.URL, cerr)
			}
			return FetchCacheResult{
				Blob:   committed.Ref.String(),
				Size:   committed.Size,
				CRC32:  committed.CRC32,
				MD5:    committed.MD5,
				SHA1:   committed.SHA1,
				Status: resp.StatusCode,
			}, nil
		}

		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
			_ = resp.Body.Close()
			if resp.StatusCode == http.StatusNotFound || resp.StatusCode == http.StatusGone {
				_ = partial.Discard()
			}
			return FetchCacheResult{}, fmt.Errorf("plugins: fetchToCache HTTP %d", resp.StatusCode)
		}

		// Full 2xx response (initial GET, server ignored Range, or If-Range
		// detected a changed resource and returned the full replacement).
		expectedTotal := resp.ContentLength
		if expectedTotal >= 0 && expectedTotal > maxBytes {
			_ = resp.Body.Close()
			_ = partial.Discard()
			return FetchCacheResult{}, fetchSizeLimitError(expectedTotal, fetchLimit, cacheQuota)
		}

		compressed := isCompressedResponse(resp)
		newMeta := partialMetaFromResponse(resp.Header, expectedTotal, compressed)
		if (useParallel || len(meta.RangeProgress) != 0) && !sentRange && canFetchCacheRanges(resp, newMeta) {
			newMeta.RangeSource = fetchCacheRangeSource(resp)
			if matchesFetchCacheRanges(meta, newMeta, resp.Header) {
				_ = resp.Body.Close()
				attemptReq.Headers = baseHeaders
				result, transferred, err := h.fetchCacheRanges(fetchCtx, req, attemptReq, partial, newMeta, connections)
				totalTransferred += transferred
				if !errors.Is(err, errFetchCacheRangeFallback) {
					return result, wrapFetchCacheError(fetchCtx, req.URL, err)
				}
				_ = partial.Discard()
				useParallel = false
				continue
			}
			newMeta.RangeSource = ""
		}
		if err := partial.Reset(newMeta); err != nil {
			_ = resp.Body.Close()
			return FetchCacheResult{}, err
		}
		if expectedTotal > 0 {
			if err := partial.Reserve(expectedTotal); err != nil {
				_ = resp.Body.Close()
				return FetchCacheResult{}, wrapFetchCacheError(fetchCtx, req.URL, err)
			}
		}

		reader := &boundedDataReader{ctx: fetchCtx, r: resp.Body, left: maxBytes}
		_, copyErr := io.CopyBuffer(partial, reader, buf)
		totalTransferred += reader.size
		_ = resp.Body.Close()
		if copyErr != nil {
			unfitBlob := errors.Is(copyErr, errDataExceedsSizeLimit) ||
				(errors.Is(copyErr, blobcache.ErrTooLarge) && !errors.Is(copyErr, blobcache.ErrQuotaFull))
			if unfitBlob || compressed || !hasResumeValidator(newMeta) || partial.Size() == 0 {
				_ = partial.Discard()
				if errors.Is(copyErr, errDataExceedsSizeLimit) && reader.size > cacheQuota {
					return FetchCacheResult{}, fetchSizeLimitError(reader.size, fetchLimit, cacheQuota)
				}
			} else {
				_ = partial.Sync()
			}
			return FetchCacheResult{}, wrapFetchCacheError(fetchCtx, req.URL, copyErr)
		}

		if expectedTotal >= 0 && partial.Size() < expectedTotal {
			if !compressed && hasResumeValidator(newMeta) && partial.Size() > 0 {
				_ = partial.Sync()
			} else {
				_ = partial.Discard()
			}
			return FetchCacheResult{}, io.ErrUnexpectedEOF
		}
		if expectedTotal >= 0 && partial.Size() > expectedTotal {
			_ = partial.Discard()
			return FetchCacheResult{}, fmt.Errorf("plugins: fetchToCache exceeded expected content length")
		}

		committed, cerr := partial.Commit(fetchCtx, req.Name)
		if cerr != nil {
			unfitBlob := errors.Is(cerr, blobcache.ErrTooLarge) && !errors.Is(cerr, blobcache.ErrQuotaFull)
			if unfitBlob || compressed || !hasResumeValidator(newMeta) || partial.Size() == 0 {
				_ = partial.Discard()
			} else {
				_ = partial.Sync()
			}
			return FetchCacheResult{}, wrapFetchCacheError(fetchCtx, req.URL, cerr)
		}
		return FetchCacheResult{
			Blob:   committed.Ref.String(),
			Size:   committed.Size,
			CRC32:  committed.CRC32,
			MD5:    committed.MD5,
			SHA1:   committed.SHA1,
			Status: resp.StatusCode,
		}, nil
	}
}

// CacheRasterize rasterises an SVG already in the plugin's own blob cache
// into a new cached bitmap blob, using Ether's bounded SVG rasteriser. The
// source read is capped at the rasteriser's SVG size limit, output sizes
// are bounded by its dimension limit, and artwork.ErrSVG is returned for
// documents the rasteriser refuses. Rendered variants are cached by the
// rasteriser (by source content and size) and the stored blob is
// content-addressed, so repeat calls return the same reference.
func (h *host) CacheRasterize(ctx context.Context, libraryKey, name, sourceBlobRef string, opts RasterizeOptions) (RasterizeResult, error) {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return RasterizeResult{}, err
	}
	if _, err := h.cacheWriteCheck(ctx, libraryKey, name); err != nil {
		return RasterizeResult{}, err
	}
	format := strings.ToLower(strings.TrimSpace(opts.Format))
	if format == "" {
		format = "png"
	}
	if opts.Width < 0 || opts.Height < 0 || opts.Width > artwork.MaxRasterDimension || opts.Height > artwork.MaxRasterDimension || (format != "png" && format != "jpeg") {
		return RasterizeResult{}, artwork.ErrSVG
	}
	rc, err := h.CacheOpen(ctx, sourceBlobRef)
	if err != nil {
		return RasterizeResult{}, err
	}
	source, err := io.ReadAll(io.LimitReader(rc, artwork.MaxSVGBytes+1))
	_ = rc.Close()
	if err != nil {
		return RasterizeResult{}, err
	}
	raster := h.m.iconRaster
	if raster == nil {
		raster = artwork.NewSVGRasterizer()
	}
	data, contentType, err := raster.Rasterize(ctx, "plugin:"+h.plugin+":"+sourceBlobRef, source, artwork.RasterOptions{Width: opts.Width, Height: opts.Height, Format: format})
	if err != nil {
		return RasterizeResult{}, err
	}
	var dims struct{ Width, Height int }
	if format == "png" {
		cfg, derr := png.DecodeConfig(bytes.NewReader(data))
		if derr != nil {
			return RasterizeResult{}, derr
		}
		dims.Width, dims.Height = cfg.Width, cfg.Height
	} else {
		cfg, derr := jpeg.DecodeConfig(bytes.NewReader(data))
		if derr != nil {
			return RasterizeResult{}, derr
		}
		dims.Width, dims.Height = cfg.Width, cfg.Height
	}
	ref, err := h.CachePut(ctx, libraryKey, name, bytes.NewReader(data))
	if err != nil {
		return RasterizeResult{}, err
	}
	return RasterizeResult{Blob: ref, ContentType: contentType, Width: dims.Width, Height: dims.Height, Size: int64(len(data))}, nil
}

func validDataRange(r DataRange, maxBytes int64) error {
	if r.Offset < 0 || r.Length <= 0 || r.Length > maxBytes || r.Offset > 1<<60 {
		return fmt.Errorf("plugins: range needs nonnegative offset and length 1..%d", maxBytes)
	}
	return nil
}

func readAllSized(r io.Reader, sizeHint int64) ([]byte, error) {
	if sizeHint < 0 {
		sizeHint = 0
	}
	capHint := min(sizeHint+512, int64(8<<20))
	if capHint < 512 {
		capHint = 512
	}
	b := make([]byte, 0, capHint)
	for {
		if len(b) == cap(b) {
			next := max(cap(b)*2, 4096)
			if sizeHint > int64(next) {
				next = int(min(sizeHint+512, int64(MaxDataReadBytes)+512))
			}
			grown := make([]byte, len(b), next)
			copy(grown, b)
			b = grown
		}
		n, err := r.Read(b[len(b):cap(b)])
		b = b[:len(b)+n]
		if err != nil {
			if err == io.EOF {
				return b, nil
			}
			return b, err
		}
	}
}

func readDataRangeBytes(ctx context.Context, r io.Reader, opt DataRange, maxBytes, sizeHint int64) ([]byte, error) {
	if err := validDataRange(opt, maxBytes); err != nil {
		return nil, err
	}
	cr := &boundedDataReader{ctx: ctx, r: r, left: opt.Offset + opt.Length}
	if opt.Offset > 0 {
		if _, err := io.CopyN(io.Discard, cr, opt.Offset); err != nil {
			return nil, err
		}
	}
	return readAllSized(io.LimitReader(cr, opt.Length), sizeHint)
}

// Always return base64: arbitrary text/control bytes then have a predictable
// JSON envelope scaled with the plugin's per-call readBytes grant.
func readDataRange(ctx context.Context, r io.Reader, opt DataRange, maxBytes, sizeHint int64) (map[string]any, error) {
	data, err := readDataRangeBytes(ctx, r, opt, maxBytes, sizeHint)
	if err != nil {
		return nil, err
	}
	return map[string]any{"bodyBase64": base64.StdEncoding.EncodeToString(data), "size": len(data)}, nil
}

func readArchiveMemberRange(ctx context.Context, archive *dataArchive, member int, opt DataRange, maxBytes int64) ([]byte, error) {
	if member < 0 || member >= len(archive.members) {
		return nil, fmt.Errorf("plugins: archive member index outside range")
	}
	f := archive.members[member]
	if uint64(opt.Offset) > f.Size {
		return nil, fmt.Errorf("plugins: archive member offset outside range")
	}
	stream, err := archive.open(member)
	if err != nil {
		return nil, err
	}
	defer stream.Close()
	rem := int64(min(f.Size-uint64(opt.Offset), uint64(maxBytes)))
	sizeHint := min(opt.Length, rem)
	return readDataRangeBytes(ctx, io.LimitReader(stream, int64(f.Size)), opt, maxBytes, sizeHint)
}

// seekReaderAt gives zip.Reader random access without materializing an archive.
// It is used by one synchronous host call, never shared between goroutines.
type seekReaderAt struct {
	ctx context.Context
	r   io.ReadSeeker
}

func (r seekReaderAt) ReadAt(p []byte, off int64) (int, error) {
	if err := r.ctx.Err(); err != nil {
		return 0, err
	}
	if ra, ok := r.r.(io.ReaderAt); ok {
		n, err := ra.ReadAt(p, off)
		if err == io.EOF && n == len(p) {
			err = nil
		}
		return n, err
	}
	if _, err := r.r.Seek(off, io.SeekStart); err != nil {
		return 0, err
	}
	n, err := io.ReadFull(r.r, p)
	if err == io.ErrUnexpectedEOF {
		err = io.EOF
	}
	return n, err
}

type ArchiveMember struct {
	Index int    `json:"index"`
	Name  string `json:"name"`
	Size  uint64 `json:"size"`
	// Unsafe names identify members only and must never be used as output paths.
	Unsafe       bool   `json:"unsafe,omitempty"`
	UnsafeReason string `json:"unsafeReason,omitempty"`
}

func openDataZIP(ctx context.Context, rc io.ReadSeeker, grants ...RuntimeLimits) (*zip.Reader, error) {
	limits := defaultDataLimits()
	if len(grants) > 0 {
		limits = grants[0]
	}
	ra := &archiveIOBudget{r: seekReaderAt{ctx, rc}, left: limits.FetchBytes}
	return parseDataZIP(rc, ra, limits)
}

func parseDataZIP(rc io.ReadSeeker, ra *archiveIOBudget, limits RuntimeLimits) (*zip.Reader, error) {
	directoryCap := archiveDirectoryCap(limits)

	size, err := rc.Seek(0, io.SeekEnd)
	if err != nil {
		return nil, err
	}
	if size < 22 || size > limits.FetchBytes {
		return nil, fmt.Errorf("plugins: ZIP size outside limit")
	}
	tailSize := min(size, int64(65557))
	tail := make([]byte, tailSize)
	if _, err := ra.ReadAt(tail, size-tailSize); err != nil {
		return nil, err
	}
	// Inspect classic/ZIP64 EOCD before zip.NewReader allocates the directory.
	// Split archives are refused; counts and bytes use owner ceilings.
	found := false
	for i := len(tail) - 22; i >= 0; i-- {
		if binary.LittleEndian.Uint32(tail[i:]) != 0x06054b50 || i+22+int(binary.LittleEndian.Uint16(tail[i+20:])) != len(tail) {
			continue
		}
		e := tail[i:]
		count := uint64(binary.LittleEndian.Uint16(e[10:]))
		directory := uint64(binary.LittleEndian.Uint32(e[12:]))
		offset := uint64(binary.LittleEndian.Uint32(e[16:]))
		directoryEnd := size - tailSize + int64(i)
		if binary.LittleEndian.Uint16(e[4:]) != 0 || binary.LittleEndian.Uint16(e[6:]) != 0 || uint64(binary.LittleEndian.Uint16(e[8:])) != count {
			return nil, fmt.Errorf("plugins: split ZIP archives are unsupported")
		}
		if count == 65535 || directory == 0xffffffff || offset == 0xffffffff {
			locator := make([]byte, 20)
			if directoryEnd < 20 {
				return nil, fmt.Errorf("plugins: invalid ZIP64 locator")
			}
			if _, err := ra.ReadAt(locator, directoryEnd-20); err != nil {
				return nil, err
			}
			if binary.LittleEndian.Uint32(locator) != 0x07064b50 || binary.LittleEndian.Uint32(locator[4:]) != 0 || binary.LittleEndian.Uint32(locator[16:]) != 1 {
				return nil, fmt.Errorf("plugins: invalid or split ZIP64 archive")
			}
			recordAt := binary.LittleEndian.Uint64(locator[8:])
			if recordAt > uint64(directoryEnd-20) || uint64(directoryEnd-20)-recordAt < 56 {
				return nil, fmt.Errorf("plugins: invalid ZIP64 directory offset")
			}
			record := make([]byte, 56)
			if _, err := ra.ReadAt(record, int64(recordAt)); err != nil {
				return nil, err
			}
			recordLength := binary.LittleEndian.Uint64(record[4:])
			if binary.LittleEndian.Uint32(record) != 0x06064b50 || recordLength < 44 || recordLength > 1<<20 || recordAt+12+recordLength != uint64(directoryEnd-20) || binary.LittleEndian.Uint32(record[16:]) != 0 || binary.LittleEndian.Uint32(record[20:]) != 0 || binary.LittleEndian.Uint64(record[24:]) != binary.LittleEndian.Uint64(record[32:]) {
				return nil, fmt.Errorf("plugins: invalid ZIP64 directory")
			}
			count = binary.LittleEndian.Uint64(record[32:])
			directory = binary.LittleEndian.Uint64(record[40:])
			offset = binary.LittleEndian.Uint64(record[48:])
			directoryEnd = int64(recordAt)
		}
		if count > uint64(limits.ArchiveMembers) || count > uint64(archiveMemory(limits)/1024) || directory > uint64(directoryCap) || offset > uint64(directoryEnd) || directory > uint64(directoryEnd)-offset || offset+directory != uint64(directoryEnd) {
			return nil, fmt.Errorf("plugins: ZIP directory exceeds owner limits or has unsupported layout")
		}
		raw := make([]byte, int(directory))
		if _, err := ra.ReadAt(raw, int64(offset)); err != nil {
			return nil, err
		}
		pos := 0
		for n := 0; n < int(count); n++ {
			if pos+46 > len(raw) || binary.LittleEndian.Uint32(raw[pos:]) != 0x02014b50 {
				return nil, fmt.Errorf("plugins: invalid ZIP directory")
			}
			header := raw[pos:]
			pos += 46 + int(binary.LittleEndian.Uint16(header[28:])) + int(binary.LittleEndian.Uint16(header[30:])) + int(binary.LittleEndian.Uint16(header[32:]))
			if pos > len(raw) {
				return nil, fmt.Errorf("plugins: invalid ZIP directory length")
			}
		}
		if pos != len(raw) {
			return nil, fmt.Errorf("plugins: ZIP directory count mismatch")
		}
		found = true
		break
	}
	if !found {
		return nil, fmt.Errorf("plugins: ZIP directory not found")
	}
	z, err := zip.NewReader(ra, size)
	// With zipinsecurepath=0, Go still returns the directory alongside this
	// warning. Names are identifiers here; the per-member guard controls opens.
	if err != nil && err != zip.ErrInsecurePath {
		return nil, err
	}
	if len(z.File) > limits.ArchiveMembers {
		return nil, fmt.Errorf("plugins: ZIP has too many members")
	}
	var total uint64
	names := 0
	for _, f := range z.File {
		names += len(f.Name)
		if int64(names) > directoryCap {
			return nil, fmt.Errorf("plugins: ZIP member names exceed directory grant")
		}
		if !f.FileInfo().IsDir() && !f.Mode().IsRegular() {
			return nil, fmt.Errorf("plugins: unsupported ZIP member type")
		}
		if f.Flags&1 != 0 || (f.Method != zip.Store && f.Method != zip.Deflate) {
			return nil, fmt.Errorf("plugins: encrypted or unsupported ZIP member")
		}
		if f.CompressedSize64 > uint64(size) || f.UncompressedSize64 > uint64(limits.ArchiveMemberBytes) || (f.UncompressedSize64 > 0 && (f.CompressedSize64 == 0 || (f.CompressedSize64 <= ^uint64(0)/maxArchiveRatio && f.UncompressedSize64 > f.CompressedSize64*maxArchiveRatio))) {
			return nil, fmt.Errorf("plugins: ZIP member exceeds size or compression-ratio limit")
		}
		if f.UncompressedSize64 > uint64(limits.ArchiveExpandedBytes)-total {
			return nil, fmt.Errorf("plugins: ZIP expanded size exceeds limit")
		}
		total += f.UncompressedSize64
	}
	return z, nil
}

// CallDataHost is the shared hosted/remote data-service funnel. Only named
// services are accepted; cache access rechecks plugin ownership each call.
func CallDataHost(ctx context.Context, h Host, name string, raw json.RawMessage) (json.RawMessage, error) {
	ctx = withCallRecord(ctx, h)
	// Remote callers receive the same maximum I/O deadline as hosted calls.
	limits := defaultDataLimits()
	if provider, ok := h.(interface {
		DataLimits(context.Context) RuntimeLimits
	}); ok {
		limits = provider.DataLimits(ctx)
	}
	if active, ok := wasm.CallLimits(ctx); ok {
		limits.MemoryBytes = active.MemoryBytes
		limits.Deadline = active.Deadline.String()
		limits.UnitBudget = active.UnitBudget
		limits.PoolSize = active.PoolSize
	}
	limits.ReadBytes = dataReadLimit(limits)
	readCap := limits.ReadBytes

	deadline, err := time.ParseDuration(limits.Deadline)
	if err != nil || deadline <= 0 {
		deadline = 12 * time.Hour
	}
	ctx, cancel := context.WithTimeout(ctx, deadline)
	defer cancel()
	var args []json.RawMessage
	if err := json.Unmarshal(raw, &args); err != nil {
		return nil, err
	}
	var value any
	if name == "runtime.limits" {
		if len(args) != 0 {
			return nil, fmt.Errorf("plugins: runtime.limits takes no arguments")
		}
		if ph, ok := h.(*host); ok {
			r, rerr := ph.callRecord(ctx)
			if rerr != nil {
				return nil, rerr
			}
			if !r.Enabled {
				return nil, ErrDisabled
			}
		}
		value = limits
	} else if name == "cache.put" {
		value, err = callCachePut(ctx, h, args)
	} else if name == "http.hash" {
		var req HashRequest
		if len(args) != 1 {
			return nil, fmt.Errorf("plugins: hash takes one request")
		}
		if err = json.Unmarshal(args[0], &req); err != nil {
			return nil, err
		}
		service, ok := h.(interface {
			HTTPHash(context.Context, HashRequest) (HashResult, error)
		})
		if !ok {
			return nil, ErrUnavailable
		}
		value, err = service.HTTPHash(ctx, req)
	} else if name == "http.fetchToCache" {
		var req struct {
			TimeoutMS             int64             `json:"timeoutMs"`
			Method                string            `json:"method"`
			URL                   string            `json:"url"`
			Headers               map[string]string `json:"headers"`
			KeepHeadersOnRedirect []string          `json:"keepHeadersOnRedirect"`
			LibraryKey            string            `json:"libraryKey"`
			Name                  string            `json:"name"`
			Resume                bool              `json:"resume"`
			Connections           int               `json:"connections"`
		}
		if len(args) != 1 {
			return nil, fmt.Errorf("plugins: fetchToCache takes one request")
		}
		if err = json.Unmarshal(args[0], &req); err != nil {
			return nil, err
		}
		if req.Method != "" && req.Method != "GET" {
			return nil, fmt.Errorf("plugins: fetchToCache supports GET only")
		}
		service, ok := h.(interface {
			HTTPFetchToCache(context.Context, FetchCacheRequest) (FetchCacheResult, error)
		})
		if !ok {
			return nil, ErrUnavailable
		}
		value, err = service.HTTPFetchToCache(ctx, FetchCacheRequest{
			FetchRequest: FetchRequest{
				TimeoutMS:             req.TimeoutMS,
				Method:                req.Method,
				URL:                   req.URL,
				Headers:               req.Headers,
				KeepHeadersOnRedirect: req.KeepHeadersOnRedirect,
			},
			LibraryKey:  req.LibraryKey,
			Name:        req.Name,
			Resume:      req.Resume,
			Connections: req.Connections,
		})
	} else if name == "cache.usage" {
		var opts struct {
			Durable bool `json:"durable"`
		}
		if len(args) != 1 || json.Unmarshal(args[0], &opts) != nil || !opts.Durable {
			return nil, &ValidationError{Fields: []FieldError{{Field: "cache.usage", Message: "expected {durable: true}"}}}
		}
		service, ok := h.(interface {
			CacheUsage(context.Context) (blobcache.DurableUsage, error)
		})
		if !ok {
			return nil, ErrUnavailable
		}
		value, err = service.CacheUsage(ctx)
	} else if name == "cache.stat" {
		var ref string
		if len(args) != 1 || json.Unmarshal(args[0], &ref) != nil || ref == "" {
			return nil, &ValidationError{Fields: []FieldError{{Field: "cache.stat", Message: "expected one blob reference"}}}
		}
		service, ok := h.(interface {
			CacheStat(context.Context, string) (blobcache.Stat, error)
		})
		if !ok {
			return nil, ErrUnavailable
		}
		value, err = service.CacheStat(ctx, ref)
	} else if name == "cache.rasterize" {
		if len(args) < 3 || len(args) > 4 {
			return nil, fmt.Errorf("plugins: cache.rasterize takes (libraryKey, name, sourceBlob[, options])")
		}
		var libraryKey, entryName, sourceBlobRef string
		var opts RasterizeOptions
		if err = json.Unmarshal(args[0], &libraryKey); err == nil {
			err = json.Unmarshal(args[1], &entryName)
		}
		if err == nil {
			err = json.Unmarshal(args[2], &sourceBlobRef)
		}
		if err == nil && len(args) == 4 && string(args[3]) != "null" {
			err = json.Unmarshal(args[3], &opts)
		}
		if err != nil {
			return nil, err
		}
		service, ok := h.(interface {
			CacheRasterize(context.Context, string, string, string, RasterizeOptions) (RasterizeResult, error)
		})
		if !ok {
			return nil, ErrUnavailable
		}
		value, err = service.CacheRasterize(ctx, libraryKey, entryName, sourceBlobRef, opts)
	} else {
		if name != "cache.read" && name != "archive.list" && name != "archive.open" && name != "archive.read" && name != "archive.extract" {
			return nil, ErrPermissionDenied
		}
		if len(args) == 0 {
			return nil, fmt.Errorf("plugins: data service needs a blob reference")
		}
		var ref string
		if err = json.Unmarshal(args[0], &ref); err != nil {
			return nil, err
		}
		var opt DataRange
		var reads []ArchiveReadItem
		var extractOpt ArchiveExtractOptions
		var member int
		switch name {
		case "archive.list":
			if len(args) != 1 {
				return nil, fmt.Errorf("plugins: archive.list takes one blob reference")
			}
		case "cache.read":
			if len(args) != 2 {
				return nil, fmt.Errorf("plugins: cache.read takes (blob, range)")
			}
			err = json.Unmarshal(args[1], &opt)
		case "archive.open":
			if len(args) != 3 {
				return nil, fmt.Errorf("plugins: archive.open takes (blob, memberIndex, range)")
			}
			if err = json.Unmarshal(args[1], &member); err == nil {
				err = json.Unmarshal(args[2], &opt)
			}
		case "archive.read":
			if len(args) != 2 {
				return nil, fmt.Errorf("plugins: archive.read takes (blob, reads)")
			}
			err = json.Unmarshal(args[1], &reads)
		case "archive.extract":
			if len(args) < 2 || len(args) > 3 {
				return nil, fmt.Errorf("plugins: archive.extract takes (blob, memberIndex[, options])")
			}
			err = json.Unmarshal(args[1], &member)
			if err == nil && len(args) == 3 && string(args[2]) != "null" {
				err = json.Unmarshal(args[2], &extractOpt)
			}
		}
		if err != nil {
			return nil, err
		}
		if name == "cache.read" || name == "archive.open" {
			if err = validDataRange(opt, readCap); err != nil {
				return nil, err
			}
		}
		if name == "archive.read" {
			if len(reads) == 0 || len(reads) > MaxArchiveReadItems {
				return nil, fmt.Errorf("plugins: archive.read takes 1..%d reads", MaxArchiveReadItems)
			}
			var totalRequested int64
			for _, item := range reads {
				if err = validDataRange(DataRange{Offset: item.Offset, Length: item.Length}, readCap); err != nil {
					return nil, err
				}
				if item.Length > readCap-totalRequested {
					return nil, fmt.Errorf("plugins: archive.read requested bytes exceed per-call readBytes limit (%d)", readCap)
				}
				totalRequested += item.Length
			}
			if err = wasm.ChargeUnits(ctx, int64(len(reads))*wasm.ArchiveReadUnitsPerMember); err != nil {
				return nil, err
			}
		}
		var defaultLibKey string
		if name == "archive.extract" {
			if checker, ok := h.(interface {
				archiveExtractCheck(context.Context, string) (string, error)
			}); ok {
				defaultLibKey, err = checker.archiveExtractCheck(ctx, extractOpt.LibraryKey)
				if err != nil {
					return nil, err
				}
			}
		}
		rc, e := h.CacheOpen(ctx, ref)
		if e != nil {
			return nil, e
		}
		defer rc.Close()
		if name == "cache.read" {
			if _, err = rc.Seek(opt.Offset, io.SeekStart); err != nil {
				return nil, err
			}
			sizeHint := min(opt.Length, int64(64<<10))
			if sizer, ok := rc.(interface{ Size() int64 }); ok {
				if rem := sizer.Size() - opt.Offset; rem >= 0 {
					sizeHint = min(opt.Length, rem)
				}
			}
			opt.Offset = 0
			value, err = readDataRange(ctx, rc, opt, readCap, sizeHint)
		} else {
			var archive *dataArchive
			var e error
			if owner, ok := h.(interface{ archiveDirectoryCache() *archiveDirectoryCache }); ok {
				archive, e = owner.archiveDirectoryCache().open(ctx, ref, rc, limits)
			} else {
				archive, e = openDataArchive(ctx, rc, limits)
			}
			if e != nil {
				return nil, e
			}
			switch name {
			case "archive.list":
				value = archive.members
			case "archive.open":
				var data []byte
				data, err = readArchiveMemberRange(ctx, archive, member, opt, readCap)
				if err != nil {
					return nil, err
				}
				value = map[string]any{"bodyBase64": base64.StdEncoding.EncodeToString(data), "size": len(data)}
			case "archive.read":
				out := make([]ArchiveReadResult, len(reads))
				for i, item := range reads {
					var data []byte
					data, err = readArchiveMemberRange(ctx, archive, item.Member, DataRange{Offset: item.Offset, Length: item.Length}, readCap)
					if err != nil {
						return nil, err
					}
					out[i] = ArchiveReadResult{
						Index:      i,
						Member:     item.Member,
						Size:       len(data),
						BodyBase64: base64.StdEncoding.EncodeToString(data),
					}
				}
				value = out
			case "archive.extract":
				if member < 0 || member >= len(archive.members) {
					return nil, fmt.Errorf("plugins: archive member index outside range")
				}
				f := archive.members[member]
				entryName := strings.TrimSpace(extractOpt.Name)
				if entryName == "" && !f.Unsafe {
					entryName = path.Base(strings.TrimSuffix(f.Name, "/"))
				}
				if entryName == "" || entryName == "." || entryName == "/" {
					entryName = fmt.Sprintf("member-%d", member)
				}
				sourceLibKey := ""
				if src, ok := rc.(interface{ LibraryKey() string }); ok {
					sourceLibKey = src.LibraryKey()
				}
				libraryKey := extractOpt.LibraryKey
				cacheLimit := int64(math.MaxInt64)
				if resolver, ok := h.(interface {
					resolveExtractTarget(context.Context, string, string, string) (string, int64, error)
				}); ok {
					libraryKey, cacheLimit, err = resolver.resolveExtractTarget(ctx, extractOpt.LibraryKey, sourceLibKey, entryName)
					if err != nil {
						return nil, err
					}
				} else if libraryKey == "" {
					if sourceLibKey != "" {
						libraryKey = sourceLibKey
					} else {
						libraryKey = defaultLibKey
					}
				}
				if f.Size > uint64(limits.ArchiveMemberBytes) {
					return nil, fmt.Errorf("plugins: archive member exceeds size grant")
				}
				if f.Size > uint64(cacheLimit) {
					return nil, fmt.Errorf("%w: archive member (%d bytes) exceeds library cache quota (%d bytes)", ErrQuotaExceeded, f.Size, cacheLimit)
				}
				stream, e := archive.open(member)
				if e != nil {
					return nil, e
				}
				defer stream.Close()
				crc, md5Hash, sha1Hash := crc32.NewIEEE(), md5.New(), sha1.New()
				reader := &archiveExtractReader{
					ctx:         ctx,
					r:           stream,
					memberLimit: limits.ArchiveMemberBytes,
					cacheLimit:  cacheLimit,
					expected:    int64(f.Size),
				}
				input := sizedCacheInput{io.TeeReader(reader, io.MultiWriter(crc, md5Hash, sha1Hash)), int64(f.Size)}
				cachedRef, e := h.CachePut(ctx, libraryKey, entryName, input)
				if e != nil {
					return nil, e
				}
				value = ArchiveExtractResult{
					Ref:   cachedRef,
					Size:  reader.size,
					SHA1:  fmt.Sprintf("%x", sha1Hash.Sum(nil)),
					MD5:   fmt.Sprintf("%x", md5Hash.Sum(nil)),
					CRC32: fmt.Sprintf("%08x", crc.Sum32()),
				}
			}
		}
	}
	if err != nil {
		return nil, err
	}
	return json.Marshal(value)
}

func defaultDataLimits() RuntimeLimits {
	return RuntimeLimits{
		MemoryBytes:          32 << 20,
		ReadBytes:            MinDataReadBytes,
		FetchBytes:           MaxDataFetchBytes,
		ArchiveMemberBytes:   maxArchiveMemberBytes,
		ArchiveExpandedBytes: maxArchiveExpandedBytes,
		ArchiveMembers:       maxArchiveMembers,
		MaxItems:             DefaultMaxPluginItems,
		Deadline:             "12h",
		PoolSize:             wasm.DefaultPoolSize,
	}
}

const (
	// DefaultFetchManyConcurrency and MaxFetchManyConcurrency bound the
	// per-call parallelism of http.fetchMany (safe host default, no owner setting).
	DefaultFetchManyConcurrency = 8
	MaxFetchManyConcurrency     = 8
	// MaxFetchManyRequests caps the number of requests in one http.fetchMany call.
	MaxFetchManyRequests = 64
	// DefaultMaxFetchPerHost bounds concurrent outbound plugin HTTP fetches
	// (http.fetch and http.fetchMany) to any single origin (scheme://host:port)
	// across the manager so plugins cannot flood an upstream host.
	DefaultMaxFetchPerHost = 6
	// MaxFetchManyBytes caps the aggregate raw response body bytes buffered across
	// all items in one http.fetchMany call so a batch cannot exhaust host or guest
	// memory. Each individual response remains bounded by MaxFetchBytes as well.
	MaxFetchManyBytes = MaxFetchBytes
)

// fetchHostLimiter bounds in-flight HTTP fetch requests per normalized origin
// (scheme://host:port). Idle origin entries are dropped once their last holder
// or waiter leaves.
type fetchHostLimiter struct {
	limit int
	mu    sync.Mutex
	hosts map[string]*fetchHostGate
}

type fetchHostGate struct {
	sem  chan struct{}
	refs int
}

func newFetchHostLimiter(limit int) *fetchHostLimiter {
	if limit == 0 {
		limit = DefaultMaxFetchPerHost
	}
	return &fetchHostLimiter{limit: limit}
}

// Acquire claims one in-flight slot for rawURL's normalized origin, waiting
// until a slot is free or ctx ends. The returned release func is idempotent.
func (l *fetchHostLimiter) Acquire(ctx context.Context, rawURL string) (func(), error) {
	if l == nil || l.limit < 0 {
		return func() {}, nil
	}
	key := fetchHostKey(rawURL)
	if key == "" {
		return func() {}, nil
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	l.mu.Lock()
	if l.hosts == nil {
		l.hosts = make(map[string]*fetchHostGate)
	}
	g, ok := l.hosts[key]
	if !ok {
		g = &fetchHostGate{sem: make(chan struct{}, l.limit)}
		l.hosts[key] = g
	}
	g.refs++
	l.mu.Unlock()

	deref := func() {
		l.mu.Lock()
		g.refs--
		if g.refs == 0 && l.hosts[key] == g {
			delete(l.hosts, key)
		}
		l.mu.Unlock()
	}

	select {
	case g.sem <- struct{}{}:
		var once sync.Once
		return func() {
			once.Do(func() {
				<-g.sem
				deref()
			})
		}, nil
	case <-ctx.Done():
		deref()
		return nil, ctx.Err()
	}
}

func fetchHostKey(rawURL string) string {
	u, err := url.Parse(strings.TrimSpace(rawURL))
	if err != nil || u.Host == "" {
		return ""
	}
	scheme := strings.ToLower(u.Scheme)
	if scheme != "http" && scheme != "https" {
		return ""
	}
	host := strings.TrimSuffix(strings.ToLower(u.Hostname()), ".")
	if host == "" {
		return ""
	}
	port := u.Port()
	if port == "" {
		if scheme == "https" {
			port = "443"
		} else {
			port = "80"
		}
	}
	return scheme + "://" + net.JoinHostPort(host, port)
}

// LimitRangeTransport shares fetchToCache's per-origin budget with range streams.
func (m *Manager) LimitRangeTransport(base http.RoundTripper) http.RoundTripper {
	if base == nil {
		base = http.DefaultTransport
	}
	if m == nil || m.fetchHosts == nil {
		return base
	}
	return limitedRangeTransport{base: base, limiter: m.fetchHosts}
}

type limitedRangeTransport struct {
	base    http.RoundTripper
	limiter *fetchHostLimiter
}

func (t limitedRangeTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	release, err := t.limiter.Acquire(req.Context(), req.URL.String())
	if err != nil {
		return nil, err
	}
	resp, err := t.base.RoundTrip(req)
	if err != nil {
		release()
		return nil, err
	}
	resp.Body = &releaseOnCloseReadCloser{ReadCloser: resp.Body, release: release}
	return resp, nil
}

type releaseOnCloseReadCloser struct {
	io.ReadCloser
	once    sync.Once
	release func()
}

func (r *releaseOnCloseReadCloser) Close() error {
	err := r.ReadCloser.Close()
	r.once.Do(func() {
		if r.release != nil {
			r.release()
		}
	})
	return err
}

// fetchByteBudget tracks aggregate raw response body bytes reserved across
// concurrent workers in one http.fetchMany batch.
type fetchByteBudget struct {
	mu        sync.Mutex
	remaining int64
	limit     int64
}

func newFetchByteBudget(limit int64) *fetchByteBudget {
	return &fetchByteBudget{remaining: limit, limit: limit}
}

func (b *fetchByteBudget) reserve(n int64) bool {
	if b == nil || n <= 0 {
		return true
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	if n > b.remaining {
		return false
	}
	b.remaining -= n
	return true
}

func (b *fetchByteBudget) refund(n int64) {
	if b == nil || n <= 0 {
		return
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	b.remaining += n
	if b.remaining > b.limit {
		b.remaining = b.limit
	}
}

// readFetchBody reads up to perItemMax bytes from body while enforcing an
// optional shared batch byte budget. On overflow or read error, reserved batch
// memory is refunded while totalRead still reports the wire bytes consumed for
// egress accounting.
func readFetchBody(body io.Reader, perItemMax int64, budget *fetchByteBudget) (data []byte, totalRead int64, err error) {
	var out []byte
	var reserved int64
	buf := make([]byte, 32<<10)
	for {
		n, rerr := body.Read(buf)
		if n > 0 {
			totalRead += int64(n)
			if int64(len(out))+int64(n) > perItemMax {
				budget.refund(reserved)
				return nil, totalRead, fmt.Errorf("plugins: response larger than %d bytes", perItemMax)
			}
			if !budget.reserve(int64(n)) {
				budget.refund(reserved)
				return nil, totalRead, fmt.Errorf("plugins: fetchMany batch response larger than %d bytes", budget.limit)
			}
			reserved += int64(n)
			out = append(out, buf[:n]...)
		}
		if rerr != nil {
			if errors.Is(rerr, io.EOF) {
				return out, totalRead, nil
			}
			budget.refund(reserved)
			return nil, totalRead, rerr
		}
	}
}

// scheduleFetchOrder interleaves indices 0..len(reqs)-1 round-robin by
// normalized origin so requests to one saturated host do not head-of-line
// block requests to other origins in the same batch.
func scheduleFetchOrder(reqs []FetchRequest) []int {
	if len(reqs) <= 1 {
		out := make([]int, len(reqs))
		for i := range out {
			out[i] = i
		}
		return out
	}
	var keys []string
	buckets := make(map[string][]int)
	for i, req := range reqs {
		key := fetchHostKey(req.URL)
		if _, seen := buckets[key]; !seen {
			keys = append(keys, key)
		}
		buckets[key] = append(buckets[key], i)
	}
	order := make([]int, 0, len(reqs))
	for len(order) < len(reqs) {
		for _, k := range keys {
			q := buckets[k]
			if len(q) == 0 {
				continue
			}
			order = append(order, q[0])
			buckets[k] = q[1:]
		}
	}
	return order
}

func clampFetchManyConcurrency(requested, count int) int {
	c := requested
	if c <= 0 {
		c = DefaultFetchManyConcurrency
	}
	if c > MaxFetchManyConcurrency {
		c = MaxFetchManyConcurrency
	}
	if count > 0 && c > count {
		c = count
	}
	if c < 1 {
		c = 1
	}
	return c
}

func fetchManyErrorFrom(err error) *FetchManyError {
	mapped := mapHostError(err)
	if f, ok := mapped.(*wasm.Fault); ok {
		return &FetchManyError{Code: f.Code, Message: f.Message}
	}
	return &FetchManyError{Code: "host_error", Message: mapped.Error()}
}

func validateFetchManyArgs(reqs []FetchRequest, opts FetchManyOptions) error {
	if len(reqs) > MaxFetchManyRequests {
		return &ValidationError{Fields: []FieldError{{
			Field:   "requests",
			Message: fmt.Sprintf("http.fetchMany accepts at most %d requests per call", MaxFetchManyRequests),
		}}}
	}
	if opts.Concurrency < 0 {
		return &ValidationError{Fields: []FieldError{{
			Field:   "concurrency",
			Message: "concurrency must be a positive integer",
		}}}
	}
	return nil
}

// runFetchMany executes reqs concurrently up to opts.Concurrency (clamped to
// MaxFetchManyConcurrency), charging per-request governance units upfront,
// enforcing MaxFetchManyBytes across the batch, preserving input order, and
// stopping promptly when ctx is canceled or its deadline expires.
func runFetchMany(
	ctx context.Context,
	reqs []FetchRequest,
	opts FetchManyOptions,
	doOne func(ctx context.Context, req FetchRequest, budget *fetchByteBudget) (FetchResponse, error),
) ([]FetchManyResult, error) {
	if err := validateFetchManyArgs(reqs, opts); err != nil {
		return nil, err
	}
	if len(reqs) == 0 {
		return []FetchManyResult{}, nil
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if len(reqs) > 1 {
		if err := wasm.ChargeUnits(ctx, int64(len(reqs)-1)*wasm.FetchManyUnitsPerRequest); err != nil {
			return nil, err
		}
	}

	results := make([]FetchManyResult, len(reqs))
	budget := newFetchByteBudget(MaxFetchManyBytes)
	order := scheduleFetchOrder(reqs)
	jobs := make(chan int, len(order))
	for _, idx := range order {
		jobs <- idx
	}
	close(jobs)

	workers := clampFetchManyConcurrency(opts.Concurrency, len(reqs))
	var wg sync.WaitGroup
	for range workers {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for idx := range jobs {
				if ctx.Err() != nil {
					return
				}
				resp, err := doOne(ctx, reqs[idx], budget)
				if err != nil {
					if ctx.Err() != nil {
						return
					}
					results[idx] = FetchManyResult{Error: fetchManyErrorFrom(err)}
					continue
				}
				results[idx] = FetchManyResult{Response: resp}
			}
		}()
	}
	wg.Wait()
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	return results, nil
}

type fetchTrafficEntry struct {
	host  string
	bytes int64
}

func (h *host) noteBatchFetchTraffic(entries []fetchTrafficEntry) {
	if len(entries) == 0 {
		return
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	h.m.healthMu.Lock()
	defer h.m.healthMu.Unlock()
	if hh, err := h.m.store.health(ctx, h.plugin); err == nil {
		for _, e := range entries {
			if e.host != "" {
				hh.Observed[e.host]++
			}
			hh.EgressBytes += e.bytes
		}
		_ = h.m.store.putHealth(ctx, h.plugin, hh)
	}
}

func clampHostHTTPFetchTimeout(timeoutMS int64) time.Duration {
	if timeoutMS <= 0 {
		return defaultHostHTTPFetchTimeout
	}
	if timeoutMS >= maxHostHTTPFetchTimeout.Milliseconds() {
		return maxHostHTTPFetchTimeout
	}
	return time.Duration(timeoutMS) * time.Millisecond
}

func (h *host) fetchOne(
	ctx context.Context,
	req FetchRequest,
	budget *fetchByteBudget,
	onTraffic func(req FetchRequest, respBytes int64),
) (FetchResponse, error) {
	reqCtx, cancel := context.WithTimeout(ctx, clampHostHTTPFetchTimeout(req.TimeoutMS))
	defer cancel()
	resp, err := h.openFetchWithOptions(reqCtx, req, fetchOptions{applyHostLimit: true})
	if err != nil {
		return FetchResponse{}, err
	}
	hostName := ""
	if u, perr := url.Parse(req.URL); perr == nil && u != nil {
		hostName = u.Hostname()
	}
	defer resp.Body.Close() //nolint:errcheck
	body, totalRead, err := readFetchBody(resp.Body, MaxFetchBytes, budget)
	if err != nil {
		if totalRead > 0 && onTraffic != nil {
			onTraffic(req, totalRead)
		}
		if strings.HasPrefix(err.Error(), "plugins:") {
			return FetchResponse{}, err
		}
		return FetchResponse{}, fetchError(hostName, err)
	}
	if onTraffic != nil {
		onTraffic(req, int64(len(body)))
	}
	out := FetchResponse{Status: resp.StatusCode, Headers: map[string]string{}, Body: body}
	for k := range resp.Header {
		out.Headers[k] = resp.Header.Get(k)
	}
	return out, nil
}

// HTTPFetchMany runs up to MaxFetchManyRequests outbound HTTP calls concurrently
// on the host (bounded to MaxFetchManyConcurrency in-flight calls per batch and
// DefaultMaxFetchPerHost concurrent fetches per origin across the manager).
// Each request applies the plugin's live network grants, local/operator host
// checks, redirect credential policy (#688), per-request timeout, and egress
// accounting. Results are returned in input order, each carrying either a
// response or a per-item error. Canceling ctx aborts in-flight requests and
// returns ctx.Err().
func (h *host) HTTPFetchMany(ctx context.Context, reqs []FetchRequest, opts FetchManyOptions) ([]FetchManyResult, error) {
	var trafficMu sync.Mutex
	var traffic []fetchTrafficEntry
	recordTraffic := func(req FetchRequest, respBytes int64) {
		hostName := ""
		if u, err := url.Parse(req.URL); err == nil && u != nil {
			hostName = u.Hostname()
		}
		trafficMu.Lock()
		traffic = append(traffic, fetchTrafficEntry{
			host:  hostName,
			bytes: respBytes + int64(len(req.Body)),
		})
		trafficMu.Unlock()
	}
	results, err := runFetchMany(ctx, reqs, opts, func(itemCtx context.Context, req FetchRequest, budget *fetchByteBudget) (FetchResponse, error) {
		return h.fetchOne(itemCtx, req, budget, recordTraffic)
	})
	trafficMu.Lock()
	snapshot := traffic
	trafficMu.Unlock()
	h.noteBatchFetchTraffic(snapshot)
	return results, err
}

// FetchManyResultWire encodes FetchManyResult entries for the hosted JSON wire
// shape: successful items match FetchResult ({status, headers, body,
// bodyBase64?}) and failed items carry {error: {code, message}}.
func FetchManyResultWire(results []FetchManyResult) []map[string]any {
	out := make([]map[string]any, len(results))
	for i, r := range results {
		if r.Error != nil {
			out[i] = map[string]any{"error": r.Error}
			continue
		}
		out[i] = FetchResult(r.Response)
	}
	return out
}

func (w wireFetchRequest) toFetchRequest() (FetchRequest, *wasm.Fault) {
	method := w.Method
	if method == "" {
		method = "GET"
	}
	body := []byte(w.Body)
	if w.BodyBase64 != "" {
		decoded, err := base64.StdEncoding.DecodeString(w.BodyBase64)
		if err != nil {
			return FetchRequest{}, &wasm.Fault{Code: "bad_arguments", Message: "bodyBase64 is not valid base64"}
		}
		body = decoded
	}
	return FetchRequest{
		Method:                method,
		URL:                   w.URL,
		Headers:               w.Headers,
		Body:                  body,
		TimeoutMS:             w.TimeoutMS,
		KeepHeadersOnRedirect: w.KeepHeadersOnRedirect,
	}, nil
}

// ParseFetchManyArgs decodes the positional JSON arguments [requests, options?]
// for the http.fetchMany host service.
func ParseFetchManyArgs(args []json.RawMessage) ([]FetchRequest, FetchManyOptions, *wasm.Fault) {
	var reqs []FetchRequest
	if len(args) > 0 && len(args[0]) > 0 && strings.TrimSpace(string(args[0])) != "null" {
		var wire []wireFetchRequest
		if err := json.Unmarshal(args[0], &wire); err != nil {
			return nil, FetchManyOptions{}, &wasm.Fault{Code: "bad_arguments", Message: "http.fetchMany takes (requests[], options?)"}
		}
		if len(wire) > MaxFetchManyRequests {
			return nil, FetchManyOptions{}, &wasm.Fault{
				Code:    string(wasm.StatusInvalidInput),
				Message: fmt.Sprintf("http.fetchMany accepts at most %d requests per call", MaxFetchManyRequests),
			}
		}
		reqs = make([]FetchRequest, len(wire))
		for i, item := range wire {
			req, fault := item.toFetchRequest()
			if fault != nil {
				return nil, FetchManyOptions{}, fault
			}
			reqs[i] = req
		}
	}
	var opts FetchManyOptions
	if len(args) > 1 && len(args[1]) > 0 && strings.TrimSpace(string(args[1])) != "null" {
		var rawOpts struct {
			Concurrency *float64 `json:"concurrency"`
		}
		if err := json.Unmarshal(args[1], &rawOpts); err != nil {
			return nil, FetchManyOptions{}, &wasm.Fault{Code: "bad_arguments", Message: "http.fetchMany options must be {concurrency?}"}
		}
		if rawOpts.Concurrency != nil {
			c := *rawOpts.Concurrency
			if math.IsNaN(c) || math.IsInf(c, 0) || math.Trunc(c) != c || c < 0 || c > math.MaxInt32 {
				return nil, FetchManyOptions{}, &wasm.Fault{Code: string(wasm.StatusInvalidInput), Message: "http.fetchMany concurrency must be a non-negative integer"}
			}
			opts.Concurrency = int(c)
		}
	}
	return reqs, opts, nil
}

const (
	// DefaultEventPublishPerMin bounds custom events published per plugin per minute.
	DefaultEventPublishPerMin = 30
	// MaxPublishedEventPayloadBytes caps the JSON payload size of a plugin-published event.
	MaxPublishedEventPayloadBytes = 64 * 1024
	// DefaultPluginFlowActionTimeout is applied when a flow action omits timeout.
	DefaultPluginFlowActionTimeout = 30 * time.Second
	// MaxPluginFlowActionTimeout is the hard ceiling for any plugin flow action.
	MaxPluginFlowActionTimeout = 60 * time.Second
	// MaxPluginFlowActionResponseBytes caps a plugin flow action JSON response body.
	MaxPluginFlowActionResponseBytes = 64 * 1024
	// MaxPluginPublishedEvents caps how many published event schemas a plugin may declare.
	MaxPluginPublishedEvents = 64
	// MaxPluginFlowActions caps how many flow actions a plugin may declare.
	MaxPluginFlowActions = 64
	// MaxEventFields caps how many fields an event schema or action output may declare.
	MaxEventFields = 64
	// MaxFlowActionParams caps how many parameters a flow action may declare.
	MaxFlowActionParams = 64
	// HeaderIdempotencyKey carries the Flow step idempotency key on plugin action calls.
	HeaderIdempotencyKey = "X-Ether-Idempotency-Key"
)

type flowActionOrigin struct {
	depth       int
	originRunID string
}

func withFlowActionOrigin(ctx context.Context, depth int, originRunID string) context.Context {
	return context.WithValue(ctx, flowActionOriginKey{}, flowActionOrigin{
		depth:       depth,
		originRunID: originRunID,
	})
}

func flowActionOriginFromContext(ctx context.Context) (flowActionOrigin, bool) {
	if ctx == nil {
		return flowActionOrigin{}, false
	}
	v, ok := ctx.Value(flowActionOriginKey{}).(flowActionOrigin)
	return v, ok
}

func isSafePluginRoute(p string) bool {
	if p == "" || len(p) > 256 {
		return false
	}
	if !strings.HasPrefix(p, "/") || strings.HasPrefix(p, "//") {
		return false
	}
	if strings.ContainsAny(p, "\r\n\\") || strings.Contains(p, "://") {
		return false
	}
	for _, seg := range strings.Split(p, "/") {
		if seg == ".." {
			return false
		}
	}
	return true
}

// SetFlowsBackends wires the Events bus, Events schema registry, and Flows
// action registry after Manager construction and immediately registers all
// currently installed enabled plugins' events and actions.
func (m *Manager) SetFlowsBackends(bus *events.Bus, reg *events.Registry, actions flows.ActionRegistry) {
	m.mu.Lock()
	m.deps.EventBus = bus
	m.deps.EventRegistry = reg
	m.deps.FlowActions = actions
	m.mu.Unlock()

	if reg == nil && actions == nil {
		return
	}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if recs, err := m.store.list(ctx); err == nil {
		for _, r := range recs {
			m.syncFlowsPlugin(ctx, r)
		}
	}
}

func (m *Manager) flowsEventBus() *events.Bus {
	m.mu.Lock()
	defer m.mu.Unlock()
	return m.deps.EventBus
}

func (m *Manager) flowsRegistries() (*events.Registry, flows.ActionRegistry) {
	m.mu.Lock()
	defer m.mu.Unlock()
	return m.deps.EventRegistry, m.deps.FlowActions
}

func (m *Manager) resolvePluginCopy(ctx context.Context, pluginID, raw, fallback string) string {
	if strings.HasPrefix(raw, "$t:") {
		if resolved, ok := m.ResolveText(ctx, pluginID, strings.TrimPrefix(raw, "$t:"), "en"); ok && strings.TrimSpace(resolved) != "" {
			return resolved
		}
		if fallback != "" {
			return fallback
		}
		return strings.TrimPrefix(raw, "$t:")
	}
	if strings.TrimSpace(raw) == "" {
		return fallback
	}
	return raw
}

func defaultCopyResolver(raw, fallback string) string {
	if strings.TrimSpace(raw) == "" {
		return fallback
	}
	return raw
}

func convertEventEnums(opts []EventEnumOption, resolve func(raw, fallback string) string) []events.EnumOption {
	if len(opts) == 0 {
		return nil
	}
	if resolve == nil {
		resolve = defaultCopyResolver
	}
	out := make([]events.EnumOption, len(opts))
	for i, opt := range opts {
		lbl := opt.Label
		if lbl != "" {
			lbl = resolve(lbl, opt.Value)
		}
		out[i] = events.EnumOption{
			Value: opt.Value,
			Label: lbl,
		}
	}
	return out
}

func convertEventFields(fields []EventFieldMeta, resolve func(raw, fallback string) string) []events.FieldSchema {
	if len(fields) == 0 {
		return nil
	}
	if resolve == nil {
		resolve = defaultCopyResolver
	}
	out := make([]events.FieldSchema, len(fields))
	for i, f := range fields {
		out[i] = events.FieldSchema{
			Name:        f.Name,
			Type:        events.FieldType(f.Type),
			Label:       resolve(f.Label, f.Name),
			Description: resolve(f.Description, ""),
			Unit:        f.Unit,
			Enum:        convertEventEnums(f.Enum, resolve),
			PII:         f.PII,
			Secret:      f.Secret,
			Filterable:  f.Filterable,
			Example:     f.Example,
		}
	}
	return out
}

// BuildPluginEventSchemas builds the events.EventSchema entries contributed by
// man for pluginID. resolve may be nil to keep literal labels.
func BuildPluginEventSchemas(pluginID string, man Manifest, resolve func(raw, fallback string) string) []events.EventSchema {
	man.Ether = man.EffectiveEther()
	if man.Ether == nil || !man.HasCapability(CapEvents) || man.Ether.Contributes.Events == nil {
		return nil
	}
	decls := man.Ether.Contributes.Events.Publish
	if len(decls) == 0 {
		return nil
	}
	if resolve == nil {
		resolve = func(raw, fallback string) string {
			if strings.TrimSpace(raw) == "" {
				return fallback
			}
			return raw
		}
	}
	out := make([]events.EventSchema, 0, len(decls))
	for _, pe := range decls {
		ver := pe.Version
		if ver <= 0 {
			ver = 1
		}
		out = append(out, events.EventSchema{
			Type:        events.PluginEventType(pluginID, pe.Key),
			Version:     ver,
			Domain:      events.PluginPrefix + pluginID,
			Label:       resolve(pe.Label, pe.Key),
			Description: resolve(pe.Description, ""),
			Owner:       pluginID,
			Fields:      convertEventFields(pe.Fields, resolve),
		})
	}
	return out
}

// BuildPluginActionSpec builds the flows.ActionSpec for one manifest-declared
// plugin flow action.
func BuildPluginActionSpec(pluginID, group string, act FlowActionMeta, resolve func(raw, fallback string) string) flows.ActionSpec {
	if resolve == nil {
		resolve = func(raw, fallback string) string {
			if strings.TrimSpace(raw) == "" {
				return fallback
			}
			return raw
		}
	}
	params := make([]flows.ParamSchema, len(act.Params))
	for i, p := range act.Params {
		params[i] = flows.ParamSchema{
			Key:         p.Key,
			Type:        events.FieldType(p.Type),
			Label:       resolve(p.Label, p.Key),
			Description: resolve(p.Description, ""),
			Required:    p.Required,
			Secret:      p.Secret,
			Template:    p.Template,
			Default:     p.Default,
			Enum:        convertEventEnums(p.Enum, resolve),
			Unit:        p.Unit,
			Picker:      p.Picker,
		}
	}
	sideEffect := true
	if act.SideEffect != nil {
		sideEffect = *act.SideEffect
	}
	if group == "" {
		group = pluginID
	}
	return flows.ActionSpec{
		Type:        flows.PluginActionType(pluginID, act.Key),
		Owner:       pluginID,
		Group:       group,
		Label:       resolve(act.Label, act.Key),
		Description: resolve(act.Description, ""),
		Icon:        act.Icon,
		Idempotent:  act.Idempotent,
		SideEffect:  sideEffect,
		Params:      params,
		Outputs:     convertEventFields(act.Outputs, resolve),
	}
}

// ValidatePublishEventCall verifies capability, declared key, payload size,
// and payload schema against man. Exported for conformance kit and Studio sandboxes.
func ValidatePublishEventCall(man Manifest, key string, payload json.RawMessage) (PublishedEventMeta, events.EventSchema, error) {
	man.Ether = man.EffectiveEther()
	if man.Ether == nil || !man.HasCapability(CapEvents) {
		return PublishedEventMeta{}, events.EventSchema{}, fmt.Errorf("%w: %s", ErrPermissionDenied, CapEvents)
	}
	if !pluginEventKeyRe.MatchString(key) {
		return PublishedEventMeta{}, events.EventSchema{}, &ValidationError{Fields: []FieldError{{
			Field:   "key",
			Message: "must match ^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*){0,2}$",
		}}}
	}
	var decl *PublishedEventMeta
	if man.Ether.Contributes.Events != nil {
		for i := range man.Ether.Contributes.Events.Publish {
			if man.Ether.Contributes.Events.Publish[i].Key == key {
				decl = &man.Ether.Contributes.Events.Publish[i]
				break
			}
		}
	}
	if decl == nil {
		return PublishedEventMeta{}, events.EventSchema{}, &ValidationError{Fields: []FieldError{{
			Field:   "key",
			Message: fmt.Sprintf("event %q is not declared in ether.contributes.events.publish", key),
		}}}
	}
	trimmed := bytes.TrimSpace(payload)
	if len(trimmed) == 0 {
		trimmed = json.RawMessage(`{}`)
	}
	if len(trimmed) > MaxPublishedEventPayloadBytes {
		return PublishedEventMeta{}, events.EventSchema{}, &ValidationError{Fields: []FieldError{{
			Field:   "payload",
			Message: fmt.Sprintf("exceeds %d byte limit", MaxPublishedEventPayloadBytes),
		}}}
	}
	pid := man.ID
	if !idRe.MatchString(pid) {
		pid = "dev.example.plugin"
	}
	ver := decl.Version
	if ver <= 0 {
		ver = 1
	}
	schema := events.EventSchema{
		Type:        events.PluginEventType(pid, decl.Key),
		Version:     ver,
		Domain:      events.PluginPrefix + pid,
		Label:       decl.Label,
		Description: decl.Description,
		Owner:       pid,
		Fields:      convertEventFields(decl.Fields, nil),
	}
	if strings.TrimSpace(schema.Label) == "" {
		schema.Label = decl.Key
	}
	reg := events.NewRegistry()
	if err := reg.Register(schema); err != nil {
		return PublishedEventMeta{}, events.EventSchema{}, &ValidationError{Fields: []FieldError{{
			Field:   "schema",
			Message: err.Error(),
		}}}
	}
	if err := reg.ValidatePayload(schema.Type, trimmed); err != nil {
		return PublishedEventMeta{}, events.EventSchema{}, &ValidationError{Fields: []FieldError{{
			Field:   "payload",
			Message: err.Error(),
		}}}
	}
	return *decl, schema, nil
}

// syncFlowsPlugin atomically replaces or removes a plugin's published event
// schemas and flow action handlers in the wired registries.
func (m *Manager) syncFlowsPlugin(ctx context.Context, r Record) {
	reg, actions := m.flowsRegistries()
	if reg == nil && actions == nil {
		return
	}
	man := r.Manifest
	man.Ether = man.EffectiveEther()
	var g Grants
	if m.store != nil {
		if loaded, err := m.store.grants(ctx, r.ID); err == nil {
			g = loaded
		}
	}
	resolve := func(raw, fallback string) string {
		return m.resolvePluginCopy(ctx, r.ID, raw, fallback)
	}

	if reg != nil {
		if !r.Enabled || man.Ether == nil || !man.HasCapability(CapEvents) || g.revoked(string(CapEvents)) {
			reg.RemovePlugin(r.ID)
		} else {
			schemas := BuildPluginEventSchemas(r.ID, man, resolve)
			if len(schemas) == 0 {
				reg.RemovePlugin(r.ID)
			} else if err := reg.ReplacePlugin(r.ID, schemas); err != nil {
				m.log.Warn("plugins: event schema sync", "plugin", r.ID, "err", err)
			}
		}
	}

	if actions != nil {
		if !r.Enabled || man.Ether == nil || !man.HasCapability(CapFlowActions) || g.revoked(string(CapFlowActions)) {
			actions.RemovePlugin(r.ID)
		} else if len(man.Ether.Contributes.FlowActions) == 0 {
			actions.RemovePlugin(r.ID)
		} else {
			handlers := make([]flows.ActionHandler, 0, len(man.Ether.Contributes.FlowActions))
			for _, act := range man.Ether.Contributes.FlowActions {
				handlers = append(handlers, m.pluginFlowActionHandler(r, act, resolve))
			}
			if err := actions.ReplacePlugin(r.ID, handlers); err != nil {
				m.log.Warn("plugins: flow action sync", "plugin", r.ID, "err", err)
			}
		}
	}
}

func (m *Manager) pluginFlowActionHandler(r Record, act FlowActionMeta, resolve func(raw, fallback string) string) flows.ActionHandler {
	pluginID := r.ID
	spec := BuildPluginActionSpec(pluginID, r.Name, act, resolve)
	timeout := DefaultPluginFlowActionTimeout
	if act.Timeout != "" {
		if d, err := time.ParseDuration(act.Timeout); err == nil && d > 0 {
			timeout = d
		}
	}
	if timeout > MaxPluginFlowActionTimeout {
		timeout = MaxPluginFlowActionTimeout
	}
	secretOutputs := map[string]bool{}
	for _, out := range act.Outputs {
		if out.Secret {
			secretOutputs[out.Name] = true
		}
	}

	return flows.ActionFunc{
		ActionSpec: spec,
		Run: func(ctx context.Context, actx flows.ActionContext, params map[string]any) (flows.ActionResult, error) {
			live, err := m.store.record(ctx, pluginID)
			if err != nil {
				return flows.ActionResult{}, err
			}
			if !live.Enabled {
				return flows.ActionResult{}, ErrDisabled
			}
			man := live.Manifest
			man.Ether = man.EffectiveEther()
			g, err := m.store.grants(ctx, pluginID)
			if err != nil {
				return flows.ActionResult{}, err
			}
			if g.revoked(string(CapFlowActions)) || man.Ether == nil || !man.HasCapability(CapFlowActions) {
				(&host{m: m, plugin: pluginID}).noteDenied(string(CapFlowActions))
				return flows.ActionResult{}, fmt.Errorf("%w: %s", ErrPermissionDenied, CapFlowActions)
			}

			route := ""
			for _, declared := range man.Ether.Contributes.FlowActions {
				if declared.Key == act.Key {
					route = declared.Route
					break
				}
			}
			if route == "" {
				return flows.ActionResult{}, fmt.Errorf("%w: flow action %q is no longer declared", ErrNotFound, act.Key)
			}

			if params == nil {
				params = map[string]any{}
			}
			reqPayload := map[string]any{
				"flowId":         actx.FlowID,
				"runId":          actx.RunID,
				"nodeId":         actx.NodeID,
				"idempotencyKey": actx.IdempotencyKey,
				"dryRun":         actx.DryRun,
				"params":         params,
			}

			if live.Shadow {
				inv, _ := json.Marshal(reqPayload)
				invRedacted := m.store.redactKnown(ctx, pluginID, redactJSON(inv))
				_, _ = m.store.journal(ctx, JournalEntry{
					Plugin:  pluginID,
					Op:      "flow_action",
					Detail:  act.Key,
					Shadow:  true,
					Inverse: json.RawMessage(invRedacted),
				})
				return flows.ActionResult{
					Output: map[string]any{
						"shadow": true,
						"action": spec.Type,
					},
				}, nil
			}

			body, err := json.Marshal(reqPayload)
			if err != nil {
				return flows.ActionResult{}, fmt.Errorf("plugins: marshal flow action request: %w", err)
			}
			headers := map[string]string{}
			if actx.IdempotencyKey != "" {
				headers[HeaderIdempotencyKey] = actx.IdempotencyKey
			}

			callCtx, cancel := context.WithTimeout(withFlowActionOrigin(ctx, actx.FlowDepth+1, actx.RunID), timeout)
			defer cancel()

			resp, err := m.Call(callCtx, pluginID, Request{
				Method:  http.MethodPost,
				Path:    route,
				Headers: headers,
				Body:    body,
			})
			if err != nil {
				return flows.ActionResult{}, err
			}
			if resp.Status < 200 || resp.Status >= 300 {
				return flows.ActionResult{}, m.formatActionError(ctx, pluginID, act.Key, resp)
			}
			if len(resp.Body) > MaxPluginFlowActionResponseBytes {
				return flows.ActionResult{}, fmt.Errorf("plugins: flow action %s response exceeds %d byte limit", spec.Type, MaxPluginFlowActionResponseBytes)
			}
			return m.decodeActionResult(ctx, pluginID, resp.Body, secretOutputs)
		},
	}
}

func (m *Manager) formatActionError(ctx context.Context, pluginID, actionKey string, resp Response) error {
	msg := ""
	raw := unwrapJSONStringBody(resp.Body)
	if len(raw) > 0 {
		var env struct {
			Error struct {
				Code    string `json:"code"`
				Message string `json:"message"`
			} `json:"error"`
			Message string `json:"message"`
		}
		if json.Unmarshal(raw, &env) == nil {
			switch {
			case env.Error.Message != "":
				msg = env.Error.Message
			case env.Message != "":
				msg = env.Message
			}
		}
	}
	if msg != "" {
		msg = logredact.String(m.store.redactKnown(ctx, pluginID, msg))
		return fmt.Errorf("plugins: flow action %s/%s failed with status %d: %s", pluginID, actionKey, resp.Status, truncate(msg, 240))
	}
	return fmt.Errorf("plugins: flow action %s/%s failed with status %d", pluginID, actionKey, resp.Status)
}

func (m *Manager) decodeActionResult(ctx context.Context, pluginID string, raw json.RawMessage, secretOutputs map[string]bool) (flows.ActionResult, error) {
	body := unwrapJSONStringBody(raw)
	if len(body) == 0 {
		return flows.ActionResult{Output: map[string]any{}}, nil
	}
	var doc map[string]any
	if err := json.Unmarshal(body, &doc); err != nil {
		return flows.ActionResult{}, fmt.Errorf("plugins: flow action returned invalid JSON object: %w", err)
	}
	if doc == nil {
		return flows.ActionResult{Output: map[string]any{}}, nil
	}

	var res flows.ActionResult
	if branch, ok := doc["branch"].(string); ok {
		res.Branch = branch
	}
	if inner, ok := doc["output"].(map[string]any); ok {
		res.Output = inner
	} else {
		res.Output = doc
	}
	if res.Output == nil {
		res.Output = map[string]any{}
	}

	encoded, err := json.Marshal(res.Output)
	if err != nil {
		return flows.ActionResult{}, fmt.Errorf("plugins: flow action output could not be encoded: %w", err)
	}
	clean := m.store.redactKnown(ctx, pluginID, string(encoded))
	if err := json.Unmarshal([]byte(clean), &res.Output); err != nil {
		return flows.ActionResult{}, fmt.Errorf("plugins: flow action output could not be safely decoded: %w", err)
	}
	redactValue(res.Output)
	for field := range secretOutputs {
		maskNestedField(res.Output, field)
	}
	return res, nil
}

func unwrapJSONStringBody(raw json.RawMessage) []byte {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || bytes.Equal(trimmed, []byte("null")) {
		return nil
	}
	if trimmed[0] == '"' {
		var s string
		if json.Unmarshal(trimmed, &s) == nil {
			return bytes.TrimSpace([]byte(s))
		}
	}
	return trimmed
}

func maskNestedField(doc map[string]any, path string) {
	if doc == nil || path == "" {
		return
	}
	parts := strings.Split(path, ".")
	cur := doc
	for i := 0; i < len(parts)-1; i++ {
		next, ok := cur[parts[i]].(map[string]any)
		if !ok {
			return
		}
		cur = next
	}
	last := parts[len(parts)-1]
	if _, exists := cur[last]; exists {
		cur[last] = events.RedactedValue
	}
}

// PublishEvent emits a declared plugin event onto Ether's event bus.
func (h *host) PublishEvent(ctx context.Context, key string, payload json.RawMessage, corr events.Correlation) error {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return err
	}
	r, g, err := h.record(ctx)
	if err != nil {
		return err
	}
	man := r.Manifest
	man.Ether = man.EffectiveEther()
	if g.revoked(string(CapEvents)) || man.Ether == nil || !man.HasCapability(CapEvents) {
		h.noteDenied(string(CapEvents))
		return fmt.Errorf("%w: %s", ErrPermissionDenied, CapEvents)
	}

	_, schema, err := ValidatePublishEventCall(man, key, payload)
	if err != nil {
		if errors.Is(err, ErrPermissionDenied) {
			h.noteDenied(string(CapEvents))
		}
		return err
	}

	trimmed := bytes.TrimSpace(payload)
	if len(trimmed) == 0 {
		trimmed = json.RawMessage(`{}`)
	}

	h.m.mu.Lock()
	limit := h.m.eventPublishLimit
	h.m.mu.Unlock()
	if limit <= 0 {
		limit = DefaultEventPublishPerMin
	}
	if !h.m.rateOK(h.m.eventPublishTimes, h.plugin, limit, time.Minute) {
		return fmt.Errorf("%w: event publishing is limited to %d per minute", ErrRateLimited, limit)
	}

	if corr.PluginID == "" {
		corr.PluginID = h.plugin
	}

	if r.Shadow {
		inv, _ := json.Marshal(map[string]any{
			"key":         key,
			"type":        schema.Type,
			"payload":     json.RawMessage(trimmed),
			"correlation": corr,
		})
		invRedacted := h.m.store.redactKnown(ctx, h.plugin, redactJSON(inv))
		_, _ = h.m.store.journal(ctx, JournalEntry{
			Plugin:  h.plugin,
			Op:      "events.publish",
			Detail:  key,
			Shadow:  true,
			Inverse: json.RawMessage(invRedacted),
		})
		return nil
	}

	bus := h.m.flowsEventBus()
	if bus == nil {
		return ErrUnavailable
	}

	var meta events.EnvelopeMeta
	if origin, ok := flowActionOriginFromContext(ctx); ok {
		meta.FlowDepth = origin.depth
		meta.OriginRunID = origin.originRunID
	}

	env := events.Envelope{
		ID:          events.NewID(),
		Type:        events.PluginEventType(h.plugin, key),
		Version:     schema.Version,
		OccurredAt:  h.m.now().UTC(),
		Source:      events.PluginPrefix + h.plugin,
		Correlation: corr,
		Meta:        meta,
		Payload:     append(json.RawMessage(nil), trimmed...),
	}
	bus.Publish(env)
	return nil
}

// KindUpsertResult is what one kinds.upsert batch did (#646): Accepted
// items were taken, of which Added were new, Updated rewrote a stored
// item, and Unchanged matched the stored item and were skipped.
type KindUpsertResult struct {
	Accepted  int
	Added     int
	Updated   int
	Unchanged int
}

// KindUpsertUndo is the upsert result plus the exact change set committed for
// the undo journal (#766): AddedIDs were newly inserted, UpdatedIDs had a
// different content hash from the stored row, and Previous carries pre-write
// copies of UpdatedIDs only when requested (omitted for unchanged items and for
// kinds declaring sync.undo: "ids").
type KindUpsertUndo struct {
	Result     KindUpsertResult
	AddedIDs   []string
	UpdatedIDs []string
	Previous   []core.KindItem
}

// KindBackends are the Ether services the kind host calls end in: the
// plugin-item store, the source resolver and the blob cache. Any field
// may be nil, in which case the matching host call returns
// ErrUnavailable. App wiring fills them (pluginitems, the indexer and
// debrid services, blobcache); the plugin id is always the caller's,
// so a plugin can only ever reach its own kinds and cache.
type KindBackends struct {
	KindUpsert func(ctx context.Context, pluginID, kindKey string, items []core.KindItem) (accepted int, err error)
	// KindUpsertStats, when set, is preferred over KindUpsert and its
	// counts ride the host reply.
	KindUpsertStats func(ctx context.Context, pluginID, kindKey string, items []core.KindItem) (KindUpsertResult, error)
	// KindUpsertUndo, when set, is preferred over KindUpsertStats and
	// KindUpsert: it reports the committed added/updated IDs from the store's
	// content-hash check and reads previous copies only for modified items when
	// snapshotPrevious is true (#766).
	KindUpsertUndo func(ctx context.Context, pluginID, kindKey string, items []core.KindItem, snapshotPrevious bool) (KindUpsertUndo, error)
	KindDelete     func(ctx context.Context, pluginID, kindKey string, externalIDs []string) error
	KindItems      func(ctx context.Context, pluginID, kindKey, cursor string, limit int) (core.KindPage, error)
	KindItemsByID  func(ctx context.Context, pluginID, kindKey string, externalIDs []string) ([]core.KindItem, error)
	KindItemCount  func(ctx context.Context, pluginID string) (int, error)
	// KindVisible and KindBrowse evaluate a plugin library's Rules and viewer
	// access policy for the requesting frontend-adapter viewer (#615).
	KindVisible func(ctx context.Context, pluginID string, viewerID int64, kindKey string, ids []string) ([]string, error)
	KindBrowse  func(ctx context.Context, pluginID string, viewerID int64, kindKey string, q core.KindBrowseRequest) (core.KindPage, error)
	// KindExpand and KindLiveSearch open a container and search for a
	// frontend-adapter viewer the way an Ether app does (kinds.expand /
	// kinds.search): Ether fetches from the plugin and stores the items.
	KindExpand     func(ctx context.Context, pluginID string, viewerID int64, kindKey, parentID string) (pending bool, err error)
	KindLiveSearch func(ctx context.Context, pluginID string, viewerID int64, kindKey, query string, limit int) (found int, err error)
	ResolveSources func(ctx context.Context, pluginID string, q core.SourceQuery) ([]core.SourceCandidate, error)
	// ResolveSourcesResult, when set, is preferred over ResolveSources and
	// carries per-indexer search status alongside candidates (#733).
	ResolveSourcesResult func(ctx context.Context, pluginID string, q core.SourceQuery) (core.SourceResolveResult, error)

	NormalizeStoredReleaseLinks func(context.Context, []byte) ([]byte, error)

	// PeekUsenetCheck returns a cached shared Usenet verdict by keyless NZB URL
	// before admitting a background check against the plugin's daily allowance.
	PeekUsenetCheck func(q core.SourceQuery) (core.SourceCandidate, bool)
	// AdmitBackgroundUsenetCheck reserves one background usenet_check candidate
	// check against the plugin's daily allowance in availability_budget.
	AdmitBackgroundUsenetCheck func(ctx context.Context, pluginID string) (outCtx context.Context, refund func(), resetAt time.Time, err error)
	CacheLimit                 func(pluginID, libraryKey string) int64
	CachePut                   func(ctx context.Context, pluginID, libraryKey, name string, r io.Reader) (blobRef string, err error)
	CacheLookup                func(pluginID, libraryKey, key string) (blobRef string, ok bool)
	CacheOpen                  func(ctx context.Context, pluginID, blobRef string) (io.ReadSeekCloser, error)
	CacheOpenForStat           func(ctx context.Context, pluginID, blobRef string) (io.ReadSeekCloser, error)
	CacheDelete                func(ctx context.Context, pluginID, blobRef string) error
	CachePartial               func(ctx context.Context, pluginID, libraryKey, key string) (*blobcache.Partial, error)
	// StreamURL mints a scoped stream ticket for one of the plugin's own
	// kind items for one viewer and returns the Ether stream URL (spec
	// §6.5). The backend re-checks item ownership and library visibility.
	StreamURL        func(ctx context.Context, pluginID string, viewerID int64, itemRef string) (string, error)
	StreamPartURL    func(ctx context.Context, pluginID string, viewerID int64, itemRef string, partIndex *int) (string, error)
	StreamURLOptions func(ctx context.Context, pluginID string, viewerID int64, itemRef string, opts StreamURLOptions) (string, error)
	// MediaProbe reads container metadata for a PlayableSource (#712).
	MediaProbe func(ctx context.Context, pluginID string, src core.PlayableSource) (core.MediaProbeResult, error)
}

// Per-call caps for kind host services (spec §3.3 sizes, host side).
const (
	MaxKindUpsertItems       = 1000
	MaxKindVisibleIDs        = 500
	MaxKindHintsBytes        = 16 << 10
	MaxKindArtRoles          = 16
	MaxSourceIndexerFilters  = 256
	MaxKindBrowseFacetValues = 256
	MaxKindBrowseAnyGroups   = 32
	// HeaderAdapterViewerToken carries a host-minted, request-scoped token on
	// frontend adapter calls so remote plugins can prove the authenticated
	// viewer on viewer-scoped host callbacks without supplying viewer IDs.
	HeaderAdapterViewerToken = "X-Ether-Viewer-Token"
	// HeaderAdapterOrigin carries the client-visible origin
	// ("scheme://host[:port][/prefix]") derived by Ether on an authenticated
	// frontend adapter request (#772).
	HeaderAdapterOrigin = "X-Ether-Origin"
)

// ValidExternalID reports whether id is a legal plugin external id
// (spec §2.2: no ':' or '/').
func ValidExternalID(id string) bool { return externalIDRe.MatchString(id) }

// CheckKindItem validates one item envelope against its kind
// declaration: identity, level, the string caps and the hints shape.
// Field-value typing against KindField is the item store's deeper
// check (spec §3.3); this one is shared by the host and the kit so a
// plugin is told the same thing everywhere. It returns a plain
// reason, or "" when the item passes.
// MaxKindItemMembers bounds one list item's members.
const MaxKindItemMembers = 500

func CheckKindItem(decl MediaKindMeta, it core.KindItem) string {
	switch {
	case !ValidExternalID(it.ID):
		return "id must start with a letter or digit and use letters, digits, dot, dash, underscore or tilde, at most 128 characters"
	case it.ParentID != "" && !ValidExternalID(it.ParentID):
		return "parentId must be a valid external id"
	case strings.TrimSpace(it.Title) == "":
		return "title is required"
	case utf8.RuneCountInString(it.Title) > 500:
		return "title is longer than 500 characters"
	case utf8.RuneCountInString(it.Summary) > 20000:
		return "summary is longer than 20000 characters"
	case len(it.Art) > MaxKindArtRoles:
		return "art lists more than 16 roles"
	case len(it.Hints) > MaxKindHintsBytes:
		return "hints are larger than 16 KiB"
	}
	lv, at, ok := decl.Level(it.Level)
	if !ok {
		return "level " + it.Level + " is not declared for this kind"
	}
	if at == 0 && it.ParentID != "" {
		return "a root-level item cannot name a parent"
	}
	if lv.Members && it.ParentID != "" {
		return "a list item (" + it.Level + ") cannot name a parent"
	}
	if at > 0 && it.ParentID == "" && !lv.Members {
		return "a " + it.Level + " item needs a parentId"
	}
	if len(it.Members) > 0 && !lv.Members {
		return "only a list level (members: true) carries members"
	}
	if len(it.Members) > MaxKindItemMembers {
		return "a list carries at most 500 members"
	}
	for _, m := range it.Members {
		if !ValidExternalID(m) || m == it.ID {
			return "members must be valid external ids of other items"
		}
	}
	if len(it.Recording) > MaxKindItemRecording || strings.ContainsAny(it.Recording, "\x00\n\r") {
		return "recording must be at most 200 characters on one line"
	}
	if it.Playable && !lv.Playable {
		return "level " + it.Level + " is not declared playable"
	}
	if len(it.Hints) > 0 {
		var obj map[string]json.RawMessage
		if err := json.Unmarshal(it.Hints, &obj); err != nil || obj == nil {
			return "hints must be a JSON object"
		}
	}
	seenArt := map[string]bool{}
	for _, a := range it.Art {
		if a.Role == "" || a.URL == "" || seenArt[a.Role] {
			return "each art entry needs a distinct role and a url"
		}
		seenArt[a.Role] = true
	}
	for key := range it.Fields {
		if !kindFieldRe.MatchString(key) {
			return "field names must match the declared field pattern"
		}
	}
	return ""
}

// kindCheck resolves the caller's record and one declared kind,
// requiring one of caps. Roles the owner switched off are absent from
// the effective manifest, so they deny like a missing capability.
func (h *host) kindCheck(ctx context.Context, kindKey string, caps ...Capability) (Record, MediaKindMeta, error) {
	r, _, err := h.record(ctx)
	if err != nil {
		return Record{}, MediaKindMeta{}, err
	}
	man := r.Manifest
	man.Ether = man.EffectiveEther()
	allowed := false
	for _, c := range caps {
		if man.HasCapability(c) {
			allowed = true
		}
	}
	if !allowed {
		h.noteDenied(string(caps[0]))
		return Record{}, MediaKindMeta{}, fmt.Errorf("%w: %s", ErrPermissionDenied, caps[0])
	}
	decl, ok := man.MediaKindByKey(kindKey)
	if !ok {
		return Record{}, MediaKindMeta{}, fmt.Errorf("%w: kind %q is not declared", ErrUnavailable, kindKey)
	}
	return r, decl, nil
}

func uniqueIDs(ids []string) []string {
	if len(ids) == 0 {
		return nil
	}
	unique := make([]string, 0, len(ids))
	seen := make(map[string]bool, len(ids))
	for _, id := range ids {
		if !seen[id] {
			seen[id] = true
			unique = append(unique, id)
		}
	}
	return unique
}

// snapshotKindItems looks up any existing items for kindKey whose IDs
// are in ids so a live KindUpsert or KindDelete can record a real
// inverse in the journal.
func (h *host) snapshotKindItems(ctx context.Context, kindKey string, ids []string) (existing []core.KindItem, missing []string) {
	unique := uniqueIDs(ids)
	if len(unique) == 0 {
		return nil, nil
	}
	readFn := h.m.kindBackends().KindItemsByID
	if readFn == nil {
		return nil, unique
	}
	items, err := readFn(ctx, h.plugin, kindKey, unique)
	if err != nil {
		return nil, unique
	}
	found := make(map[string]core.KindItem, len(items))
	for _, it := range items {
		if _, dup := found[it.ID]; !dup {
			found[it.ID] = it
		}
	}
	for _, id := range unique {
		if prev, ok := found[id]; ok {
			existing = append(existing, prev)
		} else {
			missing = append(missing, id)
		}
	}
	return existing, missing
}

func (h *host) KindUpsert(ctx context.Context, kindKey string, items []core.KindItem) (int, error) {
	result, err := h.KindUpsertWithResult(ctx, kindKey, items)
	return result.Accepted, err
}

// KindUpsertWithResult is KindUpsert reporting the added/updated/
// unchanged split when the backend provides it (#646).
func (h *host) KindUpsertWithResult(ctx context.Context, kindKey string, items []core.KindItem) (KindUpsertResult, error) {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return KindUpsertResult{}, err
	}
	r, decl, err := h.kindCheck(ctx, kindKey, CapCatalogProvider)
	if err != nil {
		return KindUpsertResult{}, err
	}
	if decl.Sync.Mode != KindSyncPush {
		return KindUpsertResult{}, fmt.Errorf("%w: kind %s is pull-synced by Ether and takes no pushes", ErrPermissionDenied, kindKey)
	}
	if len(items) > MaxKindUpsertItems {
		return KindUpsertResult{}, fmt.Errorf("plugins: kind upsert batch larger than %d items", MaxKindUpsertItems)
	}
	ids := make([]string, 0, len(items))
	for _, it := range items {
		if msg := CheckKindItem(decl, it); msg != "" {
			return KindUpsertResult{}, fmt.Errorf("plugins: kind item %q: %s", it.ID, msg)
		}
		ids = append(ids, it.ID)
	}
	if r.Shadow {
		return KindUpsertResult{Accepted: len(items)}, h.journal(ctx, r, "kinds.upsert", kindKey, kindInverse{Op: "kinds.upsert", Kind: kindKey, Items: ids})
	}
	backends := h.m.kindBackends()
	if backends.KindUpsert == nil && backends.KindUpsertStats == nil && backends.KindUpsertUndo == nil {
		return KindUpsertResult{}, ErrUnavailable
	}
	idsOnly := decl.Sync.Undo == KindSyncUndoIDs
	if backends.KindUpsertUndo != nil {
		u, err := backends.KindUpsertUndo(ctx, h.plugin, kindKey, items, !idsOnly)
		if err != nil {
			return KindUpsertResult{}, err
		}
		inv := kindInverse{
			Op:    "kinds.upsert",
			Kind:  kindKey,
			Items: u.AddedIDs,
		}
		if idsOnly {
			inv.Touched = u.UpdatedIDs
		} else {
			inv.Previous = u.Previous
		}
		if len(inv.Items) == 0 && len(inv.Touched) == 0 && len(inv.Previous) == 0 {
			return u.Result, nil
		}
		if err := h.journal(ctx, r, "kinds.upsert", kindKey, inv); err != nil {
			return KindUpsertResult{}, err
		}
		return u.Result, nil
	}
	var prev []core.KindItem
	var created []string
	if idsOnly {
		created = uniqueIDs(ids)
	} else {
		prev, created = h.snapshotKindItems(ctx, kindKey, ids)
	}
	var result KindUpsertResult
	if backends.KindUpsertStats != nil {
		result, err = backends.KindUpsertStats(ctx, h.plugin, kindKey, items)
	} else {
		var accepted int
		accepted, err = backends.KindUpsert(ctx, h.plugin, kindKey, items)
		result = KindUpsertResult{Accepted: accepted}
	}
	if err != nil {
		return KindUpsertResult{}, err
	}
	if err := h.journal(ctx, r, "kinds.upsert", kindKey, kindInverse{
		Op:       "kinds.upsert",
		Kind:     kindKey,
		Items:    created,
		Previous: prev,
	}); err != nil {
		return KindUpsertResult{}, err
	}
	return result, nil
}

func (h *host) KindDelete(ctx context.Context, kindKey string, externalIDs []string) error {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return err
	}
	r, decl, err := h.kindCheck(ctx, kindKey, CapCatalogProvider)
	if err != nil {
		return err
	}
	if decl.Sync.Mode != KindSyncPush {
		return fmt.Errorf("%w: kind %s is pull-synced by Ether and takes no pushes", ErrPermissionDenied, kindKey)
	}
	if len(externalIDs) > MaxKindUpsertItems {
		return fmt.Errorf("plugins: kind delete batch larger than %d items", MaxKindUpsertItems)
	}
	for _, id := range externalIDs {
		if !ValidExternalID(id) {
			return fmt.Errorf("plugins: kind item id %q is not a valid external id", id)
		}
	}
	if r.Shadow {
		return h.journal(ctx, r, "kinds.delete", kindKey, kindInverse{Op: "kinds.delete", Kind: kindKey, Items: externalIDs})
	}
	backend := h.m.kindBackends().KindDelete
	if backend == nil {
		return ErrUnavailable
	}
	var prev []core.KindItem
	if decl.Sync.Undo != KindSyncUndoIDs {
		prev, _ = h.snapshotKindItems(ctx, kindKey, externalIDs)
	}
	if err := backend(ctx, h.plugin, kindKey, externalIDs); err != nil {
		return err
	}
	return h.journal(ctx, r, "kinds.delete", kindKey, kindInverse{
		Op:       "kinds.delete",
		Kind:     kindKey,
		Items:    externalIDs,
		Previous: prev,
	})
}

func (h *host) KindItems(ctx context.Context, kindKey, cursor string, limit int) (core.KindPage, error) {
	if _, _, err := h.kindCheck(ctx, kindKey, CapCatalogProvider); err != nil {
		return core.KindPage{}, err
	}
	backends := h.m.kindBackends()
	backend := backends.KindItems
	if backend == nil {
		return core.KindPage{}, ErrUnavailable
	}
	if limit <= 0 {
		limit = 200
	}
	if limit > MaxKindUpsertItems {
		limit = MaxKindUpsertItems
	}
	page, err := backend(ctx, h.plugin, kindKey, cursor, limit)
	if err == nil {
		err = normalizeKindPageHints(ctx, &page, backends.NormalizeStoredReleaseLinks)
	}
	return page, err
}

// KindVisible evaluates the library's Rules and viewer access policy for a
// bounded batch (max MaxKindVisibleIDs) of external IDs in kindKey (#615).
// Only frontend adapter requests carrying an authenticated viewer may call it;
// the viewer comes solely from the host context, never from guest input.
func (h *host) KindVisible(ctx context.Context, kindKey string, ids []string) ([]string, error) {
	if _, _, err := h.kindCheck(ctx, kindKey, CapFrontendAdapter); err != nil {
		return nil, err
	}
	viewerID, ok := ViewerFromContext(ctx)
	if !ok || viewerID <= 0 {
		return nil, fmt.Errorf("%w: kinds.visible requires an authenticated frontend adapter viewer", ErrPermissionDenied)
	}
	if len(ids) > MaxKindVisibleIDs {
		return nil, &ValidationError{Fields: []FieldError{{
			Field:   "ids",
			Message: fmt.Sprintf("kinds.visible accepts at most %d ids per call", MaxKindVisibleIDs),
		}}}
	}
	if len(ids) == 0 {
		return []string{}, nil
	}
	backend := h.m.kindBackends().KindVisible
	if backend == nil {
		return nil, ErrUnavailable
	}
	visible, err := backend(ctx, h.plugin, viewerID, kindKey, ids)
	if err != nil {
		return nil, err
	}
	if visible == nil {
		visible = []string{}
	}
	return visible, nil
}

// ValidKindEmptyField reports whether field may appear as a key in
// KindBrowseRequest.Empty for decl (#807): any declared field on decl, any
// optional item envelope column (released, year, rating, summary, recording,
// parentId, index, or the virtual decade alias), or a <dateField>-decade facet
// whose base is a declared date field.
func ValidKindEmptyField(decl MediaKindMeta, field string) bool {
	if strings.TrimSpace(field) == "" || field != strings.TrimSpace(field) {
		return false
	}
	for _, f := range decl.Fields {
		if f.Key == field {
			return true
		}
	}
	switch field {
	case "released", "year", "rating", "summary", "recording", "parentId", "index", "decade":
		return true
	}
	if base, ok := libraryfilter.SplitDateDecadeFacet(field); ok {
		for _, f := range decl.Fields {
			if f.Key == base && f.Type == "date" {
				return true
			}
		}
	}
	return false
}

// KindBrowse browses or searches kindKey using the same LibraryPolicy path
// as Ether's console and protocol projectors for the requesting
// frontend-adapter viewer (#615). Only frontend adapter requests carrying an
// authenticated viewer may call it; the viewer comes solely from the host
// context, never from guest input.
func (h *host) KindBrowse(ctx context.Context, kindKey string, q core.KindBrowseRequest) (core.KindPage, error) {
	_, decl, err := h.kindCheck(ctx, kindKey, CapFrontendAdapter)
	if err != nil {
		return core.KindPage{}, err
	}
	viewerID, ok := ViewerFromContext(ctx)
	if !ok || viewerID <= 0 {
		return core.KindPage{}, fmt.Errorf("%w: kinds.browse requires an authenticated frontend adapter viewer", ErrPermissionDenied)
	}
	if q.ParentID != "" && !ValidExternalID(q.ParentID) {
		return core.KindPage{}, &ValidationError{Fields: []FieldError{{
			Field:   "parentId",
			Message: "parentId must be a valid external id",
		}}}
	}
	switch q.Total {
	case "", "cheap", "none", "exact":
	default:
		return core.KindPage{}, &ValidationError{Fields: []FieldError{{
			Field:   "total",
			Message: `total must be "cheap", "none", or "exact"`,
		}}}
	}
	if len(q.AnyGroups) > MaxKindBrowseAnyGroups {
		return core.KindPage{}, &ValidationError{Fields: []FieldError{{
			Field:   "anyGroups",
			Message: fmt.Sprintf("anyGroups accepts at most %d groups per query", MaxKindBrowseAnyGroups),
		}}}
	}
	facetValues := 0
	for _, m := range []map[string][]string{q.Facets, q.AllFacets, q.ExcludeFacets} {
		for _, vals := range m {
			facetValues += len(vals)
		}
	}
	anyAlts := 0
	for _, g := range q.AnyGroups {
		facetValues += len(g.Values)
		anyAlts += len(g.Any)
		for _, alt := range g.Any {
			facetValues += len(alt.Values)
		}
	}
	if anyAlts > MaxKindBrowseFacetValues {
		return core.KindPage{}, &ValidationError{Fields: []FieldError{{
			Field:   "anyGroups",
			Message: fmt.Sprintf("anyGroups alternatives exceed %d per query", MaxKindBrowseFacetValues),
		}}}
	}
	if facetValues > MaxKindBrowseFacetValues {
		field := "facets"
		if len(q.AnyGroups) > 0 && len(q.Facets) == 0 && len(q.AllFacets) == 0 && len(q.ExcludeFacets) == 0 {
			field = "anyGroups"
		}
		return core.KindPage{}, &ValidationError{Fields: []FieldError{{
			Field:   field,
			Message: fmt.Sprintf("facet values exceed %d per query", MaxKindBrowseFacetValues),
		}}}
	}
	if len(q.Empty) > 0 {
		keys := make([]string, 0, len(q.Empty))
		for k := range q.Empty {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			if !ValidKindEmptyField(decl, k) {
				f := "empty"
				if k != "" {
					f = "empty." + k
				}
				return core.KindPage{}, &ValidationError{Fields: []FieldError{{
					Field:   f,
					Message: fmt.Sprintf("unknown field %q", k),
				}}}
			}
		}
	}
	if q.Limit <= 0 {
		q.Limit = 200
	}
	if q.Limit > MaxKindUpsertItems {
		q.Limit = MaxKindUpsertItems
	}
	backends := h.m.kindBackends()
	backend := backends.KindBrowse
	if backend == nil {
		return core.KindPage{}, ErrUnavailable
	}
	page, err := backend(ctx, h.plugin, viewerID, kindKey, q)
	if err != nil {
		return core.KindPage{}, err
	}
	if page.Items == nil {
		page.Items = []core.KindItem{}
	}
	err = normalizeKindPageHints(ctx, &page, backends.NormalizeStoredReleaseLinks)
	return page, err
}

func normalizeKindPageHints(ctx context.Context, page *core.KindPage, normalize func(context.Context, []byte) ([]byte, error)) error {
	if normalize == nil || len(page.Items) == 0 {
		return nil
	}
	hints := make([]json.RawMessage, len(page.Items))
	for i, item := range page.Items {
		hints[i] = item.Hints
	}
	raw, err := json.Marshal(hints)
	if err != nil {
		return err
	}
	normalized, err := normalize(ctx, raw)
	if err != nil || bytes.Equal(raw, normalized) {
		return err
	}
	if err := json.Unmarshal(normalized, &hints); err != nil {
		return err
	}
	page.Items = slices.Clone(page.Items)
	for i := range page.Items {
		if len(page.Items[i].Hints) != 0 {
			page.Items[i].Hints = hints[i]
		}
	}
	return nil
}

// DefaultUsenetCheckPerMin bounds per-plugin on-demand usenet_check calls
// per minute so a resolver cannot flood Usenet indexers or NNTP providers.
const DefaultUsenetCheckPerMin = 20

// Bounds of an indexer_search typed lookup.
const (
	MaxSourceLookupFields     = 8
	MaxSourceLookupFieldBytes = 256
)

// ValidateSourceLookup checks an indexer_search lookup: it rides on a
// category search, names a simple type, and carries a few short fields.
func ValidateSourceLookup(q core.SourceQuery) *FieldError {
	l := q.Lookup
	if l == nil {
		return nil
	}
	switch {
	case strings.TrimSpace(q.Category) == "":
		return &FieldError{Field: "lookup", Message: "lookup needs a category: plugin sources answer typed lookups on category searches"}
	case !keyRe.MatchString(l.Type):
		return &FieldError{Field: "lookup.type", Message: "lookup.type must be a simple key such as album or book"}
	case len(l.Fields) > MaxSourceLookupFields:
		return &FieldError{Field: "lookup.fields", Message: fmt.Sprintf("at most %d lookup fields allowed", MaxSourceLookupFields)}
	}
	for k, v := range l.Fields {
		if !lookupFieldRe.MatchString(k) {
			return &FieldError{Field: "lookup.fields", Message: fmt.Sprintf("lookup field %q must be a simple camelCase name", k)}
		}
		if len(v) > MaxSourceLookupFieldBytes {
			return &FieldError{Field: "lookup.fields." + k, Message: fmt.Sprintf("must be at most %d bytes", MaxSourceLookupFieldBytes)}
		}
	}
	return nil
}

// SourcesPermissionAllowsSearch reports whether the declared permissions.sources
// level permits indexer search, release inspection, debrid cache checks, and
// on-demand Usenet checks.
func SourcesPermissionAllowsSearch(level string) bool {
	switch normLevel(level) {
	case "search", "search+check", "acquire", "acquire+check":
		return true
	default:
		return false
	}
}

// SourcesPermissionAllowsAcquire reports whether the declared permissions.sources
// level permits debrid_acquire.
func SourcesPermissionAllowsAcquire(level string) bool {
	switch normLevel(level) {
	case "acquire", "acquire+check":
		return true
	default:
		return false
	}
}

// SourcesPermissionAllowsBackgroundCheck reports whether the declared
// permissions.sources level permits background usenet_check calls within the
// per-plugin daily allowance.
func SourcesPermissionAllowsBackgroundCheck(level string) bool {
	switch normLevel(level) {
	case "search+check", "acquire+check":
		return true
	default:
		return false
	}
}

// WithBackgroundCall marks a plugin invocation context as background work
// (such as a scheduled job or catalog sync/expand). Background usenet_check
// calls require permissions.sources "search+check" or "acquire+check" and
// count against the per-plugin daily allowance.
func WithBackgroundCall(ctx context.Context) context.Context {
	return context.WithValue(wasm.WithBackgroundCall(ctx), backgroundCallKey{}, true)
}

func isBackgroundCall(ctx context.Context) bool {
	if bg, _ := ctx.Value(backgroundCallKey{}).(bool); bg {
		return true
	}
	return wasm.IsBackgroundCall(ctx)
}

func (h *host) ResolveSources(ctx context.Context, q core.SourceQuery) ([]core.SourceCandidate, error) {
	res, err := h.ResolveSourcesWithResult(ctx, q)
	if err != nil {
		return nil, err
	}
	return res.Candidates, nil
}

// ResolveSourcesWithResult runs ResolveSources and preserves per-indexer
// search status alongside candidates when the backend supports it (#733).
func (h *host) ResolveSourcesWithResult(ctx context.Context, q core.SourceQuery) (core.SourceResolveResult, error) {
	r, g, err := h.record(ctx)
	if err != nil {
		return core.SourceResolveResult{}, err
	}
	man := r.Manifest
	man.Ether = man.EffectiveEther()
	if !man.HasCapability(CapKindResolver) {
		h.noteDenied(string(CapKindResolver))
		return core.SourceResolveResult{}, fmt.Errorf("%w: %s", ErrPermissionDenied, CapKindResolver)
	}
	need := "search"
	switch q.Kind {
	case "indexer_search":
		if strings.TrimSpace(q.Query) == "" && strings.TrimSpace(q.Category) == "" {
			return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{{
				Field:   "query",
				Message: "indexer_search needs a query or category",
			}}}
		}
		if q.SettleMS != nil && *q.SettleMS < 0 {
			return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{{
				Field:   "settleMs",
				Message: "settleMs must be non-negative",
			}}}
		}
		if q.MinResults < 0 {
			return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{{
				Field:   "minResults",
				Message: "minResults must be non-negative",
			}}}
		}
		if q.TimeoutMS < 0 {
			return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{{
				Field:   "timeoutMs",
				Message: "timeoutMs must be non-negative",
			}}}
		}
		if len(q.SkipIndexers) > MaxSourceIndexerFilters {
			return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{{
				Field:   "skipIndexers",
				Message: fmt.Sprintf("at most %d skipIndexers entries allowed", MaxSourceIndexerFilters),
			}}}
		}
		if len(q.OnlyIndexers) > MaxSourceIndexerFilters {
			return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{{
				Field:   "onlyIndexers",
				Message: fmt.Sprintf("at most %d onlyIndexers entries allowed", MaxSourceIndexerFilters),
			}}}
		}
		if fe := ValidateSourceLookup(q); fe != nil {
			return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{*fe}}
		}
	case "indexer_search_results":
		if strings.TrimSpace(q.SearchID) == "" {
			return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{{
				Field:   "searchId",
				Message: "indexer_search_results needs a searchId",
			}}}
		}
		if q.WaitMS < 0 {
			return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{{
				Field:   "waitMs",
				Message: "waitMs must be non-negative",
			}}}
		}
	case "indexer_search_cancel":
		if strings.TrimSpace(q.SearchID) == "" {
			return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{{
				Field:   "searchId",
				Message: "indexer_search_cancel needs a searchId",
			}}}
		}
	case "indexers":
		// Lists the owner's enabled indexers (gated by the same search permission).
	case "debrid":
		// Reads the owner policy under the same permission as cache checks.
	case "debrid_check":
		if len(q.InfoHashes) == 0 && q.InfoHash == "" {
			return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{{
				Field:   "infoHashes",
				Message: "debrid_check needs an info hash",
			}}}
		}
	case "release_files":
		if q.InfoHash == "" && q.Magnet == "" && q.TorrentURL == "" && q.TorrentRef == "" && q.NZBURL == "" && q.NZBRef == "" && q.Candidate == nil {
			return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{{
				Field:   "infoHash",
				Message: "release_files needs a release reference, info hash, magnet or candidate",
			}}}
		}
	case "nzb_request":
		if strings.TrimSpace(q.NZBRef) == "" && (q.NZBIdentity == nil ||
			strings.TrimSpace(q.NZBIdentity.IndexerID) == "" || strings.TrimSpace(q.NZBIdentity.GUID) == "") {
			return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{{
				Field: "nzbRef", Message: "nzb_request needs an nzbRef or indexer release identity",
			}}}
		}
	case "usenet_check":
		nzbURL := strings.TrimSpace(q.NZBURL)
		if nzbURL == "" && q.Candidate != nil {
			nzbURL = strings.TrimSpace(q.Candidate.NZBURL)
		}
		if nzbURL == "" && q.NZBRef == "" && (q.Candidate == nil || q.Candidate.NZBRef == "") {
			return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{{
				Field:   "nzbUrl",
				Message: "usenet_check needs an nzbRef, candidate or legacy nzbUrl",
			}}}
		}
	case "debrid_acquire":
		need = "acquire"
		if q.InfoHash == "" && q.Magnet == "" && q.TorrentURL == "" && q.TorrentRef == "" && q.Candidate == nil {
			return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{{
				Field:   "infoHash",
				Message: "debrid_acquire needs an info hash, magnet, torrentUrl or candidate",
			}}}
		}
	default:
		return core.SourceResolveResult{}, &ValidationError{Fields: []FieldError{{
			Field:   "kind",
			Message: fmt.Sprintf("unknown source query kind %q", q.Kind),
		}}}
	}
	level := normLevel(r.Manifest.Ether.Permissions.Sources)
	if err := h.deny(r, g, "sources", level, func(l string) bool {
		return SourcesPermissionAllowsAcquire(l) || (need == "search" && SourcesPermissionAllowsSearch(l))
	}); err != nil {
		return core.SourceResolveResult{}, err
	}
	nzbQuery := q.Kind == "usenet_check" || q.Kind == "nzb_request"
	bgUsenetCheck := nzbQuery && isBackgroundCall(ctx)
	if bgUsenetCheck {
		if err := h.deny(r, g, "sources.check", level, SourcesPermissionAllowsBackgroundCheck); err != nil {
			return core.SourceResolveResult{}, err
		}
	}
	backends := h.m.kindBackends()
	if backends.ResolveSourcesResult == nil && backends.ResolveSources == nil {
		return core.SourceResolveResult{}, ErrUnavailable
	}
	callCtx := ctx
	var refundCheck func()
	var resetAt time.Time
	if nzbQuery {
		if bgUsenetCheck {
			// Reuse a live verdict from the shared cache before spending the
			// plugin's daily background allowance.
			if q.Kind == "usenet_check" && backends.PeekUsenetCheck != nil {
				if cand, ok := backends.PeekUsenetCheck(q); ok {
					return core.SourceResolveResult{Candidates: []core.SourceCandidate{pluginSourceCandidate(cand)}}, nil
				}
			}
			if backends.AdmitBackgroundUsenetCheck == nil {
				return core.SourceResolveResult{}, ErrUnavailable
			}
			var admitErr error
			callCtx, refundCheck, resetAt, admitErr = backends.AdmitBackgroundUsenetCheck(ctx, h.plugin)
			if admitErr != nil {
				if errors.Is(admitErr, core.ErrBudgetExhausted) {
					return core.SourceResolveResult{}, h.m.rateLimitError(
						"background usenet_check daily allowance exhausted",
						resetAt,
					)
				}
				return core.SourceResolveResult{}, pluginSourceError(admitErr)
			}
		} else {
			// On-demand viewer calls never count against the daily background
			// allowance; only the per-minute burst limit applies.
			limit := h.m.usenetCheckLimit
			if limit <= 0 {
				limit = DefaultUsenetCheckPerMin
			}
			if ok, retryAt := h.m.rateOKRetryAt(h.m.usenetCheckTimes, h.plugin, limit, time.Minute); !ok {
				return core.SourceResolveResult{}, h.m.rateLimitError(
					fmt.Sprintf("usenet_check is limited to %d per minute", limit),
					retryAt,
				)
			}
		}
	}
	var (
		res  core.SourceResolveResult
		rerr error
	)
	if backends.ResolveSourcesResult != nil {
		res, rerr = backends.ResolveSourcesResult(callCtx, h.plugin, q)
	} else {
		var cands []core.SourceCandidate
		cands, rerr = backends.ResolveSources(callCtx, h.plugin, q)
		res = core.SourceResolveResult{Candidates: cands}
	}
	if rerr != nil {
		if bgUsenetCheck {
			if errors.Is(rerr, core.ErrNotAvailable) && refundCheck != nil {
				refundCheck()
			}
			if errors.Is(rerr, core.ErrBudgetExhausted) {
				if refundCheck != nil {
					refundCheck()
				}
				return core.SourceResolveResult{}, h.m.rateLimitError(
					"background usenet_check daily allowance exhausted",
					resetAt,
				)
			}
		}
		return core.SourceResolveResult{}, pluginSourceError(rerr)
	}
	res.Candidates = slices.Clone(res.Candidates)
	for i := range res.Candidates {
		res.Candidates[i] = pluginSourceCandidate(res.Candidates[i])
	}
	return res, nil
}

// Keep indexer-owned locators on the host, including inside magnet parameters.
// The same response boundary serves hosted, HTTP, and tunnel plugins.
func pluginSourceCandidate(c core.SourceCandidate) core.SourceCandidate {
	if !strings.HasPrefix(c.NZBURL, core.PluginNZBRefPrefix) {
		c.NZBURL = ""
	}
	if !strings.HasPrefix(c.TorrentURL, core.PluginTorrentRefPrefix) {
		c.TorrentURL = ""
	}
	if c.Magnet != "" {
		hash := newznab.InfoHashFromMagnet(c.Magnet)
		c.Magnet = newznab.BareMagnet(hash)
	}
	return c
}

// Backend errors can contain an upstream response or request URL. Return
// fixed classifications and allow structured errors produced by the host.
func pluginSourceError(err error) error {
	var invalid *ValidationError
	var limit *RateLimitError
	if errors.As(err, &invalid) {
		return invalid
	}
	if errors.As(err, &limit) {
		return limit
	}
	for _, public := range []error{
		context.DeadlineExceeded, context.Canceled, ErrNotFound, ErrPermissionDenied,
		core.ErrBudgetExhausted, core.ErrReleaseRejected, core.ErrSourceUnavailable,
		core.ErrNotCached, core.ErrNotAvailable,
	} {
		if errors.Is(err, public) {
			return public
		}
	}
	return ErrUnavailable
}

// sizedCacheInput lets storage reserve known content lengths before reading.
type sizedCacheInput struct {
	io.Reader
	size int64
}

// libraryLimit resolves a declared or owner-selected library ceiling. Pool
// admission separately accounts for other libraries, streams and partials.
func (b KindBackends) libraryLimit(pluginID, libraryKey string, decl KindCacheDecl) int64 {
	limit := decl.MaxBytes
	if b.CacheLimit != nil {
		if selected := b.CacheLimit(pluginID, libraryKey); selected > 0 {
			limit = selected
		}
	}
	if limit <= 0 {
		return math.MaxInt64
	}
	return limit
}

func (h *host) CachePut(ctx context.Context, libraryKey, name string, r io.Reader) (string, error) {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return "", err
	}
	decl, err := h.cacheWriteCheck(ctx, libraryKey, name)
	if err != nil {
		return "", err
	}
	b := h.m.kindBackends()
	backend := b.CachePut
	if backend == nil {
		return "", ErrUnavailable
	}
	limit := b.libraryLimit(h.plugin, libraryKey, decl.Cache)
	var limited *boundedDataReader
	if limit < math.MaxInt64 {
		limited = &boundedDataReader{ctx: ctx, r: r, left: limit}
		if sized, ok := r.(interface{ ExpectedSize() int64 }); ok {
			if sized.ExpectedSize() > limit {
				return "", ErrQuotaExceeded
			}
			r = sizedCacheInput{limited, sized.ExpectedSize()}
		} else {
			r = limited
		}
	}
	ref, err := backend(ctx, h.plugin, libraryKey, name, r)
	if (limited != nil && limited.left < 0) || errors.Is(err, blobcache.ErrTooLarge) {
		return "", ErrQuotaExceeded
	}

	return ref, err
}

// viewerContextKey carries the authenticated viewer of a proxied request
// into a plugin call, so a host service can act as that viewer without the
// plugin passing (or being trusted with) the identity.
type viewerContextKey struct{}

// WithViewer attaches a viewer id to a plugin call context.
func WithViewer(ctx context.Context, viewerID int64) context.Context {
	return context.WithValue(ctx, viewerContextKey{}, viewerID)
}

// ViewerFromContext returns the viewer attached by WithViewer, if any.
func ViewerFromContext(ctx context.Context) (int64, bool) {
	id, ok := ctx.Value(viewerContextKey{}).(int64)
	return id, ok
}

// WithAdapterOrigin attaches the host-derived client-visible origin
// ("scheme://host[:port][/prefix]") for an active frontend adapter request (#772).
func WithAdapterOrigin(ctx context.Context, origin string) context.Context {
	origin = strings.TrimRight(strings.TrimSpace(origin), "/")
	if origin == "" {
		return ctx
	}
	return context.WithValue(ctx, adapterOriginContextKey{}, origin)
}

// AdapterOriginFromContext returns the origin attached by WithAdapterOrigin, if any.
func AdapterOriginFromContext(ctx context.Context) (string, bool) {
	origin, ok := ctx.Value(adapterOriginContextKey{}).(string)
	return origin, ok && origin != ""
}

// AdapterKeyFromPath extracts the adapter key from a plugin-side frontend
// adapter route ("/ether/v1/frontend/<key>/...").
func AdapterKeyFromPath(path string) string {
	rest, ok := strings.CutPrefix(path, "/ether/v1/frontend/")
	if !ok || rest == "" {
		return ""
	}
	key, _, _ := strings.Cut(rest, "/")
	return key
}

// AdapterKeyFromContext returns the adapter key of the active frontend adapter
// call path attached to ctx, if any.
func AdapterKeyFromContext(ctx context.Context) (string, bool) {
	key := AdapterKeyFromPath(callPathFromContext(ctx))
	return key, key != ""
}

// AdapterCallInfo identifies the active /ether/v1/frontend/* call that minted
// an X-Ether-Viewer-Token so remote host callbacks enforce the same viewer,
// origin, and route policies as hosted plugins.
type AdapterCallInfo struct {
	ViewerID    int64
	Path        string
	SearchQuery string
	Origin      string
}

func isFrontendAdapterPath(path string) bool {
	return isFrontendAdapterRoute(path) || isViewerScreenPath(path)
}

// isFrontendAdapterRoute is strictly a frontend adapter's own traffic.
func isFrontendAdapterRoute(path string) bool {
	return strings.HasPrefix(path, "/ether/v1/frontend/") && len(path) > len("/ether/v1/frontend/")
}

// isViewerScreenPath is a screen's viewer-scoped source or action call: like
// an adapter call, it carries the authenticated viewer so the plugin can use
// the viewer-bound host services (kinds.visible, kinds.state, its KV).
func isViewerScreenPath(path string) bool {
	return strings.HasPrefix(path, "/ether/v1/screens/") && len(path) > len("/ether/v1/screens/")
}

// bindAdapterViewer attaches the authenticated viewer from X-Ether-Viewer to
// ctx and mints a request-scoped X-Ether-Viewer-Token for remote callbacks,
// strictly on /ether/v1/frontend/* adapter calls. Non-adapter calls never
// receive a viewer context or token, and any pre-existing token header is
// stripped before binding.
func (m *Manager) bindAdapterViewer(ctx context.Context, pluginID string, req *Request, deadline time.Duration) (context.Context, func()) {
	if req != nil && req.Headers != nil {
		for k := range req.Headers {
			if strings.EqualFold(k, HeaderAdapterViewerToken) {
				delete(req.Headers, k)
			}
		}
	}
	if req == nil || !isFrontendAdapterPath(req.Path) || req.Headers == nil {
		return ctx, func() {}
	}
	raw := req.Headers["X-Ether-Viewer"]
	if raw == "" {
		return ctx, func() {}
	}
	id, err := strconv.ParseInt(raw, 10, 64)
	if err != nil || id <= 0 {
		return ctx, func() {}
	}
	ctx = WithViewer(ctx, id)
	origin := strings.TrimRight(strings.TrimSpace(req.Headers[HeaderAdapterOrigin]), "/")
	if origin != "" {
		ctx = WithAdapterOrigin(ctx, origin)
	}
	var b [32]byte
	if _, err := rand.Read(b[:]); err != nil {
		return ctx, func() {}
	}
	token := hex.EncodeToString(b[:])
	now := time.Now()
	if m.now != nil {
		now = m.now()
	}
	ttl := deadline
	if ttl < time.Minute {
		ttl = time.Minute
	}
	m.adapterViewerMu.Lock()
	if m.adapterViewerTokens == nil {
		m.adapterViewerTokens = make(map[string]adapterViewerGrant)
	}
	for k, v := range m.adapterViewerTokens {
		if !now.Before(v.expires) {
			delete(m.adapterViewerTokens, k)
		}
	}
	m.adapterViewerTokens[token] = adapterViewerGrant{
		pluginID:    pluginID,
		viewerID:    id,
		path:        req.Path,
		searchQuery: extractCallSearchQuery(*req),
		origin:      origin,
		expires:     now.Add(ttl),
	}
	m.adapterViewerMu.Unlock()
	req.Headers[HeaderAdapterViewerToken] = token
	return ctx, func() { m.revokeAdapterViewerToken(token) }
}

func (m *Manager) revokeAdapterViewerToken(token string) {
	if token == "" {
		return
	}
	m.adapterViewerMu.Lock()
	delete(m.adapterViewerTokens, token)
	m.adapterViewerMu.Unlock()
}

// ResolveAdapterCallToken verifies that token belongs to an active
// /ether/v1/frontend/* call for pluginID and returns its authenticated viewer
// and active route context.
func (m *Manager) ResolveAdapterCallToken(pluginID, token string) (AdapterCallInfo, bool) {
	token = strings.TrimSpace(token)
	if pluginID == "" || token == "" {
		return AdapterCallInfo{}, false
	}
	now := time.Now()
	if m.now != nil {
		now = m.now()
	}
	m.adapterViewerMu.Lock()
	defer m.adapterViewerMu.Unlock()
	grant, ok := m.adapterViewerTokens[token]
	if !ok {
		return AdapterCallInfo{}, false
	}
	if !now.Before(grant.expires) {
		delete(m.adapterViewerTokens, token)
		return AdapterCallInfo{}, false
	}
	if grant.pluginID != pluginID || grant.viewerID <= 0 {
		return AdapterCallInfo{}, false
	}
	return AdapterCallInfo{
		ViewerID:    grant.viewerID,
		Path:        grant.path,
		SearchQuery: grant.searchQuery,
		Origin:      grant.origin,
	}, true
}

// ResolveAdapterViewerToken verifies that token belongs to an active
// /ether/v1/frontend/* call for pluginID and returns its authenticated viewer.
func (m *Manager) ResolveAdapterViewerToken(pluginID, token string) (int64, bool) {
	info, ok := m.ResolveAdapterCallToken(pluginID, token)
	if !ok {
		return 0, false
	}
	return info.ViewerID, true
}

func validateStreamSourceID(source string) error {
	if source == "" {
		return nil
	}
	if strings.TrimSpace(source) == "" {
		return &ValidationError{Fields: []FieldError{{Field: "source", Message: "stream url source must not be blank"}}}
	}
	if len(source) > maxStreamSourceIDLen {
		return &ValidationError{Fields: []FieldError{{Field: "source", Message: "stream url source exceeds maximum length"}}}
	}
	for _, r := range source {
		if r < 0x20 || r == 0x7f {
			return &ValidationError{Fields: []FieldError{{Field: "source", Message: "stream url source must not contain control characters"}}}
		}
	}
	return nil
}

// StreamURL mints a scoped stream ticket for one of the plugin's own kind
// items and returns the Ether stream URL (spec §6.5). The viewer is the one
// the proxied request authenticated, carried on the call context as
// X-Ether-Viewer. The backend re-checks that the item belongs to this plugin
// and that the viewer may see its library.
func (h *host) StreamURL(ctx context.Context, itemRef string) (string, error) {
	return h.StreamURLWithOptions(ctx, itemRef, StreamURLOptions{})
}

func (h *host) StreamPartURL(ctx context.Context, itemRef string, partIndex *int) (string, error) {
	return h.StreamURLWithOptions(ctx, itemRef, StreamURLOptions{PartIndex: partIndex})
}

func (h *host) StreamURLWithOptions(ctx context.Context, itemRef string, opts StreamURLOptions) (string, error) {
	rec, _, err := h.record(ctx)
	if err != nil {
		return "", err
	}
	man := rec.Manifest
	man.Ether = man.EffectiveEther()
	if man.Ether == nil || !man.HasCapability(CapFrontendAdapter) {
		h.noteDenied(string(CapFrontendAdapter))
		return "", fmt.Errorf("%w: %s", ErrPermissionDenied, CapFrontendAdapter)
	}
	viewerID, ok := ViewerFromContext(ctx)
	if !ok || viewerID <= 0 {
		return "", fmt.Errorf("%w: stream url needs an authenticated viewer", ErrPermissionDenied)
	}
	if strings.TrimSpace(itemRef) == "" {
		return "", fmt.Errorf("plugins: stream url needs an item ref")
	}
	if opts.PartIndex != nil && *opts.PartIndex < 0 {
		return "", fmt.Errorf("plugins: stream url partIndex must be non-negative")
	}
	if opts.Fallback && opts.Source == "" {
		return "", fmt.Errorf("stream url: fallback requires a source")
	}
	if err := validateStreamSourceID(opts.Source); err != nil {
		return "", err
	}
	backends := h.m.kindBackends()
	if backends.StreamURLOptions != nil {
		return backends.StreamURLOptions(ctx, h.plugin, viewerID, itemRef, opts)
	}
	if opts.Source != "" || opts.Absolute || opts.Wait != nil {
		return "", ErrUnavailable
	}
	if backends.StreamPartURL != nil {
		return backends.StreamPartURL(ctx, h.plugin, viewerID, itemRef, opts.PartIndex)
	}
	if backends.StreamURL == nil {
		return "", ErrUnavailable
	}
	u, err := backends.StreamURL(ctx, h.plugin, viewerID, itemRef)
	if err != nil || opts.PartIndex == nil {
		return u, err
	}
	sep := "?"
	if strings.Contains(u, "?") {
		sep = "&"
	}
	return u + sep + "part=" + strconv.Itoa(*opts.PartIndex), nil
}

func validateBlobRef(blobRef string) error {
	hexPart, ok := strings.CutPrefix(blobRef, "blob:")
	if !ok || len(hexPart) != 64 {
		return &ValidationError{Fields: []FieldError{{Field: "blobRef", Message: "cache reference must be blob:<sha256>"}}}
	}
	if _, err := hex.DecodeString(hexPart); err != nil {
		return &ValidationError{Fields: []FieldError{{Field: "blobRef", Message: "cache reference must be blob:<sha256>"}}}
	}
	return nil
}

func validateDurableBlobRef(ref string) error {
	if _, err := blobcache.ParseDurableRef(blobcache.Ref(ref)); err != nil {
		return &ValidationError{Fields: []FieldError{{Field: "blobRef", Message: "durable reference must be durable:<sha256>"}}}
	}
	return nil
}

func (h *host) CacheOpen(ctx context.Context, blobRef string) (io.ReadSeekCloser, error) {
	return h.cacheOpen(ctx, blobRef, false)
}

func (h *host) cacheOpen(ctx context.Context, blobRef string, statOnly bool) (io.ReadSeekCloser, error) {
	if strings.HasPrefix(blobRef, blobcache.DurableRefPrefix) {
		if err := validateDurableBlobRef(blobRef); err != nil {
			return nil, err
		}
		return h.openDurableBlob(ctx, blobRef)
	}
	r, err := h.callRecord(ctx)
	if err != nil {
		return nil, err
	}
	if !r.Enabled {
		return nil, ErrDisabled
	}
	if err := validateBlobRef(blobRef); err != nil {
		return nil, err
	}
	if s := h.m.deps.DurableStorage; s != nil {
		if src, err := s.Open(h.plugin, blobcache.Ref(blobRef)); !errors.Is(err, blobcache.ErrNotFound) {
			return src, storageError(err)
		}
	}
	backends := h.m.kindBackends()
	backend := backends.CacheOpen
	if statOnly {
		backend = backends.CacheOpenForStat
	}
	if backend == nil {
		return nil, ErrUnavailable
	}
	return backend(ctx, h.plugin, blobRef)
}

// CacheDelete removes one cached blob from this plugin's own library cache
// namespaces, freeing its quota immediately. Deleting a ref that is absent or
// already evicted succeeds.
func (h *host) CacheDelete(ctx context.Context, blobRef string) error {
	if strings.HasPrefix(blobRef, blobcache.DurableRefPrefix) {
		if err := validateDurableBlobRef(blobRef); err != nil {
			return err
		}
		return h.deleteDurableBlob(ctx, blobRef)
	}
	if err := h.requireWritableToolContext(ctx); err != nil {
		return err
	}
	rec, _, err := h.record(ctx)
	if err != nil {
		return err
	}
	man := rec.Manifest
	man.Ether = man.EffectiveEther()
	if man.Ether == nil || len(man.Ether.Contributes.MediaKinds) == 0 || !(man.HasCapability(CapCatalogProvider) || man.HasCapability(CapKindResolver)) {
		h.noteDenied("cache")
		return fmt.Errorf("%w: cache", ErrPermissionDenied)
	}
	if err := validateBlobRef(blobRef); err != nil {
		return err
	}
	backend := h.m.kindBackends().CacheDelete
	if backend == nil {
		return ErrUnavailable
	}
	return backend(ctx, h.plugin, blobRef)
}

func (h *host) cacheWriteCheck(ctx context.Context, libraryKey, name string) (MediaKindMeta, error) {
	rec, _, err := h.record(ctx)
	if err != nil {
		return MediaKindMeta{}, err
	}
	man := rec.Manifest
	man.Ether = man.EffectiveEther()
	// The library key must name one of this plugin's own kinds; the
	// blob cache namespace follows from it, so a plugin can never
	// write into another library's cache.
	var decl MediaKindMeta
	found := false
	if man.Ether != nil {
		for _, k := range man.Ether.Contributes.MediaKinds {
			if core.PluginLibraryKey(h.plugin, k.Key) == libraryKey {
				decl, found = k, true
			}
		}
	}
	if !found || !(man.HasCapability(CapCatalogProvider) || man.HasCapability(CapKindResolver)) {
		h.noteDenied("cache")
		return MediaKindMeta{}, fmt.Errorf("%w: cache", ErrPermissionDenied)
	}
	if strings.TrimSpace(name) == "" {
		return MediaKindMeta{}, fmt.Errorf("plugins: cache put needs a name")
	}
	return decl, nil
}

func (h *host) archiveExtractCheck(ctx context.Context, explicitLibraryKey string) (string, error) {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return "", err
	}
	if explicit := strings.TrimSpace(explicitLibraryKey); explicit != "" {
		if _, err := h.cacheWriteCheck(ctx, explicit, "_"); err != nil {
			return "", err
		}
		return explicit, nil
	}
	rec, _, err := h.record(ctx)
	if err != nil {
		return "", err
	}
	man := rec.Manifest
	man.Ether = man.EffectiveEther()
	if man.Ether == nil || len(man.Ether.Contributes.MediaKinds) == 0 || !(man.HasCapability(CapCatalogProvider) || man.HasCapability(CapKindResolver)) {
		h.noteDenied("cache")
		return "", fmt.Errorf("%w: cache", ErrPermissionDenied)
	}
	return core.PluginLibraryKey(h.plugin, man.Ether.Contributes.MediaKinds[0].Key), nil
}

func (h *host) resolveExtractTarget(ctx context.Context, explicitLibraryKey, sourceLibraryKey, name string) (string, int64, error) {
	if explicit := strings.TrimSpace(explicitLibraryKey); explicit != "" {
		decl, err := h.cacheWriteCheck(ctx, explicit, name)
		if err != nil {
			return "", 0, err
		}
		return explicit, h.m.kindBackends().libraryLimit(h.plugin, explicit, decl.Cache), nil
	}
	if src := strings.TrimSpace(sourceLibraryKey); src != "" {
		if decl, err := h.cacheWriteCheck(ctx, src, name); err == nil {
			return src, h.m.kindBackends().libraryLimit(h.plugin, src, decl.Cache), nil
		}
	}
	libKey, err := h.archiveExtractCheck(ctx, "")
	if err != nil {
		return "", 0, err
	}
	decl, err := h.cacheWriteCheck(ctx, libKey, name)
	if err != nil {
		return "", 0, err
	}
	return libKey, h.m.kindBackends().libraryLimit(h.plugin, libKey, decl.Cache), nil
}

const (
	// MediaProbeTimeout is the hard per-call timeout enforced on every
	// media.probe host call.
	MediaProbeTimeout = 10 * time.Second
	// DefaultMediaProbePerMin is the per-plugin sliding-window rate limit for
	// media.probe host calls.
	DefaultMediaProbePerMin = 60
)

// MediaPermissionAllowsProbe reports whether a normalized permissions.media
// level permits media.probe host calls.
func MediaPermissionAllowsProbe(level string) bool {
	return normLevel(level) == "probe"
}

// MediaProbeAllowedPath reports whether a plugin call to path may invoke
// media.probe. Only jobs, actions, Flow actions, tools, event deliveries,
// setup/test, feed, background kind sync, Live TV sync, declared scheduled
// calls, and background calls are permitted; every interactive viewer or
// client request path (including /resolve, /search, /catalog, /stream, /meta,
// /subtitles, /view, /options, /health, /configure, and frontend adapter
// routes) is refused.
func MediaProbeAllowedPath(man Manifest, path string, background bool) bool {
	p, _, _ := strings.Cut(strings.TrimSpace(path), "?")
	if p == "" {
		return false
	}
	if isClientRequestPath(p) {
		return false
	}
	if background {
		return true
	}
	switch {
	case strings.HasPrefix(p, "/ether/action/"),
		strings.HasPrefix(p, "/ether/job/"),
		strings.HasPrefix(p, "/ether/v1/flow-actions/"),
		p == "/ether/event",
		strings.HasPrefix(p, "/ether/tool/"),
		strings.HasPrefix(p, "/ether/v1/setup/"),
		p == "/ether/test",
		strings.HasPrefix(p, "/ether/feed/"),
		wasm.KindSyncPath(p),
		wasm.LiveTVSyncPath(p):
		return true
	}
	man.Ether = man.EffectiveEther()
	if man.Ether != nil {
		for _, s := range man.Ether.Schedule {
			callPath, _, _ := strings.Cut(strings.TrimSpace(s.Call), "?")
			if callPath == p {
				return true
			}
		}
		for _, fa := range man.Ether.Contributes.FlowActions {
			route, _, _ := strings.Cut(strings.TrimSpace(fa.Route), "?")
			if route == p {
				return true
			}
		}
	}
	return false
}

// ValidateMediaProbeSource validates the PlayableSource argument passed to
// media.probe. It accepts the same source shape /resolve returns.
func ValidateMediaProbeSource(src core.PlayableSource) error {
	pattern := strings.ToLower(strings.TrimSpace(src.Pattern))
	hasBlob := strings.TrimSpace(src.BlobRef) != ""
	if pattern == "" {
		switch {
		case src.Container != nil:
			pattern = "container"
		case src.Release != nil:
			pattern = "release"
		case strings.TrimSpace(src.Path) != "" && strings.TrimSpace(src.URL) == "" && !hasBlob:
			pattern = "file"
		default:
			pattern = "range"
		}
	}
	switch pattern {
	case "file":
		if strings.TrimSpace(src.Path) == "" {
			return &ValidationError{Fields: []FieldError{{Field: "path", Message: "file source requires path"}}}
		}
	case "release":
		if src.Release == nil {
			return &ValidationError{Fields: []FieldError{{Field: "release", Message: "release source requires release"}}}
		}
		r := src.Release
		hasTarget := strings.TrimSpace(r.InfoHash) != "" ||
			strings.TrimSpace(r.Magnet) != "" ||
			strings.TrimSpace(r.TorrentURL) != "" ||
			strings.TrimSpace(r.NZBURL) != ""
		if !hasTarget && r.Candidate != nil {
			c := r.Candidate
			hasTarget = strings.TrimSpace(c.InfoHash) != "" ||
				strings.TrimSpace(c.Magnet) != "" ||
				strings.TrimSpace(c.TorrentURL) != "" ||
				strings.TrimSpace(c.NZBURL) != "" ||
				(c.PluginRelease != nil && strings.TrimSpace(c.PluginRelease.Plugin) != "" && strings.TrimSpace(c.PluginRelease.ID) != "")
		}
		if !hasTarget {
			return &ValidationError{Fields: []FieldError{{Field: "release", Message: "release source requires infoHash, magnet, torrentUrl, nzbUrl, or candidate"}}}
		}
	case "container":
		if src.Container == nil {
			return &ValidationError{Fields: []FieldError{{Field: "container", Message: "container source requires container"}}}
		}
		if len(src.Container.Volumes) == 0 {
			return &ValidationError{Fields: []FieldError{{Field: "container.volumes", Message: "container source requires at least one volume"}}}
		}
		for i, v := range src.Container.Volumes {
			if strings.TrimSpace(v.URL) == "" && strings.TrimSpace(v.BlobRef) == "" {
				return &ValidationError{Fields: []FieldError{{Field: fmt.Sprintf("container.volumes[%d]", i), Message: "container volume requires url or blobRef"}}}
			}
		}
	case "range", "download", "direct":
		if strings.TrimSpace(src.URL) == "" && !hasBlob {
			return &ValidationError{Fields: []FieldError{{Field: "url", Message: pattern + " source requires url or blobRef"}}}
		}
	default:
		return &ValidationError{Fields: []FieldError{{Field: "pattern", Message: fmt.Sprintf("unknown source pattern %q", src.Pattern)}}}
	}
	return nil
}

// SetMediaProbeRateLimit overrides the per-plugin media.probe requests-per-minute
// limit. Passing <= 0 restores DefaultMediaProbePerMin. Intended for tests.
func (m *Manager) SetMediaProbeRateLimit(limit int) {
	m.mu.Lock()
	m.mediaProbeLimit = limit
	m.mu.Unlock()
}

func (m *Manager) mediaProbePerMin() int {
	m.mu.Lock()
	limit := m.mediaProbeLimit
	m.mu.Unlock()
	if limit <= 0 {
		return DefaultMediaProbePerMin
	}
	return limit
}

// MediaProbe reads container metadata ({durationSec, container, width, height,
// sizeBytes}) for a PlayableSource, reusing the durable release_probes cache
// when available. Requires permissions.media: "probe" (checked live against
// grants), is restricted to jobs, actions, sync, and other non-viewer routes,
// is rate-limited per plugin, and is hard-bounded at MediaProbeTimeout (10 s).
func (h *host) MediaProbe(ctx context.Context, src core.PlayableSource) (core.MediaProbeResult, error) {
	r, g, err := h.record(ctx)
	if err != nil {
		return core.MediaProbeResult{}, err
	}
	var level string
	if r.Manifest.Ether != nil {
		level = normLevel(r.Manifest.Ether.Permissions.Media)
	}
	if err := h.deny(r, g, "media", level, MediaPermissionAllowsProbe); err != nil {
		return core.MediaProbeResult{}, err
	}

	if path := callPathFromContext(ctx); path != "" {
		if !MediaProbeAllowedPath(r.Manifest, path, isBackgroundCall(ctx) || wasm.IsBackgroundCall(ctx)) {
			h.noteDenied("media_client_path")
			return core.MediaProbeResult{}, fmt.Errorf("%w: media.probe cannot run on viewer or client request path %s", ErrPermissionDenied, path)
		}
	}

	if err := ValidateMediaProbeSource(src); err != nil {
		return core.MediaProbeResult{}, err
	}

	h.m.mu.Lock()
	backend := h.m.deps.Backends.MediaProbe
	h.m.mu.Unlock()
	if backend == nil {
		return core.MediaProbeResult{}, ErrUnavailable
	}

	limit := h.m.mediaProbePerMin()
	if !h.m.rateOK(h.m.mediaProbeTimes, h.plugin, limit, time.Minute) {
		return core.MediaProbeResult{}, fmt.Errorf("%w: media.probe exceeds %d requests/minute", ErrRateLimited, limit)
	}

	pctx, cancel := context.WithTimeout(ctx, MediaProbeTimeout)
	defer cancel()
	return backend(pctx, h.plugin, src)
}

// BeginAdapterUpload reserves request-scoped staging for a declared adapter
// upload route and returns the effective limit for the HTTP body reader.
// The proxy calls it after authenticating the viewer.
func (m *Manager) BeginAdapterUpload(ctx context.Context, id, key, subpath string, size int64) (*blobcache.Upload, int64, error) {
	if m.deps.DurableStorage == nil {
		return nil, 0, ErrUnavailable
	}
	r, err := m.store.record(ctx, id)
	if err != nil {
		return nil, 0, err
	}
	if !r.Enabled || !r.Manifest.HasCapability(CapFrontendAdapter) {
		return nil, 0, ErrPermissionDenied
	}
	if e := r.Manifest.EffectiveEther(); e != nil {
		for _, adapter := range e.Contributes.FrontendAdapters {
			if adapter.Key != key {
				continue
			}
			limit := min(adapter.UploadLimit(subpath), adapterUploadCeiling(m.runtimeConfig().RuntimeOverrides[id].UploadBytes))
			if limit == 0 {
				break
			}
			if size > limit {
				return nil, 0, blobcache.ErrTooLarge
			}
			if size <= 0 {
				size = limit
			}
			upload, err := m.deps.DurableStorage.BeginUpload(id, size)
			return upload, limit, err
		}
	}
	return nil, 0, ErrPermissionDenied
}

func adapterUploadCeiling(configured int64) int64 {
	if configured <= 0 {
		return DefaultAdapterUploadBytes
	}
	return min(configured, MaxAdapterUploadBytes)
}

// Remote host callbacks can arrive without the viewer token. Track active
// interactive calls by plugin so a sidecar cannot accidentally hash a large
// blob while answering one of those calls.
func (m *Manager) trackRemoteClientCall(man Manifest, path string) func() {
	if man.RuntimeKind() != "remote" || !(isClientRequestPath(path) || isFrontendAdapterPath(path)) {
		return func() {}
	}
	m.remoteClientMu.Lock()
	if m.activeRemoteClients == nil {
		m.activeRemoteClients = make(map[string]int)
	}
	m.activeRemoteClients[man.ID]++
	m.remoteClientMu.Unlock()
	return sync.OnceFunc(func() {
		m.remoteClientMu.Lock()
		if m.activeRemoteClients[man.ID] == 1 {
			delete(m.activeRemoteClients, man.ID)
		} else {
			m.activeRemoteClients[man.ID]--
		}
		m.remoteClientMu.Unlock()
	})
}

func (m *Manager) remoteClientActive(pluginID string) bool {
	m.remoteClientMu.Lock()
	defer m.remoteClientMu.Unlock()
	return m.activeRemoteClients[pluginID] > 0
}

// CacheStat retrieves the digests of an owned blob. Only small cold reads are
// admitted on viewer paths, and cached or staged answers require no hashing.
func (h *host) CacheStat(ctx context.Context, ref string) (blobcache.Stat, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	src, err := h.cacheOpen(ctx, ref, true)
	if err != nil {
		if errors.Is(err, blobcache.ErrNotFound) {
			err = ErrNotFound
		}
		return blobcache.Stat{}, err
	}
	defer src.Close()
	maxBytes := blobcache.MaxStatBytes
	path := callPathFromContext(ctx)
	_, viewer := ViewerFromContext(ctx)
	if viewer || isClientRequestPath(path) ||
		(path != "" && !h.allowsLongFetchToCache(ctx)) ||
		(path == "" && h.m.remoteClientActive(h.plugin)) {
		maxBytes = blobcache.InteractiveStatBytes
	}
	stat, err := blobcache.StatOwned(ctx, blobcache.Ref(ref), src, maxBytes)
	return stat, storageError(err)
}

func (h *host) durableWriteCheck(ctx context.Context) error {
	if err := h.requireWritableToolContext(ctx); err != nil {
		return err
	}
	return h.durableReadCheck(ctx)
}

func (h *host) durableReadCheck(ctx context.Context) error {
	r, g, err := h.record(ctx)
	if err != nil {
		return err
	}
	return h.deny(r, g, "storage", storagePermission(r.Manifest), allowsDurableStorage)
}

func storagePermission(m Manifest) string {
	if e := m.EffectiveEther(); e != nil {
		return normLevel(string(e.Permissions.Storage))
	}
	return "none"
}

func (m *Manager) grantedDurableQuota(man Manifest) *blobcache.DurableQuota {
	s := m.deps.DurableStorage
	if s == nil || !allowsDurableStorage(storagePermission(man)) {
		return nil
	}
	quota := s.Quota(man.ID)
	return &quota
}

func (h *host) cachePutDurable(ctx context.Context, name string, body []byte, fromBlob string) (string, error) {
	h.m.storageMu.RLock()
	defer h.m.storageMu.RUnlock()
	if err := h.durableWriteCheck(ctx); err != nil {
		return "", err
	}
	s := h.m.deps.DurableStorage
	if s == nil {
		return "", ErrUnavailable
	}
	if err := ctx.Err(); err != nil {
		return "", err
	}
	if fromBlob != "" {
		ref, err := s.Promote(h.plugin, blobcache.Ref(fromBlob))
		return ref.String(), storageError(err)
	}
	upload, err := s.BeginUpload(h.plugin, int64(len(body)))
	if err != nil {
		return "", storageError(err)
	}
	defer upload.Close()
	ref, _, err := upload.Stage(ctx, name, "", bytes.NewReader(body))
	if err != nil {
		return "", storageError(err)
	}
	out, err := s.Promote(h.plugin, ref)
	return out.String(), storageError(err)
}

type cachePutOptions struct {
	Durable  bool   `json:"durable"`
	FromBlob string `json:"fromBlob"`
}

func callCachePut(ctx context.Context, h Host, args []json.RawMessage) (map[string]string, error) {
	bad := func() error {
		return &ValidationError{Fields: []FieldError{{Field: "cache.put", Message: "expected (libraryKey, name, data[, {durable, fromBlob}])"}}}
	}
	var library, name string
	var opts cachePutOptions
	if len(args) < 3 || len(args) > 4 ||
		json.Unmarshal(args[0], &library) != nil || json.Unmarshal(args[1], &name) != nil ||
		(len(args) == 4 && json.Unmarshal(args[3], &opts) != nil) {
		return nil, bad()
	}
	if (opts.Durable && library != "") || (opts.FromBlob != "" && (!opts.Durable || string(args[2]) != "null")) {
		return nil, bad()
	}
	var body []byte
	if opts.FromBlob != "" {
		if err := validateBlobRef(opts.FromBlob); err != nil {
			return nil, err
		}
	} else {
		var plain string
		if json.Unmarshal(args[2], &plain) == nil {
			body = []byte(plain)
		} else {
			var data struct {
				Body       string `json:"body"`
				BodyBase64 string `json:"bodyBase64"`
			}
			if json.Unmarshal(args[2], &data) != nil {
				return nil, bad()
			}
			body = []byte(data.Body)
			if data.BodyBase64 != "" {
				var err error
				body, err = base64.StdEncoding.DecodeString(data.BodyBase64)
				if err != nil {
					return nil, bad()
				}
			}
		}
	}
	var ref string
	var err error
	if opts.Durable {
		service, ok := h.(interface {
			cachePutDurable(context.Context, string, []byte, string) (string, error)
		})
		if !ok {
			return nil, ErrUnavailable
		}
		ref, err = service.cachePutDurable(ctx, name, body, opts.FromBlob)
	} else {
		ref, err = h.CachePut(ctx, library, name, bytes.NewReader(body))
	}
	return map[string]string{"blob": ref}, err
}

func (h *host) openDurableBlob(ctx context.Context, ref string) (io.ReadSeekCloser, error) {
	if err := h.durableReadCheck(ctx); err != nil {
		return nil, err
	}
	s := h.m.deps.DurableStorage
	if s == nil {
		return nil, ErrUnavailable
	}
	src, err := s.Open(h.plugin, blobcache.Ref(ref))
	return src, storageError(err)
}

// CacheUsage reports saved blob usage for this plugin's namespace.
func (h *host) CacheUsage(ctx context.Context) (blobcache.DurableUsage, error) {
	if err := h.durableReadCheck(ctx); err != nil {
		return blobcache.DurableUsage{}, err
	}
	s := h.m.deps.DurableStorage
	if s == nil {
		return blobcache.DurableUsage{}, ErrUnavailable
	}
	out, err := s.Usage(h.plugin)
	return out, storageError(err)
}

func (h *host) deleteDurableBlob(ctx context.Context, ref string) error {
	h.m.storageMu.RLock()
	defer h.m.storageMu.RUnlock()
	if err := h.durableWriteCheck(ctx); err != nil {
		return err
	}
	s := h.m.deps.DurableStorage
	if s == nil {
		return ErrUnavailable
	}
	_, err := s.Delete(h.plugin, blobcache.Ref(ref))
	return storageError(err)
}

// HotRuntime is implemented by hosted runtimes whose plugin exports the
// hot-path ABI (SPEC §5.2): ranking steps and rule conditions. The ranking
// adapters reach it through Manager.Hot. Budgets are the manifest's
// (lowered, never raised) and every call reports a classified outcome.
type HotRuntime interface {
	Runtime
	// RankBatch returns one key per candidate (higher ranks first). A
	// candidate that exceeded its budget gets the neutral key 0 and counts
	// in HotOutcome.Slow; a batch that ran out of time returns neutral keys
	// for the rest.
	RankBatch(ctx context.Context, cands []CandidateFacts, config json.RawMessage) (keys []int64, out HotOutcome, err error)
	// CondMatch evaluates a rule condition; false when the budget runs out.
	CondMatch(ctx context.Context, cand CandidateFacts, operator string, value json.RawMessage) (match bool, out HotOutcome, err error)
	HasRankKey() bool
	HasCondMatch() bool
	// Budgets reports the effective per-candidate and per-batch limits.
	Budgets() HotBudgets
}

// HotOutcome classifies one hot-path call for health and replay.
type HotOutcome struct {
	// Status is ok, error, timeout, forbidden, aborted or governance.
	Status   string        `json:"status"`
	Duration time.Duration `json:"durationNs"`
	Units    int64         `json:"units"`
	// Slow counts candidates that went neutral on budget.
	Slow     int  `json:"slow"`
	MemoHits int  `json:"memoHits"`
	Trap     bool `json:"trap,omitempty"`
}

// Timeout reports whether the call ran out of time or budget.
func (o HotOutcome) Timeout() bool {
	return o.Status == string(wasm.StatusTimeout) || o.Status == string(wasm.StatusGovernance)
}

// HotBudgets are the effective hot-path limits for one plugin.
type HotBudgets struct {
	PerCandidate time.Duration `json:"perCandidateNs"`
	PerBatch     time.Duration `json:"perBatchNs"`
}

// rankingBudget is the manifest's per-step budget (SPEC §4.3: budget).
type rankingBudget struct {
	PerCandidateMicros int64 `json:"perCandidateMicros"`
	PerBatchMicros     int64 `json:"perBatchMicros"`
	PerBatchMillis     int64 `json:"perBatchMillis"`
}

// HotLimits lowers the runtime's hot-path defaults to the tightest budget a
// manifest declares across its ranking steps. The engine clamps anything
// above its defaults, so a manifest can lower budgets but never raise them.
// Studio replay uses it to run a plugin under its installed budgets.
func HotLimits(m Manifest) wasm.Limits {
	lim := RuntimeLimitsFor(m)
	if m.Ether == nil {
		return lim
	}
	for _, step := range m.Ether.Contributes.RankingSteps {
		if len(step.Budget) == 0 {
			continue
		}
		var b rankingBudget
		if json.Unmarshal(step.Budget, &b) != nil {
			continue
		}
		if b.PerCandidateMicros > 0 {
			d := time.Duration(b.PerCandidateMicros) * time.Microsecond
			if lim.RankPerCandidate == 0 || d < lim.RankPerCandidate {
				lim.RankPerCandidate = d
			}
		}
		batch := time.Duration(b.PerBatchMicros) * time.Microsecond
		if b.PerBatchMillis > 0 {
			batch = time.Duration(b.PerBatchMillis) * time.Millisecond
		}
		if batch > 0 && (lim.RankBatch == 0 || batch < lim.RankBatch) {
			lim.RankBatch = batch
		}
	}
	return lim
}

func hotOutcome(o wasm.Outcome) HotOutcome {
	return HotOutcome{Status: string(o.Status), Duration: o.Duration, Units: o.Units, Slow: o.SlowCandidates, MemoHits: o.MemoHits, Trap: o.Trap}
}

// HostedRuntimeFactory opens hosted plugins (runtime.kind "hosted") on the
// wazero engine: JavaScript and TypeScript entries run on QuickJS, raw
// modules through the documented WASM ABI.
func HostedRuntimeFactory(eng *wasm.Engine) RuntimeFactory {
	return func(inst Installed) (Runtime, error) {
		if inst.Manifest.Ether == nil {
			return nil, fmt.Errorf("plugin %s: hosted plugins need an ether block", inst.ID)
		}
		decl := inst.Manifest.Ether.Runtime
		host := hostBridge{h: inst.Host}
		lim := HotLimits(inst.Manifest)
		lim.Stremio = inst.Manifest.SpeaksStremio()
		if inst.RuntimeLimits != nil {
			l := inst.RuntimeLimits
			lim.MemoryBytes = l.MemoryBytes
			lim.Deadline, _ = time.ParseDuration(l.Deadline)
			lim.UnitBudget = l.UnitBudget
			lim.PoolSize = l.PoolSize
		}
		lim.Busy = inst.Busy
		switch {
		case decl.Module != "":
			module, ok := inst.Files(decl.Module)
			if !ok {
				return nil, fmt.Errorf("plugin %s: module %q is missing", inst.ID, decl.Module)
			}
			p, err := eng.LoadWASM(inst.ID, inst.Manifest.Version, module, host, lim)
			if err != nil {
				return nil, err
			}
			return &hostedRuntime{p: p}, nil
		case decl.Entry != "":
			src, ok := inst.Files(decl.Entry)
			if !ok {
				return nil, fmt.Errorf("plugin %s: entry %q is missing", inst.ID, decl.Entry)
			}
			js := string(src)
			if ext := strings.ToLower(path.Ext(decl.Entry)); ext == ".ts" || ext == ".tsx" || ext == ".mts" {
				out, _, diags := wasm.Compile(map[string]string{decl.Entry: js}, decl.Entry)
				if err := diagnosticsError(diags); err != nil {
					return nil, fmt.Errorf("plugin %s: %w", inst.ID, err)
				}
				js = string(out)
			}
			p, err := eng.LoadJS(inst.ID, inst.Manifest.Version, js, host, lim)
			if err != nil {
				return nil, err
			}
			return &hostedRuntime{p: p}, nil
		default:
			return nil, fmt.Errorf("plugin %s: hosted runtime needs an entry or a module", inst.ID)
		}
	}
}

func diagnosticsError(diags []wasm.Diagnostic) error {
	var msgs []string
	for _, d := range diags {
		if d.Severity == "error" {
			msgs = append(msgs, d.Text)
		}
	}
	if len(msgs) == 0 {
		return nil
	}
	return errors.New("compile: " + strings.Join(msgs, "; "))
}

type hostedRuntime struct {
	p *wasm.Plugin
}

// EffectiveBudgets mirrors the engine's clamping: the budgets a manifest
// gets as SPEC 5.2 states them, in reference-machine time. The engine
// scales them by its measured speed (wasm.HotScale); Budgets reports that.
func EffectiveBudgets(lim wasm.Limits) HotBudgets {
	per, batch := lim.RankPerCandidate, lim.RankBatch
	if per <= 0 || per > wasm.DefaultRankPerCandidate {
		per = wasm.DefaultRankPerCandidate
	}
	if batch <= 0 || batch > wasm.DefaultRankBatch {
		batch = wasm.DefaultRankBatch
	}
	return HotBudgets{PerCandidate: per, PerBatch: batch}
}

// Budgets reports the limits in force on this machine: the manifest's,
// scaled by the engine's measured speed.
func (r *hostedRuntime) Budgets() HotBudgets {
	per, batch := r.p.Budgets()
	return HotBudgets{PerCandidate: per, PerBatch: batch}
}

func (r *hostedRuntime) Call(ctx context.Context, req Request) (Response, error) {
	q := make(map[string][]string, len(req.Query))
	for k, v := range req.Query {
		q[k] = []string{v}
	}
	for k, v := range req.RepeatedQuery {
		if len(v) > 1 {
			q[k] = append([]string(nil), v...)
		}
	}
	headers := req.Headers
	if req.Locale != "" {
		headers = cloneHeaders(headers)
		headers["X-Ether-Locale"] = req.Locale
	}
	resp, err := r.p.Call(ctx, wasm.Request{Op: req.Op, ID: req.ID, Method: req.Method, Path: req.Path, Query: q, Headers: headers, Body: req.Body, BodyBase64: req.BodyBase64, ContentType: req.ContentType, Upload: req.Upload, Foreground: req.Foreground, Deadline: req.Deadline, AISearch: req.AISearch})
	if err != nil {
		return Response{}, err
	}
	var blob *FrontendBlob
	if len(resp.Blob) > 0 {
		if err := json.Unmarshal(resp.Blob, &blob); err != nil {
			return Response{}, fmt.Errorf("invalid frontend blob response: %w", err)
		}
	}
	var media *FrontendMedia
	if len(resp.Media) > 0 && string(resp.Media) != "null" {
		if err := json.Unmarshal(resp.Media, &media); err != nil {
			return Response{}, fmt.Errorf("invalid frontend media response: %w", err)
		}
	}
	var art *FrontendArt
	if len(resp.Art) > 0 && string(resp.Art) != "null" {
		if err := json.Unmarshal(resp.Art, &art); err != nil {
			return Response{}, fmt.Errorf("invalid frontend art response: %w", err)
		}
	}
	return Response{Status: resp.Status, Headers: resp.Headers, Body: resp.Body, Blob: blob, Media: media, Art: art}, nil
}

func (r *hostedRuntime) RankBatch(ctx context.Context, cands []CandidateFacts, config json.RawMessage) ([]int64, HotOutcome, error) {
	in := make([]wasm.Candidate, len(cands))
	for i, c := range cands {
		facts, err := json.Marshal(c)
		if err != nil {
			return nil, HotOutcome{Status: string(wasm.StatusError)}, err
		}
		in[i] = wasm.Candidate{ReleaseID: c.ReleaseID, Facts: facts}
	}
	keys, out, err := r.p.RankBatch(ctx, in, config)
	return keys, hotOutcome(out), err
}

func (r *hostedRuntime) CondMatch(ctx context.Context, cand CandidateFacts, operator string, value json.RawMessage) (bool, HotOutcome, error) {
	facts, err := json.Marshal(cand)
	if err != nil {
		return false, HotOutcome{Status: string(wasm.StatusError)}, err
	}
	ok, out, err := r.p.CondMatch(ctx, wasm.Candidate{ReleaseID: cand.ReleaseID, Facts: facts}, operator, value)
	return ok, hotOutcome(out), err
}

func cloneHeaders(h map[string]string) map[string]string {
	out := make(map[string]string, len(h)+1)
	for k, v := range h {
		out[k] = v
	}
	return out
}

// Hot returns the hosted runtime of an enabled plugin when it exports the
// hot-path ABI, loading it if needed. It may block on a load, so it is for
// background work (replay, Studio); the play path uses HotReady.
func (m *Manager) Hot(ctx context.Context, pluginID string) (HotRuntime, bool) {
	r, err := m.Get(ctx, pluginID)
	if err != nil || !r.Enabled {
		return nil, false
	}
	rt, err := m.runtimeFor(ctx, r)
	if err != nil {
		return nil, false
	}
	hot, ok := rt.(HotRuntime)
	return hot, ok
}

// HotReady is the play-path accessor. It never blocks: it returns the
// plugin's hosted runtime only when it is already loaded, and otherwise
// starts loading it in the background and reports false, so the caller
// treats the plugin's steps and conditions as neutral for this resolve.
// Plugins in shadow mode are never ready on the play path. Runtimes are dropped on update, disable, remove and failure (closeRuntime)
// and warmed again when descriptors sync.
func (m *Manager) HotReady(pluginID string) (HotRuntime, bool) {
	m.mu.Lock()
	rt, ok := m.runtimes[pluginID]
	shadow := m.shadow[pluginID]
	m.mu.Unlock()
	if shadow {
		// A plugin in shadow mode never changes real picks; replay and the
		// shadow report show what it would have done.
		return nil, false
	}
	if !ok {
		m.warmAsync(pluginID)
		return nil, false
	}
	hot, ok := rt.(HotRuntime)
	return hot, ok
}

// prewarmHot loads, in the background, the runtime of an enabled plugin
// that contributes ranking steps or rule conditions, so the first resolve
// after start, install, update or enable finds it ready.
func (m *Manager) prewarmHot(r Record) {
	if !r.Enabled || r.Manifest.Ether == nil {
		return
	}
	c := r.Manifest.Ether.Contributes
	if len(c.RankingSteps) == 0 && len(c.RuleConditions) == 0 {
		return
	}
	m.warmAsync(r.ID)
}

// warmAsync loads one plugin's runtime once in the background.
func (m *Manager) warmAsync(pluginID string) {
	m.mu.Lock()
	if m.warming[pluginID] {
		m.mu.Unlock()
		return
	}
	m.warming[pluginID] = true
	m.mu.Unlock()
	go func() {
		defer func() {
			m.mu.Lock()
			delete(m.warming, pluginID)
			m.mu.Unlock()
		}()
		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()
		for attempt := 0; attempt < 3; attempt++ {
			r, err := m.Get(ctx, pluginID)
			if err != nil || !r.Enabled {
				return
			}
			_, err = m.runtimeFor(ctx, r)
			if err == nil {
				return
			}
			if errors.Is(err, ErrUnavailable) && attempt < 2 {
				continue
			}
			m.log.Warn("plugins: warm hot runtime", "plugin", pluginID, "err", err)
			return
		}
	}()
}

// hostBridge maps the hosted runtime's dotted host calls (positional JSON
// argument arrays) onto the Host interface. Grant checks, journalling and
// shadow mode all live behind Host.
type hostBridge struct{ h Host }

func (b hostBridge) CallHost(ctx context.Context, name string, raw json.RawMessage) (json.RawMessage, error) {
	if b.h == nil {
		return nil, wasm.Forbidden("no host services are configured for this plugin")
	}
	var args []json.RawMessage
	if len(raw) > 0 && string(raw) != "null" {
		if err := json.Unmarshal(raw, &args); err != nil {
			return nil, &wasm.Fault{Code: "bad_arguments", Message: "host arguments must be an array"}
		}
	}
	str := func(i int) string {
		var s string
		if i < len(args) {
			_ = json.Unmarshal(args[i], &s)
		}
		return s
	}
	num := func(i int) int64 {
		var n float64
		if i < len(args) {
			_ = json.Unmarshal(args[i], &n)
		}
		return int64(n)
	}
	result := func(v any, err error) (json.RawMessage, error) {
		if err != nil {
			return nil, mapHostError(err)
		}
		if v == nil {
			return json.RawMessage("null"), nil
		}
		if r, ok := v.(json.RawMessage); ok {
			return r, nil
		}
		out, err := json.Marshal(v)
		return out, err
	}
	if strings.HasPrefix(name, "kinds.") {
		if vs, ok := b.h.(interface {
			callViewerState(context.Context, string, []json.RawMessage) (any, error, bool)
		}); ok {
			if v, err, handled := vs.callViewerState(ctx, name, args); handled {
				return result(v, err)
			}
		}
	}
	switch name {
	case "runtime.limits", "http.hash", "http.fetchToCache", "cache.read", "cache.stat", "cache.usage", "cache.rasterize", "archive.list", "archive.open", "archive.read", "archive.extract":
		out, err := CallDataHost(ctx, b.h, name, raw)
		if err != nil {
			return nil, mapHostError(err)
		}
		return out, nil
	case "kv.get":
		v, ok, err := b.h.KVGet(ctx, str(0))
		if err != nil || !ok {
			return result(nil, err)
		}
		return result(string(v), nil)
	case "kv.put":
		var value string
		if len(args) > 1 {
			if err := json.Unmarshal(args[1], &value); err != nil {
				value = string(args[1]) // non-string values are stored as JSON text
			}
		}
		return result(nil, b.h.KVPut(ctx, str(0), []byte(value)))
	case "kv.delete":
		return result(nil, b.h.KVDelete(ctx, str(0)))
	case "kv.list":
		keys, err := b.h.KVList(ctx, str(0))
		return result(keys, err)
	case "kv.usage":
		usage, err := b.h.KVUsage(ctx)
		return result(usage, err)
	case "badges.set":
		var entries []BadgeEntry
		if len(args) > 1 && len(args[1]) > 0 && string(args[1]) != "null" {
			if err := json.Unmarshal(args[1], &entries); err != nil {
				return nil, &wasm.Fault{Code: "bad_arguments", Message: "badges.set takes (setKey, entries[])"}
			}
		}
		return result(nil, b.h.BadgesSet(ctx, str(0), entries))
	case "badges.clear":
		return result(nil, b.h.BadgesClear(ctx, str(0)))
	case "badges.usage":
		usage, err := b.h.BadgesUsage(ctx)
		return result(usage, err)
	case "settings.get":
		v, err := b.h.Settings(ctx)
		return result(v, err)
	case "secret.get":
		v, err := b.h.SecretGet(ctx, str(0))
		return result(v, err)
	case "secret.set":
		if len(args) < 2 {
			return nil, &wasm.Fault{Code: "bad_arguments", Message: "secret.set takes (name, value, ttlSec?)"}
		}
		var secName, secVal string
		if err := json.Unmarshal(args[0], &secName); err != nil {
			return nil, &wasm.Fault{Code: "bad_arguments", Message: "secret.set name must be a string"}
		}
