	_, _ = w.Write(out)
}

func (h *HostHandler) decode(w http.ResponseWriter, r *http.Request, max int64, into any) bool {
	raw, err := readBody(w, r, max)
	if err != nil {
		h.finishErr(w, err)
		return false
	}
	if err := json.Unmarshal(raw, into); err != nil {
		writeHostError(w, http.StatusBadRequest, "invalid", "Body is not valid JSON")
		return false
	}
	return true
}

// finishErr maps a host error onto the EPP error shape and reports
// whether the handler may continue. Host errors are mapped, never
// echoed raw: a storage error must not leak SQL or paths to a
// plugin.
func (h *HostHandler) finishErr(w http.ResponseWriter, err error) bool {
	if err == nil {
		return true
	}
	var blockedLocal *plugins.BlockedLocalHostError
	if errors.As(err, &blockedLocal) {
		writeHostError(w, http.StatusForbidden, "permission_denied", blockedLocal.PluginMessage())
		return false
	}
	var blockedOp *plugins.BlockedOperatorHostError
	if errors.As(err, &blockedOp) {
		writeHostError(w, http.StatusForbidden, "permission_denied", blockedOp.PluginMessage())
		return false
	}
	switch {
	case errors.Is(err, ErrPermissionDenied):
		writeHostError(w, http.StatusForbidden, "permission_denied", "This plugin does not have the grant this call needs")
	case errors.Is(err, ErrNotFound):
		writeHostError(w, http.StatusNotFound, "not_found", "Not found")
	case errors.Is(err, plugins.ErrQuotaExceeded):
		msg := strings.TrimPrefix(err.Error(), "remote: response body too large: ")
		writeHostError(w, http.StatusRequestEntityTooLarge, "quota_exceeded", msg)
	case errors.Is(err, ErrTooLarge):
		writeHostError(w, http.StatusRequestEntityTooLarge, "too_large", "Request body is too large")
	case errors.Is(err, ErrInvalid):
		writeHostError(w, http.StatusBadRequest, "invalid", cleanMessage(err))
	case errors.Is(err, ErrRateLimited):
		var rl *plugins.RateLimitError
		if errors.As(err, &rl) {
			sec := rl.RetryAfterSeconds(time.Now())
			if sec > 0 {
				w.Header().Set("Retry-After", strconv.FormatInt(sec, 10))
			}
			errObj := map[string]any{
				"code":    "rate_limited",
				"message": rl.Error(),
			}
			if sec > 0 {
				errObj["retryAfterSec"] = sec
			}
			if !rl.RetryAt.IsZero() {
				errObj["retryAt"] = rl.RetryAt.UTC().Format(time.RFC3339)
			}
			writeJSON(w, http.StatusTooManyRequests, map[string]any{"error": errObj})
			return false
		}
		writeHostError(w, http.StatusTooManyRequests, "rate_limited", strings.TrimPrefix(err.Error(), "remote: rate limit exceeded: "))
	case errors.Is(err, ErrNotConfigured):
		writeHostError(w, http.StatusNotImplemented, "not_configured", "Language model is not configured")
	case errors.Is(err, ErrInvalidOutput):
		writeHostError(w, http.StatusBadGateway, "invalid_output", "Language model returned invalid or oversized output")
	case errors.Is(err, ErrUnavailable):
		writeHostError(w, http.StatusServiceUnavailable, "unavailable", "This host service is not available")
	case errors.Is(err, ErrUnauthorized):
		writeHostError(w, http.StatusUnauthorized, "unauthorized", "Plugin credential rejected")
	case errors.Is(err, context.DeadlineExceeded):
		writeHostError(w, http.StatusGatewayTimeout, "deadline", "The call ran past its deadline")
	default:
		h.log.Warn("plugin host call failed", "err", err)
		writeHostError(w, http.StatusInternalServerError, "error", "The host call failed")
	}
	return false
}

// cleanMessage strips the sentinel prefix from an ErrInvalid so the
// plugin sees the specific reason ("path escapes...") only.
func cleanMessage(err error) string {
	msg := err.Error()
	msg = strings.TrimPrefix(msg, "remote: invalid request: ")
	msg = strings.TrimPrefix(msg, "remote: invalid request")
	if msg == "" {
		return "The request is not valid"
	}
	return msg
}

// pageParams reads limit/offset, or page/pageSize, clamped.
func pageParams(r *http.Request) (limit, offset int) {
	q := r.URL.Query()
	limit = defaultPageLimit
	if v, err := strconv.Atoi(q.Get("limit")); err == nil && v > 0 {
		limit = v
	}
	if v, err := paging.ParseOffset(q.Get("offset"), limit); err == nil && v >= 0 {
		offset = v
	}
	if q.Get("page") != "" {
		pageSize := limit
		if v, err := strconv.Atoi(q.Get("pageSize")); err == nil && v > 0 {
			pageSize = v
		}
		if v, err := strconv.Atoi(q.Get("page")); err == nil && v >= 1 {
			limit = pageSize
			offset = paging.PageOffset(v, pageSize)
		}
	}
	if limit > maxPageLimit {
		limit = maxPageLimit
	}
	return limit, offset
}

func readBody(w http.ResponseWriter, r *http.Request, max int64) ([]byte, error) {
	if r.Body == nil {
		return nil, nil
	}
	raw, err := io.ReadAll(io.LimitReader(r.Body, max+1))
	if err != nil {
		return nil, err
	}
	if int64(len(raw)) > max {
		return nil, ErrTooLarge
	}
	return raw, nil
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	httpjson.Write(w, status, v)
}

// writeHostError emits the EPP error shape (SPEC §5.1.2).
func writeHostError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, map[string]any{
		"error": map[string]any{"code": code, "message": message},
	})
}

// dataCall exposes only bounded blob/archive services, authenticated like all
// other plugin-host calls. HostAdapter performs the live grant checks.
func (h *HostHandler) dataCall(w http.ResponseWriter, r *http.Request) {
	var args json.RawMessage
	if !h.decode(w, r, maxHostBodyBytes, &args) {
		return
	}
	service, ok := h.host.(interface {
		CallDataHost(context.Context, string, string, json.RawMessage) (json.RawMessage, error)
	})
	if !ok {
		writeHostError(w, http.StatusServiceUnavailable, "unavailable", "Data services unavailable")
		return
	}
	name := r.PathValue("service")
	ctx := r.Context()
	if name == "cache.stat" && strings.TrimSpace(r.Header.Get(HeaderViewerToken)) != "" {
		ctx = plugins.WithCallContext(ctx, "/ether/v1/frontend/", "")
	}
	out, err := service.CallDataHost(ctx, pluginIDOf(r), name, args)
	if !h.finishErr(w, err) {
		return
	}
	writeJSON(w, http.StatusOK, out)
}

const (
	maxHashHeaders     = 32
	maxHashHeaderBytes = 16 << 10
)

func init() {
	store.Register("plugins", 8, `
CREATE TABLE plugins_remote_hashes(plugin TEXT NOT NULL,urlkey TEXT NOT NULL,etag TEXT NOT NULL,modified TEXT NOT NULL,size INTEGER NOT NULL,value BLOB NOT NULL,checked INTEGER NOT NULL,PRIMARY KEY(plugin,urlkey));
CREATE INDEX plugins_remote_hashes_age ON plugins_remote_hashes(plugin,checked);
CREATE TABLE plugins_remote_hash_budget(plugin TEXT PRIMARY KEY,day TEXT NOT NULL,bytes INTEGER NOT NULL);
`)
}

type HashRequest struct {
	URL        string `json:"url"`
	Algo       string `json:"algo"`
	ExpectSize *int64 `json:"expectSize,omitempty"`
	// Headers sends optional request headers with the hash fetch. Values may
	// use {secret:<name>} placeholders expanded via permissions.secrets;
	// hop-by-hop and framing headers are rejected, headers follow redirects
	// only under Ether's redirect credential policy (same origin, strict
	// same-site subdomain, or KeepHeadersOnRedirect within granted hosts), and
	// values are never logged or persisted in the hash cache.
	Headers map[string]string `json:"headers,omitempty"`
	// KeepHeadersOnRedirect lists optional host or wildcard (*.example.org)
	// patterns (within permissions.network / granted hosts) that may keep
	// credentials and caller headers across redirects. Never applies across
	// HTTPS -> HTTP downgrades.
	KeepHeadersOnRedirect []string `json:"keepHeadersOnRedirect,omitempty"`
}

// HashResult never includes remote bytes. All three digests share a single read.
type HashResult struct {
	Pending   bool   `json:"pending,omitempty"`
	RetryInMS int64  `json:"retryInMs,omitempty"`
	Size      int64  `json:"size"`
	SHA256    string `json:"sha256,omitempty"`
	SHA1      string `json:"sha1,omitempty"`
	MD5       string `json:"md5,omitempty"`
}

type remoteHashWork struct {
	key    string
	cancel context.CancelFunc
	done   chan struct{}
	err    error
	ended  time.Time
}

type remoteHashEntry struct {
	HashResult
	etag, modified string
	checked        int64
}

func validateHashHeaders(headers map[string]string, expanded bool) error {
	if len(headers) == 0 {
		return nil
	}
	if len(headers) > maxHashHeaders {
		return &ValidationError{Fields: []FieldError{{
			Field:   "headers",
			Message: fmt.Sprintf("at most %d headers are allowed", maxHashHeaders),
		}}}
	}
	seen := make(map[string]struct{}, len(headers))
	totalBytes := 0
	for name, val := range headers {
		if name == "" || !httpguts.ValidHeaderFieldName(name) {
			return &ValidationError{Fields: []FieldError{{
				Field:   "headers",
				Message: fmt.Sprintf("invalid header name %q", name),
			}}}
		}
		canonical := http.CanonicalHeaderKey(name)
		if forbiddenHashHeaders[canonical] {
			return &ValidationError{Fields: []FieldError{{
				Field:   "headers",
				Message: fmt.Sprintf("header %q is not allowed", canonical),
			}}}
		}
		if _, dup := seen[canonical]; dup {
			return &ValidationError{Fields: []FieldError{{
				Field:   "headers",
				Message: fmt.Sprintf("duplicate header %q", canonical),
			}}}
		}
		seen[canonical] = struct{}{}
		totalBytes += len(name) + len(val)
		if totalBytes > maxHashHeaderBytes {
			return &ValidationError{Fields: []FieldError{{
				Field:   "headers",
				Message: fmt.Sprintf("headers exceed %d bytes", maxHashHeaderBytes),
			}}}
		}
		if strings.ContainsAny(val, "\r\n\x00") || !httpguts.ValidHeaderFieldValue(val) {
			msg := fmt.Sprintf("header %q has an invalid HTTP header value", canonical)
			if expanded {
				msg = fmt.Sprintf("header %q expanded to an invalid HTTP header value", canonical)
			}
			return &ValidationError{Fields: []FieldError{{Field: "headers", Message: msg}}}
		}
	}
	return nil
}

func (h *host) expandHashHeaders(ctx context.Context, headers map[string]string) (map[string]string, error) {
	if len(headers) == 0 {
		return nil, nil
	}
	if err := validateHashHeaders(headers, false); err != nil {
		return nil, err
	}
	expanded, err := kindstream.ExpandHeaders(ctx, headers, h.SecretGet)
	if err != nil {
		if errors.Is(err, kindstream.ErrInvalidTemplate) {
			return nil, &ValidationError{Fields: []FieldError{{Field: "headers", Message: err.Error()}}}
		}
		return nil, err
	}
	if err := validateHashHeaders(expanded, true); err != nil {
		return nil, err
	}
	return expanded, nil
}

func (h *host) hashPermission(ctx context.Context, req HashRequest) error {
	if req.Algo != "sha256" && req.Algo != "sha1" && req.Algo != "md5" {
		return fmt.Errorf("plugins: hash algo must be sha256, sha1 or md5")
	}
	if req.ExpectSize != nil && (*req.ExpectSize < 0 || *req.ExpectSize > RemoteHashMaxBytes) {
		return fmt.Errorf("plugins: hash size outside limit")
	}
	u, err := url.Parse(req.URL)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Hostname() == "" {
		return ErrPermissionDenied
	}
	if err := h.allowNetworkURL(ctx, u); err != nil {
		return err
	}
	if len(req.KeepHeadersOnRedirect) > 0 {
		r, g, err := h.record(ctx)
		if err != nil {
			return err
		}
		if _, err := validateKeepHeadersOnRedirect(r.Manifest, g, req.KeepHeadersOnRedirect); err != nil {
			if errors.Is(err, ErrPermissionDenied) {
				h.noteDenied("network")
			}
			return err
		}
	}
	if _, err := h.expandHashHeaders(ctx, req.Headers); err != nil {
		return err
	}
	return nil
}

func (h *host) cachedRemoteHash(ctx context.Context, key string) (remoteHashEntry, error) {
	var e remoteHashEntry
	var data []byte
	err := h.m.store.db.QueryRowContext(ctx, `SELECT etag,modified,value,checked FROM plugins_remote_hashes WHERE plugin=? AND urlkey=?`, h.plugin, key).Scan(&e.etag, &e.modified, &data, &e.checked)
	if err == nil {
		err = json.Unmarshal(data, &e.HashResult)
	}
	return e, err
}

func (h *host) HTTPHash(ctx context.Context, req HashRequest) (HashResult, error) {
	if err := h.hashPermission(ctx, req); err != nil {
		return HashResult{}, err
	}
	key := fmt.Sprintf("%x", sha256.Sum256([]byte(req.URL)))
	e, err := h.cachedRemoteHash(ctx, key)
	if err != nil && !errors.Is(err, sql.ErrNoRows) {
		return HashResult{}, err
	}
	if err == nil && h.m.now().Sub(time.Unix(e.checked, 0)) < remoteHashFresh {
		if req.ExpectSize != nil && *req.ExpectSize != e.Size {
			return HashResult{}, fmt.Errorf("plugins: hash size did not match expectSize")
		}
		return e.HashResult, nil
	}
	m := h.m
	m.remoteHashMu.Lock()
	defer m.remoteHashMu.Unlock()
	if m.remoteHashes == nil {
		m.remoteHashes = map[string]*remoteHashWork{}
	}
	if work := m.remoteHashes[h.plugin]; work != nil {
		select {
		case <-work.done:
			// The worker may have committed after our first cache read.
			if work.key == key && work.err == nil {
				if fresh, err := h.cachedRemoteHash(ctx, key); err == nil && m.now().Sub(time.Unix(fresh.checked, 0)) < remoteHashFresh {
					if req.ExpectSize != nil && *req.ExpectSize != fresh.Size {
						return HashResult{}, fmt.Errorf("plugins: hash size did not match expectSize")
					}
					return fresh.HashResult, nil
				}
			}
			if work.key == key && work.err != nil && m.now().Sub(work.ended) < 30*time.Second {
				return HashResult{}, work.err
			}
		default:
			return HashResult{Pending: true, RetryInMS: 1000}, nil
		}
	}
	// Recheck enabled state under the cancellation lock so a disable cannot
	// race between authorization and registering this worker.
	if _, _, err := h.record(ctx); err != nil {
		return HashResult{}, err
	}
	workerReq := req
	if len(req.Headers) > 0 {
		workerReq.Headers = maps.Clone(req.Headers)
	}
	workCtx, cancel := context.WithTimeout(context.Background(), 12*time.Hour)
	w := &remoteHashWork{key: key, cancel: cancel, done: make(chan struct{})}
	m.remoteHashes[h.plugin] = w
	go func() {
		defer cancel()
		select {
		case folderHashSlots <- struct{}{}:
			defer func() { <-folderHashSlots }()
		case <-workCtx.Done():
			w.err = workCtx.Err()
			close(w.done)
			return
		}
		// Waiting plugins consume a goroutine, never a dedicated OS thread.
		runtime.LockOSThread()
		lowerJobPriority()
		w.err = h.computeRemoteHash(workCtx, workerReq, key, e)
		w.ended = m.now()
		close(w.done)
	}()
	return HashResult{Pending: true, RetryInMS: 1000}, nil
}

func (m *Manager) cancelRemoteHashes(id string) {
	m.remoteHashMu.Lock()
	defer m.remoteHashMu.Unlock()
	for plugin, w := range m.remoteHashes {
		if id == "" || plugin == id {
			w.cancel()
		}
	}
}

func (h *host) computeRemoteHash(ctx context.Context, req HashRequest, key string, old remoteHashEntry) error {
	if err := wasm.WaitBackground(ctx, h.m.deps.Busy); err != nil {
		return err
	}
	expanded, err := h.expandHashHeaders(ctx, req.Headers)
	if err != nil {
		return err
	}
	headers := make(map[string]string, len(expanded)+3)
	stripCrossOrigin := make([]string, 0, len(expanded))
	for k, v := range expanded {
		ck := http.CanonicalHeaderKey(k)
		if ck == "Accept-Encoding" || ck == "If-None-Match" || ck == "If-Modified-Since" {
			continue
		}
		headers[ck] = v
		stripCrossOrigin = append(stripCrossOrigin, ck)
	}
	headers["Accept-Encoding"] = "identity"
	if old.etag != "" {
		headers["If-None-Match"] = old.etag
	} else if old.modified != "" {
		headers["If-Modified-Since"] = old.modified
	}
	fetchCtx, cancel := context.WithTimeout(ctx, 10*time.Minute)
	defer cancel()
	resp, err := h.openFetchWithOptions(fetchCtx, FetchRequest{
		URL:                   req.URL,
		Headers:               headers,
		KeepHeadersOnRedirect: req.KeepHeadersOnRedirect,
	}, fetchOptions{
		stripCrossOriginHeaders: stripCrossOrigin,
		stripAllCallerHeaders:   true,
	})
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode == 304 && old.SHA256 != "" {
		_, err = h.m.store.db.ExecContext(ctx, `UPDATE plugins_remote_hashes SET checked=? WHERE plugin=? AND urlkey=?`, h.m.now().Unix(), h.plugin, key)
		return err
	}
	if resp.StatusCode != 200 {
		return fmt.Errorf("plugins: hash HTTP %d", resp.StatusCode)
	}
	if resp.ContentLength > RemoteHashMaxBytes {
		return fmt.Errorf("plugins: hash size outside limit")
	}
	if req.ExpectSize != nil && resp.ContentLength >= 0 && resp.ContentLength != *req.ExpectSize {
		return fmt.Errorf("plugins: hash size did not match expectSize")
	}
	// Reserve the remaining allowance durably before reading. An interrupted
	// process conservatively keeps its reservation; normal completion refunds it.
	day := h.m.now().UTC().Format("2006-01-02")
	_, err = h.m.store.db.ExecContext(ctx, `INSERT INTO plugins_remote_hash_budget(plugin,day,bytes) VALUES(?,?,0) ON CONFLICT(plugin) DO UPDATE SET day=excluded.day,bytes=0 WHERE plugins_remote_hash_budget.day<>excluded.day`, h.plugin, day)
	if err != nil {
		return err
	}
	var used int64
	if err = h.m.store.db.QueryRowContext(ctx, `SELECT bytes FROM plugins_remote_hash_budget WHERE plugin=?`, h.plugin).Scan(&used); err != nil {
		return err
	}
	allowance := RemoteHashDailyBytes - used
	if allowance <= 0 {
		h.m.log.Info("plugins: daily hash byte budget reached", "plugin", h.plugin)
		return fmt.Errorf("plugins: daily hash byte budget reached")
	}
	if resp.ContentLength > allowance {
		h.m.log.Info("plugins: daily hash byte budget reached", "plugin", h.plugin)
		return fmt.Errorf("plugins: daily hash byte budget reached")
	}
	reserve := allowance
	if resp.ContentLength >= 0 {
		reserve = resp.ContentLength
	}
	reservation, err := h.m.store.db.ExecContext(ctx, `UPDATE plugins_remote_hash_budget SET bytes=bytes+? WHERE plugin=? AND day=? AND bytes+?<=?`, reserve, h.plugin, day, reserve, RemoteHashDailyBytes)
	if err != nil {
		return err
	}
	if n, err := reservation.RowsAffected(); err != nil {
		return err
	} else if n != 1 {
		h.m.log.Info("plugins: daily hash byte budget reached", "plugin", h.plugin)
		return fmt.Errorf("plugins: daily hash byte budget reached")
	}
	var size int64
	defer func() {
		refundCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		_, _ = h.m.store.db.ExecContext(refundCtx, `UPDATE plugins_remote_hash_budget SET bytes=bytes-? WHERE plugin=? AND day=?`, max(int64(0), reserve-size), h.plugin, day)
	}()
	a, b, c := sha256.New(), sha1.New(), md5.New()
	buf := make([]byte, 256<<10)
	var checkedGrants time.Time
	limit := min(RemoteHashMaxBytes, reserve)
	for {
		if err = wasm.WaitBackground(ctx, h.m.deps.Busy); err != nil {
			return err
		}
		// Recheck grants at most once a second rather than querying the store
		// for every chunk. Disable/uninstall also cancels the read context.
		if time.Since(checkedGrants) >= time.Second {
			if err = h.hashPermission(ctx, req); err != nil {
				return err
			}
			checkedGrants = time.Now()
		}
		n, readErr := resp.Body.Read(buf[:min(int64(len(buf)), limit-size+1)])
		size += int64(n)
		if size > limit {
			return fmt.Errorf("plugins: hash exceeded byte limit")
		}
		if n > 0 {
			_, _ = a.Write(buf[:n])
			_, _ = b.Write(buf[:n])
			_, _ = c.Write(buf[:n])
		}
		if readErr == io.EOF {
			break
		}
		if readErr != nil {
			return fetchError(resp.Request.URL.Hostname(), readErr)
		}
	}
	if req.ExpectSize != nil && size != *req.ExpectSize {
		return fmt.Errorf("plugins: hash size did not match expectSize")
	}
	result := HashResult{Size: size, SHA256: fmt.Sprintf("%x", a.Sum(nil)), SHA1: fmt.Sprintf("%x", b.Sum(nil)), MD5: fmt.Sprintf("%x", c.Sum(nil))}
	data, _ := json.Marshal(result)
	_, err = h.m.store.db.ExecContext(ctx, `INSERT INTO plugins_remote_hashes(plugin,urlkey,etag,modified,size,value,checked) VALUES(?,?,?,?,?,?,?) ON CONFLICT(plugin,urlkey) DO UPDATE SET etag=excluded.etag,modified=excluded.modified,size=excluded.size,value=excluded.value,checked=excluded.checked`, h.plugin, key, resp.Header.Get("ETag"), resp.Header.Get("Last-Modified"), size, data, h.m.now().Unix())
	if err != nil {
		return err
	}
	_, err = h.m.store.db.ExecContext(ctx, `DELETE FROM plugins_remote_hashes WHERE plugin=? AND urlkey IN (SELECT urlkey FROM plugins_remote_hashes WHERE plugin=? ORDER BY checked DESC LIMIT 2147483647 OFFSET 2048)`, h.plugin, h.plugin)
	return err
}

func applyRuntimeCeilings(c runtimeCeilings, l config.PluginRuntimeLimits) runtimeCeilings {
	if l.MemoryBytes > 0 {
		c.memory = min(l.MemoryBytes, uint64(wasm.MaxMemoryBytes))
	}
	if d, err := time.ParseDuration(l.Deadline); err == nil && d > 0 {
		c.deadline = min(d, 365*24*time.Hour)
	}
	if l.UnitBudget > 0 {
		c.units = l.UnitBudget
	}
	if l.PoolSize > 0 {
		c.poolSize = min(l.PoolSize, wasm.MaxPoolSize)
	}
	if l.FetchBytes > 0 {
		c.fetch = min(l.FetchBytes, int64(1<<60))
	}
	if l.ArchiveMemberBytes > 0 {
		c.member = min(l.ArchiveMemberBytes, int64(1<<60))
	}
	if l.ArchiveExpandedBytes > 0 {
		c.expanded = min(l.ArchiveExpandedBytes, int64(1<<60))
	}
	if l.ArchiveMembers > 0 {
		c.members = min(l.ArchiveMembers, 1000000)
	}
	if l.MaxItems > 0 {
		c.maxItems = l.MaxItems
	}
	if l.ListItems > 0 {
		c.listItems = min(l.ListItems, MaxListItems)
	}
	return c
}

func (m *Manager) runtimeConfig() config.Plugins {
	if m != nil && m.deps.ReadRuntimeConfig != nil {
		return m.deps.ReadRuntimeConfig()
	}
	return config.Plugins{}
}

func (m *Manager) runtimeCeilings(id string) runtimeCeilings {
	cfg := m.runtimeConfig()
	c := applyRuntimeCeilings(defaultRuntimeCeilings(), cfg.RuntimeLimits)
	return applyRuntimeCeilings(c, cfg.RuntimeOverrides[id])
}

func (m *Manager) grantedMaxItems(man Manifest, c runtimeCeilings) int {
	n := c.maxItems
	if m != nil && m.runtimeConfig().RuntimeOverrides[man.ID].MaxItems > 0 {
		return n
	}
	if man.Ether != nil && man.Ether.Runtime.Limits != nil && man.Ether.Runtime.Limits.MaxItems > 0 {
		n = min(n, man.Ether.Runtime.Limits.MaxItems)
	}
	return n
}

// MaxPluginItems returns the effective stored-item ceiling across all content
// libraries owned by id (default 2,000,000; owner-configurable globally and per
// plugin with no upper bound).
func (m *Manager) MaxPluginItems(id string) int {
	if m == nil {
		return DefaultMaxPluginItems
	}
	c := m.runtimeCeilings(id)
	if m.store != nil && id != "" {
		if rec, err := m.store.record(context.Background(), id); err == nil {
			return m.grantedMaxItems(rec.Manifest, c)
		}
	}
	return c.maxItems
}

func runtimeLimitsWithCeilings(m Manifest, c runtimeCeilings) wasm.Limits {
	l := wasm.Limits{
		MemoryBytes: min(uint64(32<<20), c.memory),
		Deadline:    c.deadline,
		UnitBudget:  c.units,
		PoolSize:    min(wasm.DefaultPoolSize, c.poolSize),
		Stremio:     m.SpeaksStremio(),
	}
	if m.Ether != nil && m.Ether.Runtime.Limits != nil {
		r := m.Ether.Runtime.Limits
		if r.MemoryBytes > 0 {
			l.MemoryBytes = min(r.MemoryBytes, c.memory)
		}
		if d, err := time.ParseDuration(r.Deadline); err == nil && d > 0 {
			l.Deadline = min(d, c.deadline)
		}
		if r.UnitBudget > 0 {
			l.UnitBudget = min(r.UnitBudget, c.units)
		}
		if r.PoolSize > 0 {
			l.PoolSize = min(r.PoolSize, c.poolSize)
		}
	}
	return l
}

func (m *Manager) grantedPoolSize(man Manifest, c runtimeCeilings) int {
	if m != nil && m.runtimeConfig().RuntimeOverrides[man.ID].PoolSize > 0 {
		return c.poolSize
	}
	n := min(wasm.DefaultPoolSize, c.poolSize)
	if man.Ether != nil && man.Ether.Runtime.Limits != nil && man.Ether.Runtime.Limits.PoolSize > 0 {
		n = min(man.Ether.Runtime.Limits.PoolSize, c.poolSize)
	}
	return n
}

func (m *Manager) grantedRuntimeLimits(man Manifest) *RuntimeLimits {
	if man.RuntimeKind() != "hosted" {
		return nil
	}
	c := m.runtimeCeilings(man.ID)
	l := runtimeLimitsWithCeilings(man, c)
	r := &RuntimeLimits{
		MemoryBytes: l.MemoryBytes,
		ReadBytes:   wasm.DataReadBytes(l.MemoryBytes),
		Deadline:    l.Deadline.String(),
		UnitBudget:  l.UnitBudget,
		PoolSize:    m.grantedPoolSize(man, c),
	}
	r.FetchBytes = c.fetch
	r.ArchiveMemberBytes = c.member
	r.ArchiveExpandedBytes = c.expanded
	r.ArchiveMembers = c.members
	r.MaxItems = m.grantedMaxItems(man, c)
	if req := man.Ether.Runtime.Limits; req != nil {
		if req.FetchBytes > 0 {
			r.FetchBytes = min(r.FetchBytes, req.FetchBytes)
		}
		if req.ArchiveMemberBytes > 0 {
			r.ArchiveMemberBytes = min(r.ArchiveMemberBytes, req.ArchiveMemberBytes)
		}
		if req.ArchiveExpandedBytes > 0 {
			r.ArchiveExpandedBytes = min(r.ArchiveExpandedBytes, req.ArchiveExpandedBytes)
		}
		if req.ArchiveMembers > 0 {
			r.ArchiveMembers = min(r.ArchiveMembers, req.ArchiveMembers)
		}
	}
	return r
}

func (m *Manager) handleRuntimeLimits(w http.ResponseWriter, r *http.Request) {
	plugin := r.URL.Query().Get("plugin")
	if r.Method == http.MethodPut {
		var req struct {
			Plugin string                     `json:"plugin"`
			Limits config.PluginRuntimeLimits `json:"limits"`
		}
		if err := decode(r, &req); err != nil {
			m.fail(w, err)
			return
		}
		if req.Limits.MemoryBytes > wasm.MaxMemoryBytes || req.Limits.UnitBudget < 0 || req.Limits.PoolSize < 0 || req.Limits.PoolSize > wasm.MaxPoolSize || req.Limits.FetchBytes < 0 || req.Limits.ArchiveMemberBytes < 0 || req.Limits.ArchiveExpandedBytes < 0 || req.Limits.ArchiveMembers < 0 || req.Limits.ArchiveMembers > 1000000 || req.Limits.MaxItems < 0 || req.Limits.ListItems < 0 || req.Limits.ListItems > MaxListItems {
			writeErr(w, http.StatusBadRequest, "validation", fmt.Sprintf("Memory must be at most 4 GiB, instances at most %d, titles per list at most %d, and resource limits must not be negative.", wasm.MaxPoolSize, MaxListItems), nil)
			return
		}
		if req.Limits.UploadBytes < 0 || req.Limits.UploadBytes > MaxAdapterUploadBytes || (req.Plugin == "" && req.Limits.UploadBytes != 0) {
			m.fail(w, &ValidationError{Fields: []FieldError{{Field: "uploadBytes", Message: "expected a per-plugin upload limit from 0 to 512 MiB"}}})
			return
		}
		plugin = req.Plugin
		if req.Limits.DurableBytes < 0 || req.Limits.DurableFiles < 0 ||
			(plugin == "" && (req.Limits.DurableBytes != 0 || req.Limits.DurableFiles != 0)) ||
			req.Limits.DurableFreePercent < 0 || req.Limits.DurableFreePercent > 100 ||
			(plugin != "" && req.Limits.DurableFreePercent != 0) {
			writeErr(w, http.StatusBadRequest, "durable_quota_invalid", "Invalid durable storage settings.", nil)
			return
		}
		if req.Limits.Deadline != "" {
			if d, err := time.ParseDuration(req.Limits.Deadline); err != nil || d <= 0 || d > 365*24*time.Hour {
				writeErr(w, http.StatusBadRequest, "validation", "Time limit must be positive and at most one year.", nil)
				return
			}
		}
		if req.Plugin != "" {
			if _, err := m.Get(r.Context(), req.Plugin); err != nil {
				m.fail(w, err)
				return
			}
		}
		if m.deps.SaveRuntimeConfig == nil {
			m.fail(w, fmt.Errorf("runtime settings are unavailable"))
			return
		}
		m.storageMu.Lock()
		cfg := m.runtimeConfig()
		before := cfg.RuntimeLimits
		if plugin != "" {
			before = cfg.RuntimeOverrides[plugin]
		}
		after := req.Limits
		if after.DurableBytes > before.DurableBytes || after.DurableFiles > before.DurableFiles {
			capacity, _ := m.deps.DurableStorage.Capacity(cfg.RuntimeLimits.DurableFreePercent)
			if (after.DurableBytes > before.DurableBytes && after.DurableBytes > capacity.Bytes) ||
				(after.DurableFiles > before.DurableFiles && after.DurableFiles > capacity.Files) {
				m.storageMu.Unlock()
				writeErr(w, http.StatusBadRequest, "durable_quota_ceiling", "Durable quota exceeds the current volume ceiling.", nil)
				return
			}
		}
		err := m.deps.SaveRuntimeConfig(plugin, after)
		m.storageMu.Unlock()
		if err != nil {
			m.fail(w, err)
			return
		}
		// Durable quotas are consulted live and do not require stopping plugin jobs.
		if runtimeLimitsWithoutDurable(before) != runtimeLimitsWithoutDurable(after) {
			recs, err := m.List(r.Context())
			if err != nil {
				m.fail(w, err)
				return
			}
			for _, rec := range recs {
				if plugin == "" || plugin == rec.ID {
					m.closeRuntime(rec.ID)
				}
			}
		}
		m.broadcast(r.Context())
	}
	cfg := m.runtimeConfig()
	out := struct {
		config.Plugins
		DurableStorage *durableLimitsStatus `json:"durableStorage,omitempty"`
	}{Plugins: cfg}
	if plugin != "" && m.deps.DurableStorage != nil {
		rec, err := m.Get(r.Context(), plugin)
		if err != nil {
			m.fail(w, err)
			return
		}
		if allowsDurableStorage(storagePermission(rec.Manifest)) {
			store := m.deps.DurableStorage
			capacity, diskErr := store.Capacity(cfg.RuntimeLimits.DurableFreePercent)
			usage, usageErr := store.Usage(plugin)
			out.DurableStorage = &durableLimitsStatus{
				Capacity: capacity, DiskAvailable: diskErr == nil,
			}
			if usageErr == nil {
				out.DurableStorage.Usage = &usage
			}
		}
	}
	writeJSON(w, http.StatusOK, out)
}

func runtimeLimitsWithoutDurable(l config.PluginRuntimeLimits) config.PluginRuntimeLimits {
	l.DurableBytes, l.DurableFiles, l.DurableFreePercent = 0, 0, 0
	return l
}

type durableLimitsStatus struct {
	Capacity      blobcache.DurableCapacity `json:"capacity"`
	DiskAvailable bool                      `json:"diskAvailable"`
	Usage         *blobcache.DurableUsage   `json:"usage,omitempty"`
}

type cachedCallRecord struct {
	m      *Manager
	plugin string
	rec    Record
}

func withCallRecord(ctx context.Context, h Host) context.Context {
	ph, ok := h.(*host)
	if !ok {
		return ctx
	}
	rec, err := ph.m.store.record(ctx, ph.plugin)
	if err != nil {
		return ctx
	}
	return context.WithValue(ctx, callRecordKey{}, cachedCallRecord{m: ph.m, plugin: ph.plugin, rec: rec})
}

func (h *host) callRecord(ctx context.Context) (Record, error) {
	if cached, ok := ctx.Value(callRecordKey{}).(cachedCallRecord); ok && cached.m == h.m && cached.plugin == h.plugin {
		return cached.rec, nil
	}
	return h.m.store.record(ctx, h.plugin)
}

// SourceDataLimits returns the same owner grants for a kind source download or
// extraction as a plugin-initiated fetchToCache or archive.extract operation.
func (m *Manager) SourceDataLimits(ctx context.Context, pluginID string) RuntimeLimits {
	return (&host{m: m, plugin: pluginID}).DataLimits(ctx)
}

// DataLimits exposes owner grants to shared hosted/remote data services.
func (h *host) DataLimits(ctx context.Context) RuntimeLimits {
	rec, err := h.callRecord(ctx)
	if err == nil {
		if l := h.m.grantedRuntimeLimits(rec.Manifest); l != nil {
			return *l
		}
	}
	c := h.m.runtimeCeilings(h.plugin)
	maxItems := c.maxItems
	if err == nil {
		maxItems = h.m.grantedMaxItems(rec.Manifest, c)
	}
	return RuntimeLimits{
		FetchBytes:           c.fetch,
		ArchiveMemberBytes:   c.member,
		ArchiveExpandedBytes: c.expanded,
		ArchiveMembers:       c.members,
		MaxItems:             maxItems,
		MemoryBytes:          c.memory,
		ReadBytes:            wasm.DataReadBytes(c.memory),
		Deadline:             c.deadline.String(),
	}
}

// NonSecretSettings applies declared defaults, then stored public settings.
// Explicit zero, false, empty and null values take precedence over defaults.
// Studio uses the same secret field classifier as installed settings storage.
func NonSecretSettings(settings map[string]any, schema json.RawMessage, declaredSecrets []string) map[string]any {
	secretNames := secretFieldNames(schema)
	for _, key := range declaredSecrets {
		secretNames[key] = true
	}
	out := make(map[string]any, len(settings))
	var doc map[string]any
	if json.Unmarshal(schema, &doc) == nil {
		visitSettingsFields(doc, func(key string, field map[string]any) {
			if field["kind"] == "secret" || field["type"] == "secret" {
				secretNames[key] = true
			}
		})
		visitSettingsFields(doc, func(key string, field map[string]any) {
			if value, exists := field["default"]; exists && !secretNames[key] {
				out[key] = value
			}
		})
	}
	for key, value := range settings {
		if !secretNames[key] {
			out[key] = value
		}
	}
	return out
}

// Only traverse the schema's supported field containers, never default values or
// arbitrary nested objects that happen to contain a key/default pair.
func visitSettingsFields(doc map[string]any, visit func(string, map[string]any)) {
	for _, container := range []string{"fields", "groups"} {
		entries, _ := doc[container].([]any)
		for _, entry := range entries {
			field, ok := entry.(map[string]any)
			if !ok {
				continue
			}
			if container == "fields" && field["kind"] != "group" {
				if key, ok := firstString(field, "key", "name", "id", "field"); ok {
					visit(key, field)
				}
			}
			visitSettingsFields(field, visit)
		}
	}
	properties, _ := doc["properties"].(map[string]any)
	for key, raw := range properties {
		if field, ok := raw.(map[string]any); ok {
			visit(key, field)
		}
	}
}

func settingsSecrets(rec Record) []string {
	if rec.Manifest.Ether == nil {
		return nil
	}
	return rec.Manifest.Ether.Permissions.Secrets
}

func init() {
	// v5: guided-setup step results (spec §8), one row per step the
	// owner has tested or skipped.
	store.Register("plugins", 5, `CREATE TABLE plugins_setup(plugin TEXT NOT NULL,step TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',detail TEXT NOT NULL DEFAULT '',at INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(plugin,step));`)
}

// Setup step statuses stored in plugins_setup.
const (
	SetupPending = "pending"
	SetupOK      = "ok"
	SetupFailed  = "failed"
	SetupSkipped = "skipped"
)

// SetupStepState is the stored result of one setup step.
type SetupStepState struct {
	Step   string    `json:"step"`
	Status string    `json:"status"` // pending|ok|failed|skipped
	Detail string    `json:"detail,omitempty"`
	At     time.Time `json:"at"`
}

// SetupTestResult is the plugin's answer to a setup test call.
type SetupTestResult struct {
	OK     bool              `json:"ok"`
	Detail string            `json:"detail,omitempty"`
	Fields map[string]string `json:"fields,omitempty"` // settings key -> problem
}

func validateSetup(e *EtherBlock, add func(string, string), label func(string, string, int)) {
	if e.Contributes.Setup == nil {
		return
	}
	steps := e.Contributes.Setup.Steps
	if len(steps) == 0 {
		add("ether.contributes.setup.steps", "must list at least one step")
	}
	schemaFields := settingsFieldKeys(e.Settings)
	seen := map[string]bool{}
	for i, s := range steps {
		base := fmt.Sprintf("ether.contributes.setup.steps[%d]", i)
		if !keyRe.MatchString(s.Key) || seen[s.Key] {
			add(base+".key", "must be a unique simple key")
		}
		seen[s.Key] = true
		label(base+".label", s.Label, 60)
		if s.Hint != "" && !strings.HasPrefix(s.Hint, "$t:") {
			if msg := LintCopy(s.Hint, 120); msg != "" {
				add(base+".hint", msg)
			}
			if strings.Count(strings.TrimRight(s.Hint, "."), ".") > 0 {
				add(base+".hint", "must be one sentence")
			}
		}
		for j, f := range s.Fields {
			if !keyRe.MatchString(f) {
				add(fmt.Sprintf("%s.fields[%d]", base, j), "must be a settings field key")
			} else if schemaFields != nil && !schemaFields[f] {
				add(fmt.Sprintf("%s.fields[%d]", base, j), "is not a field in the settings schema")
			}
		}
		if s.Test != "" && !strings.HasPrefix(s.Test, "/") {
			add(base+".test", "must be a plugin route starting with /")
		}
	}
}

// settingsFieldKeys extracts every "key" string from an inline settings
// schema. A "$ref" schema is resolved at install, so it returns nil
// and field membership is not checked here.
func settingsFieldKeys(raw json.RawMessage) map[string]bool {
	if len(raw) == 0 {
		return map[string]bool{}
	}
	var doc any
	if err := json.Unmarshal(raw, &doc); err != nil {
		return nil
	}
	if obj, ok := doc.(map[string]any); ok {
		if _, isRef := obj["$ref"]; isRef {
			return nil
		}
	}
	out := map[string]bool{}
	var walk func(v any)
	walk = func(v any) {
		switch n := v.(type) {
		case map[string]any:
			if k, ok := n["key"].(string); ok {
				out[k] = true
			}
			for _, child := range n {
				walk(child)
			}
		case []any:
			for _, child := range n {
				walk(child)
			}
		}
	}
	walk(doc)
	return out
}

func (s *storage) setupState(ctx context.Context, plugin string) ([]SetupStepState, error) {
	rows, err := s.db.QueryContext(ctx, `SELECT step,status,detail,at FROM plugins_setup WHERE plugin=? ORDER BY step`, plugin)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []SetupStepState
	for rows.Next() {
		var st SetupStepState
		var at int64
		if err := rows.Scan(&st.Step, &st.Status, &st.Detail, &at); err != nil {
			return nil, err
		}
		st.At = time.Unix(at, 0).UTC()
		out = append(out, st)
	}
	return out, rows.Err()
}

func (s *storage) putSetupState(ctx context.Context, plugin, step, status, detail string) error {
	_, err := s.db.ExecContext(ctx, `INSERT INTO plugins_setup(plugin,step,status,detail,at) VALUES(?,?,?,?,?)
ON CONFLICT(plugin,step) DO UPDATE SET status=excluded.status,detail=excluded.detail,at=excluded.at`,
		plugin, step, status, detail, s.now().Unix())
	return err
}

// SetupState returns every recorded setup step result for a plugin,
// with unrecorded steps reported as pending, in manifest order.
func (m *Manager) SetupState(ctx context.Context, pluginID string) ([]SetupStepState, error) {
	r, err := m.Get(ctx, pluginID)
	if err != nil {
		return nil, err
	}
	stored, err := m.store.setupState(ctx, pluginID)
	if err != nil {
		return nil, err
	}
	byStep := map[string]SetupStepState{}
	for _, st := range stored {
		byStep[st.Step] = st
	}
	var out []SetupStepState
	if e := r.Manifest.EffectiveEther(); e != nil && e.Contributes.Setup != nil {
		for _, step := range e.Contributes.Setup.Steps {
			if st, ok := byStep[step.Key]; ok {
				out = append(out, st)
			} else {
				out = append(out, SetupStepState{Step: step.Key, Status: SetupPending})
			}
		}
	}
	return out, nil
}

// SetupBlockers lists the required setup steps still holding a plugin
// back: steps that have neither passed nor been skipped by the owner
// (spec §8). Content adapters keep libraries hidden and sync stopped
// while this is non-empty.
func (m *Manager) SetupBlockers(ctx context.Context, pluginID string) ([]string, error) {
	r, err := m.Get(ctx, pluginID)
	if err != nil {
		return nil, err
	}
	e := r.Manifest.EffectiveEther()
	if e == nil || e.Contributes.Setup == nil {
		return nil, nil
	}
	state, err := m.SetupState(ctx, pluginID)
	if err != nil {
		return nil, err
	}
	byStep := map[string]SetupStepState{}
	for _, st := range state {
		byStep[st.Step] = st
	}
	var blocked []string
	for _, step := range e.Contributes.Setup.Steps {
		if !step.Required {
			continue
		}
		if st := byStep[step.Key]; st.Status != SetupOK && st.Status != SetupSkipped {
			blocked = append(blocked, step.Key)
		}
	}
	return blocked, nil
}

func setupStepOf(r Record, key string) (SetupStep, bool) {
	if e := r.Manifest.EffectiveEther(); e != nil && e.Contributes.Setup != nil {
		for _, s := range e.Contributes.Setup.Steps {
			if s.Key == key {
				return s, true
			}
		}
	}
	return SetupStep{}, false
}

// TestSetupStep runs one setup step's test against the saved settings
// and records the result. Only the step's non-secret field values are
// sent; secrets reach the plugin through SecretGet, never in the test
// body (spec §8). A step with no test route passes once it is run.
func (m *Manager) TestSetupStep(ctx context.Context, pluginID, stepKey string) (SetupTestResult, error) {
	r, err := m.Get(ctx, pluginID)
	if err != nil {
		return SetupTestResult{}, err
	}
	step, ok := setupStepOf(r, stepKey)
	if !ok {
		return SetupTestResult{}, fmt.Errorf("%w: plugin has no setup step %q", ErrUnavailable, stepKey)
	}
	if step.Test == "" {
		res := SetupTestResult{OK: true}
		if err := m.store.putSetupState(ctx, pluginID, stepKey, SetupOK, ""); err != nil {
			return res, err
		}
		m.syncDescriptors(ctx, r)
		m.broadcast(ctx)
		return res, nil
	}
	settings, err := m.HostFor(pluginID).Settings(ctx)
	if err != nil {
		return SetupTestResult{}, err
	}
	values := map[string]any{}
	for _, f := range step.Fields {
		if v, present := settings[f]; present {
			values[f] = v
		}
	}
	body, err := json.Marshal(map[string]any{"step": stepKey, "fields": values})
	if err != nil {
		return SetupTestResult{}, err
	}
	callCtx, cancel := context.WithTimeout(ctx, 20*time.Second)
	defer cancel()
	resp, err := m.Call(callCtx, pluginID, Request{Method: "POST", Path: step.Test, Body: body})
	if err != nil {
		_ = m.store.putSetupState(ctx, pluginID, stepKey, SetupFailed, "The plugin did not answer")
		m.syncDescriptors(ctx, r)
		m.broadcast(ctx)
		return SetupTestResult{OK: false, Detail: "The plugin did not answer"}, nil
	}
	var res SetupTestResult
	if len(resp.Body) > 0 {
		_ = json.Unmarshal(resp.Body, &res)
	}
	if resp.Status >= 300 {
		res.OK = false
		if res.Detail == "" {
			res.Detail = fmt.Sprintf("The plugin answered with status %d", resp.Status)
		}
	}
	res.Detail = textclip.Bytes(res.Detail, 500)
	status := SetupFailed
	if res.OK {
		status = SetupOK
	}
	if err := m.store.putSetupState(ctx, pluginID, stepKey, status, res.Detail); err != nil {
		return SetupTestResult{}, err
	}
	m.syncDescriptors(ctx, r)
	m.broadcast(ctx)
	return res, nil
}

// SkipSetupStep records the owner's "skip for now" on one step, which
// unblocks the plugin while leaving the step visibly unfinished.
func (m *Manager) SkipSetupStep(ctx context.Context, pluginID, stepKey string) error {
	r, err := m.Get(ctx, pluginID)
	if err != nil {
		return err
	}
	if _, ok := setupStepOf(r, stepKey); !ok {
		return fmt.Errorf("%w: plugin has no setup step %q", ErrUnavailable, stepKey)
	}
	if err := m.store.putSetupState(ctx, pluginID, stepKey, SetupSkipped, ""); err != nil {
		return err
	}
	m.syncDescriptors(ctx, r)
	m.broadcast(ctx)
	return nil
}

// ToolDeps holds dependencies for the Studio and extensibility agent and MCP tools.
type ToolDeps struct {
	Studio       *Studio
	Registry     *extend.Registry
	TextResolver extend.TextResolver
	Manager      *plugins.Manager
	Runner       *Runner
	Engine       *wasm.Engine
}

// RegisterTools registers the Studio and extensibility tools into cat.
func RegisterTools(cat *tools.Catalogue, deps ToolDeps) error {
	if cat == nil {
		return fmt.Errorf("studio: tool catalogue is required")
	}
	return cat.Register(append(Tools(deps), ProjectTools(deps.Studio)...)...)
}

// Tools returns the 8 Studio and extensibility tools (WS11h):
// registry_describe, viewspec_validate, viewspec_render, plugin_scaffold,
// plugin_check, plugin_replay, plugin_shadow_report, and plugin_install.
func Tools(deps ToolDeps) []tools.Tool {
	if deps.Runner == nil {
		deps.Runner = NewRunner(ReplayDeps{
			Manager: deps.Manager,
			Engine:  deps.Engine,
		})
	}
	return []tools.Tool{
		registryDescribeTool(deps),
		viewspecValidateTool(),
		viewspecRenderTool(deps),
		pluginScaffoldTool(deps),
		pluginCheckTool(deps),
		pluginReplayTool(deps),
		pluginShadowReportTool(deps),
		pluginInstallTool(deps),
	}
}

func registryDescribeTool(deps ToolDeps) tools.Tool {
	schema := json.RawMessage(`{
		"type": "object",
		"properties": {
			"kind": {
				"type": "string",
				"description": "Optional descriptor kind to filter by (for example rankingStep, ruleField, collectionSource, page, widget, tool)."
			},
			"id": {
				"type": "string",
				"description": "Optional descriptor ID to inspect."
			},
			"owner": {
				"type": "string",
				"description": "Optional owner filter (builtin or a plugin ID)."
			},
			"locale": {
				"type": "string",
				"description": "Locale code for resolving copy, defaulting to en."
			},
			"limit": {
				"type": "integer",
				"minimum": 1,
				"maximum": 200,
				"description": "Maximum number of descriptors to return (1 to 200)."
			}
		},
		"additionalProperties": false
	}`)

	return tools.Tool{
		Name:        "registry_describe",
		Title:       "Describe extension registry",
		Description: "List registered extension descriptors by kind or owner, or inspect one descriptor in detail.",
		InputSchema: schema,
		ReadOnly:    true,
		Audience:    tools.AudienceOwner,
		Owner:       extend.Builtin,
		Execute: func(_ context.Context, _ tools.Principal, input map[string]any) (tools.Result, error) {
			if deps.Registry == nil {
				return tools.Result{}, tools.Userf("The extension registry is not available.")
			}
			kindStr, err := optString(input, "kind", 64)
			if err != nil {
				return tools.Result{}, err
			}
			idStr, err := optString(input, "id", 128)
			if err != nil {
				return tools.Result{}, err
			}
			ownerStr, err := optString(input, "owner", 128)
			if err != nil {
				return tools.Result{}, err
			}
			locale, err := optString(input, "locale", 16)
			if err != nil {
				return tools.Result{}, err
			}
			if locale == "" {
				locale = "en"
			}
			limit, err := optInt(input, "limit", 100, 1, 200)
			if err != nil {
				return tools.Result{}, err
			}

			if kindStr != "" && !extend.Known(extend.Kind(kindStr)) {
				return tools.Result{}, tools.Userf("Unknown descriptor kind %q.", kindStr)
			}

			resolver := deps.TextResolver
			if resolver == nil && deps.Manager != nil {
				resolver = deps.Manager.TextResolver()
			}
			resolveDescriptor := func(d extend.Descriptor) extend.Descriptor {
				if resolver != nil {
					if d.Label.Plugin != "" && d.Label.Key != "" {
						if s, ok := resolver(d.Label.Plugin, d.Label.Key, locale); ok {
							d.Label.Resolved = s
						}
					}
					if d.Hint.Plugin != "" && d.Hint.Key != "" {
						if s, ok := resolver(d.Hint.Plugin, d.Hint.Key, locale); ok {
							d.Hint.Resolved = s
						}
					}
				}
				return d
			}

			if kindStr != "" && idStr != "" {
				d, ok := deps.Registry.Get(extend.Kind(kindStr), idStr)
				if !ok {
					return tools.Result{}, tools.Userf("Descriptor %q of kind %q was not found.", idStr, kindStr)
				}
				return tools.Result{
					Data: map[string]any{
						"descriptor": resolveDescriptor(d),
					},
				}, nil
			}

			var list []extend.Descriptor
			if kindStr != "" {
				list = deps.Registry.List(extend.Kind(kindStr))
			} else {
				list = deps.Registry.List()
			}
			filtered := make([]extend.Descriptor, 0, len(list))
			for _, d := range list {
				if idStr != "" && d.ID != idStr {
					continue
				}
				if ownerStr != "" && d.Owner != ownerStr {
					continue
				}
				filtered = append(filtered, resolveDescriptor(d))
				if len(filtered) >= limit {
					break
				}
			}

			return tools.Result{
				Data: map[string]any{
					"count":       len(filtered),
					"descriptors": filtered,
				},
				Links: []tools.Link{
					{Label: "Open plugins", Route: "/settings/plugins"},
				},
			}, nil
		},
	}
}

func viewspecValidateTool() tools.Tool {
	schema := json.RawMessage(`{
		"type": "object",
		"required": ["spec"],
		"properties": {
			"spec": {
				"description": "The ViewSpec JSON object or JSON string to validate."
			}
		},
		"additionalProperties": false
	}`)

	return tools.Tool{
		Name:        "viewspec_validate",
		Title:       "Validate ViewSpec document",
		Description: "Validate a ViewSpec JSON document against Ether's plugin UI rules and report any field errors.",
		InputSchema: schema,
		ReadOnly:    true,
		Audience:    tools.AudienceOwner,
		Owner:       extend.Builtin,
		Execute: func(_ context.Context, _ tools.Principal, input map[string]any) (tools.Result, error) {
			rawSpec, ok := input["spec"]
			if !ok || rawSpec == nil {
				return tools.Result{}, tools.Userf("Provide a spec object to validate.")
			}
			specBytes, err := encodeBoundedJSON(rawSpec, maxManifestBytes, "spec")
			if err != nil {
				return tools.Result{}, err
			}
			res := viewspec.ValidatePlugin(specBytes)
			errs := res.Errors
			if errs == nil {
				errs = []string{}
			}
			return tools.Result{
				Data: map[string]any{
					"ok":     res.OK,
					"errors": errs,
				},
			}, nil
		},
	}
}

func viewspecRenderTool(deps ToolDeps) tools.Tool {
	schema := json.RawMessage(`{
		"type": "object",
		"properties": {
			"spec": {
				"description": "The ViewSpec JSON object or JSON string to validate and prepare for console rendering."
			},
			"data": {
				"description": "Optional data object bound to the ViewSpec document."
			},
			"plugin": {
				"type": "string",
				"description": "Optional installed plugin ID to load a contributed page from."
			},
			"page": {
				"type": "string",
				"description": "Optional contributed page key on the installed plugin."
			}
		},
		"additionalProperties": false
	}`)

	return tools.Tool{
		Name:        "viewspec_render",
		Title:       "Render ViewSpec preview",
		Description: "Validate a ViewSpec document and data payload, and return the validated spec, data, and console preview URL.",
		InputSchema: schema,
		ReadOnly:    true,
		Audience:    tools.AudienceOwner,
		Owner:       extend.Builtin,
		Execute: func(ctx context.Context, _ tools.Principal, input map[string]any) (tools.Result, error) {
			pluginID, err := optString(input, "plugin", 128)
			if err != nil {
				return tools.Result{}, err
			}
			pageKey, err := optString(input, "page", 64)
			if err != nil {
				return tools.Result{}, err
			}

			var specBytes []byte
			var dataObj map[string]any

			if rawSpec, ok := input["spec"]; ok && rawSpec != nil {
				specBytes, err = encodeBoundedJSON(rawSpec, maxManifestBytes, "spec")
				if err != nil {
					return tools.Result{}, err
				}
			}
			if rawData, ok := input["data"]; ok && rawData != nil {
				dataBytes, err := encodeBoundedJSON(rawData, maxManifestBytes, "data")
				if err != nil {
					return tools.Result{}, err
				}
				if err := json.Unmarshal(dataBytes, &dataObj); err != nil {
					return tools.Result{}, tools.Userf("The data field must be a JSON object.")
				}
			}

			if len(specBytes) == 0 {
				if pluginID == "" || pageKey == "" {
					return tools.Result{}, tools.Userf("Provide either spec or both plugin and page.")
				}
				if deps.Manager == nil {
					return tools.Result{}, tools.Userf("The plugin manager is not available.")
				}
				rec, err := deps.Manager.Get(ctx, pluginID)
				if err != nil {
					return tools.Result{}, tools.Userf("Plugin %q is not installed.", pluginID)
				}
				route := ""
				if rec.Manifest.Ether != nil {
					for _, p := range rec.Manifest.Ether.Contributes.Pages {
						if p.Key == pageKey {
							route = p.Route
							break
						}
					}
				}
				if route == "" {
					return tools.Result{}, tools.Userf("Page %q was not found on plugin %q.", pageKey, pluginID)
				}
				resp, err := deps.Manager.Call(ctx, pluginID, plugins.Request{
					PluginID: pluginID,
					Method:   "GET",
					Path:     route,
				})
				if err != nil {
					return tools.Result{}, tools.Userf("Could not load page %q from plugin %q.", pageKey, pluginID)
				}
				body := unwrapResponseBody(resp.Body)
				var pageEnvelope struct {
					Spec json.RawMessage `json:"spec"`
					Data map[string]any  `json:"data"`
				}
				if json.Unmarshal(body, &pageEnvelope) == nil && len(pageEnvelope.Spec) > 0 {
					specBytes = pageEnvelope.Spec
					if dataObj == nil {
						dataObj = pageEnvelope.Data
					}
				} else {
					specBytes = body
				}
			}

			if dataObj == nil {
				dataObj = map[string]any{}
			}

			valRes := viewspec.ValidatePlugin(specBytes)
			if !valRes.OK {
				return tools.Result{
					Data: map[string]any{
						"ok":     false,
						"errors": valRes.Errors,
					},
				}, nil
			}

			var specObj map[string]any
			_ = json.Unmarshal(specBytes, &specObj)

			consoleURL := "/settings/plugins/studio/preview"
			if pluginID != "" && pageKey != "" {
				consoleURL = fmt.Sprintf("/plugins/%s/pages/%s", pluginID, pageKey)
			}

			return tools.Result{
				Data: map[string]any{
					"ok":         true,
					"spec":       specObj,
					"data":       dataObj,
					"consoleUrl": consoleURL,
				},
				Links: []tools.Link{
					{Label: "Open preview in console", Route: consoleURL},
				},
			}, nil
		},
	}
}

// ScaffoldRequest describes a new plugin to generate.
type ScaffoldRequest struct {
	ID           string   `json:"id"`
	Name         string   `json:"name"`
	Kind         string   `json:"kind,omitempty"`
	Capabilities []string `json:"capabilities,omitempty"`
	Summary      string   `json:"summary,omitempty"`
}

// ScaffoldResult holds the generated manifest and source files.
type ScaffoldResult struct {
	Manifest plugins.Manifest  `json:"manifest"`
	Files    map[string]string `json:"files"`
}

// Scaffold builds a valid manifest and TypeScript entry file for the requested
// plugin kind and capabilities.
func Scaffold(req ScaffoldRequest) (ScaffoldResult, error) {
	id := strings.TrimSpace(req.ID)
	name := strings.TrimSpace(req.Name)
	if id == "" || len(id) > 120 {
		return ScaffoldResult{}, tools.Userf("Provide a reverse-DNS plugin id of at most 120 characters.")
	}
	if name == "" || len(name) > 80 {
		return ScaffoldResult{}, tools.Userf("Provide a plugin name of at most 80 characters.")
	}
	summary := strings.TrimSpace(req.Summary)
	if summary == "" {
		summary = "Custom plugin for Ether."
	}
	if len(summary) > 140 {
		return ScaffoldResult{}, tools.Userf("Summary must be at most 140 characters.")
	}

	kind := plugins.Kind(strings.TrimSpace(req.Kind))
	if kind == "" {
		kind = plugins.KindExtension
	}
	var caps []plugins.Capability
	for _, c := range req.Capabilities {
		c = strings.TrimSpace(c)
		if c != "" {
			caps = append(caps, plugins.Capability(c))
		}
	}
	if len(caps) == 0 {
		switch kind {
		case plugins.KindSource:
			caps = []plugins.Capability{plugins.CapStreamSource}
		case plugins.KindNotificationChannel:
			caps = []plugins.Capability{plugins.CapNotify}
		case plugins.KindLiveTVSource:
			caps = []plugins.Capability{plugins.CapLiveTV}
		default:
			caps = []plugins.Capability{plugins.CapRankingStep}
		}
	}

	m := plugins.Manifest{
		ID:          id,
		Version:     "0.1.0",
		Name:        name,
		Description: summary,
		Types:       []string{"movie", "series"},
		Ether: &plugins.EtherBlock{
			Protocol:     plugins.Protocol,
			Kind:         kind,
			Capabilities: caps,
			Summary:      summary,
			Runtime: plugins.RuntimeDecl{
				Kind:  "hosted",
				Entry: "plugin.ts",
			},
		},
	}

	if kind == plugins.KindIntegration {
		m.Ether.Contributes.Integration = &plugins.IntegrationMeta{
			Category: "automation",
			Adds:     []string{"Syncs watch activity."},
			Connect:  "none",
		}
	}

	var codeLines []string
	codeLines = append(codeLines, `type Request = { method: string; path: string; query?: Record<string, string[]>; body?: unknown };`)
	codeLines = append(codeLines, `type Response = { status: number; headers?: Record<string, string>; body?: unknown };`)

	needHandle := false
	for _, cap := range caps {
		switch cap {
		case plugins.CapStreamSource:
			needHandle = true
			m.Ether.Contributes.Source = &plugins.SourceMeta{Class: "direct"}
		case plugins.CapListSource:
			needHandle = true
			m.Catalogs = []plugins.StremioCat{{Type: "movie", ID: "picks", Name: "Picked movies"}}
			m.Ether.Contributes.ListSources = []plugins.ListSourceMeta{
				{Key: "picks", Label: "Picked movies", Catalog: "picks", MaxItems: 100, Refresh: "1h"},
			}
		case plugins.CapLiveTV:
			needHandle = true
			m.Ether.Contributes.Channels = &plugins.ChannelsMeta{Refresh: "1h", Test: true}
		case plugins.CapSubtitles:
			needHandle = true
			m.Ether.Contributes.Subtitles = &plugins.SubtitlesMeta{
				Languages: json.RawMessage(`"any"`),
				Formats:   []string{"srt", "vtt"},
			}
		case plugins.CapMarkers:
			needHandle = true
			m.Ether.Contributes.Markers = &plugins.MarkersMeta{Kinds: []string{"intro", "credits"}}
		case plugins.CapNotify:
			needHandle = true
			m.Ether.Contributes.Notification = &plugins.NotificationMeta{
				SendTest:  true,
				Formats:   []string{"plain"},
				MaxLength: 2000,
			}
		case plugins.CapEvents:
			needHandle = true
			m.Ether.Contributes.Events = &plugins.EventsMeta{
				Subscribe: []string{plugins.EventPlaybackCompleted},
			}
		case plugins.CapFlowActions:
			needHandle = true
			m.Ether.Contributes.FlowActions = []plugins.FlowActionMeta{
				{
					Key:        "run_action",
					Label:      "Run custom action",
					Route:      "/ether/v1/flow-actions/run_action",
					Idempotent: true,
					Timeout:    "15s",
				},
			}
		case plugins.CapRankingStep:
			m.Ether.Contributes.RankingSteps = []plugins.RankingStepMeta{
				{Key: "prefer_custom", Label: "Prefer matching releases"},
			}
		case plugins.CapRuleCondition:
			m.Ether.Contributes.RuleConditions = []plugins.RuleConditionMeta{
				{Key: "custom_match", Label: "Custom release match", Operators: []string{"equals", "contains"}},
			}
		case plugins.CapTools:
			needHandle = true
			m.Ether.Contributes.Tools = []plugins.ToolMeta{
				{
					Name:        "status_summary",
					Title:       "Status summary",
					Description: "Return a short status summary from the plugin.",
					InputSchema: json.RawMessage(`{"type":"object","properties":{}}`),
					ReadOnly:    true,
				},
			}
		case plugins.CapUI:
			needHandle = true
			m.Ether.Contributes.Pages = []plugins.PageMeta{
				{Key: "overview", Label: "Overview", Route: "/ether/view/overview"},
			}
		}
	}

	if needHandle || (!slices.Contains(caps, plugins.CapRankingStep) && !slices.Contains(caps, plugins.CapRuleCondition)) {
		codeLines = append(codeLines, `
function handle(req: Request): Response {
  if (req.path === "/ether/health" || req.path === "/ether/test") {
    return { status: 200, body: { status: "ok" } };
  }
  if (req.path === "/ether/event") {
    return { status: 200, body: { ack: [] } };
  }
  if (req.path === "/ether/channels.json") {
    return { status: 200, body: { channels: [] } };
  }
  return { status: 200, body: { metas: [] } };
}
(globalThis as any).handle = handle;`)
	}
	if slices.Contains(caps, plugins.CapRankingStep) {
		codeLines = append(codeLines, `
function rank_key(candidate: { name: string }, _config: Record<string, unknown>): number {
  return candidate.name ? 0 : 0;
}
(globalThis as any).rank_key = rank_key;`)
	}
	if slices.Contains(caps, plugins.CapRuleCondition) {
		codeLines = append(codeLines, `
function cond_match(candidate: { name: string }, operator: string, value: unknown): boolean {
  const target = typeof value === "string" ? value : "";
  if (operator === "contains" && target !== "") {
    return candidate.name.includes(target);
  }
  return candidate.name === target;
}
(globalThis as any).cond_match = cond_match;`)
	}

	if err := m.Validate(); err != nil {
		return ScaffoldResult{}, tools.Userf("Generated manifest is not valid: %s", err.Error())
	}

	return ScaffoldResult{
		Manifest: m,
		Files: map[string]string{
			"plugin.ts": strings.TrimSpace(strings.Join(codeLines, "\n")) + "\n",
		},
	}, nil
}

func pluginScaffoldTool(_ ToolDeps) tools.Tool {
	schema := json.RawMessage(`{
		"type": "object",
		"required": ["id", "name"],
		"properties": {
			"id": {
				"type": "string",
				"description": "Reverse-DNS plugin ID (for example org.example.dub-ranker)."
			},
			"name": {
				"type": "string",
				"description": "Human-readable plugin name."
			},
			"kind": {
				"type": "string",
				"description": "Plugin kind: source, integration, notification_channel, livetv_source, or extension."
			},
			"capabilities": {
				"type": "array",
				"items": { "type": "string" },
				"description": "Capabilities the plugin contributes."
			},
			"summary": {
				"type": "string",
				"description": "Short one-sentence summary in sentence case."
			}
		},
		"additionalProperties": false
	}`)

	return tools.Tool{
		Name:        "plugin_scaffold",
		Title:       "Scaffold plugin",
		Description: "Generate a valid manifest and TypeScript entry file for a new Ether plugin.",
		InputSchema: schema,
		ReadOnly:    true,
		Audience:    tools.AudienceOwner,
		Owner:       extend.Builtin,
		Execute: func(_ context.Context, _ tools.Principal, input map[string]any) (tools.Result, error) {
			id, err := reqString(input, "id", 120)
			if err != nil {
				return tools.Result{}, err
			}
			name, err := reqString(input, "name", 80)
			if err != nil {
				return tools.Result{}, err
			}
			kind, err := optString(input, "kind", 40)
			if err != nil {
				return tools.Result{}, err
			}
			summary, err := optString(input, "summary", 140)
			if err != nil {
				return tools.Result{}, err
			}
			caps, err := optStringSlice(input, "capabilities", 12, 40)
			if err != nil {
				return tools.Result{}, err
			}

			res, err := Scaffold(ScaffoldRequest{
				ID:           id,
				Name:         name,
				Kind:         kind,
				Capabilities: caps,
				Summary:      summary,
			})
			if err != nil {
				return tools.Result{}, err
			}
			return tools.Result{
				Data: map[string]any{
					"manifest": res.Manifest,
					"files":    res.Files,
				},
			}, nil
		},
	}
}

// CheckRequest holds the manifest and files to validate in Studio.
type CheckRequest struct {
	Manifest json.RawMessage   `json:"manifest"`
	Files    map[string]string `json:"files,omitempty"`
}

// ToolCheckReport is the output of Check.
type ToolCheckReport struct {
	OK      bool                 `json:"ok"`
	Issues  []plugins.FieldError `json:"issues"`
	Exports map[string]bool      `json:"exports,omitempty"`
}

// Check validates a plugin's manifest, copy rules, settings schema, ViewSpec
// files, and hosted TypeScript or JavaScript entry code.
func Check(ctx context.Context, _ *wasm.Engine, req CheckRequest) (ToolCheckReport, error) {
	files := make(map[string][]byte, len(req.Files))
	for name, contents := range req.Files {
		files[name] = []byte(contents)
	}
	rep := kit.Check(ctx, &kit.Package{ManifestRaw: req.Manifest, Files: files})
	out := ToolCheckReport{OK: rep.OK, Issues: []plugins.FieldError{}, Exports: rep.Exports}
	for _, issue := range rep.Errors {
		out.Issues = append(out.Issues, plugins.FieldError{Field: issue.Field, Message: issue.Message})
	}
	return out, nil
}

func pluginCheckTool(deps ToolDeps) tools.Tool {
	schema := json.RawMessage(`{
		"type": "object",
		"properties": {
			"plugin": {
				"type": "string",
				"description": "Optional installed plugin ID to check."
			},
			"manifest": {
				"description": "Manifest JSON object or JSON string to check."
			},
			"files": {
				"type": "object",
				"description": "Map of file paths to file contents for the plugin."
			}
		},
		"additionalProperties": false
	}`)

	return tools.Tool{
		Name:        "plugin_check",
		Title:       "Check plugin",
		Description: "Validate a plugin manifest, copy rules, settings schema, ViewSpec documents, and TypeScript or JavaScript entry code.",
		InputSchema: schema,
		ReadOnly:    true,
		Audience:    tools.AudienceOwner,
		Owner:       extend.Builtin,
		Execute: func(ctx context.Context, _ tools.Principal, input map[string]any) (tools.Result, error) {
			pluginID, err := optString(input, "plugin", 128)
			if err != nil {
				return tools.Result{}, err
			}
			var manifestBytes []byte
			files := map[string]string{}

			if pluginID != "" {
				if deps.Manager == nil {
					return tools.Result{}, tools.Userf("The plugin manager is not available.")
				}
				rec, err := deps.Manager.Get(ctx, pluginID)
				if err != nil {
					return tools.Result{}, tools.Userf("Plugin %q is not installed.", pluginID)
				}
				manifestBytes = rec.ManifestRaw
				if len(manifestBytes) == 0 {
					manifestBytes, _ = json.Marshal(rec.Manifest)
				}
				if deps.Runner != nil {
					for k, v := range deps.Runner.loadArtifactFiles(ctx, rec.ID, rec.Version) {
						files[k] = string(v)
					}
				}
			} else {
				rawManifest, ok := input["manifest"]
				if !ok || rawManifest == nil {
					return tools.Result{}, tools.Userf("Provide either an installed plugin id or a manifest.")
				}
				manifestBytes, err = encodeBoundedJSON(rawManifest, maxManifestBytes, "manifest")
				if err != nil {
					return tools.Result{}, err
				}
				files, err = optFileMap(input, "files")
				if err != nil {
					return tools.Result{}, err
				}
			}

			eng := deps.Engine
			rep, err := Check(ctx, eng, CheckRequest{
				Manifest: manifestBytes,
				Files:    files,
			})
			if err != nil {
				return tools.Result{}, err
			}
			return tools.Result{
				Data: map[string]any{
					"ok":      rep.OK,
					"issues":  rep.Issues,
					"exports": rep.Exports,
				},
			}, nil
		},
	}
}

func pluginReplayTool(deps ToolDeps) tools.Tool {
	schema := json.RawMessage(`{
		"type": "object",
		"required": ["kind"],
		"properties": {
			"plugin": {
				"type": "string",
				"description": "Installed plugin ID to replay."
			},
			"devInstance": {
				"type": "object",
				"description": "Unsaved Studio plugin instance with manifest, entry or files, and settings."
			},
			"kind": {
				"type": "string",
				"enum": ["ranking", "events", "list", "channels"],
				"description": "Replay mode to run: ranking, events, list, or channels."
			},
			"params": {
				"type": "object",
				"description": "Mode-specific replay parameters (stepKey, position, limit, days, sourceKey, probeLimit)."
			}
		},
		"additionalProperties": false
	}`)

	return tools.Tool{
		Name:        "plugin_replay",
		Title:       "Replay plugin",
		Description: "Replay recorded resolution history, events, list pages, or channels against an installed plugin or Studio dev instance.",
		InputSchema: schema,
		ReadOnly:    true,
		OpenWorld:   true,
		Audience:    tools.AudienceOwner,
		Owner:       extend.Builtin,
		Execute: func(ctx context.Context, _ tools.Principal, input map[string]any) (tools.Result, error) {
			if deps.Runner == nil {
				return tools.Result{}, tools.Userf("The Studio replay runner is not available.")
			}
			rawInput, err := encodeBoundedJSON(input, maxRequestBytes, "input")
			if err != nil {
				return tools.Result{}, err
			}
			var req ReplayRequest
			if err := json.Unmarshal(rawInput, &req); err != nil {
				return tools.Result{}, tools.Userf("Invalid replay parameters: %s", err.Error())
			}
			report, err := deps.Runner.Replay(ctx, req)
			if err != nil {
				return tools.Result{}, tools.Userf("Replay failed: %s", err.Error())
			}
			dataBytes, _ := json.Marshal(report)
			var dataMap map[string]any
			_ = json.Unmarshal(dataBytes, &dataMap)
			return tools.Result{
				Data: dataMap,
			}, nil
		},
	}
}

