		Kind:            plugins.KindExtension,
		Capabilities:    []plugins.Capability{plugins.CapTools},
		DefaultPluginID: "community.studio.tool",
		DefaultName:     "Room lights tool",
		DefaultRoute:    "/ether/tool/check_room_lights",
		Files: map[string]string{
			"manifest.json": prettyJSON(manifest),
			"i18n/en.json":  prettyJSON(stringsEN),
			"src/plugin.ts": code,
		},
	}
}

// applyProjectOptions customizes a template's files for the given PluginID, Name, Slot, or StremioURL.
func applyProjectOptions(tpl Template, opts CreateProjectOptions) (pluginID, name string, files map[string]string) {
	files = make(map[string]string, len(tpl.Files))
	for k, v := range tpl.Files {
		files[k] = v
	}
	pluginID = strings.TrimSpace(opts.PluginID)
	if pluginID == "" {
		pluginID = tpl.DefaultPluginID
	}
	name = strings.TrimSpace(opts.Name)
	if name == "" {
		name = tpl.DefaultName
	}

	var man map[string]any
	if err := json.Unmarshal([]byte(files["manifest.json"]), &man); err != nil {
		return pluginID, name, files
	}
	man["id"] = pluginID
	man["name"] = name

	etherObj, _ := man["ether"].(map[string]any)
	contributes, _ := etherObj["contributes"].(map[string]any)

	if slot := strings.TrimSpace(opts.Slot); slot != "" && etherObj != nil && contributes != nil {
		ensureUICap(etherObj)
		var en map[string]string
		if json.Unmarshal([]byte(files["i18n/en.json"]), &en) == nil && en != nil {
			if en["slot_label"] == "" {
				en["slot_label"] = "Plugin action"
				files["i18n/en.json"] = prettyJSON(en)
			}
		}
		switch slot {
		case "page":
			contributes["pages"] = []map[string]any{
				{
					"key":   "overview",
					"label": "$t:page_label",
					"route": "/ether/view/overview",
				},
			}
		case "command":
			contributes["commands"] = []map[string]any{
				{
					"key":    "run_command",
					"label":  "$t:slot_label",
					"action": "createHighlight",
				},
			}
		default:
			entry := map[string]any{"slot": slot, "key": "custom_slot", "label": "$t:slot_label"}
			if strings.HasPrefix(slot, "actionMenu.") {
				action := "createHighlight"
				switch tpl.ID {
				case "list":
					action = "syncShelf"
				case "local_files":
					action = "matchFolder"
				}
				entry["action"] = action
			} else {
				entry["route"] = "/ether/view/overview"
			}
			contributes["slots"] = []map[string]any{entry}
		}
	}

	// Add-on links often carry a debrid key in the path, so only the host is
	// written into source; the link itself is never stored with the draft.
	if u, err := url.Parse(strings.TrimSpace(opts.StremioURL)); err == nil && u.Host != "" {
		if src, ok := files["src/plugin.ts"]; ok {
			files["src/plugin.ts"] = fmt.Sprintf("// Upstream Stremio add-on host: %s\n", u.Host) + src
		}
	}

	if opts.LiveSearch != nil && contributes != nil {
		if kinds, ok := contributes["mediaKinds"].([]any); ok {
			for _, k := range kinds {
				if kind, ok := k.(map[string]any); ok {
					browse, _ := kind["browse"].(map[string]any)
					if browse == nil {
						browse = map[string]any{}
						kind["browse"] = browse
					}
					browse["liveSearch"] = *opts.LiveSearch
				}
			}
		}
	}

	files["manifest.json"] = prettyJSON(man)
	return pluginID, name, files
}

func ensureUICap(etherObj map[string]any) {
	raw, _ := etherObj["capabilities"].([]any)
	for _, item := range raw {
		if item == "ui" {
			return
		}
	}
	if strs, ok := etherObj["capabilities"].([]string); ok {
		for _, s := range strs {
			if s == "ui" {
				return
			}
		}
		etherObj["capabilities"] = append(strs, "ui")
		return
	}
	etherObj["capabilities"] = append(raw, "ui")
}

// ViewerRequestPath identifies calls on a viewer's browse/search/playback path.
// Administrative actions, setup, catalogue sync and background jobs use
// owner-granted limits.
func ViewerRequestPath(path string) bool {
	for _, prefix := range []string{"/stream/", "/catalog/", "/meta/", "/subtitles/", "/ether/open", "/ether/search", "/ether/files/", "/ether/metadata/", "/ether/subtitles/", "/ether/markers", "/ether/debrid/hints"} {
		if strings.HasPrefix(path, prefix) {
			return true
		}
	}
	return (strings.HasPrefix(path, "/ether/v1/kinds/") && !KindSyncPath(path)) ||
		strings.HasPrefix(path, "/ether/v1/live/") ||
		strings.HasPrefix(path, "/ether/v1/screens/")
}

// OptionalCallPath identifies calls Ether makes only to save work and
// drops at its own deadline (/ether/debrid/hints): a timeout there, on
// Ether's deadline or the route's own budget, says nothing about the
// plugin's health.
func OptionalCallPath(path string) bool {
	p, _, _ := strings.Cut(path, "?")
	return p == "/ether/debrid/hints"
}

// IsSourceSearchPath identifies a stream_source plugin's category search
// (/ether/search) and release file listing (/ether/files/{id}) routes (#792).
func IsSourceSearchPath(path string) bool {
	p, _, _ := strings.Cut(path, "?")
	return p == "/ether/search" || strings.HasPrefix(p, "/ether/files/")
}

// KindSyncPath identifies a media kind's background catalogue calls (browse,
// changes, and expand). Ether makes them in the background to fill a library,
// never while a viewer waits, so they run on the plugin's granted limits (the
// manifest's request, capped only by the owner's ceilings) instead of the
// viewer budget. A big first sync or facet expansion can then take as long as
// it needs.
func KindSyncPath(path string) bool {
	p, _, _ := strings.Cut(path, "?")
	return strings.HasPrefix(p, "/ether/v1/kinds/") &&
		(strings.HasSuffix(p, "/browse") || strings.HasSuffix(p, "/changes") || strings.HasSuffix(p, "/expand"))
}

// LiveTVSyncPath identifies a Live TV source plugin's background lineup and
// guide refresh calls (/ether/channels.json and /ether/guide/*). Ether makes
// them in the background to import channels and programmes, never while a
// viewer waits, so they run on the plugin's granted limits.
func LiveTVSyncPath(path string) bool {
	p, _, _ := strings.Cut(path, "?")
	return p == "/ether/channels.json" || strings.HasPrefix(p, "/ether/guide/")
}

// GrantedLimitsPath reports whether path runs on the plugin's owner-granted
// deadline and unit budget rather than a fixed protocol or viewer cap:
// background kind sync (/browse, /changes, /expand), Live TV lineup and guide sync
// (/ether/channels.json, /ether/guide/*), jobs, setup, owner actions,
// agent tools, and event deliveries.
func GrantedLimitsPath(path string) bool {
	p, _, _ := strings.Cut(path, "?")
	return KindSyncPath(p) ||
		LiveTVSyncPath(p) ||
		strings.HasPrefix(p, "/ether/job/") ||
		strings.HasPrefix(p, "/ether/v1/setup/") ||
		strings.HasPrefix(p, "/ether/action/") ||
		strings.HasPrefix(p, "/ether/tool/") ||
		p == "/ether/event"
}

// BackgroundPoolPath reports whether path is a background job, sync, or event
// delivery call bounded below PoolSize so interactive viewer resolves,
// frontend adapter requests and health checks retain free instances.
func BackgroundPoolPath(path string) bool {
	p, _, _ := strings.Cut(path, "?")
	return strings.HasPrefix(p, "/ether/job/") || KindSyncPath(p) || LiveTVSyncPath(p) || p == "/ether/event"
}

// ResolvePoolPath reports whether path is a playback resolution or stream-open
// call that receives priority access and a reserved pool lane so slow
// frontend-adapter requests or background jobs cannot starve playback.
func ResolvePoolPath(path string) bool {
	p, _, _ := strings.Cut(path, "?")
	if strings.HasPrefix(p, "/ether/open") || strings.HasPrefix(p, "/stream/") || IsSourceSearchPath(p) {
		return true
	}
	return strings.HasPrefix(p, "/ether/v1/kinds/") &&
		(strings.HasSuffix(p, "/resolve") || strings.HasSuffix(p, "/match"))
}

// FrontendAdapterPath reports whether path targets a plugin-contributed
// frontend adapter route (/ether/v1/frontend/*).
func FrontendAdapterPath(path string) bool {
	p, _, _ := strings.Cut(path, "?")
	return strings.HasPrefix(p, "/ether/v1/frontend/") && len(p) > len("/ether/v1/frontend/")
}

// UnitsForDeadline converts a call deadline into its matching governance unit
// budget at one unit per WallUnitInterval (100 µs, or 10,000 units per second),
// so a viewer route's unit budget matches the deadline it is advertised.
func UnitsForDeadline(d time.Duration) int64 {
	if d <= 0 {
		return 0
	}
	return int64(d / WallUnitInterval)
}

// StremioDeadline is the per-route deadline for a third-party Stremio add-on
// or an add-on-backed plugin (ether.stremio: true). Their stream searches
// routinely take seconds (they search trackers and debrid caches live); the
// caller's own deadline still bounds every call.
func StremioDeadline(path string) time.Duration {
	switch {
	case strings.HasPrefix(path, "/stream/"), strings.HasPrefix(path, "/catalog/"), strings.HasPrefix(path, "/manifest.json"):
		return 20 * time.Second
	case strings.HasPrefix(path, "/meta/"), strings.HasPrefix(path, "/subtitles/"):
		return 10 * time.Second
	default:
		return 30 * time.Second
	}
}

// DeadlineFor returns the baseline per-route deadline from SPEC §5.1.2.
// Routes in GrantedLimitsPath use the plugin's owner-granted deadline instead
// when dispatched through EffectiveDeadline.
func DeadlineFor(path string) time.Duration {
	p, _, _ := strings.Cut(path, "?")
	switch {
	case strings.HasPrefix(p, "/ether/configure"), strings.HasPrefix(p, "/ether/health"):
		return 5 * time.Second
	case strings.HasPrefix(p, "/ether/test"):
		return 15 * time.Second
	case strings.HasPrefix(p, "/ether/options"), strings.HasPrefix(p, "/ether/view"):
		return 2 * time.Second
	case p == "/ether/debrid/hints":
		// Asked while a viewer waits on Play. Ether's own 500 ms deadline
		// starts before the call, so it ends first; a timeout here has no
		// health effect (OptionalCallPath).
		return 500 * time.Millisecond
	case strings.HasPrefix(p, "/ether/open"), strings.HasPrefix(p, "/stream/"):
		return 3 * time.Second
	case IsSourceSearchPath(p):
		// A category search or file listing asks the plugin's own tracker
		// or engine live; the caller's search deadline still bounds it.
		return 10 * time.Second
	case strings.HasPrefix(p, "/ether/tool"):
		return 15 * time.Second
	case strings.HasPrefix(p, "/ether/job"):
		return 5 * time.Minute
	case strings.HasPrefix(p, "/meta/"), strings.HasPrefix(p, "/ether/metadata/"), strings.HasPrefix(p, "/catalog/"), strings.HasPrefix(p, "/ether/event"), strings.HasPrefix(p, "/ether/action"), strings.HasPrefix(p, "/ether/markers"):
		return 10 * time.Second
	case strings.HasPrefix(p, "/subtitles/"), strings.HasPrefix(p, "/ether/subtitles/"):
		return 5 * time.Second
	case strings.HasPrefix(p, "/ether/v1/setup/"):
		return 20 * time.Second
	case strings.HasPrefix(p, "/ether/v1/flow-actions/"):
		return 60 * time.Second
	case strings.HasPrefix(p, "/ether/v1/kinds/"):
		if strings.HasSuffix(p, "/live/resolve") || strings.HasSuffix(p, "/match") {
			return 5 * time.Second
		}
		if strings.HasSuffix(p, "/resolve") {
			// Leave room for a parallel indexer fan-out and the guest's
			// matching and source checks within a playback slice.
			return 12 * time.Second
		}
		return 10 * time.Second
	case strings.HasPrefix(p, "/ether/v1/live/"):
		return 15 * time.Second
	case strings.HasPrefix(p, "/ether/v1/screens/"):
		// A screen's data read or action: a viewer is waiting on it.
		if strings.Contains(p, "/actions/") {
			return 8 * time.Second
		}
		return 4 * time.Second
	default:
		return 30 * time.Second
	}
}

// EffectiveDeadline returns the enforced deadline for path given the plugin's
// granted deadline ceiling and whether it speaks Stremio add-on routes.
func EffectiveDeadline(path string, granted time.Duration, stremio bool) time.Duration {
	if GrantedLimitsPath(path) {
		if granted > 0 {
			return granted
		}
		return DeadlineFor(path)
	}
	route := DeadlineFor(path)
	if stremio {
		route = StremioDeadline(path)
	}
	if granted > 0 && granted < route {
		return granted
	}
	return route
}

// WaitBackground yields before starting work and at each host-service boundary.
func WaitBackground(ctx context.Context, busy func() bool) error {
	for busy != nil && busy() {
		timer := time.NewTimer(time.Second)
		select {
		case <-ctx.Done():
			timer.Stop()
			return ctx.Err()
		case <-timer.C:
		}
	}
	return ctx.Err()
}

func limitsForRequest(l Limits, path string) Limits {
	l.Deadline = EffectiveDeadline(path, l.Deadline, l.Stremio)
	if ViewerRequestPath(path) {
		l.UnitBudget = min(l.UnitBudget, UnitsForDeadline(l.Deadline))
	}
	return l
}

// faultPrefix marks a classified fault inside a JS exception message, the
// same trick appkit-sandbox uses to carry faults across the boundary.
const faultPrefix = "__ETHER_FAULT__"

func encodeFault(f *Fault) string {
	b, _ := json.Marshal(f)
	return faultPrefix + string(b)
}

func decodeFault(msg string) *Fault {
	at := strings.Index(msg, faultPrefix)
	if at < 0 {
		return nil
	}
	var f Fault
	// The payload may be followed by a JS stack trace; decode one value.
	dec := json.NewDecoder(strings.NewReader(msg[at+len(faultPrefix):]))
	if dec.Decode(&f) != nil || f.Code == "" {
		return nil
	}
	return &f
}

// ensureQJS creates the first QuickJS runtime in the process with
// CloseOnContextDone enabled. fastschema/qjs caches its wazero runtime
// config package-globally from the first New call, and context-driven
// module close is the only reliable way to interrupt a tight JS loop
// (its MaxExecutionTime does not interrupt one), so the first runtime
// must be ours.
func ensureQJS() {
	qjsOnce.Do(func() {
		defer func() { _ = recover() }()
		if rt, err := qjs.New(qjs.Option{Context: context.Background(), CloseOnContextDone: true,
			Stdout: io.Discard, Stderr: io.Discard}); err == nil {
			defer func() { _ = recover() }()
			rt.Close()
		}
	})
}

// codecPrelude installs __ether_text_decode, __ether_text_encode, TextDecoder,
// and TextEncoder backed by native Go UTF-8 helpers so guest plugins never pay
// per-byte JavaScript loops when decoding or encoding UTF-8 buffers.
const codecPrelude = `
"use strict";
(() => {
  const rawDecode = __ether_raw_text_decode;
  const rawEncode = __ether_raw_text_encode;
  delete globalThis.__ether_raw_text_decode;
  delete globalThis.__ether_raw_text_encode;

  const utf8Labels = new Set([
    "utf-8",
    "utf8",
    "unicode-1-1-utf-8",
    "unicode11utf8",
    "unicode20utf8",
    "x-unicode20utf8",
  ]);

  const toView = (input, fnName) => {
    if (ArrayBuffer.isView(input)) {
      return new Uint8Array(input.buffer, input.byteOffset, input.byteLength);
    }
    if (input instanceof ArrayBuffer) {
      return new Uint8Array(input);
    }
    throw new TypeError(fnName + ": input must be an ArrayBuffer or ArrayBufferView");
  };

  const decodeBuf = (ab, offset, length, fatal) => {
    try {
      return rawDecode(ab, offset, length, fatal);
    } catch (e) {
      const msg = String(e && e.message || e);
      if (fatal && msg.indexOf("not valid for encoding") >= 0) {
        throw new TypeError(msg);
      }
      if (msg.indexOf("detached") >= 0 || msg.indexOf("ArrayBuffer") >= 0) {
        throw new TypeError(msg);
      }
      throw e;
    }
  };

  globalThis.__ether_text_decode = (input) => {
    if (input === undefined) return "";
    if (ArrayBuffer.isView(input)) {
      return decodeBuf(input.buffer, input.byteOffset, input.byteLength, false);
    }
    if (input instanceof ArrayBuffer) {
      return decodeBuf(input, 0, input.byteLength, false);
    }
    throw new TypeError("__ether_text_decode: input must be an ArrayBuffer or ArrayBufferView");
  };

  globalThis.__ether_text_encode = (input) => {
    const s = input === undefined ? "" : String(input);
    return s.indexOf("\x00") < 0 ? rawEncode(s, false) : rawEncode(JSON.stringify(s), true);
  };

  const validSecondByte = (lead, b1) => {
    if (lead === 0xe0) return b1 >= 0xa0 && b1 <= 0xbf;
    if (lead === 0xed) return b1 >= 0x80 && b1 <= 0x9f;
    if (lead === 0xf0) return b1 >= 0x90 && b1 <= 0xbf;
    if (lead === 0xf4) return b1 >= 0x80 && b1 <= 0x8f;
    return b1 >= 0x80 && b1 <= 0xbf;
  };

  const trailingIncomplete = (u8) => {
    const len = u8.byteLength;
    if (len === 0) return 0;
    const b0 = u8[len - 1];
    if (b0 >= 0xc2 && b0 <= 0xf4) return 1;
    if (len >= 2 && b0 >= 0x80 && b0 <= 0xbf) {
      const p1 = u8[len - 2];
      if (p1 >= 0xe0 && p1 <= 0xf4 && validSecondByte(p1, b0)) return 2;
      if (len >= 3) {
        const p2 = u8[len - 3];
        if (p2 >= 0xf0 && p2 <= 0xf4 && validSecondByte(p2, p1)) return 3;
      }
    }
    return 0;
  };

  if (typeof globalThis.TextDecoder !== "function") {
    class TextDecoder {
      constructor(label = "utf-8", options = undefined) {
        const norm = String(label).replace(/^[\t\n\f\r ]+|[\t\n\f\r ]+$/g, "").toLowerCase();
        if (!utf8Labels.has(norm)) {
          throw new RangeError("TextDecoder: unsupported encoding \"" + label + "\"");
        }
        if (options !== undefined && options !== null && typeof options !== "object") {
          throw new TypeError("TextDecoder: options must be an object");
        }
        this._fatal = Boolean(options && options.fatal);
        this._ignoreBOM = Boolean(options && options.ignoreBOM);
        this._pending = null;
        this._bomSeen = false;
      }
      get encoding() { return "utf-8"; }
      get fatal() { return this._fatal; }
      get ignoreBOM() { return this._ignoreBOM; }
      decode(input = undefined, options = undefined) {
        if (options !== undefined && options !== null && typeof options !== "object") {
          throw new TypeError("TextDecoder.decode: options must be an object");
        }
        const stream = Boolean(options && options.stream);
        if (!stream && !this._pending) {
          const hadBomSeen = this._bomSeen;
          this._bomSeen = false;
          if (input === undefined) return "";
          let out;
          if (ArrayBuffer.isView(input)) {
            out = decodeBuf(input.buffer, input.byteOffset, input.byteLength, this._fatal);
          } else if (input instanceof ArrayBuffer) {
            out = decodeBuf(input, 0, input.byteLength, this._fatal);
          } else {
            throw new TypeError("TextDecoder.decode: input must be an ArrayBuffer or ArrayBufferView");
          }
          if (!this._ignoreBOM && !hadBomSeen && out.length > 0 && out.charCodeAt(0) === 0xfeff) {
            return out.slice(1);
          }
          return out;
        }
        const view = input === undefined ? new Uint8Array(0) : toView(input, "TextDecoder.decode");
        if (input !== undefined && view.byteLength === 0) {
          decodeBuf(view.buffer, view.byteOffset, 0, this._fatal);
        }
        let combined = view;
        if (this._pending) {
          combined = new Uint8Array(this._pending.length + view.byteLength);
          combined.set(this._pending, 0);
          combined.set(view, this._pending.length);
          this._pending = null;
        }
        let decodeLen = combined.byteLength;
        if (stream && decodeLen > 0) {
          const keep = trailingIncomplete(combined);
          if (keep > 0) {
            decodeLen -= keep;
            this._pending = combined.slice(decodeLen);
          }
        }
        const rawOut = decodeLen > 0
          ? decodeBuf(combined.buffer, combined.byteOffset, decodeLen, this._fatal)
          : "";
        let res = rawOut;
        if (rawOut.length > 0) {
          if (!this._ignoreBOM && !this._bomSeen && rawOut.charCodeAt(0) === 0xfeff) {
            res = rawOut.slice(1);
          }
          this._bomSeen = true;
        }
        if (!stream) {
          this._bomSeen = false;
        }
        return res;
      }
    }
    globalThis.TextDecoder = TextDecoder;
  }

  if (typeof globalThis.TextEncoder !== "function") {
    class TextEncoder {
      get encoding() { return "utf-8"; }
      encode(input = "") {
        return new Uint8Array(globalThis.__ether_text_encode(input === undefined ? "" : String(input)));
      }
    }
    globalThis.TextEncoder = TextEncoder;
  }
})();
`

// servicePrelude builds the ether global for request-ABI instances. Host
// calls are synchronous functions backed by __ether_host, charged by the
// Go side; a Fault comes back as a thrown Error whose message carries the
// fault prefix, and ether.abort throws an aborted fault.
const servicePrelude = `
"use strict";
globalThis.ether = (() => {
  const call = (name, args) => {
    try { return JSON.parse(__ether_host(name, JSON.stringify(args))); }
    catch (e) {
      const message = String(e && e.message || e);
      const at = message.indexOf("__ETHER_FAULT__");
      if (at >= 0) {
        try {
          const fault = JSON.parse(message.slice(at + "__ETHER_FAULT__".length));
          e.code = fault.code || fault.Code;
          if (typeof fault.retryAfterSec === "number") e.retryAfterSec = fault.retryAfterSec;
          if (typeof fault.retryAt === "string") e.retryAt = fault.retryAt;
        } catch (_) {}
      }
      throw e;
    }
  };
  const ether = {
    log: (...a) => { try { __ether_host("log", JSON.stringify(a.map(String))); } catch (e) {} },
    abort: (msg) => { throw new Error("__ETHER_FAULT__" + JSON.stringify({ code: "aborted", message: String(msg == null ? "aborted" : msg) })); },
    runtime: { limits: () => call("runtime.limits", []) },
    kv: { get: (k) => call("kv.get", [k]), put: (k, v) => call("kv.put", [k, v]),
          delete: (k) => call("kv.delete", [k]), list: (p) => call("kv.list", [p == null ? "" : p]),
          usage: () => call("kv.usage", []) },
    badges: { set: (setKey, entries) => call("badges.set", [setKey, entries == null ? [] : entries]),
              clear: (setKey) => call("badges.clear", [setKey]),
              usage: () => call("badges.usage", []) },
    settings: { get: () => call("settings.get", []) },
    secret: { get: (n) => call("secret.get", [n]),
              set: (n, v, ttlSec) => call("secret.set", ttlSec === undefined ? [n, v] : [n, v, ttlSec]),
              delete: (n) => call("secret.delete", [n]) },
    http: { hash: (req) => call("http.hash", [req]),
            fetch: (req) => call("http.fetch", [req]),
            fetchMany: (reqs, opts) => call("http.fetchMany", opts == null ? [reqs == null ? [] : reqs] : [reqs == null ? [] : reqs, opts]),
            fetchToCache: (req) => call("http.fetchToCache", [req]) },
    catalog: { search: (q) => call("catalog.search", [q]), get: (id) => call("catalog.get", [id]) },
    addon: { get: (route) => call("addon.get", [route]) },
    viewers: { granted: () => call("viewers.granted", []), history: (id, page) => call("viewers.history", [id, page == null ? 0 : page]),
               setWatchState: (v, titleId, watched) => call("viewers.setWatchState",
                 typeof v === "object" && v !== null ? [v.viewerId, v.titleId, v.watched] : [v, titleId, watched]) },
    collections: { upsert: (c) => call("collections.upsert", [c]) },
    screens: { invalidate: () => call("screens.invalidate", []),
               putRecords: (records) => call("screens.putRecords", [records == null ? [] : records]) },
    kinds: { upsert: (kind, items) => call("kinds.upsert", [kind, items == null ? [] : items]),
             delete: (kind, ids) => call("kinds.delete", [kind, ids == null ? [] : ids]),
             items: (kind, cursor, limit) => call("kinds.items", [kind, cursor == null ? "" : cursor, limit == null ? 0 : limit]),
             visible: (kind, ids) => call("kinds.visible", [kind, ids == null ? [] : ids]),
