{
  "$id": "https://ether.dev/schemas/plugin-sources.v1.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "description": "Plugin source host queries, candidates and release hints. File selectors apply to torrents (provider file list) and NZBs (document order). See docs/plugin-kinds.md.",
  "$defs": {
    "sourceQuery": {
      "type": "object",
      "required": [
        "kind"
      ],
      "properties": {
        "kind": {
          "enum": [
            "indexer_search",
            "indexer_search_results",
            "indexer_search_cancel",
            "indexers",
            "debrid_check",
            "debrid_acquire",
            "release_files",
            "usenet_check",
            "nzb_request"
          ]
        },
        "query": {
          "type": "string",
          "description": "Search text for indexer_search. May be omitted or empty when category is set to fetch the newest up to 100 recent releases."
        },
        "category": {
          "type": "string",
          "description": "Comma-separated Newznab category IDs (1000–8999) or standard family names. Applied to generic indexer_search; when query is empty, requests recent releases. Stremio add-ons and source plugins are asked only when the plugin declared one of the categories in ether.contributes.source.search."
        },
        "lookup": {
          "type": "object",
          "required": [
            "type"
          ],
          "properties": {
            "type": {
              "type": "string",
              "pattern": "^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$"
            },
            "fields": {
              "type": "object",
              "maxProperties": 8,
              "propertyNames": {
                "pattern": "^[a-z][a-zA-Z0-9_]{0,31}$"
              },
              "additionalProperties": {
                "type": "string",
                "maxLength": 256
              }
            }
          },
          "description": "indexer_search with category only. A typed lookup (for example {type: \"album\", fields: {artist, title}}) passed to source plugins that declared its type in ether.contributes.source.search.lookups; every other indexer searches query alone."
        },
        "profile": {
          "type": "string",
          "description": "Quality profile name used to score video release names on indexer_search; omit or leave empty to use the owner's default profile."
        },
        "stream": {
          "type": "boolean",
          "description": "indexer_search only. When true, starts the indexer fan-out and answers immediately with a searchId handle to poll via indexer_search_results or stop via indexer_search_cancel."
        },
        "searchId": {
          "type": "string",
          "description": "Streaming search handle returned by indexer_search with stream: true. Required on indexer_search_results and indexer_search_cancel; scoped to the calling plugin."
        },
        "waitMs": {
          "type": "integer",
          "minimum": 0,
          "maximum": 10000,
          "description": "indexer_search_results only. How long in milliseconds to wait for at least one new arrival or search completion before returning (capped at 10000 ms; 0 returns immediately with buffered arrivals)."
        },
        "firstResults": {
          "type": "boolean",
          "description": "indexer_search only. When true, return as soon as the fastest indexers produce results plus the settleMs window (250 ms by default), while slower indexers continue populating Ether's search cache in the background."
        },
        "settleMs": {
          "type": "integer",
          "minimum": 0,
          "maximum": 30000,
          "description": "indexer_search only. Grace window in milliseconds after the first matching result arrives before returning early (default 250 when firstResults is true; 0 returns immediately). Also applies when minResults is met if explicitly provided. Capped at 30000 ms."
        },
        "minResults": {
          "type": "integer",
          "minimum": 0,
          "description": "indexer_search only. Minimum deduplicated candidate count required before returning early. Combined with firstResults, returns as soon as either minResults is met or firstResults' settleMs window expires."
        },
        "skipIndexers": {
          "type": "array",
          "maxItems": 256,
          "items": {
            "type": "string"
          },
          "description": "indexer_search only. Indexer IDs or display names (case-insensitive) to exclude from this search. Skipped indexers are reported with status \"skipped\" and take precedence over onlyIndexers."
        },
        "onlyIndexers": {
          "type": "array",
          "maxItems": 256,
          "items": {
            "type": "string"
          },
          "description": "indexer_search only. Restrict this search to matching indexer IDs or display names (case-insensitive). Non-matching enabled indexers are reported with status \"skipped\"."
        },
        "timeoutMs": {
          "type": "integer",
          "minimum": 0,
          "maximum": 30000,
