	res := api.Build(api.BuildOptions{
		EntryPoints: []string{"sdk/examples/anime-tosho/plugin.ts"},
		Bundle:      true,
		Format:      api.FormatIIFE,
		GlobalName:  "__plugin",
		Platform:    api.PlatformNeutral,
		Target:      api.ES2020,
		Outfile:     "sdk/examples/anime-tosho/dist/plugin.js",
