MAX_BADGE_LABEL_LEN = 16
POSTER_BADGE_QUOTA_TITLES = 200_000

_BADGE_SET_KEY_RE = re.compile(r"^[a-z][a-z0-9_]{0,31}$")
_BADGE_LABEL_RE = re.compile(r"^[A-Z0-9 +&'./-]+$")
_IMDB_BADGE_RE = re.compile(r"^tt[0-9]{1,12}$")


